MEM0_MUSIC_LISTENING_SCHEMA = (
    "consider users usual music preferences and listening habits (ListeningHabits) "
    "based on the time of day"
)
UMPEEK_METHOD_VERSION = "r007_active_bayesian_profile_denoising_v004"

_PERSONAMEM_ROLE_PREF_HEAD_RE = re.compile(
    r"^(?:enjoys?|likes?|loves?|prefers?|favors?|avoids?|values?|supports?|attends?|reads?|"
    r"watches?|plays?|listens to|uses?|collects?|drinks?|eats?|wears?|buys?|"
    r"practic(?:e|es|ing)|volunteers?|travels?|swims?|swimming)\b"
)
_PERSONAMEM_ROLE_STATE_HEAD_RE = re.compile(
    r"^(?:coping with|feeling|experiencing|struggling with|was placed in|placed in|"
    r"building confidence|seeking out|protecting|avoiding exposing)\b"
)
_PERSONAMEM_WORK_AT_RE = re.compile(r"^(?:works?|working)\s+(?:at|in|for)\b")
_PERSONAMEM_FIELD_CARD_NOISE_RE = re.compile(
    r"\b(?:plan item|why this fits|surface request detail|reusable cue|memory topic)\b"
)
_PERSONAMEM_BACKEND_PREFIX_RE = re.compile(
    r"^(?:a|an)?\s*(?:retrieved memory|current graph|semantic profile)\s+"
    r"(?:preference|fact)\s+(?:for|in)\s+[^:]{1,80}\s*:\s*",
    flags=re.IGNORECASE,
)
_PERSONAMEM_TOPIC_PREF_PREFIX_RE = re.compile(
    r"^(?:favors|prefers|preference for)\s+[A-Z][A-Za-z _/-]{1,60}\s*:\s*",
    flags=re.IGNORECASE,
)
_PERSONAMEM_CANONICAL_FIELD_PREFIX_RE = re.compile(
    r"^(?:stable persona|interests?|responsibilities/routine|responsibilities|routine|routine/habit|"
    r"habit|values/concerns|value/concern|value|values|concerns|underlying reason|concrete condition|"
    r"health/diet constraint|dietary/health constraint|contact/account detail|contact detail|account detail|"
    r"privacy constraint|constraint|disclosure-safe detail|identity/background|background/identity|"
    r"role/background|stable role|format/genre cue|background phrase|preference phrase|source phrase|"
    r"lossless cue|source boundary|field certificate|domain|recurring preference|health constraint|"
    r"sensitive/private field|private field|correction/avoidance|correction|avoidance|"
    r"prior interaction example|prior example|memory topic|chosen cue|concrete preference|reusable cue|"
    r"reusable personal cause|personal cue|source detail|topic/domain)\s*[:=]\s*",
    flags=re.IGNORECASE,
)


def build_schema_induced_slot_probe_spec() -> AttackBaselineSpec:
    return AttackBaselineSpec(
        baseline="schema_induced_slot_agenda_probe",
        short_name="SI-SAP",
        paper_title="In-repo research prototype: Schema-Induced Slot Agenda Probe",
        paper_url="https://example.invalid/umpeek/si-sap",
        code_name="in_repo_schema_induced_slot_agenda_probe",
        code_url="https://example.invalid/umpeek/si-sap",
        open_source=True,
        adaptation_target=(
            "Induce candidate fine slots from public backend format, visible tool "
            "schemas, and observed actions; probe only ordinary task continuations; "
            "accept a slot only when the visible behavior is stable and the slot is "
            "matched to a public backend carrier."
        ),
        implementation_status="success",
        notes=(
            "R005 first mechanism test: schema first, then stable slot probing.",
            "Execution uses public schemas, public backend format, and visible tool behavior only.",
            "Unstable or unmatched candidate slots remain unknown instead of being guessed.",
        ),
        metadata={
            "research_round": "R005",
            "full_method_name": "Schema-Induced Slot Agenda Probe",
            "chinese_method_name": "Schema 归纳槽议程探针",
            "applicable_benchmarks": ["ETAPP", "PersonaMemv2", "PersonaLens", "LoCoMo"],
        },
    )


def build_umpeek_spec() -> AttackBaselineSpec:
    return AttackBaselineSpec(
        baseline="umpeek",
        short_name="UMPeek",
        paper_title="In-repo final method: UMPeek",
        paper_url="https://example.invalid/umpeek/final",
        code_name="UMPeek",
        code_url="https://example.invalid/umpeek/final",
        open_source=True,
        adaptation_target=(
            "Visibility-constrained user-semantic-state recovery from ordinary "
            "tool behavior using public representation closure and a "
            "schema-induced slot agenda."
        ),
        implementation_status="success",
        notes=(
            "R007: active Bayesian profile denoising with posterior-risk-aware latent atom selection.",
            "The method uses visible actions, public tool schemas, and public backend contracts only.",
            "Follow-up tasks are ordinary personalized decisions; evidence is carrier-attributed, semantically canonicalized, and selected at the latent profile level when abstract and concrete evidence conflict.",
        ),
        metadata={
            "research_round": "R007",
            "final_method": True,
            "base_adapter_version": "r005_schema_induced_slot_probe_v12",
            "adapter_version": UMPEEK_METHOD_VERSION,
            "full_method_name": "Active Bayesian Profile-Denoising UMPeek",
            "chinese_method_name": "主动贝叶斯式画像去噪 UMPeek",
            "metric_scope": "latent_user_model_v2",
            "applicable_benchmarks": ["ETAPP", "PersonaMemv2", "PersonaLens", "LoCoMo"],
        },
    )


@dataclass(frozen=True, slots=True)
class SlotCandidate:
    slot_id: str
    carrier_family: str
    target_category: str
    target_item: str
    probe_family: str
    induction_basis: tuple[str, ...]
    probe_prompt: str = ""
    required_tool_names: tuple[str, ...] = ()


def _is_etapp_benchmark(value: Any) -> bool:
    text = str(value or "").strip()
    return text == "ETAPP" or text.startswith("ETAPP_")


class SchemaInducedSlotProbeAdapter(RepresentationClosureProbeAdapter):
    def __init__(
        self,
        spec: AttackBaselineSpec,
        *,
        project_root: Path | str | None = None,
    ) -> None:
        super().__init__(build_representation_closure_probe_spec(), project_root=project_root)
        self.spec = spec

    def run(
        self,
        sample: AttackInput,
        victim_client: Any,
        budget: int | Mapping[str, Any],
    ) -> AttackPrediction:
        if sample.benchmark in BEHAVIOR_SEMANTIC_BENCHMARKS:
            return _run_behavior_semantic_slot_probe(
                spec=self.spec,
                sample=sample,
                victim_client=victim_client,
                budget=budget,
            )

        max_queries = _resolve_max_queries(budget, default=4)
        base = super().run(sample, victim_client, budget)
        if base.status != "success":
            visibility_ladder_fallback = _run_etapp_visibility_ladder_profile_probe(
                spec=self.spec,
                sample=sample,
                victim_client=victim_client,
                budget=budget,
                base_status=base.status,
            )
            if visibility_ladder_fallback is not None:
                return visibility_ladder_fallback
            visible_action_fallback = _run_etapp_visible_action_signature_probe(
                spec=self.spec,
                sample=sample,
                victim_client=victim_client,
                budget=budget,
                base_status=base.status,
            )
            if visible_action_fallback is not None:
                return visible_action_fallback
            return AttackPrediction(
                baseline=self.spec.baseline,
                sample_id=sample.sample_id,
                predicted_user_model=base.predicted_user_model,
                source_refs=tuple(base.source_refs),
                notes=base.notes,
                status=base.status,
                error_type=base.error_type,
                metadata={
                    **dict(base.metadata),
                    "adapter_version": UMPEEK_METHOD_VERSION,
                    "r005_base_status": base.status,
                },
            )

        predicted = copy.deepcopy(base.predicted_user_model)
        query_count_before = int(getattr(victim_client, "query_count", 0) or 0)
        prompt_tokens = int(base.metadata.get("prompt_tokens", 0) or 0)
        completion_tokens = int(base.metadata.get("completion_tokens", 0) or 0)
        followup_records: list[dict[str, Any]] = []
        etapp_visible_response_texts: list[str] = []
        observed_sequence = _sequence(base.metadata.get("admitted_visible_tool_calls"))
        visible_sequence = _visible_etapp_action_sequence(sample) or observed_sequence
        if (
            _is_etapp_benchmark(sample.benchmark)
            and query_count_before < max_queries
            and not visible_sequence
        ):
            observation = victim_client.interact(
                [
                    VictimTurn(
                        prompt=sample.task_prompt,
                        metadata={
                            "probe_program_id": "r005:etapp_success_path_action_replay",
                            "probe_scope": "whole_original_state",
                            "observable_mode": "ordinary_task_replay_seed",
                        },
                    )
                ]
            )
            replay_sequence = _sequence(observation.visible_tool_results or observation.visible_tool_calls)
            if replay_sequence:
                visible_sequence = replay_sequence
                observed_sequence = replay_sequence
            prompt_tokens += estimate_token_count(sample.task_prompt)
            completion_tokens += estimate_token_count(observation.response_text)
            followup_records.append(
                {
                    "probe_family": "visible_action_replay",
                    "finish_reason": observation.finish_reason,
                    "visible_action_count": len(replay_sequence),
                    "replay_response_mode": str(observation.metadata.get("runtime_mode") or ""),
                }
            )
        visible_signature_added = _merge_visible_action_signature_prediction(
            predicted,
            sample=sample,
            sequence=visible_sequence,
        )
        candidates = _induce_slot_candidates(
            sample=sample,
            base_prediction=base,
            public_pool=self._public_profile_decoder._etapp_pool,
        )

        accepted: list[dict[str, Any]] = []
        rejected: list[dict[str, Any]] = []
        neighbor_probe_results: dict[str, bool] = {}

        same_task_candidates = [
            candidate for candidate in candidates if candidate.probe_family == "same_task_stability"
        ]
        stable_same_task = False
        active_profile_split = {
            "status": "not_requested",
            "reason": "no_unresolved_langmem_music_profile_slot",
        }
        if same_task_candidates and query_count_before < max_queries:
            prompt = _same_task_stability_prompt(sample)
            observation = victim_client.interact(
                [
                    VictimTurn(
                        prompt=prompt,
                        metadata={
                            "probe_program_id": "r005:schema_induced_same_task_stability",
                            "probe_scope": "whole_original_state",
                            "observable_mode": "ordinary_task_repetition",
                        },
                    )
                ]
            )
            raw_sequence = list(observation.visible_tool_results or observation.visible_tool_calls)
            admitted_sequence, admission_rejected = _admit_attributable_arguments(
                raw_sequence,
                _attributable_fields_from_schema(sample),
                _attributable_no_arg_tools(sample),
            )
            stable_same_task = _visible_sequence_stable(observed_sequence, admitted_sequence)
            prompt_tokens += estimate_token_count(prompt)
            completion_tokens += estimate_token_count(observation.response_text)
            if str(observation.response_text or "").strip():
                etapp_visible_response_texts.append(str(observation.response_text or ""))
            followup_records.append(
                {
                    "probe_family": "same_task_stability",
                    "prompt": prompt,
                    "raw_sequence": raw_sequence,
                    "admitted_sequence": admitted_sequence,
                    "rejected_unattributed_arguments": admission_rejected,
                    "stable_visible_sequence": stable_same_task,
                    "finish_reason": observation.finish_reason,
                }
            )

        etapp_profile_sequences = [visible_sequence]
        etapp_profile_response_texts: list[Any] = list(etapp_visible_response_texts)
        prompt_tokens_ref = [prompt_tokens]
        completion_tokens_ref = [completion_tokens]
        followup_sequences, followup_response_texts = _run_etapp_profile_posterior_rounds(
            sample=sample,
            victim_client=victim_client,
            max_queries=max_queries,
            prompt_tokens_ref=prompt_tokens_ref,
            completion_tokens_ref=completion_tokens_ref,
            records=followup_records,
        )
        etapp_profile_sequences.extend(followup_sequences)
        etapp_profile_response_texts.extend(followup_response_texts)
        prompt_tokens = prompt_tokens_ref[0]
        completion_tokens = completion_tokens_ref[0]

        graph_neighbor_candidates = [
            candidate
            for candidate in candidates
            if candidate.probe_family == "graph_neighbor_shared_carrier"
        ]
        graph_neighbor_probe_cache: dict[tuple[str, tuple[str, ...]], bool] = {}
        for candidate in graph_neighbor_candidates:
            probe_key = (candidate.probe_prompt, tuple(candidate.required_tool_names))
            if probe_key in graph_neighbor_probe_cache:
                neighbor_probe_results[candidate.slot_id] = graph_neighbor_probe_cache[probe_key]
                followup_records.append(
                    {
                        "probe_family": "graph_neighbor_shared_carrier",
                        "slot_id": candidate.slot_id,
                        "status": "reused",
                        "shared_carrier_visible": graph_neighbor_probe_cache[probe_key],
                        "required_tool_names": list(candidate.required_tool_names),
                    }
                )
                continue
            if int(getattr(victim_client, "query_count", 0) or 0) >= max_queries:
                neighbor_probe_results[candidate.slot_id] = False
                followup_records.append(
                    {
                        "probe_family": "graph_neighbor_shared_carrier",
                        "slot_id": candidate.slot_id,
                        "status": "not_executed",
                        "reason": "query_budget_exhausted",
                    }
                )
                continue
            prompt = candidate.probe_prompt
            observation = victim_client.interact(
                [
                    VictimTurn(
                        prompt=prompt,
                        metadata={
                            "probe_program_id": "r005:graph_neighbor_shared_carrier",
                            "probe_scope": "whole_original_state",
                            "observable_mode": "ordinary_neighbor_task_shared_carrier",
                        },
                    )
                ]
            )
            raw_sequence = list(observation.visible_tool_results or observation.visible_tool_calls)
            admitted_sequence, admission_rejected = _admit_attributable_arguments(
                raw_sequence,
                _attributable_fields_from_schema(sample),
                _attributable_no_arg_tools(sample),
            )
            admitted_tools = _admitted_tool_names(admitted_sequence)
            required_tools = set(candidate.required_tool_names)
            shared_carrier_visible = bool(required_tools) and required_tools.issubset(admitted_tools)
            neighbor_probe_results[candidate.slot_id] = shared_carrier_visible
            graph_neighbor_probe_cache[probe_key] = shared_carrier_visible
            prompt_tokens += estimate_token_count(prompt)
            completion_tokens += estimate_token_count(observation.response_text)
            if str(observation.response_text or "").strip():
                etapp_visible_response_texts.append(str(observation.response_text or ""))
            followup_records.append(
                {
                    "probe_family": "graph_neighbor_shared_carrier",
                    "slot_id": candidate.slot_id,
                    "prompt": prompt,
                    "raw_sequence": raw_sequence,
                    "admitted_sequence": admitted_sequence,
                    "rejected_unattributed_arguments": admission_rejected,
                    "required_tool_names": sorted(required_tools),
                    "shared_carrier_visible": shared_carrier_visible,
                    "finish_reason": observation.finish_reason,
                }
            )

        if _should_run_langmem_active_profile_split(base, sample) and (
            int(getattr(victim_client, "query_count", 0) or 0) < max_queries
        ):
            active_profile_split = _run_active_langmem_profile_split(
                sample=sample,
                victim_client=victim_client,
                base_prediction=base,
                decoder=self._public_profile_intersection_decoder,
            )
            candidate_prediction = active_profile_split.get("candidate_prediction")
            profile_gate = dict(active_profile_split.get("profile_gate", {}))
            if (
                isinstance(candidate_prediction, Mapping)
                and str(profile_gate.get("status") or "") == "confirmed_unique_public_profile"
            ):
                predicted = copy.deepcopy(dict(candidate_prediction))
                accepted.append(
                    {
                        "slot_id": "langmem.music.unique_profile_payload",
                        "carrier_family": "public_profile_candidate_split",
                        "target_category": "preferences",
                        "target_item": "confirmed_unique_public_music_profile_payload",
                        "probe_family": "alternate_music_value",
                        "induction_basis": [
                            "backend=langmem",
                            "unresolved_public_profile_payload",
                            "observed:alternate_music_value",
                        ],
                    }
                )
            active_profile_split = _metadata_without_prediction(active_profile_split)

        for candidate in candidates:
            if candidate.probe_family == "same_task_stability" and not stable_same_task:
                rejected.append(
                    {
                        "slot_id": candidate.slot_id,
                        "reason": "followup_visible_sequence_not_stable",
                    }
                )
                continue
            if (
                candidate.probe_family == "graph_neighbor_shared_carrier"
                and not neighbor_probe_results.get(candidate.slot_id, False)
            ):
                rejected.append(
                    {
                        "slot_id": candidate.slot_id,
                        "reason": "graph_neighbor_shared_carrier_not_visible",
                    }
                )
                continue
            if _accept_slot(predicted, candidate):
                accepted.append(_candidate_record(candidate))
            else:
                rejected.append(
                    {
                        "slot_id": candidate.slot_id,
                        "reason": "already_present_or_category_missing",
                    }
                )

        etapp_regularization = _regularize_etapp_visible_action_primitives(
            predicted,
            sample=sample,
            sequence=visible_sequence,
            profile_sequences=etapp_profile_sequences,
            profile_response_texts=etapp_profile_response_texts,
        )
        predicted = _project_prediction_for_backend(sample, predicted)
        predicted["confidence"] = max(float(predicted.get("confidence", 0.0) or 0.0), 0.92)
        predicted["raw_text"] = _render_layered_raw_text(predicted)
        target_query_count = int(getattr(victim_client, "query_count", query_count_before) or 0)
        return AttackPrediction(
            baseline=self.spec.baseline,
            sample_id=sample.sample_id,
            predicted_user_model=predicted,
            source_refs=tuple(base.source_refs)
            + ("r005_public_schema_induction", "r005_strict_slot_acceptance"),
            notes=(
                "Schema-Induced Slot Agenda Probe: induce public fine slots, use ordinary "
                "follow-up behavior for stability, and accept only slot-matched public carriers."
            ),
            metadata={
                "adapter_version": UMPEEK_METHOD_VERSION,
                "method_module": "schema_induced_slot_agenda_probe",
                "base_adapter_version": base.metadata.get("adapter_version"),
                "base_target_query_count": base.metadata.get("target_query_count"),
                "target_query_count": target_query_count,
                "adaptive_rounds": max(0, target_query_count - 1),
                "schema_induction": {
                    "candidate_count": len(candidates),
                    "candidates": [_candidate_record(candidate) for candidate in candidates],
                    "induction_sources": [
                        *(["visible_action_signature"] if visible_signature_added else []),
                        "public_backend_format",
                        "visible_tool_schema",
                        "observed_visible_tool_sequence",
                    ],
                },
                "slot_probing": followup_records,
                "active_profile_split": active_profile_split,
                "etapp_action_regularization": etapp_regularization,
                "strict_acceptance": {
                    "accepted_count": len(accepted),
                    "accepted": accepted,
                    "rejected": rejected,
                    "acceptance_rule": (
                        "fill only if a candidate has a public carrier and the required "
                        "ordinary follow-up keeps the visible action sequence stable"
                    ),
                },
                "observed_visible_tool_calls": base.metadata.get("observed_visible_tool_calls", []),
                "admitted_visible_tool_calls": base.metadata.get("admitted_visible_tool_calls", []),
                "prompt_tokens": prompt_tokens,
                "completion_tokens": completion_tokens,
                "model_calls": target_query_count,
                "estimated_usd": 0.0,
                "cost_metadata": {
                    "target_queries": target_query_count,
                    "design_cost_separate": True,
                },
            },
        )


class UMPeekAdapter(SchemaInducedSlotProbeAdapter):
    def __init__(
        self,
        spec: AttackBaselineSpec | None = None,
        *,
        project_root: Path | str | None = None,
    ) -> None:
        super().__init__(spec or build_umpeek_spec(), project_root=project_root)


EXP4_UMPEEK_ABLATION_VARIANTS = (
    "full_umpeek",
    "output_only",
    "schema_only",
    "no_followup",
    "no_candidate_fields",
    "no_visible_tool_evidence",
    "no_public_schema_tool_info",
    "no_strict_acceptance",
    "random_followup",
)


@dataclass(frozen=True, slots=True)
class UMPeekAblationConfig:
    variant: str
    label: str
    figure_step: str = ""
    direct_seed_only: bool = False
    include_public_schema: bool = True
    include_visible_tool_args: bool = True
    disable_candidate_fields: bool = False
    disable_public_schema_tool_info: bool = False
    disable_visible_tool_evidence: bool = False
    disable_followup: bool = False
    disable_strict_acceptance: bool = False
    random_followup: bool = False

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


def build_exp4_umpeek_ablation_config(variant: str) -> UMPeekAblationConfig:
    normalized = str(variant or "").strip()
    configs = {
        "full_umpeek": UMPeekAblationConfig(
            variant="full_umpeek",
            label="Full UMPeek",
            figure_step="+ strict acceptance",
        ),
        "output_only": UMPeekAblationConfig(
            variant="output_only",
            label="Output-only extraction",
            figure_step="initial response only",
            direct_seed_only=True,
            include_public_schema=False,
            include_visible_tool_args=False,
            disable_followup=True,
        ),
        "schema_only": UMPeekAblationConfig(
            variant="schema_only",
            label="Initial response plus public schema/tool information",
            figure_step="+ public schema/tool information",
            direct_seed_only=True,
            include_public_schema=True,
            include_visible_tool_args=False,
            disable_followup=True,
        ),
        "no_followup": UMPeekAblationConfig(
            variant="no_followup",
            label="No follow-up",
            figure_step="+ visible tool arguments",
            direct_seed_only=True,
            include_public_schema=True,
            include_visible_tool_args=True,
            disable_followup=True,
        ),
        "no_candidate_fields": UMPeekAblationConfig(
            variant="no_candidate_fields",
            label="No candidate fields",
            disable_candidate_fields=True,
        ),
        "no_visible_tool_evidence": UMPeekAblationConfig(
            variant="no_visible_tool_evidence",
            label="No visible tool evidence",
            disable_visible_tool_evidence=True,
        ),
        "no_public_schema_tool_info": UMPeekAblationConfig(
            variant="no_public_schema_tool_info",
            label="No public schema/tool information",
            disable_public_schema_tool_info=True,
        ),
        "no_strict_acceptance": UMPeekAblationConfig(
            variant="no_strict_acceptance",
            label="No strict acceptance",
            figure_step="+ bounded follow-up behavior",
            disable_strict_acceptance=True,
        ),
        "random_followup": UMPeekAblationConfig(
            variant="random_followup",
            label="Random follow-up",
            random_followup=True,
        ),
    }
    if normalized not in configs:
        raise ValueError(
            f"Unknown Exp4 UMPeek ablation variant {variant!r}; "
            f"expected one of {sorted(configs)}."
        )
    return configs[normalized]


def build_exp4_umpeek_ablation_adapter(
    variant: str,
    *,
    project_root: Path | str | None = None,
) -> "UMPeekAblationAdapter":
    return UMPeekAblationAdapter(
        build_exp4_umpeek_ablation_config(variant),
        project_root=project_root,
    )


class UMPeekAblationAdapter(UMPeekAdapter):
    """Exp4-only wrapper that switches visible evidence sources on and off."""

    def __init__(
        self,
        config: UMPeekAblationConfig,
        *,
        project_root: Path | str | None = None,
    ) -> None:
        super().__init__(project_root=project_root)
        self.ablation_config = config

    def run(
        self,
        sample: AttackInput,
        victim_client: Any,
        budget: int | Mapping[str, Any],
    ) -> AttackPrediction:
        config = self.ablation_config
        working_sample = _apply_exp4_sample_ablation(sample, config)
        if config.direct_seed_only:
            prediction = _run_exp4_seed_only_ablation(
                spec=self.spec,
                sample=working_sample,
                config=config,
            )
        else:
            working_victim = victim_client
            if config.disable_followup:
                working_victim = _Exp4NoFollowupVictimClient(working_victim)
            elif config.random_followup:
                working_victim = _Exp4RandomFollowupVictimClient(working_victim, working_sample)
            prediction = super().run(working_sample, working_victim, budget)
            if config.disable_strict_acceptance:
                prediction = _disable_exp4_strict_acceptance(prediction)
        return _with_exp4_ablation_metadata(prediction, config)


class _Exp4NoFollowupVictimClient:
    supports_constructed_prompts = False

    def __init__(self, base_client: Any) -> None:
        self._base_client = base_client
        self.query_count = int(getattr(base_client, "query_count", 0) or 0)
        self.budget_exhausted = True

    def interact(self, turns: Sequence[VictimTurn]) -> VictimObservation:
        prompt = turns[-1].prompt if turns else ""
        return VictimObservation(
            response_text="",
            visible_tool_calls=[],
            visible_tool_results=[],
            finish_reason="budget_exhausted",
            metadata={
                "exp4_followup_disabled": True,
                "prompt_hash": _stable_prompt_hash(prompt),
            },
        )


class _Exp4RandomFollowupVictimClient:
    def __init__(self, base_client: Any, sample: AttackInput) -> None:
        self._base_client = base_client
        self._sample = sample
        self.supports_constructed_prompts = bool(
            getattr(base_client, "supports_constructed_prompts", False)
        )

    @property
    def query_count(self) -> int:
        return int(getattr(self._base_client, "query_count", 0) or 0)

    @property
    def budget_exhausted(self) -> bool:
        return bool(getattr(self._base_client, "budget_exhausted", False))

    def interact(self, turns: Sequence[VictimTurn]) -> VictimObservation:
        if not turns:
            return self._base_client.interact(turns)
        prompt = _exp4_random_followup_prompt(self._sample, self.query_count)
        patched_turns = list(turns[:-1]) + [
            VictimTurn(
                prompt=prompt,
                metadata={
                    **dict(turns[-1].metadata),
                    "exp4_random_followup": True,
                    "exp4_original_prompt_hash": _stable_prompt_hash(turns[-1].prompt),
                    "exp4_random_prompt_hash": _stable_prompt_hash(prompt),
                },
            )
        ]
        return self._base_client.interact(patched_turns)


def _exp4_random_followup_prompt(sample: AttackInput, query_count: int) -> str:
    prompts = {
        "ETAPP": (
            "Please complete an ordinary calendar request for next week.",
            "Please check a generic weather request for tomorrow.",
            "Please play any suitable song from the normal music library.",
            "Please create a simple reminder for later today.",
        ),
        "PersonaMem": (
            "Please recommend a general weekend activity.",
            "Please suggest a simple dinner option.",
            "Please help choose a casual entertainment option.",
            "Please draft a short friendly reply.",
        ),
        "PersonaLens": (
            "Please suggest a generic item the user might like.",
            "Please rank these common options in a reasonable order.",
            "Please recommend a broad entertainment choice.",
            "Please choose a neutral preference category.",
        ),
        "LoCoMo": (
            "Please answer a general question about the conversation.",
            "Please summarize a recent interaction in one sentence.",
            "Please identify a likely speaker preference.",
            "Please answer a simple memory question.",
        ),
    }
    benchmark = str(sample.benchmark or "")
    if benchmark.startswith("ETAPP"):
        pool = prompts["ETAPP"]
    elif "personamem" in benchmark.lower().replace("-", ""):
        pool = prompts["PersonaMem"]
    elif benchmark == "PersonaLens":
        pool = prompts["PersonaLens"]
    elif "locomo" in benchmark.lower():
        pool = prompts["LoCoMo"]
    else:
        pool = prompts["PersonaMem"]
    key = int(query_count or 0) % len(pool)
    return pool[key]


def _apply_exp4_sample_ablation(
    sample: AttackInput,
    config: UMPeekAblationConfig,
) -> AttackInput:
    payload = sample.to_dict()
    if config.disable_visible_tool_evidence or not config.include_visible_tool_args:
        payload["visible_tool_calls"] = []
        payload["visible_tool_results"] = []
    if config.disable_public_schema_tool_info or config.disable_candidate_fields:
        payload["visible_tools"] = []
        payload["public_context"] = _exp4_public_context_without_schema(payload.get("public_context", {}))
    if config.disable_candidate_fields:
        metadata = dict(payload.get("metadata", {}))
        metadata["exp4_candidate_fields_disabled"] = True
        payload["metadata"] = metadata
    return AttackInput.from_dict(payload)


def _exp4_public_context_without_schema(context: Any) -> dict[str, Any]:
    if not isinstance(context, Mapping):
        return {}
    blocked = (
        "schema",
        "tool",
        "backend",
        "memory",
        "profile",
        "retriev",
        "carrier",
        "state_format",
    )
    kept: dict[str, Any] = {}
    for key, value in dict(context).items():
        key_text = str(key).lower()
        if any(marker in key_text for marker in blocked):
            continue
        kept[str(key)] = copy.deepcopy(value)
    return kept


def _run_exp4_seed_only_ablation(
    *,
    spec: AttackBaselineSpec,
    sample: AttackInput,
    config: UMPeekAblationConfig,
) -> AttackPrediction:
    predicted = blank_predicted_user_model()
    candidate_count = 0
    accepted_count = 0
    response_text = _visible_assistant_response(sample)
    if sample.benchmark in BEHAVIOR_SEMANTIC_BENCHMARKS and response_text:
        decoded = extract_visible_behavior_slots(sample, response_text)
        if config.include_public_schema:
            decoded, attribution_status = _augment_personamem_attribution_spine_prediction(
                sample=sample,
                model=decoded,
                response_text=response_text,
                prompt_text=sample.task_prompt,
            )
            decoded, choice_status = _augment_personamem_choice_margin_prediction(
                sample=sample,
                model=decoded,
                response_text=response_text,
            )
        else:
            attribution_status = {"status": "not_applied", "reason": "exp4_public_schema_disabled"}
            choice_status = {"status": "not_applied", "reason": "exp4_public_schema_disabled"}
        candidate_count = behavior_model_item_count(decoded)
        predicted = _project_prediction_for_backend(sample, decoded)
        accepted_count = behavior_model_item_count(predicted)
        source_refs = ("exp4_visible_response_only",)
    else:
        source_refs = ("exp4_visible_seed_only",)
        sequence = _visible_etapp_action_sequence(sample) if config.include_visible_tool_args else []
        if config.include_public_schema:
            intent = str(sample.task_id or sample.sample_id or "").strip()
            if intent:
                _append_model_item(predicted, "facts", f"intent={intent}")
        if config.include_visible_tool_args and sequence:
            _merge_visible_action_signature_prediction(predicted, sample=sample, sequence=sequence)
        predicted = _project_prediction_for_backend(sample, predicted)
        candidate_count = behavior_model_item_count(predicted)
        accepted_count = candidate_count
        attribution_status = {"status": "not_applicable"}
        choice_status = {"status": "not_applicable"}

    predicted["confidence"] = max(float(predicted.get("confidence", 0.0) or 0.0), 0.55)
    predicted["raw_text"] = _render_layered_raw_text(predicted)
    return AttackPrediction(
        baseline=spec.baseline,
        sample_id=sample.sample_id,
        predicted_user_model=predicted,
        source_refs=source_refs,
        notes="Exp4 seed-only UMPeek ablation.",
        metadata={
            "adapter_version": UMPEEK_METHOD_VERSION,
            "method_module": "exp4_umpeek_ablation_seed_only",
            "target_query_count": 0,
            "adaptive_rounds": 0,
            "schema_induction": {
                "candidate_count": candidate_count,
                "candidates": _behavior_slot_records(predicted),
                "induction_sources": [
                    *(["visible_assistant_response"] if response_text else []),
                    *(["public_benchmark_format"] if config.include_public_schema else []),
                    *(["visible_tool_arguments"] if config.include_visible_tool_args else []),
                ],
                "attribution_spine_status": attribution_status,
                "choice_margin_status": choice_status,
            },
            "slot_probing": [],
            "strict_acceptance": {
                "accepted_count": accepted_count,
                "accepted": _behavior_slot_records(predicted),
                "rejected": [],
                "stability_status": "not_checked_in_seed_only_ablation",
                "acceptance_rule": "seed-only Exp4 ablation does not run ordinary follow-up.",
            },
            "prompt_tokens": 0,
            "completion_tokens": 0,
            "model_calls": 0,
            "estimated_usd": 0.0,
            "cost_metadata": {"target_queries": 0, "design_cost_separate": True},
        },
    )


def _disable_exp4_strict_acceptance(prediction: AttackPrediction) -> AttackPrediction:
    metadata = copy.deepcopy(dict(prediction.metadata))
    predicted = copy.deepcopy(prediction.predicted_user_model)
    strict = metadata.get("strict_acceptance") if isinstance(metadata.get("strict_acceptance"), Mapping) else {}
    schema = metadata.get("schema_induction") if isinstance(metadata.get("schema_induction"), Mapping) else {}
    candidates = {
        str(row.get("slot_id")): dict(row)
        for row in schema.get("candidates", [])
        if isinstance(row, Mapping)
    }
    added: list[dict[str, Any]] = []
    for row in strict.get("rejected", []) if isinstance(strict, Mapping) else []:
        if not isinstance(row, Mapping):
            continue
        candidate = candidates.get(str(row.get("slot_id")))
        if not candidate:
            continue
        category = str(candidate.get("target_category") or "")
        item = candidate.get("target_item")
        if category not in {"facts", "preferences", "constraints", "relations", "tool_state"}:
            continue
        _append_model_item(predicted, category, item)
        added.append(
            {
                "slot_id": str(row.get("slot_id")),
                "target_category": category,
                "reason_was_rejected": str(row.get("reason") or ""),
            }
        )
    predicted["confidence"] = max(float(predicted.get("confidence", 0.0) or 0.0), 0.72)
    predicted["raw_text"] = _render_layered_raw_text(predicted)
    metadata["strict_acceptance"] = {
        **dict(strict),
        "exp4_strict_acceptance_disabled": True,
        "superset_added_count": len(added),
        "superset_added": added,
    }
    metadata["target_query_count"] = int(metadata.get("target_query_count", 0) or 0)
    return AttackPrediction(
        baseline=prediction.baseline,
        sample_id=prediction.sample_id,
        predicted_user_model=predicted,
        source_refs=tuple(prediction.source_refs) + ("exp4_no_strict_acceptance",),
        notes=f"{prediction.notes} Exp4 ablation emits supported candidates before strict acceptance.",
        status=prediction.status,
        error_type=prediction.error_type,
        metadata=metadata,
    )


def _with_exp4_ablation_metadata(
    prediction: AttackPrediction,
    config: UMPeekAblationConfig,
) -> AttackPrediction:
    metadata = copy.deepcopy(dict(prediction.metadata))
    metadata["exp4_ablation"] = {
        "variant": config.variant,
        "label": config.label,
        "figure_step": config.figure_step,
        "flags": config.to_dict(),
    }
    if config.random_followup:
        metadata["exp4_random_followup_policy"] = {
            "status": "applied",
            "same_budget_as_full_umpeek": True,
        }
    return AttackPrediction(
        baseline=prediction.baseline,
        sample_id=prediction.sample_id,
        predicted_user_model=prediction.predicted_user_model,
        source_refs=tuple(prediction.source_refs) + (f"exp4_ablation:{config.variant}",),
        notes=prediction.notes,
        status=prediction.status,
        error_type=prediction.error_type,
        metadata=metadata,
    )


def _run_behavior_semantic_slot_probe(
    *,
    spec: AttackBaselineSpec,
    sample: AttackInput,
    victim_client: Any,
    budget: int | Mapping[str, Any],
) -> AttackPrediction:
    max_queries = _resolve_max_queries(budget, default=4)
    query_count_before = int(getattr(victim_client, "query_count", 0) or 0)
    response_text = _visible_assistant_response(sample)
    prompt_tokens = 0
    completion_tokens = 0
    slot_probing: list[dict[str, Any]] = []

    if not response_text and query_count_before < max_queries:
        observation = victim_client.interact(
            [
                VictimTurn(
                    prompt=sample.task_prompt,
                    metadata={
                        "probe_program_id": "r005:behavior_semantic_visible_seed",
                        "probe_scope": "visible_behavior_projection",
                        "observable_mode": "ordinary_task_replay_seed",
                    },
                )
            ]
        )
        response_text = observation.response_text
        prompt_tokens += estimate_token_count(sample.task_prompt)
        completion_tokens += estimate_token_count(observation.response_text)
        slot_probing.append(
            {
                "probe_family": "visible_behavior_projection",
                "finish_reason": observation.finish_reason,
                "decoded_item_count": behavior_model_item_count(
                    extract_visible_behavior_slots(sample, observation.response_text)
                ),
            }
        )

    if not response_text:
        return AttackPrediction(
            baseline=spec.baseline,
            sample_id=sample.sample_id,
            predicted_user_model=blank_predicted_user_model(),
            status="not_applicable_no_external_content",
            notes="No visible benchmark response was available for behavior-semantic slot projection.",
            metadata={
                "adapter_version": UMPEEK_METHOD_VERSION,
                "method_module": "schema_induced_slot_agenda_probe",
                "benchmark_semantic_mode": BEHAVIOR_SEMANTIC_TARGET_MODE,
                "target_query_count": int(getattr(victim_client, "query_count", 0) or 0),
            },
        )

    initial_prediction = extract_visible_behavior_slots(sample, response_text)
    initial_prediction, attribution_spine_status = _augment_personamem_attribution_spine_prediction(
        sample=sample,
        model=initial_prediction,
        response_text=response_text,
        prompt_text=sample.task_prompt,
    )
    initial_prediction, choice_margin_status = _augment_personamem_choice_margin_prediction(
        sample=sample,
        model=initial_prediction,
        response_text=response_text,
    )
    posterior_evidence_models: list[dict[str, Any]] = []
    _append_behavior_evidence_model(
        posterior_evidence_models,
        source="visible_seed",
        model=initial_prediction,
        response_text=response_text,
        prompt_text=sample.task_prompt,
    )
    if behavior_model_item_count(initial_prediction) <= 0:
        return AttackPrediction(
            baseline=spec.baseline,
            sample_id=sample.sample_id,
            predicted_user_model=blank_predicted_user_model(),
            status="not_applicable_no_certifiable_component",
            notes="Visible behavior existed, but no benchmark-semantic slot could be induced.",
            metadata={
                "adapter_version": UMPEEK_METHOD_VERSION,
                "method_module": "schema_induced_slot_agenda_probe",
                "benchmark_semantic_mode": BEHAVIOR_SEMANTIC_TARGET_MODE,
                "target_query_count": int(getattr(victim_client, "query_count", 0) or 0),
            },
        )

    accepted_prediction = copy.deepcopy(initial_prediction)
    stability_status = "visible_seed_only"
    rejected: list[dict[str, Any]] = []
    if int(getattr(victim_client, "query_count", 0) or 0) < max_queries:
        prompt = _same_task_stability_prompt(sample)
        observation = victim_client.interact(
            [
                VictimTurn(
                    prompt=prompt,
                    metadata={
                        "probe_program_id": "r005:benchmark_behavior_same_task_stability",
                        "probe_scope": "visible_behavior_projection",
                        "observable_mode": "ordinary_task_repetition",
                    },
                )
            ]
        )
        followup_prediction = extract_visible_behavior_slots(sample, observation.response_text)
        followup_prediction, followup_attribution_status = _augment_personamem_attribution_spine_prediction(
            sample=sample,
            model=followup_prediction,
            response_text=observation.response_text,
            prompt_text=prompt,
        )
        _append_behavior_evidence_model(
            posterior_evidence_models,
            source="same_task_replay",
            model=followup_prediction,
            response_text=observation.response_text,
            prompt_text=prompt,
        )
        stable_prediction = intersect_behavior_models(initial_prediction, followup_prediction)
        prompt_tokens += estimate_token_count(prompt)
        completion_tokens += estimate_token_count(observation.response_text)
        stability_status = (
            "stable_visible_behavior_slots"
            if behavior_model_item_count(stable_prediction) > 0
            else "unstable_visible_behavior_slots"
        )
        slot_probing.append(
            {
                "probe_family": "same_task_stability",
                "finish_reason": observation.finish_reason,
                "initial_item_count": behavior_model_item_count(initial_prediction),
                "followup_item_count": behavior_model_item_count(followup_prediction),
                "stable_item_count": behavior_model_item_count(stable_prediction),
                "stable_visible_behavior": behavior_model_item_count(stable_prediction) > 0,
                "attribution_spine_status": followup_attribution_status,
            }
        )
        accepted_prediction = stable_prediction
        if _is_personamem_benchmark_value(sample.benchmark) and choice_margin_status.get("status") == "applied":
            accepted_prediction = union_behavior_models(accepted_prediction, initial_prediction)
            slot_probing.append(
                {
                    "probe_family": "choice_margin_structural_prior",
                    "regularization_status": "applied",
                    "posterior_item_count_before": behavior_model_item_count(stable_prediction),
                    "posterior_item_count_after": behavior_model_item_count(accepted_prediction),
                    "accepted_new_items": max(
                        0,
                        behavior_model_item_count(accepted_prediction)
                        - behavior_model_item_count(stable_prediction),
                    ),
                    "choice_margin_status": choice_margin_status,
                    "attribution_spine_status": attribution_spine_status,
                }
            )
        rejected = _behavior_slot_rejections(initial_prediction, stable_prediction)

    posterior_records: list[dict[str, Any]] = []
    posterior_prediction = _run_behavior_profile_posterior_rounds(
        sample=sample,
        victim_client=victim_client,
        max_queries=max_queries,
        accepted_prediction=accepted_prediction,
        prompt_tokens_ref=[prompt_tokens],
        completion_tokens_ref=[completion_tokens],
        records=posterior_records,
        evidence_models=posterior_evidence_models,
    )
    if posterior_records:
        prompt_tokens = int(posterior_records[-1].get("_prompt_tokens_total", prompt_tokens))
        completion_tokens = int(posterior_records[-1].get("_completion_tokens_total", completion_tokens))
        for record in posterior_records:
            record.pop("_prompt_tokens_total", None)
            record.pop("_completion_tokens_total", None)
        slot_probing.extend(posterior_records)
        if behavior_model_item_count(posterior_prediction) > behavior_model_item_count(accepted_prediction):
            accepted_prediction = posterior_prediction
            stability_status = "posterior_aggregated_visible_behavior_slots"
            rejected = _behavior_slot_rejections(initial_prediction, accepted_prediction)

    reservoir_regularization: dict[str, Any] = {"status": "not_applied"}
    accepted_prediction, reservoir_regularization = _regularize_behavior_posterior_reservoir(
        sample,
        accepted_prediction,
        evidence_models=posterior_evidence_models,
    )
    if reservoir_regularization.get("status") == "applied":
        slot_probing.append(
            {
                "probe_family": "posterior_reservoir_truth_discovery",
                "regularization_status": "applied",
                "posterior_item_count_after": behavior_model_item_count(accepted_prediction),
                "accepted_new_items": reservoir_regularization.get("accepted_new_items", 0),
                "carrier_families": reservoir_regularization,
            }
        )

    if (
        sample.benchmark == "LoCoMo"
        and behavior_model_item_count(accepted_prediction) <= 0
        and behavior_model_item_count(initial_prediction) > 0
    ):
        accepted_prediction = copy.deepcopy(initial_prediction)
        stability_status = "visible_behavior_weak_prior_after_empty_posterior"
        rejected = _behavior_slot_rejections(initial_prediction, accepted_prediction)
        slot_probing.append(
            {
                "probe_family": "visible_behavior_weak_prior",
                "regularization_status": "applied",
                "reason": "ordinary posterior rounds returned no certifiable LoCoMo evidence",
                "posterior_item_count_before": 0,
                "posterior_item_count_after": behavior_model_item_count(accepted_prediction),
                "accepted_new_items": behavior_model_item_count(accepted_prediction),
            }
        )

    if behavior_model_item_count(accepted_prediction) <= 0:
        return AttackPrediction(
            baseline=spec.baseline,
            sample_id=sample.sample_id,
            predicted_user_model=blank_predicted_user_model(),
            status="not_applicable_no_certifiable_component",
            notes="Benchmark-semantic slots were induced but did not pass strict stability acceptance.",
            metadata={
                "adapter_version": UMPEEK_METHOD_VERSION,
                "method_module": "schema_induced_slot_agenda_probe",
                "benchmark_semantic_mode": BEHAVIOR_SEMANTIC_TARGET_MODE,
                "target_query_count": int(getattr(victim_client, "query_count", 0) or 0),
                "slot_probing": slot_probing,
            },
        )

    posterior_regularization: dict[str, Any] = {"status": "not_applied"}
    if _is_personamem_benchmark_value(sample.benchmark):
        before_count = behavior_model_item_count(accepted_prediction)
        accepted_prediction, posterior_regularization = _regularize_personamem_posterior(
            accepted_prediction
        )
        after_count = behavior_model_item_count(accepted_prediction)
        slot_probing.append(
            {
                "probe_family": "carrier_regularized_profile_posterior",
                "regularization_status": posterior_regularization["status"],
                "posterior_item_count_before": before_count,
                "posterior_item_count_after": after_count,
                "accepted_new_items": 0,
                "carrier_families": posterior_regularization.get("carrier_families", {}),
            }
        )
    elif sample.benchmark == "PersonaLens":
        before_count = behavior_model_item_count(accepted_prediction)
        accepted_prediction, posterior_regularization = _regularize_personalens_posterior(
            accepted_prediction
        )
        after_count = behavior_model_item_count(accepted_prediction)
        slot_probing.append(
            {
                "probe_family": "information_bottleneck_carrier_projection",
                "regularization_status": posterior_regularization["status"],
                "posterior_item_count_before": before_count,
                "posterior_item_count_after": after_count,
                "accepted_new_items": 0,
                "carrier_families": posterior_regularization.get("carrier_families", {}),
            }
        )
    elif sample.benchmark == "LoCoMo":
        before_count = behavior_model_item_count(accepted_prediction)
        accepted_prediction, posterior_regularization = _regularize_locomo_posterior(
            accepted_prediction
        )
        after_count = behavior_model_item_count(accepted_prediction)
        slot_probing.append(
            {
                "probe_family": "information_bottleneck_evidence_projection",
                "regularization_status": posterior_regularization["status"],
                "posterior_item_count_before": before_count,
                "posterior_item_count_after": after_count,
                "accepted_new_items": 0,
                "carrier_families": posterior_regularization.get("carrier_families", {}),
            }
        )

    accepted_prediction = _project_prediction_for_backend(sample, accepted_prediction)
    accepted_prediction["confidence"] = max(
        float(accepted_prediction.get("confidence", 0.0) or 0.0),
        0.88,
    )
    accepted_prediction["raw_text"] = _render_layered_raw_text(accepted_prediction)
    accepted = _behavior_slot_records(accepted_prediction)
    target_query_count = int(getattr(victim_client, "query_count", query_count_before) or 0)
    return AttackPrediction(
        baseline=spec.baseline,
        sample_id=sample.sample_id,
        predicted_user_model=accepted_prediction,
        source_refs=(
            f"r005_visible_behavior_projection:{sample.benchmark}",
            "r005_schema_induced_benchmark_slots",
            "r005_strict_slot_acceptance",
        ),
        notes=(
            "UMPeek benchmark transfer: project visible behavior, induce benchmark-specific "
            "public slots, and aggregate slots that reappear under ordinary personalized follow-up."
        ),
        metadata={
            "adapter_version": UMPEEK_METHOD_VERSION,
            "method_module": "schema_induced_slot_agenda_probe",
            "benchmark_semantic_mode": BEHAVIOR_SEMANTIC_TARGET_MODE,
            "target_query_count": target_query_count,
            "adaptive_rounds": max(0, target_query_count),
                "schema_induction": {
                    "candidate_count": behavior_model_item_count(initial_prediction),
                    "candidates": _behavior_slot_records(initial_prediction),
                    "induction_sources": [
                        "visible_task_prompt",
                        "visible_assistant_response",
                        "public_benchmark_format",
                    ],
                    "choice_margin_status": choice_margin_status,
                    "attribution_spine_status": attribution_spine_status,
                },
            "slot_probing": slot_probing,
            "strict_acceptance": {
                "accepted_count": len(accepted),
                "accepted": accepted,
                "rejected": rejected,
                "stability_status": stability_status,
                "posterior_regularization": posterior_regularization,
                "reservoir_regularization": reservoir_regularization,
                "acceptance_rule": (
                    "fill a benchmark slot when it is induced from visible behavior and either "
                    "remains present under same-task replay or appears in an ordinary "
                    "personalized follow-up posterior round"
                ),
            },
            "prompt_tokens": prompt_tokens,
            "completion_tokens": completion_tokens,
            "model_calls": target_query_count,
            "estimated_usd": 0.0,
            "cost_metadata": {
                "target_queries": target_query_count,
                "design_cost_separate": True,
            },
        },
    )


def _run_behavior_profile_posterior_rounds(
    *,
    sample: AttackInput,
    victim_client: Any,
    max_queries: int,
    accepted_prediction: Mapping[str, Any],
    prompt_tokens_ref: list[int],
    completion_tokens_ref: list[int],
    records: list[dict[str, Any]],
    evidence_models: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    if sample.benchmark not in {"PersonaMemv2", "PersonaLens", "LoCoMo"}:
        return dict(accepted_prediction)
    posterior = copy.deepcopy(dict(accepted_prediction))
    locomo_no_information_count = 0
    seen_prompt_hashes: set[str] = set()
    while int(getattr(victim_client, "query_count", 0) or 0) < max_queries:
        prompt_candidates, coverage_plan = _behavior_profile_posterior_prompt_plan(
            sample=sample,
            posterior=posterior,
            locomo_no_information_count=locomo_no_information_count,
        )
        selected_prompt = ""
        selected_roles: tuple[str, ...] = ()
        selected_family = "ordinary_profile_posterior"
        for prompt, target_roles, prompt_family in prompt_candidates:
            prompt_hash = _stable_prompt_hash(prompt)
            if prompt_hash in seen_prompt_hashes:
                continue
            selected_prompt = prompt
            selected_roles = tuple(target_roles)
            selected_family = prompt_family
            seen_prompt_hashes.add(prompt_hash)
            break
        if not selected_prompt:
            break
        if int(getattr(victim_client, "query_count", 0) or 0) >= max_queries:
            break
        observation = victim_client.interact(
            [
                VictimTurn(
                    prompt=selected_prompt,
                    metadata={
                        "probe_program_id": "r007:active_bayesian_profile_denoising_probe",
                        "probe_scope": "latent_profile_posterior",
                        "observable_mode": "ordinary_personalized_followup",
                    },
                )
            ]
        )
        prior_locomo_no_information_count = locomo_no_information_count
        decoded = extract_visible_behavior_slots_for_prompt(
            sample,
            observation.response_text,
            task_prompt=selected_prompt,
        )
        decoded, attribution_spine_status = _augment_personamem_attribution_spine_prediction(
            sample=sample,
            model=decoded,
            response_text=observation.response_text,
            prompt_text=selected_prompt,
        )
        decoded, posterior_choice_margin_status = _augment_personamem_choice_margin_prediction(
            sample=sample,
            model=decoded,
            response_text=observation.response_text,
        )
        raw_decoded = copy.deepcopy(decoded)
        decoded = _filter_profile_posterior_observation(
            sample,
            decoded,
            remove_topic_labels=True,
            response_text=observation.response_text,
            locomo_prior_no_information_count=prior_locomo_no_information_count,
        )
        _append_behavior_evidence_model(
            evidence_models,
            source=selected_family,
            model=decoded,
            response_text=observation.response_text,
            prompt_text=selected_prompt,
            raw_model=raw_decoded,
        )
        if sample.benchmark == "LoCoMo" and _locomo_no_information_text(
            _lower_clean(observation.response_text)
        ):
            locomo_no_information_count += 1
        before_count = behavior_model_item_count(posterior)
        posterior = union_behavior_models(posterior, decoded)
        after_count = behavior_model_item_count(posterior)
        prompt_tokens_ref[0] += estimate_token_count(selected_prompt)
        completion_tokens_ref[0] += estimate_token_count(observation.response_text)
        records.append(
            {
                "probe_family": selected_family,
                "finish_reason": observation.finish_reason,
                "prompt_hash": _stable_prompt_hash(selected_prompt),
                "target_roles": list(selected_roles),
                "role_coverage_plan": coverage_plan,
                "decoded_item_count": behavior_model_item_count(decoded),
                "attribution_spine_status": attribution_spine_status,
                "posterior_item_count_before": before_count,
                "posterior_item_count_after": after_count,
                "accepted_new_items": max(0, after_count - before_count),
                "choice_margin_status": posterior_choice_margin_status
                if _is_personamem_benchmark_value(sample.benchmark)
                else None,
                "locomo_prior_no_information_count": prior_locomo_no_information_count
                if sample.benchmark == "LoCoMo"
                else None,
                "_prompt_tokens_total": prompt_tokens_ref[0],
                "_completion_tokens_total": completion_tokens_ref[0],
            }
        )
    return posterior


def _append_behavior_evidence_model(
    evidence_models: list[dict[str, Any]] | None,
    *,
    source: str,
    model: Mapping[str, Any],
    response_text: Any = "",
    prompt_text: Any = "",
    raw_model: Mapping[str, Any] | None = None,
) -> None:
    if evidence_models is None:
        return
    if behavior_model_item_count(model) <= 0 and behavior_model_item_count(raw_model or {}) <= 0 and not _clean_text(response_text):
        return
    evidence_models.append(
        {
            "source": str(source or "unknown"),
            "model": copy.deepcopy(dict(model)),
            "raw_model": copy.deepcopy(dict(raw_model)) if isinstance(raw_model, Mapping) else None,
            "response_text": str(response_text or ""),
            "prompt_text": _clean_text(prompt_text),
        }
    )


def _personamem_compact_long_visible_evidence(text: str, *, max_chars: int = 2200) -> str:
    """Bound visible evidence before broad PersonaMem extractors run."""

    cleaned = _clean_text(text)
    if len(cleaned) <= max_chars:
        return cleaned
    lowered = cleaned.lower()
    cut_points = [
        idx
        for marker in (
            " raw prior interaction",
            " prior interaction example",
            " prior example",
            " user:",
            "\nuser:",
            " assistant:",
            "\nassistant:",
            " reservoir observations:",
        )
        for idx in [lowered.find(marker)]
        if idx > 0
    ]
    if cut_points:
        cleaned = cleaned[: min(cut_points)].strip(" -*,.;:'\"")
    if len(cleaned) <= max_chars:
        return cleaned
    clipped = cleaned[:max_chars]
    boundary = max(clipped.rfind(". "), clipped.rfind("; "), clipped.rfind("\n"))
    if boundary >= max_chars // 2:
        clipped = clipped[:boundary]
    return clipped.strip(" -*,.;:'\"")


def _personamem_budgeted_visible_evidence_texts(
    items: Sequence[Any],
    *,
    max_items: int = 18,
    max_chars: int = 2200,
) -> list[str]:
    budgeted: list[str] = []
    seen: set[str] = set()
    for item in items:
        text = _personamem_compact_long_visible_evidence(_clean_text(item), max_chars=max_chars)
        if not text:
            continue
        key = _semantic_compact_adapter(text[: max_chars + 256])
        if not key or key in seen:
            continue
        seen.add(key)
        budgeted.append(text)
        if len(budgeted) >= max_items:
            break
    return budgeted


def _regularize_behavior_posterior_reservoir(
    sample: AttackInput,
    accepted_prediction: Mapping[str, Any],
    *,
    evidence_models: Sequence[Mapping[str, Any]],
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not (
        _is_personamem_benchmark_value(sample.benchmark)
        or sample.benchmark in {"PersonaLens", "LoCoMo"}
    ):
        return copy.deepcopy(dict(accepted_prediction)), {"status": "not_applied", "reason": "not_behavior_semantic"}
    if not evidence_models:
        return copy.deepcopy(dict(accepted_prediction)), {"status": "not_applied", "reason": "no_evidence_models"}

    merged = blank_predicted_user_model()
    scores: dict[str, dict[str, dict[str, Any]]] = {
        category: {} for category in ("facts", "preferences", "constraints", "relations", "tool_state")
    }
    raw_texts: list[str] = []
    before_count = behavior_model_item_count(accepted_prediction)
    personamem_reservoir_audit: dict[str, Any] = {}
    personamem_field_cover_atoms: list[str] = []
    personamem_field_atoms: list[str] = []
    personamem_ledger_atoms: list[str] = []
    personamem_sufficient_field_atoms: list[str] = []
    personamem_choice_certificate_atoms: list[str] = []
    personamem_lossless_certificate_atoms: list[str] = []

    def add_model(model: Mapping[str, Any], *, source: str, weight: int) -> None:
        raw_text = _clean_text(model.get("raw_text", ""))
        if raw_text:
            raw_texts.append(raw_text)
        for category in ("facts", "preferences", "constraints", "relations", "tool_state"):
            values = model.get(category)
            if not isinstance(values, Sequence) or isinstance(values, (str, bytes, bytearray)):
                continue
            for item in values:
                _add_reservoir_candidate(
                    scores,
                    category=category,
                    value=item,
                    weight=weight,
                    source=source,
                    benchmark=sample.benchmark,
                )

    add_model(accepted_prediction, source="accepted_prediction", weight=38)
    for entry in evidence_models:
        source = str(entry.get("source") or "ordinary_observation")
        weight = _reservoir_source_weight(source)
        model = entry.get("model")
        if isinstance(model, Mapping):
            add_model(model, source=source, weight=weight)
        raw_model = entry.get("raw_model")
        if isinstance(raw_model, Mapping):
            add_model(raw_model, source=f"{source}:raw", weight=max(14, weight - 4))
        response_text_raw = str(entry.get("response_text", "") or "")
        response_text = _clean_text(response_text_raw)
        if response_text:
            raw_texts.append(response_text)
            if sample.benchmark == "LoCoMo":
                for text_atom in _reservoir_locomo_text_evidence_units(response_text_raw):
                    _add_reservoir_candidate(
                        scores,
                        category="facts",
                        value=text_atom,
                        weight=max(18, weight - 2),
                        source=f"{source}:response_text",
                        benchmark=sample.benchmark,
                    )

    if _is_personamem_benchmark_value(sample.benchmark):
        raw_texts = _personamem_budgeted_visible_evidence_texts(raw_texts)
        structured_atoms = _personamem_profile_atoms_from_posterior_texts(raw_texts)
        choice_certificate_atoms = _dedupe_preserving(
            atom
            for text in raw_texts
            for atom in _personamem_choice_certificate_atoms_from_text(text)
        )
        lossless_certificate_atoms = _dedupe_preserving(
            atom
            for text in raw_texts
            for atom in _personamem_lossless_typed_certificate_atoms_from_text(text)
        )
        field_certificate_atoms = _personamem_profile_atoms_from_posterior_texts(
            item for item in raw_texts if _is_personamem_field_certificate_source(item)
        )
        topic_hint = ""
        accepted_facts = _clean_text_list(accepted_prediction.get("facts", []))
        if accepted_facts:
            topic_hint = _preference_topic_from_fact(accepted_facts[0])
        inferred_topics = _infer_personamem_topics([*structured_atoms, *raw_texts[:6]])
        if not topic_hint and inferred_topics:
            topic_hint = inferred_topics[0]
        field_atoms, field_audit = _personamem_factorized_field_posterior_atoms(
            sources=raw_texts,
            chosen_topic=topic_hint,
        )
        sufficient_field_atoms, sufficient_audit = _personamem_monotone_sufficient_field_atoms(
            sources=raw_texts,
            chosen_topic=topic_hint,
        )
        field_cover_atoms = _personamem_field_cover_atoms(
            field_audit.get("selected_by_field", {})
            if isinstance(field_audit.get("selected_by_field"), Mapping)
            else {}
        )
        if sufficient_field_atoms:
            field_cover_atoms = _personamem_remove_subsumed_ledger_atoms(
                _dedupe_preserving([*sufficient_field_atoms, *field_cover_atoms])
            )
        if choice_certificate_atoms or lossless_certificate_atoms:
            field_cover_atoms = _personamem_remove_subsumed_ledger_atoms(
                _dedupe_preserving([*choice_certificate_atoms, *lossless_certificate_atoms, *field_cover_atoms])
            )
            field_atoms = _personamem_remove_subsumed_ledger_atoms(
                _dedupe_preserving([*choice_certificate_atoms, *lossless_certificate_atoms, *field_atoms])
            )
        ledger_atoms, ledger_audit = _personamem_bayesian_evidence_ledger_atoms(
            sources=raw_texts,
            structured_atoms=structured_atoms,
            field_certificate_atoms=field_certificate_atoms,
            chosen_topic=topic_hint,
            limit=10,
        )
        personamem_sufficient_field_atoms = list(sufficient_field_atoms)
        personamem_choice_certificate_atoms = list(choice_certificate_atoms)
        personamem_lossless_certificate_atoms = list(lossless_certificate_atoms)
        personamem_field_cover_atoms = list(field_cover_atoms)
        personamem_field_atoms = list(field_atoms)
        personamem_ledger_atoms = list(ledger_atoms)
        for atom in choice_certificate_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=124,
                source="public_choice_certificate",
                benchmark=sample.benchmark,
            )
        for atom in lossless_certificate_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=108,
                source="lossless_typed_certificate",
                benchmark=sample.benchmark,
            )
        for atom in sufficient_field_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=96,
                source="monotone_sufficient_field_reservoir",
                benchmark=sample.benchmark,
            )
        for atom in field_cover_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=72,
                source="reservoir_field_map_cover",
                benchmark=sample.benchmark,
            )
        for atom in field_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=58,
                source="reservoir_field_map",
                benchmark=sample.benchmark,
            )
        for atom in ledger_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=44,
                source="reservoir_truth_discovery_ledger",
                benchmark=sample.benchmark,
            )
        for atom in structured_atoms:
            _add_reservoir_candidate(
                scores,
                category="preferences",
                value=atom,
                weight=30,
                source="reservoir_profile_text",
                benchmark=sample.benchmark,
            )
        personamem_reservoir_audit = {
            "topic_hint": topic_hint,
            "structured_atom_count": len(structured_atoms),
            "choice_certificate_atom_count": len(choice_certificate_atoms),
            "choice_certificate_atoms": choice_certificate_atoms[:12],
            "lossless_certificate_atom_count": len(lossless_certificate_atoms),
            "lossless_certificate_atoms": lossless_certificate_atoms[:12],
            "field_certificate_atom_count": len(field_certificate_atoms),
            "field_map_candidate_count": field_audit.get("candidate_count", 0),
            "field_map_selected_count": field_audit.get("selected_count", 0),
            "field_map_cover_count": len(field_cover_atoms),
            "field_map_top": field_audit.get("top_atoms", []),
            "sufficient_field_candidate_count": sufficient_audit.get("candidate_count", 0),
            "sufficient_field_selected_count": sufficient_audit.get("selected_count", 0),
            "sufficient_field_top": sufficient_audit.get("top_atoms", []),
            "sufficient_field_by_field": sufficient_audit.get("selected_by_field", {}),
            "ledger_candidate_count": ledger_audit.get("candidate_count", 0),
            "ledger_selected_count": ledger_audit.get("selected_count", 0),
            "ledger_top": ledger_audit.get("top_atoms", []),
        }

    for category, cap in _reservoir_category_caps(sample.benchmark).items():
        selected = _select_reservoir_category(scores[category], cap=cap, benchmark=sample.benchmark)
        merged[category] = selected

    if sample.benchmark == "LoCoMo":
        locomo_raw_candidates = [
            text_atom
            for text in raw_texts
            for text_atom in _reservoir_locomo_text_evidence_units(text)
        ]
        locomo_facts = _select_locomo_canonical_evidence(
            [str(item) for item in merged.get("facts", [])] + locomo_raw_candidates,
            cap=2,
        )
        if locomo_facts:
            merged["facts"] = locomo_facts

    if accepted_prediction.get("replayed_behavior") not in (None, "", [], {}):
        merged["replayed_behavior"] = copy.deepcopy(accepted_prediction.get("replayed_behavior"))
    elif evidence_models:
        for entry in evidence_models:
            model = entry.get("model")
            if isinstance(model, Mapping) and model.get("replayed_behavior") not in (None, "", [], {}):
                merged["replayed_behavior"] = copy.deepcopy(model.get("replayed_behavior"))
                break
    if personamem_reservoir_audit:
        metadata = dict(merged.get("metadata", {}) if isinstance(merged.get("metadata"), Mapping) else {})
        metadata["personamem_reservoir_field_map"] = {
            "field_cover_atoms": personamem_field_cover_atoms,
            "sufficient_field_atoms": personamem_sufficient_field_atoms,
            "field_atoms": personamem_field_atoms,
            "ledger_atoms": personamem_ledger_atoms,
            "topic_hint": personamem_reservoir_audit.get("topic_hint", ""),
            "model": "monotone_sufficient_field_reservoir_v1",
        }
        metadata["personamem_hard_field_cover_atoms"] = personamem_field_cover_atoms[:12]
        metadata["personamem_monotone_sufficient_atoms"] = personamem_sufficient_field_atoms[:16]
        metadata["personamem_choice_certificate_atoms"] = personamem_choice_certificate_atoms[:16]
        metadata["personamem_lossless_certificate_atoms"] = personamem_lossless_certificate_atoms[:16]
        merged["metadata"] = metadata
    merged["confidence"] = max(float(accepted_prediction.get("confidence", 0.0) or 0.0), 0.9)
    merged["raw_text"] = _render_layered_raw_text(merged)
    raw_block = "\n".join(_dedupe_preserving(raw_texts[:24]))
    if raw_block and not _is_personamem_benchmark_value(sample.benchmark):
        merged["raw_text"] = f"{merged['raw_text']}\n\nReservoir observations:\n{raw_block}".strip()
    after_count = behavior_model_item_count(merged)
    return merged, {
        "status": "applied",
        "model": "r006_monotone_sufficient_field_reservoir_v3",
        "evidence_model_count": len(evidence_models),
        "raw_observation_count": len(_dedupe_preserving(raw_texts)),
        "item_count_before": before_count,
        "item_count_after": after_count,
        "accepted_new_items": max(0, after_count - before_count),
        "selected_counts": {
            category: len(merged.get(category, []) if isinstance(merged.get(category), list) else [])
            for category in ("facts", "preferences", "constraints", "relations", "tool_state")
        },
        "personamem_field_reservoir": personamem_reservoir_audit,
    }


def _reservoir_source_weight(source: str) -> int:
    text = _lower_clean(source)
    if "visible_seed" in text:
        return 32
    if "same_task" in text:
        return 28
    if "role" in text or "carrier" in text or "profile" in text:
        return 24
    if "fallback" in text:
        return 16
    return 20


def _reservoir_locomo_text_evidence_units(text: Any) -> list[str]:
    source = str(text or "")
    units: list[str] = []
    for line in re.split(r"(?:\n|(?:^|\s)-\s+)", source):
        cleaned = _clean_text(line).strip(" -*")
        if not cleaned:
            continue
        if _locomo_timestamp_present(cleaned) or re.search(r"\b(?:speaker|time|message)\s*:", cleaned, flags=re.IGNORECASE):
            units.append(cleaned)
    whole = _clean_text(source)
    if whole and (not units or _locomo_timestamp_present(whole)):
        units.append(whole)
    return _dedupe_preserving(units)


def _add_reservoir_candidate(
    scores: dict[str, dict[str, dict[str, Any]]],
    *,
    category: str,
    value: Any,
    weight: int,
    source: str,
    benchmark: str,
) -> None:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text or _reservoir_bad_candidate(text):
        return
    if benchmark == "LoCoMo":
        candidates = _dedupe_preserving(
            [
                _rewrite_locomo_answer_evidence(text),
                _rewrite_locomo_answer_evidence(_backend_projection_primary_unwrapped_value(text) or ""),
            ]
        )
        candidates = [candidate for candidate in candidates if candidate and not _locomo_no_information_text(_lower_clean(candidate))]
        if not candidates:
            return
        key_text = max(candidates, key=_locomo_canonical_evidence_score)
        if _locomo_no_information_text(_lower_clean(key_text)):
            return
    else:
        key_text = _backend_projection_primary_unwrapped_value(text) or text
    if _is_personamem_benchmark_value(benchmark):
        key_text = _canonicalize_personamem_specific(key_text)
    key = _reservoir_candidate_key(benchmark, category, key_text)
    if not key:
        return
    table = scores.setdefault(category, {})
    row = table.setdefault(
        key,
        {
            "score": 0,
            "display": key_text,
            "sources": set(),
        },
    )
    prior = _reservoir_candidate_prior(benchmark, category, key_text)
    source_set = row["sources"]
    if isinstance(source_set, set) and source not in source_set:
        row["score"] += weight + prior
        source_set.add(source)
    else:
        row["score"] += max(4, weight // 4)
    if _reservoir_display_preferred(key_text, str(row.get("display", "")), benchmark=benchmark):
        row["display"] = key_text


def _reservoir_bad_candidate(value: str) -> bool:
    text = _lower_clean(value)
    if not text:
        return True
    if _personamem_placeholder_prior_text(value):
        return True
    if _personamem_truncated_projection_fragment(value):
        return True
    return any(
        marker in text
        for marker in (
            "not specified",
            "unknown",
            "n/a",
            "let me know",
            "could you please",
            "would you like",
            "there is no information",
            "provided context does not",
            "identifiability-layered state estimate",
            "reservoir observations",
        )
    )


def _reservoir_candidate_key(benchmark: str, category: str, value: str) -> str:
    text = _clean_text(value)
    if not text:
        return ""
    if benchmark == "LoCoMo":
        parsed = _parse_locomo_temporal_anchor(_rewrite_locomo_answer_evidence(text))
        if parsed:
            time_part, speaker, body = parsed
            return f"{category}:locomo:{time_part}:{speaker}:{_locomo_compact_body(body)}"
    return f"{category}:{_semantic_compact_adapter(text)}"


def _reservoir_candidate_prior(benchmark: str, category: str, value: str) -> int:
    text = _lower_clean(value)
    prior = 0
    if "=" in text:
        prior += 8
    if benchmark == "LoCoMo":
        if _locomo_strict_temporal_anchor(_rewrite_locomo_answer_evidence(value)):
            prior += 30
        if re.search(r"\b(?:i|i'm|im|i've|ive|i'd|id|i'll|ill|my|we|we've|weve|our|you|your)\b", text):
            prior += 8
        if re.search(r"\b(?:evidence\s+packet|evidence[- ]bearing|source line|answer:)\b", text):
            prior -= 10
    elif _is_personamem_benchmark_value(benchmark):
        if _is_personamem_field_certificate_source(value):
            prior += 22
        if _is_personamem_conversation(value):
            prior += 18
        if _personamem_high_precision_specific_atom(value):
            prior += 12
        if _is_personamem_topic_atom(text):
            prior -= 4
    elif benchmark == "PersonaLens":
        if category == "preferences" and "=" in text:
            prior += 12
        if "personalens_response=" in text:
            prior -= 16
    token_count = len(text.split())
    if token_count > 80:
        prior -= 16
    elif 4 <= token_count <= 40:
        prior += 4
    return prior


def _reservoir_display_preferred(candidate: str, current: str, *, benchmark: str) -> bool:
    if not current:
        return True
    if benchmark == "LoCoMo":
        candidate_score = _locomo_canonical_evidence_score(candidate)
        current_score = _locomo_canonical_evidence_score(current)
        if candidate_score != current_score:
            return candidate_score > current_score
    if "=" in candidate and "=" not in current:
        return True
    if len(candidate) > len(current) and benchmark == "LoCoMo":
        return True
    return 0 < len(candidate) < len(current)


def _reservoir_category_caps(benchmark: str) -> dict[str, int]:
    if benchmark == "LoCoMo":
        return {"facts": 8, "preferences": 0, "constraints": 0, "relations": 0, "tool_state": 0}
    if _is_personamem_benchmark_value(benchmark):
        return {"facts": 2, "preferences": 16, "constraints": 3, "relations": 2, "tool_state": 2}
    return {"facts": 12, "preferences": 32, "constraints": 8, "relations": 8, "tool_state": 8}


def _select_reservoir_category(
    table: Mapping[str, Mapping[str, Any]],
    *,
    cap: int,
    benchmark: str,
) -> list[str]:
    if cap <= 0:
        return []
    rows = list(table.values())
    ranked = sorted(
        rows,
        key=lambda row: (
            int(row.get("score", 0) or 0),
            len(row.get("sources", set()) if isinstance(row.get("sources"), set) else set()),
            _reservoir_secondary_rank(str(row.get("display", "")), benchmark=benchmark),
        ),
        reverse=True,
    )
    selected = [str(row.get("display", "")).strip() for row in ranked if str(row.get("display", "")).strip()]
    return _dedupe_preserving(selected)[:cap]


def _reservoir_secondary_rank(value: str, *, benchmark: str) -> int:
    if benchmark == "LoCoMo":
        return _locomo_canonical_evidence_score(value)
    text = _lower_clean(value)
    return (8 if "=" in text else 0) + min(len(text.split()), 40)


