def _personamem_profile_atoms_from_posterior_texts(items: Sequence[Any]) -> list[str]:
    """Recover structured profile atoms no matter which visible field held them."""

    atoms: list[str] = []
    seen_texts: set[str] = set()
    for item in items:
        for text in _backend_projection_unwrapped_values(item):
            if not text:
                continue
            if text in seen_texts:
                continue
            seen_texts.add(text)
            atoms.extend(_personamem_structured_profile_atoms(text))
    return _dedupe_preserving(atoms)


def _backend_projection_unwrapped_values(item: Any) -> list[str]:
    """Expose semantic values hidden inside backend runtime wrappers.

    The wrapper forms are backend contracts, not recovered user facts.  UMPeek
    should reason over the inner schema/role/value payload while preserving the
    wrapper again when projecting the final prediction.
    """

    text = _clean_text(item)
    if not text:
        return []
    values = [text]
    wrapper_patterns = (
        r"^(?:retrieved memory (?:fact|preference|constraint) for [^:]+):\s*(?P<value>.+)$",
        r"^(?:current graph (?:fact|preference|constraint) for [^:]+):\s*(?P<value>.+)$",
        r"^(?:semantic profile (?:fact|preference) in [^:]+):\s*(?P<value>.+)$",
        r"^(?:procedural memory constraint in [^:]+):\s*(?P<value>.+)$",
        r"^(?:mem0 recovered action cue|graphiti visible action support|langmem action memory)\s+(?P<value>.+)$",
    )
    for pattern in wrapper_patterns:
        match = re.match(pattern, text, flags=re.IGNORECASE)
        if match:
            values.append(_clean_text(match.group("value")).strip(" -*,.;:"))
            break
    relation_match = re.match(r"^\((?P<head>[^,]+),(?P<edge>[^,]+),(?P<value>.+)\)$", text)
    if relation_match and re.search(
        r"\b(?:fact|preference|relation|memory|links_to_user_state)\b",
        relation_match.group("edge"),
        flags=re.IGNORECASE,
    ):
        values.append(_clean_text(relation_match.group("value")).strip(" -*,.;:"))
    return _dedupe_preserving(values)


def _backend_projection_primary_unwrapped_value(item: Any) -> str:
    values = _backend_projection_unwrapped_values(item)
    return values[-1] if values else ""


def _replace_backend_projection_wrapped_value(item: Any, replacement: str) -> str:
    text = _clean_text(item)
    replacement_text = _clean_text(replacement).strip(" -*,.;:")
    if not text or not replacement_text:
        return text
    colon_wrappers = (
        r"^(?P<prefix>retrieved memory (?:fact|preference|constraint) for [^:]+):\s*(?P<value>.+)$",
        r"^(?P<prefix>current graph (?:fact|preference|constraint) for [^:]+):\s*(?P<value>.+)$",
        r"^(?P<prefix>semantic profile (?:fact|preference) in [^:]+):\s*(?P<value>.+)$",
        r"^(?P<prefix>procedural memory constraint in [^:]+):\s*(?P<value>.+)$",
    )
    for pattern in colon_wrappers:
        match = re.match(pattern, text, flags=re.IGNORECASE)
        if match:
            return f"{_clean_text(match.group('prefix'))}: {replacement_text}"
    relation_match = re.match(r"^\((?P<head>[^,]+),(?P<edge>[^,]+),(?P<value>.+)\)$", text)
    if relation_match:
        return f"({_clean_text(relation_match.group('head'))},{_clean_text(relation_match.group('edge'))},{replacement_text})"
    return replacement_text


_PERSONAMEM_STRUCTURED_FIELD_LABEL_PATTERN = (
    r"Stable persona|Interests?|Responsibilities/Routine|Routine/Habit|Responsibilities|Routine|Habit|"
    r"Values/Concerns|Value/Concern|Values|Concerns|"
    r"Underlying reason|Concrete condition|Health/Diet constraint|Dietary/Health constraint|"
    r"Contact/Account detail|Contact detail|Account detail|Privacy constraint|Constraint|"
    r"Disclosure-safe detail|Identity/Background|Background/Identity|Role/Background|Stable role|"
    r"Format/genre cue|Selected archetype|Background cue|"
    r"Background phrase|Preference phrase|Source phrase|Lossless cue|Source boundary|"
    r"Field certificate|Domain|Stable role|Recurring preference|Health constraint|"
    r"Sensitive/Private field|Private field|Memory topic|"
    r"Correction/Avoidance|Correction|Avoidance|Prior interaction example|Raw prior interaction|Prior example|"
    r"Health/Wellness cue|Work/School cue|Hobby/Home cue|Media/Sports cue|"
    r"Favorite team/person/genre|Current project or sector|Concrete collection or object|Facet|"
    r"Chosen cue|Concrete preference|Reusable cue|Reusable personal cause|"
    r"Personal cue|Source detail|Topic/Domain"
)
_PERSONAMEM_STRUCTURED_FIELD_LABEL_RE = re.compile(
    rf"\b(?P<label>{_PERSONAMEM_STRUCTURED_FIELD_LABEL_PATTERN})\s*[:=]\s*"
    rf"(?P<body>.*?)(?=(?:\s|[.;,]\s)+(?:{_PERSONAMEM_STRUCTURED_FIELD_LABEL_PATTERN})\s*[:=]|"
    rf"(?:\s|[.;,]\s)+Role\s*:|$)",
    flags=re.IGNORECASE | re.DOTALL,
)


def _personamem_structured_profile_atoms(text: str) -> list[str]:
    return list(_personamem_structured_profile_atoms_cached(str(text or "")))


@lru_cache(maxsize=4096)
def _personamem_structured_profile_atoms_cached(text: str) -> tuple[str, ...]:
    return tuple(_personamem_structured_profile_atoms_uncached(text))


def _personamem_structured_profile_atoms_uncached(text: str) -> list[str]:
    atoms: list[str] = []
    label_pattern = _PERSONAMEM_STRUCTURED_FIELD_LABEL_PATTERN
    text = _segment_personamem_field_certificate_text(text)
    text = re.sub(rf"[.;,]+\s+(?=(?:{label_pattern})\s*[:=])", " ", text, flags=re.IGNORECASE)
    text = re.sub(rf"\s+-\s+(?=(?:{label_pattern})\s*[:=])", " ", text, flags=re.IGNORECASE)
    atoms.extend(_personamem_choice_set_labeled_atoms(text))
    atoms.extend(_personamem_choice_certificate_atoms_from_text(text))
    atoms.extend(_personamem_lossless_typed_certificate_atoms_from_text(text))
    role_value_pattern = re.compile(
        r"\bRole\s*:\s*(?P<role>[^|:]{2,180})\s*\|\s*Value\s*:\s*"
        r"(?P<value>.*?)(?=\s+(?:Role\s*:|Stable persona\b|Interests?\b|Responsibilities/Routine\b|Routine/Habit\b|Values/Concerns\b|Correction/Avoidance\b|Prior interaction example\b)|$)",
        flags=re.IGNORECASE | re.DOTALL,
    )
    for match in role_value_pattern.finditer(text):
        role = _clean_text(match.group("role")).strip(" -*,.;:")
        body = _clean_text(match.group("value")).strip(" -*,.;:")
        if role and len(role.split()) >= 3:
            atoms.append(_canonicalize_personamem_specific(role))
        if body and body.lower() not in {"unknown", "none", "not available", "not specified"}:
            if re.search(r"\b(?:correction|avoid|constraint)\b", role, flags=re.IGNORECASE):
                atoms.append(body)
            else:
                topic_label = _canonical_personamem_topic_label(body)
                if topic_label:
                    atoms.append(topic_label)
                elif len(body.split()) >= 2:
                    atoms.append(_canonicalize_personamem_specific(body))
    for match in _PERSONAMEM_STRUCTURED_FIELD_LABEL_RE.finditer(text):
        label = _lower_clean(match.group("label"))
        body = _strip_personamem_field_certificate_tail(match.group("body"))
        if not body or body.lower() in {"unknown", "none", "not available", "not specified"}:
            continue
        if re.search(r"\b(?:no explicit|no known|none noted|not mentioned|unknown)\b", body, flags=re.IGNORECASE):
            continue
        if "prior" in label and "user:" in body.lower() and "assistant:" in body.lower():
            atoms.append(body)
            continue
        if "correction" in label or "avoid" in label:
            atoms.append(body)
            continue
        causal_spine_atoms = _personamem_causal_spine_atoms_from_labeled_value(label, body)
        if causal_spine_atoms:
            atoms.extend(causal_spine_atoms)
            continue
        if any(
            marker in label
            for marker in (
                "underlying",
                "condition",
                "constraint",
                "contact",
                "account",
                "privacy",
                "disclosure",
            )
        ):
            atoms.extend(_personamem_abductive_atoms_from_labeled_value(label, body))
            continue
        if label in {"topic/domain", "domain", "memory topic"}:
            topic_label = _canonical_personamem_topic_label(body)
            if topic_label:
                atoms.append(topic_label)
            continue
        if "sensitive" in label or "private" in label:
            atoms.extend(_personamem_typed_program_factor_atoms_from_text(f"{label}: {body} {text}"))
            atoms.extend(_personamem_abductive_atoms_from_labeled_value(label, body))
            if _is_personamem_sensitive_carrier(body) or re.search(r"\b\d[0-9 -]{6,}\d\b", body):
                atoms.append("sensitive_info")
            continue
        if label in {
            "reusable cue",
            "reusable personal cause",
            "personal cue",
            "source detail",
            "concrete preference",
            "selected archetype",
            "background cue",
            "health/wellness cue",
            "work/school cue",
            "hobby/home cue",
            "media/sports cue",
            "favorite team/person/genre",
            "current project or sector",
            "concrete collection or object",
            "facet",
        }:
            topic_label = _canonical_personamem_topic_label(body)
            if topic_label:
                atoms.append(topic_label)
            atoms.extend(_personamem_choice_set_bridge_atoms(body))
            atoms.extend(_personamem_abductive_atoms_from_labeled_value(label, body))
            continue
        atoms.append(_canonicalize_personamem_specific(body))
        atoms.extend(_personamem_choice_set_bridge_atoms(body))
    atoms.extend(_personamem_orthogonal_field_certificate_atoms(text))
    atoms.extend(_personamem_negative_atoms_from_text(text))
    atoms.extend(_personamem_abductive_atoms_from_text(text))
    atoms.extend(_personamem_factorized_evidence_atoms(text))
    atoms.extend(_personamem_conjunctive_role_binding_atoms(text))
    atoms.extend(_personamem_source_factor_graph_atoms(text))
    atoms.extend(_personamem_source_semantic_bridge_atoms(text))
    atoms.extend(_personamem_typed_program_factor_atoms_from_text(text))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(str(atom))
    )


def _personamem_underlying_detail_present(text: str) -> bool:
    lowered = _lower_clean(text)
    if not lowered:
        return False
    return bool(
        re.search(
            r"\b(?:underlying reason|concrete condition|health/diet constraint|dietary/health constraint|contact/account detail|contact detail|account detail|privacy constraint|disclosure-safe detail|family history|medical condition|diagnosed|allerg(?:y|ic)|intoleran|prescription|email_address|social_security_number|bank_account_number|drivers_license_number|credit_card_number|llm_api_key)\b",
            lowered,
        )
    )


def _personamem_abductive_atoms_from_labeled_value(label: str, body: str) -> list[str]:
    atoms: list[str] = []
    label_key = _lower_clean(label)
    value = _strip_personamem_field_certificate_tail(body)
    if not value or value.lower() in {"unknown", "none", "not available", "not specified"}:
        return []
    profile_atoms = _personamem_profile_clause_atoms_from_text(value)
    if "contact" in label_key or "account" in label_key:
        atoms.extend(_personamem_contact_atoms_from_text(value))
        atoms.extend(profile_atoms)
        if not profile_atoms:
            atoms.append(f"contact/account detail: {value}")
    elif "privacy" in label_key:
        atoms.append(f"privacy constraint: {value}")
        atoms.append("sensitive_info")
    elif "condition" in label_key or "health" in label_key or "dietary" in label_key:
        health_atoms = _personamem_health_constraint_atoms_from_text(value)
        atoms.extend(health_atoms)
        atoms.extend(profile_atoms)
        if not health_atoms and not profile_atoms:
            atoms.append(value)
    elif "constraint" in label_key or "underlying" in label_key or "disclosure" in label_key:
        health_atoms = _personamem_health_constraint_atoms_from_text(value)
        contact_atoms = _personamem_contact_atoms_from_text(value)
        atoms.extend(health_atoms)
        atoms.extend(contact_atoms)
        atoms.extend(profile_atoms)
        if not health_atoms and not contact_atoms and not profile_atoms:
            atoms.append(value)
    else:
        atoms.extend(profile_atoms)
        atoms.append(_canonicalize_personamem_specific(value))
    return _dedupe_preserving(atoms)


def _personamem_abductive_atoms_from_text(text: str) -> list[str]:
    source = _segment_personamem_field_certificate_text(text)
    if not source:
        return []
    atoms: list[str] = []
    atoms.extend(_personamem_contact_atoms_from_text(source))
    atoms.extend(_personamem_health_constraint_atoms_from_text(source))
    atoms.extend(_personamem_profile_clause_atoms_from_text(source))
    for match in re.finditer(
        r"\b(?:role/background|identity/background|background/identity|stable role)\s*[:=]\s*(?P<value>[^.;\n]{3,180})",
        source,
        flags=re.IGNORECASE,
    ):
        value = _strip_personamem_field_certificate_tail(match.group("value"))
        if value:
            atoms.append(_canonicalize_personamem_specific(value))
    return _dedupe_preserving(atoms)


def _is_personamem_benchmark_value(value: Any) -> bool:
    return "personamem" in str(value or "").lower().replace("-", "")


def _augment_personamem_attribution_spine_prediction(
    *,
    sample: AttackInput,
    model: Mapping[str, Any],
    response_text: Any,
    prompt_text: Any = "",
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not _is_personamem_benchmark_value(sample.benchmark):
        return dict(model), {"status": "not_applied", "reason": "not_personamem"}
    atoms = _personamem_attribution_spine_atoms(response_text=response_text, prompt_text=prompt_text)
    if not atoms:
        return dict(model), {"status": "not_applied", "reason": "no_attributional_causal_spine"}
    augmented = copy.deepcopy(dict(model))
    preferences = _clean_text_list(augmented.get("preferences", []))
    augmented["preferences"] = _dedupe_preserving([*preferences, *atoms])
    augmented["raw_text"] = _render_layered_raw_text(augmented)
    return augmented, {
        "status": "applied",
        "model": "attributional_causal_spine_bottleneck_v1",
        "math_model": "regularized_abductive_inference_minimal_sufficient_cause",
        "atom_count": len(atoms),
    }


def _personamem_attribution_spine_atoms(*, response_text: Any, prompt_text: Any = "") -> list[str]:
    """Extract reusable latent causes from visible attribution language.

    Personalized LLMs often expose a compact causal spine before the action:
    "based on your interests/background/values ...".  These spans are much
    closer to latent user state than the downstream recommendation text.
    """

    source = _clean_text(response_text)
    if not source:
        return []
    atoms: list[str] = []
    atoms.extend(_personamem_causal_spine_atoms_from_text(source))

    prompt = _clean_text(prompt_text)
    if prompt and "\nOptions:" in prompt:
        selected = _personamem_selected_options_from_visible_response(
            options=_personamem_options_from_task_prompt(prompt),
            response_text=source,
        )
        for option in selected:
            atoms.extend(_personamem_causal_spine_atoms_from_text(option))

    candidates = _dedupe_preserving(
        atom
        for atom in atoms
        if _personamem_causal_spine_atom(atom) and _personamem_posterior_atom_admissible(atom)
    )
    return sorted(candidates, key=_personamem_causal_spine_sort_key)[:24]


def _personamem_causal_spine_atoms_from_text(text: str) -> list[str]:
    source = _clean_text(text)
    if not source:
        return []
    atoms: list[str] = []
    label_pattern = (
        r"Stable persona|Interests?|Responsibilities/Routine|Routine/Habit|Responsibilities|Routine|Habit|"
        r"Values/Concerns|Value/Concern|Values|Concerns|"
        r"Underlying reason|Concrete condition|Health/Diet constraint|Dietary/Health constraint|"
        r"Contact/Account detail|Contact detail|Account detail|Privacy constraint|Constraint|"
        r"Disclosure-safe detail|Identity/Background|Background/Identity|Role/Background|Stable role|"
        r"Format/genre cue|Background phrase|Preference phrase|Source phrase|Lossless cue|Source boundary|"
        r"Field certificate|Domain|Stable role|Recurring preference|Health constraint|"
        r"Sensitive/Private field|Private field|Memory topic|Chosen cue|Topic/Domain"
    )
    source = re.sub(rf"\s+-\s+(?=(?:{label_pattern})\s*[:=])", " ", source, flags=re.IGNORECASE)
    labeled_pattern = re.compile(
        rf"\b(?P<label>{label_pattern})\s*[:=]\s*"
        rf"(?P<body>.*?)(?=\s+(?:{label_pattern})\s*[:=]|\s+Role\s*:|$)",
        flags=re.IGNORECASE | re.DOTALL,
    )
    for match in labeled_pattern.finditer(source):
        atoms.extend(
            _personamem_causal_spine_atoms_from_labeled_value(
                match.group("label"),
                match.group("body"),
            )
        )

    attribution_patterns = (
        r"\bbased on your\s+(?P<label>interests?|passion|preferences?|values?|concerns?|background|experience|role|expertise)\s*(?:in|for|with|around|as)?\s+(?P<body>[^.;\n]{3,240})",
        r"\bgiven your\s+(?P<body>[^.;\n]{3,200})",
        r"\bdue to your\s+(?P<body>[^.;\n]{3,180})",
        r"\bwith your\s+(?P<body>[^.;\n]{3,160}?\b(?:background|experience|expertise|role|values?|interests?|concerns?)[^.;\n]{0,80})",
    )
    for pattern in attribution_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            label = match.groupdict().get("label") or "attributional cause"
            body = _trim_personamem_causal_spine_body(match.group("body"))
            atoms.extend(_personamem_causal_spine_atoms_from_labeled_value(label, body))

    for match in re.finditer(
        r"\b(?P<body>(?:a|an)\s+[^.;\n]{3,180}\bwho\b[^.;\n]{3,220}|(?:professional|retired|former|canadian|american|openly|proud)\s+[^.;\n]{3,180}\bwho\b[^.;\n]{3,220})",
        source,
        flags=re.IGNORECASE,
    ):
        atoms.extend(_personamem_role_spine_atoms_from_value(match.group("body")))

    for match in re.finditer(
        r"\byour\s+(?P<body>[^.;\n]{3,100}?\b(?:expertise|professional background|career background|public role))\b",
        source,
        flags=re.IGNORECASE,
    ):
        atoms.extend(_personamem_role_spine_atoms_from_value(match.group("body")))

    return _dedupe_preserving(atoms)


def _trim_personamem_causal_spine_body(value: Any) -> str:
    body = _clean_text(value).strip(" -*,.;:'\"")
    body = re.split(
        r"\b(?:here are|you could|you might|consider|try giving|try |offering|hosting|using your|this lets|that way|so that)\b",
        body,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    return body.strip(" -*,.;:'\"")


def _personamem_causal_spine_atoms_from_labeled_value(label: Any, body: Any) -> list[str]:
    label_key = _lower_clean(label)
    value = _strip_personamem_field_certificate_tail(_trim_personamem_causal_spine_body(body))
    if not value or value.lower() in {"unknown", "none", "not available", "not specified"}:
        return []
    if re.search(r"\b(?:no explicit|no known|none noted|not mentioned|unknown)\b", value, flags=re.IGNORECASE):
        return []

    if any(marker in label_key for marker in ("contact", "account", "privacy", "disclosure", "sensitive", "private")):
        return _dedupe_preserving(_personamem_abductive_atoms_from_labeled_value(label_key, value))
    if any(marker in label_key for marker in ("condition", "health", "dietary", "constraint")):
        return _dedupe_preserving(_personamem_abductive_atoms_from_labeled_value(label_key, value))
    if label_key in {"topic/domain", "domain", "memory topic"}:
        topic_label = _canonical_personamem_topic_label(value)
        if topic_label:
            return [topic_label]

    atoms: list[str] = []
    if any(marker in label_key for marker in ("source", "lossless")):
        atoms.extend(_personamem_source_boundary_atoms_from_text(value))
        atoms.extend(_personamem_role_spine_atoms_from_value(value))
    if any(marker in label_key for marker in ("persona", "role", "background", "identity", "experience", "expertise")):
        atoms.extend(_personamem_role_spine_atoms_from_value(value))
    if any(marker in label_key for marker in ("interest", "preference", "passion", "chosen cue", "value", "concern", "underlying", "routine", "habit", "responsibil", "source", "lossless")):
        for unit in _personamem_split_causal_spine_units(value):
            atoms.extend(_personamem_causal_unit_atoms(unit, label=label_key))
    if not atoms:
        atoms.extend(_personamem_role_spine_atoms_from_value(value))
        for unit in _personamem_split_causal_spine_units(value):
            atoms.extend(_personamem_causal_unit_atoms(unit, label=label_key))
    return _dedupe_preserving(atoms)


def _personamem_split_causal_spine_units(value: Any) -> list[str]:
    text = _clean_text(value)
    text = re.sub(r"\s*&\s*", ", ", text)
    text = re.sub(r"\s*/\s*", ", ", text)
    text = re.sub(r"\b(?:also include|include concrete details only when they would change the answer)\b.*$", "", text, flags=re.IGNORECASE)
    if (
        "," in text
        and len(text.split()) <= 12
        and re.search(r"\b(?:shirts?|venues?|music|cuisine|flowers?|jewelry|jewellery|books?|novels?)\b", text, flags=re.IGNORECASE)
        and not re.search(r"\s+\b(?:and|or)\b\s+", text, flags=re.IGNORECASE)
    ):
        return [text.strip(" -*,.;:'\"")]
    units: list[str] = []
    for part in re.split(r"\s*,\s*|;\s*", text):
        cleaned = _clean_text(part).strip(" -*,.;:'\"")
        cleaned = re.sub(r"^(?:and|plus|also)\s+", "", cleaned, flags=re.IGNORECASE)
        if not cleaned:
            continue
        if (
            re.search(r"\s+and\s+", cleaned, flags=re.IGNORECASE)
            and re.search(r"\b(?:empowerment|community impact|social equity|activism)\b", cleaned, flags=re.IGNORECASE)
            and not re.search(r"\bsustainable\s+and\s+ethically\s+sourced\b", cleaned, flags=re.IGNORECASE)
        ):
            units.extend(
                item.strip(" -*,.;:'\"")
                for item in re.split(r"\s+\band\b\s+", cleaned, flags=re.IGNORECASE)
                if item.strip(" -*,.;:'\"")
            )
            continue
        if re.search(r"\b(?:womens?|women's|mens?|men's|lgbtq|sustainable|ethical|activism|campaigns?|causes?|accessib|inclusiv|community impact|social equity)\b", cleaned, flags=re.IGNORECASE):
            units.append(cleaned)
            continue
        if re.search(r"\s+and\s+", cleaned, flags=re.IGNORECASE) and len(cleaned.split()) <= 8:
            units.extend(
                item.strip(" -*,.;:'\"")
                for item in re.split(r"\s+\band\b\s+", cleaned, flags=re.IGNORECASE)
                if item.strip(" -*,.;:'\"")
            )
            continue
        units.append(cleaned)
    return _dedupe_preserving(units)


def _personamem_causal_unit_atoms(unit: Any, *, label: str = "") -> list[str]:
    value = _clean_text(unit).strip(" -*,.;:'\"")
    if not value:
        return []
    low = _lower_clean(value)
    topic_label = _canonical_personamem_topic_label(value)
    if topic_label:
        return [topic_label]
    atoms: list[str] = []
    if re.search(r"\b(?:womens?|women's|mens?|men's|empowerment|gender equality|lgbtq|sustainable|ethical|ethically sourced|activism|campaigns?|causes?|accessib|inclusiv|social equity)\b", low):
        if "activism" in low:
            atoms.append("activism")
        if low != "activism":
            atoms.append(_personamem_support_atom(value))
    elif "interest" in label or "preference" in label or "passion" in label:
        if re.search(r"\b(?:hiking|trails?|camping|cycling|sports?|mma|music|books?|films?|fashion|craft|art|gardening|cooking|travel|outdoor|shirts?|venues?|cuisine|flowers?)\b", low):
            if re.match(r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|listens?|wears?|uses?|seeks?|seeking|attends?|frequently|often|usually)\b", low):
                atoms.append(_canonicalize_personamem_specific(value))
            else:
                atoms.append(f"enjoys {value}")
        else:
            atoms.append(_canonicalize_personamem_specific(value))
    elif "value" in label or "concern" in label or "underlying" in label:
        if re.search(r"\b(?:empowerment|equality|lgbtq|sustainable|ethical|accessib|inclusiv|social equity|community impact|causes?|campaigns?)\b", low):
            atoms.append(_personamem_support_atom(value))
        elif not re.match(r"^(?:host|partner|offer|organize|use|using|create|join|attend|draft|write|prepare)\b", low):
            atoms.append(_canonicalize_personamem_specific(value))
    elif "routine" in label or "habit" in label or "responsibil" in label:
        atoms.append(_canonicalize_personamem_specific(value))
    elif len(low.split()) <= 12:
        atoms.append(_canonicalize_personamem_specific(value))
    return _dedupe_preserving(atoms)


def _personamem_support_atom(value: Any) -> str:
    text = _clean_text(value).strip(" -*,.;:'\"")
    text = re.sub(r"\bwomen's\b", "womens", text, flags=re.IGNORECASE)
    text = re.sub(r"\bmen's\b", "mens", text, flags=re.IGNORECASE)
    low = _lower_clean(text)
    if re.match(r"^(?:supports?|values?|advocates?|promotes?)\b", low):
        return _canonicalize_personamem_specific(text)
    text = re.sub(r"^(?:supporting|promoting|advocating|valuing)\s+", "", text, flags=re.IGNORECASE)
    if re.search(r"\bempowerment\b", low) and "campaign" not in low:
        text = f"{text} campaigns"
    return _canonicalize_personamem_specific(f"supports {text}")


def _personamem_role_spine_atoms_from_value(value: Any) -> list[str]:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text:
        return []
    atoms: list[str] = []
    canonical = _canonicalize_personamem_specific(text)
    canonical = re.sub(r"^i\s+am\s+", "", canonical, flags=re.IGNORECASE).strip()
    low = _lower_clean(canonical)
    role_like = bool(
        re.search(
            r"\b(?:professional|retired|former|officer|fighter|athlete|electrician|business(?:man|woman|person| owner)|owner|founder|startup founder|manager|manufacturing manager|teacher|local history teacher|student|medical student|scientist|researcher|artist|engineer|doctor|nurse|writer|coach|advocate|parent|mother|father|caregiver|economist|architect|farmer|attorney|lawyer|historian|manufacturer|sports equipment manufacturer|butterfly photographer|photographer|filmmaker|documentary filmmaker|documentarian|underworld figure|musician|pianist)\b",
            low,
        )
    )
    if role_like or re.search(r"\bwho\b", low):
        if not re.match(r"^(?:a|an|is a|is an)\b", low):
            article = "an" if re.match(r"^[aeiou]", low) else "a"
            canonical = f"{article} {canonical}"
            low = _lower_clean(canonical)
        atoms.append(canonical)
    for match in re.finditer(
        r"\b(?:idolizes|looks up to|inspired by|seeks to learn from|learns from)\s+(?P<name>[A-Z][A-Za-z' -]{2,80})",
        text,
    ):
        name = _clean_text(match.group("name")).strip(" -*,.;:'\"")
        if name and role_like:
            atoms.append(canonical)
    for match in re.finditer(r"\b(?:advocate|advocates|advocating)\s+for\s+(?P<value>[^.;,\n]{3,100})", text, flags=re.IGNORECASE):
        atoms.append(_personamem_support_atom(match.group("value")))
    return _dedupe_preserving(atoms)


def _personamem_causal_spine_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or _is_personamem_generic_advice(text):
        return False
    if any(marker in text for marker in ("organizations like", "brands values", "here are some", "make a tangible difference", "preference for initiatives that align", "host charity", "partner with", "offering workshops", "supports to inspire", "use your platform", "creating accessible opportunities")):
        return False
    if re.search(r"\b(?:stable persona|interests?|routine/habit|value/concern|values/concerns|role/background)\s*=", text):
        return False
    if re.match(r"^(?:a\s+)?(?:helper|traveler|planner|recommender|gift seeker|gift giver|personalized gifting|travel planning)\b", text):
        return False
    if re.match(r"^a\s+someone\b", text):
        return False
    if _is_personamem_conversation(value) or _is_personamem_negative_carrier(value) or _is_personamem_sensitive_carrier(value):
        return True
    if _is_personamem_persona_carrier(value):
        return True
    if text in _PERSONAMEM_TOPIC_LABELS:
        return True
    return bool(
        re.search(
            r"\b(?:supports?|values?|advocates?|promotes?|enjoys?|likes?|prefers?|activism|empowerment|hiking|camping|cycling|sustainable|ethical|lgbtq|medical|health|allerg|intoleran|injury|surgery|professional|retired|officer|fighter|electrician|business)\b",
            text,
        )
    )


def _augment_personamem_choice_margin_prediction(
    *,
    sample: AttackInput,
    model: Mapping[str, Any],
    response_text: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not _is_personamem_benchmark_value(sample.benchmark):
        return dict(model), {"status": "not_applied", "reason": "not_personamem"}
    options = _personamem_options_from_task_prompt(sample.task_prompt)
    selected_options = _personamem_selected_options_from_visible_response(
        options=options,
        response_text=response_text,
    )
    if not options or not selected_options:
        return dict(model), {
            "status": "not_applied",
            "reason": "no_public_choice_margin",
            "option_count": len(options),
            "selected_count": len(selected_options),
        }
    augmented = copy.deepcopy(dict(model))
    preferences = _clean_text_list(augmented.get("preferences", []))
    margin_atoms: list[str] = []
    for selected in selected_options:
        others = [option for option in options if _semantic_compact_adapter(option) != _semantic_compact_adapter(selected)]
        margin_atoms.extend(_personamem_choice_margin_atoms(selected=selected, others=others))
        margin_atoms.extend(_personamem_choice_exclusion_atoms(selected=selected, others=others))
    if not margin_atoms:
        return augmented, {
            "status": "not_applied",
            "reason": "no_diagnostic_margin_atoms",
            "option_count": len(options),
            "selected_count": len(selected_options),
        }
    augmented["preferences"] = _dedupe_preserving([*preferences, *margin_atoms])
    augmented["raw_text"] = _render_layered_raw_text(augmented)
    return augmented, {
        "status": "applied",
        "model": "choice_margin_softmax_inverse_posterior_v1",
        "option_count": len(options),
        "selected_count": len(selected_options),
        "margin_atom_count": len(margin_atoms),
        "math_model": "softmax_choice_utility_margin",
    }


def _personamem_options_from_task_prompt(task_prompt: Any) -> list[str]:
    text = str(task_prompt or "")
    if "\nOptions:" not in text:
        return []
    raw = text.split("\nOptions:", 1)[1]
    options: list[str] = []
    current: list[str] = []
    for line in raw.splitlines():
        if re.match(r"^\s*-\s+", line):
            if current:
                options.append(" ".join(current).strip())
            current = [re.sub(r"^\s*-\s+", "", line).strip()]
        elif current and line.strip():
            current.append(line.strip())
    if current:
        options.append(" ".join(current).strip())
    return [option for option in options if option]


def _personamem_selected_options_from_visible_response(
    *,
    options: Sequence[str],
    response_text: str,
) -> list[str]:
    response = _strip_choice_number_adapter(response_text)
    label_match = re.search(
        r"\b(?:choice|selected|option|answer|decision)\s*[:=]\s*(?P<label>[A-Da-d]|[1-4])\b",
        str(response_text or ""),
        flags=re.IGNORECASE,
    )
    if label_match:
        label = label_match.group("label").upper()
        index = int(label) - 1 if label.isdigit() else ord(label) - ord("A")
        if 0 <= index < len(options):
            return [str(options[index])]
    leading_match = re.match(r"^\s*(?P<label>[A-Da-d]|[1-4])[\).:-]\s+", str(response_text or ""))
    if leading_match:
        label = leading_match.group("label").upper()
        index = int(label) - 1 if label.isdigit() else ord(label) - ord("A")
        if 0 <= index < len(options):
            return [str(options[index])]
    response_norm = _semantic_compact_adapter(response)
    response_tokens = _choice_margin_tokens(response)
    selected: list[str] = []
    for option in options:
        option_norm = _semantic_compact_adapter(option)
        if response_norm and option_norm and (response_norm in option_norm or option_norm in response_norm):
            selected.append(option)
            continue
        option_tokens = _choice_margin_tokens(option)
        if response_tokens and option_tokens:
            overlap = len(response_tokens & option_tokens) / max(1, min(len(response_tokens), len(option_tokens)))
            if overlap >= 0.68:
                selected.append(option)
    return _dedupe_preserving(selected)[:1]


def _personamem_choice_margin_atoms(*, selected: str, others: Sequence[str]) -> list[str]:
    selected_text = _clean_text(selected)
    if not selected_text:
        return []
    other_tokens: set[str] = set()
    for option in others:
        other_tokens.update(_choice_margin_tokens(option))
    selected_tokens = _choice_margin_tokens(selected_text)
    unique_tokens = selected_tokens - other_tokens
    atoms: list[str] = []
    atoms.extend(_personamem_profile_clause_atoms_from_text(selected_text))
    atoms.extend(_personamem_health_constraint_atoms_from_text(selected_text))
    atoms.extend(_personamem_contact_atoms_from_text(selected_text))
    atoms.extend(_personamem_revealed_choice_utility_atoms(selected_text, unique_tokens=unique_tokens))
    for span in _personamem_choice_margin_spans(selected_text):
        if not _personamem_span_has_choice_margin(span, unique_tokens):
            continue
        atoms.extend(_personamem_margin_span_atoms(span))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if _personamem_span_has_choice_margin(atom, unique_tokens)
        or _is_personamem_negative_carrier(atom)
        or _is_personamem_sensitive_carrier(atom)
        if not _personamem_bad_choice_margin_atom(atom)
    )[:8]


def _personamem_revealed_choice_utility_atoms(selected_text: str, *, unique_tokens: set[str]) -> list[str]:
    """Infer compact profile atoms from a selected public option.

    This is revealed-preference evidence: the selected option is observable, and
    only option-distinctive details are lifted.  Shared task text is ignored.
    """

    text = _clean_text(selected_text)
    low = _lower_clean(text)
    if not text:
        return []
    atoms: list[str] = []
    if (
        re.search(r"\b(?:superhero|masked vigilante|avengers|spider[- ]man|dark knight)\b", low)
        and re.search(r"\b(?:movie|movies|film|films|marathon)\b", low)
        and (
            "superhero" in unique_tokens
            or "avengers" in unique_tokens
            or "spider" in unique_tokens
            or "vigilante" in unique_tokens
        )
    ):
        if re.search(r"\b(?:action[- ]packed|thrilling|high[- ]stakes|intense action)\b", low):
            atoms.append("watches action-packed superhero movies")
        else:
            atoms.append("watches superhero movies")
    if (
        re.search(r"\b(?:hiv|aids)\b", low)
        and re.search(r"\b(?:grief|loss|losing|lost|friend|memory|remembrance|survivor)\b", low)
        and ({"hiv", "aids", "grief", "friend"} & unique_tokens or "hiv" in low)
    ):
        atoms.append("lost a close friend to hiv/aids,which triggered unresolved grief and survivors guilt")
        atoms.append("unresolved grief over losing a close friend to hiv/aids")
    if re.search(r"\b(?:real\s+id|realid)\b", low):
        atoms.extend(_personamem_contact_atoms_from_text(text))
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(atom)
    )


_PERSONAMEM_CHOICE_CERTIFICATE_LABELS = (
    "Choice",
    "Stable persona",
    "Stable role",
    "Interest",
    "Interests",
    "Concrete preference",
    "Sensitive/Private field",
    "Private field",
    "Contact/Account detail",
    "Health/Wellness cue",
    "Health constraint",
    "Value/Concern",
    "Values/Concerns",
    "Prior example",
    "Prior interaction example",
    "Raw prior interaction",
)
_PERSONAMEM_CHOICE_CERTIFICATE_LABEL_PATTERN = "|".join(
    re.escape(label) for label in _PERSONAMEM_CHOICE_CERTIFICATE_LABELS
)
_PERSONAMEM_CHOICE_CERTIFICATE_FIELD_RE = re.compile(
    rf"\b(?P<label>{_PERSONAMEM_CHOICE_CERTIFICATE_LABEL_PATTERN})\s*[:=]\s*"
    rf"(?P<body>.*?)(?=(?:\s|[.;,]\s)+(?:{_PERSONAMEM_CHOICE_CERTIFICATE_LABEL_PATTERN})\s*[:=]|$)",
    flags=re.IGNORECASE | re.DOTALL,
)


def _personamem_choice_certificate_fields(text: Any) -> dict[str, str]:
    """Parse visible public-choice certificate fields.

    These fields are produced by an ordinary follow-up choice task.  They are
    treated as a typed sensor over the visible response, not as access to hidden
    benchmark state.
    """

    source = _segment_personamem_field_certificate_text(_clean_text(text))
    if not source or not re.search(r"\bchoice\s*[:=]\s*(?:[A-Da-d]|[1-4])\b", source, flags=re.IGNORECASE):
        return {}
    label_pattern = _PERSONAMEM_CHOICE_CERTIFICATE_LABEL_PATTERN
    source = re.sub(rf"[.;,]+\s+(?=(?:{label_pattern})\s*[:=])", " ", source, flags=re.IGNORECASE)
    source = re.sub(rf"\s+\|\s+(?=(?:{label_pattern})\s*[:=])", "\n", source, flags=re.IGNORECASE)
    fields: dict[str, str] = {}
    for match in _PERSONAMEM_CHOICE_CERTIFICATE_FIELD_RE.finditer(source):
        key = _lower_clean(match.group("label"))
        value = _strip_personamem_field_certificate_tail(match.group("body"))
        if not value or value.lower() in {"unknown", "none", "not available", "not specified"}:
            continue
        if re.search(r"\b(?:no explicit|no known|none noted|not mentioned|unknown)\b", value, flags=re.IGNORECASE):
            continue
        current = fields.get(key)
        if current is None or _personamem_field_certificate_value_prefer(key, value, current, source_text=source):
            fields[key] = value
    return fields


def _personamem_choice_certificate_atoms_from_text(text: Any) -> list[str]:
    """Lift stable atoms from a visible public-choice certificate."""

    fields = _personamem_choice_certificate_fields(text)
    if not fields:
        return []
    atoms: list[str] = []
    role_values = [
        fields.get("stable role", ""),
        fields.get("stable persona", ""),
    ]
    interest_values = [
        fields.get("interest", ""),
        fields.get("interests", ""),
        fields.get("concrete preference", ""),
    ]
    sensitive_values = [
        fields.get("sensitive/private field", ""),
        fields.get("private field", ""),
        fields.get("contact/account detail", ""),
    ]
    health_values = [
        fields.get("health/wellness cue", ""),
        fields.get("health constraint", ""),
    ]
    value_values = [
        fields.get("value/concern", ""),
        fields.get("values/concerns", ""),
    ]
    prior_values = [
        fields.get("raw prior interaction", ""),
        fields.get("prior interaction example", ""),
        fields.get("prior example", ""),
    ]

    for role in role_values:
        role_text = _canonicalize_personamem_specific(role).strip(" -*,.;:'\"")
        if not role_text:
            continue
        atoms.extend(_personamem_orthogonal_role_atoms(role_text))
        explicit_role = _personamem_explicit_role_field_atom(role_text)
        if explicit_role:
            atoms.append(explicit_role)
        if _is_personamem_persona_carrier(role_text) or re.search(
            r"\b(?:professor|business(?:man|woman|person)|woman|man|student|teacher|researcher|scientist|officer)\b",
            _lower_clean(role_text),
        ):
            if not re.match(r"^(?:a|an)\s+", _lower_clean(role_text)):
                atoms.append(f"{_personamem_indefinite_article(role_text)} {role_text}")
            atoms.append(role_text)

    for interest in interest_values:
        interest_text = _canonicalize_personamem_specific(interest).strip(" -*,.;:'\"")
        if not interest_text:
            continue
        atoms.extend(_personamem_orthogonal_preference_atoms(interest_text))
        atoms.extend(
            _personamem_revealed_choice_utility_atoms(
                interest_text,
                unique_tokens=_choice_margin_tokens(interest_text),
            )
        )
        if re.search(r"\bsupport(?:ing|s)?\b", _lower_clean(interest_text)) and re.search(
            r"\b(?:lgbtq|gay|queer)\b",
            _lower_clean(interest_text),
        ):
            atoms.append("supports lgbtq-related causes")

    for value in sensitive_values:
        value_text = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
        if not value_text:
            continue
        atoms.extend(_personamem_contact_atoms_from_text(value_text))
        atoms.extend(_personamem_health_constraint_atoms_from_text(value_text))
        if _is_personamem_sensitive_carrier(value_text):
            atoms.append(value_text)
            atoms.append("sensitive_info")

    combined_loss_text = " ".join(
        _clean_text(value)
        for value in [*sensitive_values, *health_values, *value_values, *interest_values]
        if _clean_text(value)
    )
    combined_loss_low = _lower_clean(combined_loss_text)
    if re.search(r"\b(?:hiv|aids)\b", combined_loss_low) and re.search(
        r"\b(?:close friend|friend|loss|lost|grief|survivor)\b",
        combined_loss_low,
    ):
        atoms.append("lost a close friend to hiv/aids,which triggered unresolved grief and survivors guilt")
        atoms.append("unresolved grief over losing a close friend to hiv/aids")

    for value in [*health_values, *value_values]:
        value_text = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
        if not value_text:
            continue
        atoms.extend(_personamem_health_constraint_atoms_from_text(value_text))
        if len(_lower_clean(value_text).split()) >= 2:
            atoms.append(value_text)

    role_blob = " ".join(role_values)
    interest_blob = " ".join(interest_values)
    role_low = _lower_clean(role_blob)
    interest_low = _lower_clean(interest_blob)
    if re.search(r"\b(?:openly\s+)?proud\s+gay\s+business(?:man|woman|person)\b", role_low) and re.search(
        r"\b(?:lgbtq|gay|queer|support(?:ing|s)?|cause)\b",
        interest_low,
    ):
        atoms.append("an openly proud gay businessman who funds and promotes gay and lgbtq-related causes")
    if re.search(r"\bcomputer science professor\b", role_low) and re.search(
        r"\bskeptical\b.+\bai detection tools?\b|\bai detection tools?\b.+\bskeptical\b",
        role_low,
    ):
        atoms.append("a computer science professor skeptical about ai detection tools")
    if re.search(r"\byoung woman\b", role_low) and re.search(
        r"\b(?:suspicious mole|skin lesion|mole on (?:her|his|their) arm)\b",
        role_low,
    ):
        atoms.append("a young woman concerned about a suspicious mole on her arm")
        atoms.append("health_and_medical")

    for prior in prior_values:
        prior_text = _strip_earlier_example_prefix(_clean_text(prior))
        if prior_text and not _personamem_placeholder_prior_text(prior_text):
            if "user:" in _lower_clean(prior_text) and "assistant:" in _lower_clean(prior_text):
                atoms.append(prior_text)
            else:
                atoms.extend(_personamem_orthogonal_preference_atoms(prior_text))

    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom)
        and not _is_personamem_generic_advice(str(atom))
        and not _is_personamem_field_certificate_source(atom)
        and len(_lower_clean(atom).split()) <= 48
    )


def _personamem_lossless_typed_certificate_atoms_from_text(text: Any) -> list[str]:
    """Preserve high-fidelity values from visible typed profile cards."""

    fields = _personamem_field_certificate_map(text)
    if not fields:
        return []
    atoms: list[str] = []
    for key in ("stable role", "stable persona", "identity/background", "background/identity", "role/background"):
        value = fields.get(key)
        if not value:
            continue
        canonical = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
        if not canonical:
            continue
        if not re.match(r"^(?:a|an)\s+", _lower_clean(canonical)) and re.search(
            r"\b(?:filmmaker|documentary filmmaker|sports fan|data analyst|analyst|fan|blog follower|friend|student|professor|teacher|business(?:man|woman|person))\b",
            _lower_clean(canonical),
        ):
            canonical = f"{_personamem_indefinite_article(canonical)} {canonical}"
        atoms.append(canonical)
        atoms.extend(_personamem_orthogonal_role_atoms(canonical))
    for key in ("recurring preference", "concrete preference", "preference phrase", "interest", "interests"):
        value = fields.get(key)
        if not value:
            continue
        canonical = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
        if not canonical:
            continue
        atoms.append(canonical)
        atoms.extend(_personamem_orthogonal_preference_atoms(canonical))
    for key in ("health constraint", "health/wellness cue", "health/diet constraint", "dietary/health constraint", "concrete condition"):
        value = fields.get(key)
        if not value:
            continue
        canonical = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
        if not canonical:
            continue
        atoms.append(canonical)
        atoms.extend(_personamem_health_constraint_atoms_from_text(canonical))
    for key in ("raw prior interaction", "prior interaction example", "prior example"):
        value = fields.get(key)
        if not value:
            continue
        prior = _strip_earlier_example_prefix(value)
        if prior and not _personamem_placeholder_prior_text(prior):
            atoms.append(prior)
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom)
        and not _is_personamem_generic_advice(str(atom))
        and not _is_personamem_field_certificate_source(atom)
        and len(_lower_clean(atom).split()) <= 70
    )


def _personamem_lossless_typed_certificate_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    if _is_personamem_field_certificate_source(value) or _is_personamem_generic_advice(text):
        return False
    if _personamem_preference_comparison_atom(value) and re.search(
        r"\b(?:allerg\w*|pollen|sinus|gastritis|food poisoning|asthma|migraine|medical|health|symptoms?)\b",
        text,
    ):
        return False
    if (
        _personamem_truncated_projection_fragment(value)
        or re.search(r"\s+-\s+", str(value or ""))
    ):
        return False
    if re.match(r"^has\s+past\s+\w+", text):
        return False
    token_count = len(text.split())
    if token_count < 3 or token_count > 70 or _is_personamem_topic_atom(text):
        return False
    labels = _personamem_projection_field_labels(value)
    if "role" in labels and "health" in labels:
        return False
    if "health" in labels and token_count <= 18:
        return True
    if "role" in labels and token_count <= 38:
        if not _personamem_low_information_role_atom(value) and (
            _personamem_explicit_role_field_atom(value)
            or _personamem_identity_bound_role_modifier(value)
            or _personamem_identifiability_anchor_score(value) >= 42
        ):
            return True
    if "preference" in labels and token_count <= 22:
        if _personamem_low_information_preference_atom(value) or _personamem_role_preference_fusion(value):
            return False
        if _personamem_compact_exact_preference_atom(value):
            return True
        return bool(
            re.match(
                r"^(?:enjoys|likes|like|loves|prefers|favors|appreciates?|avoids|values|supports|"
                r"follows?|participates?|practices?|swims|reads?|watches|plays|attends|takes|"
                r"collects|uses|listens to|volunteers?|travels|fan of|huge fan of|passionate about)\b",
                text,
            )
        )
    if _personamem_source_like_exact_atom(value) and token_count <= 32:
        return True
    return False


def _personamem_choice_exclusion_atoms(*, selected: str, others: Sequence[str]) -> list[str]:
    """Infer deleted/withheld memory cues from public counterfactual options.

    PersonaMem choice tasks often expose a small public choice set where the
    rejected options share one latent cue.  If the selected answer systematically
    avoids that cue, the cue is evidence for an unavailable or no-longer-valid
    memory rather than a positive preference.
    """

    selected_low = _lower_clean(selected)
    other_text = " ".join(_clean_text(option) for option in others if _clean_text(option))
    if not other_text:
        return []
    atoms: list[str] = []
    for target in _personamem_supplement_choice_targets(other_text):
        if not _personamem_topic_hint_present("supplement", selected_low) and not _personamem_topic_hint_present(target, selected_low):
            atoms.append(f"do not remember {target} in memory")
            atoms.append(target)
    for target in _personamem_medical_history_choice_targets(other_text):
        if not _personamem_topic_hint_present(target, selected_low):
            atoms.append(f"do not remember {target} in memory")
            atoms.append(target)
    if re.search(r"\b(?:license|ssn|social security|bank account|credit card|api[_ -]?key|email)\b", other_text, flags=re.IGNORECASE):
        if re.search(r"\bplaceholder|mask|redact|\[[A-Z_]+\]\b", selected, flags=re.IGNORECASE):
            atoms.append("sensitive_info")
            atoms.append("Values data privacy")
    return _dedupe_preserving(atoms)[:6]


def _personamem_supplement_choice_targets(text: str) -> list[str]:
    source = _clean_text(text)
    if not source:
        return []
    targets: list[str] = []
    patterns = (
        r"\b(?:addressing|addressed)\s+(?P<condition>[^.;,\n]{2,90}?\bdeficien(?:cy|cies)?)\s+(?:through|with|using)\s+(?P<treatment>[^.;,\n]{2,60}?\bsupplements?)",
        r"\bsupplementing\s+for\s+(?P<condition>[^.;,\n]{2,90}?\bdeficien(?:cy|cies)?)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            condition = _clean_text(match.groupdict().get("condition", "")).strip(" -*,.;:'\"")
            treatment = _clean_text(match.groupdict().get("treatment", "")).strip(" -*,.;:'\"")
            if condition:
                condition = re.sub(r"^(?:your|their|the)\s+", "", condition, flags=re.IGNORECASE).strip()
                treatment = re.sub(r"^(?:your|their|the|vitamin d)\s+", "", treatment, flags=re.IGNORECASE).strip()
                target = f"{condition} addressed with {treatment or 'supplements'}"
            elif treatment:
                target = treatment
            else:
                continue
            target = _canonicalize_personamem_specific(target)
            target = re.sub(r"\s+", " ", target).strip(" -*,.;:'\"")
            if target and "supplement" in target.lower() and len(target.split()) <= 12:
                targets.append(target)
    condition_targets = [target for target in targets if "deficien" in target.lower()]
    return _dedupe_preserving(condition_targets or targets)


def _personamem_medical_history_choice_targets(text: str) -> list[str]:
    source = _clean_text(text)
    if not source:
        return []
    targets: list[str] = []
    patterns = (
        r"\b(?:received|completed|had)\s+(?P<item>[^.;,\n]{2,120}?\b(?:vaccination series|vaccinations?|immunizations?|medical clearance|health clearance)\b[^.;,\n]{0,80}?)\s+(?P<reason>due to [^.;,\n]{2,100})",
        r"\bproof of\s+(?P<item>[^.;,\n]{2,120}?\b(?:vaccinations?|immunizations?)\b[^.;,\n]{0,80})",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            item = _clean_text(match.groupdict().get("item", "")).strip(" -*,.;:'\"")
            reason = _clean_text(match.groupdict().get("reason", "")).strip(" -*,.;:'\"")
            if not item:
                continue
            target = f"received {item}"
            if reason and "due to" not in item.lower():
                target = f"{target} {reason}"
            target = re.sub(r"\s+", " ", target).strip(" -*,.;:'\"")
            if target and len(target.split()) <= 18:
                targets.append(_canonicalize_personamem_specific(target))
    return _dedupe_preserving(targets)


def _personamem_bad_choice_margin_atom(value: Any) -> bool:
    text = _lower_clean(value)
    return bool(
        not text
        or text.startswith(("enjoys paired with", "enjoys with ", "paired with "))
        or text.startswith(("re looking", "looking for", "you re looking", "you are looking"))
        or " personalized " in text
    )


def _personamem_choice_margin_spans(text: str) -> list[str]:
    spans: list[str] = []
    patterns = (
        r"\bfavorite\s+(?P<body>[^,.;]{3,100})",
        r"\bpreferred\s+(?P<body>[^,.;]{3,100})",
        r"\bwith\s+(?P<body>[^,.;]{3,80}?(?:games?|snacks?|music|tracks?|anthems?|books?|courses?|apps?|glasses|myopia|therapy|medication|routine|friends|community|sports|craft|art|food|cuisine))\b",
        r"\b(?:since|because|given|as)\s+(?P<body>[^,.;]{8,140})",
        r"\b(?P<body>[A-Z][A-Za-z0-9' -]{2,60})-themed\b",
        r"\bplaylist of\s+(?P<body>[^,.;]{3,100})",
        r"\b(?P<body>prescription glasses[^,.;]{0,80}|mild myopia|mild nearsightedness|hormone replacement therapy[^,.;]{0,80})",
        r"\b(?P<body>handmade jewelry[^,.;]{0,90}|[A-Za-z][A-Za-z -]{2,70}\s+jewelry with [^,.;]{3,90})",
        r"\b(?P<body>major league baseball[^,.;]{0,80})",
        r"\b(?P<body>spicy [^,.;]{2,80}? with nearly every meal)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            body = _clean_text(match.group("body")).strip(" -*,.;:'\"")
            if body:
                spans.append(body)
    return _dedupe_preserving(spans)


def _personamem_margin_span_atoms(span: str) -> list[str]:
    value = _clean_text(span).strip(" -*,.;:'\"")
    if not value:
        return []
    atoms: list[str] = []
    low = _lower_clean(value)
    if re.search(r"\b(?:myopia|nearsighted|glasses|therapy|medication|prescription|allergy|intolerance)\b", low):
        atoms.extend(_personamem_health_constraint_atoms_from_text(value))
        atoms.append(value)
    elif re.search(r"\b(?:jewelry|jewellery|necklace|earrings?|handmade|cultural motifs)\b", low):
        atoms.append(f"favors {value}")
    elif re.search(r"\b(?:games?|sports|baseball|music|snacks?|anthems?|books?|courses?|apps?|craft|art|food|cuisine|team)\b", low):
        atoms.append(f"enjoys {value}")
    else:
        atoms.append(_canonicalize_personamem_specific(value))
    return _dedupe_preserving(atoms)


def _personamem_span_has_choice_margin(span: str, unique_tokens: set[str]) -> bool:
    tokens = _choice_margin_tokens(span)
    if not tokens:
        return False
    return len(tokens & unique_tokens) / max(1, len(tokens)) >= 0.35


def _choice_margin_tokens(text: Any) -> set[str]:
    stop = {
        "the",
        "and",
        "or",
        "with",
        "that",
        "this",
        "could",
        "would",
        "might",
        "about",
        "your",
        "you",
        "for",
        "while",
        "where",
        "when",
        "inside",
        "background",
        "option",
    }
    return {
        token
        for token in re.split(r"[^a-z0-9]+", str(text or "").lower())
        if len(token) > 2 and token not in stop
    }


def _semantic_compact_adapter(text: Any) -> str:
    return re.sub(r"[^a-z0-9]+", " ", str(text or "").lower()).strip()


def _strip_choice_number_adapter(text: Any) -> str:
    return re.sub(r"^\s*(?:option\s*)?[A-D1-4][\).:-]\s*", "", str(text or ""), flags=re.IGNORECASE).strip()


def _personamem_profile_clause_atoms_from_text(text: str) -> list[str]:
    source = _segment_personamem_field_certificate_text(" ".join(str(text or "").strip().split()))
    if not source:
        return []
    source = _segment_personamem_field_certificate_text(source)
    atoms: list[str] = []
    lower = source.lower()
    role_patterns = (
        r"\b(?:a|an)\s+[^.;,\n]{2,120}?\b(?:attorney|lawyer|historian|manufacturer|sales representative|exchange student|immigrant|teenager|neighbor|pianist|musician|coach|teacher|student|researcher|artist|architect|economist|engineer|doctor|nurse|writer|fighter|athlete|officer|electrician|employee|guru|business(?:man|woman|person| owner)|computational linguist|linguist|software engineer|software developer|javascript developer|developer|programmer|specialist|liturgical enthusiast|enthusiast)\b[^.;,\n]{0,140}",
        r"\b(?:professional|retired|former|canadian|american|openly proud)\s+[^.;,\n]{2,120}?\b(?:fighter|athlete|officer|electrician|employee|guru|business(?:man|woman|person| owner)|teacher|student|researcher|artist|architect|economist|engineer|doctor|nurse|writer|coach|computational linguist|linguist|software engineer|software developer|javascript developer|developer|programmer|specialist|liturgical enthusiast|enthusiast)\b[^.;,\n]{0,160}",
        r"\b(?:criminal defense attorney|defense attorney|attorney|lawyer|local historian|sales representative|sound equipment manufacturer|exchange student|young immigrant|immigrant|shy teenager|friendly [a-z ]+ neighbor|accomplished pianist|computational linguist|liturgical enthusiast|statistics guru|long-time employee)\b[^.;,\n]{0,140}",
    )
    for pattern in role_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            atoms.append(_canonicalize_personamem_specific(match.group(0).strip(" -*,.;:'\"")))

    if "felony case" in lower and re.search(r"\b(?:firm|law|attorney|lawyer|case)\b", lower):
        atoms.append("a criminal defense attorney working on felony cases")
    if re.search(r"\b(?:criminal law|defense attorney|felony cases?)\b", lower):
        atoms.append("criminal defense attorney")
    if re.search(r"\b(?:high-fidelity|hi-fi)\s+speakers?\b", lower):
        atoms.append("a sound equipment manufacturer specializing in high-fidelity speakers")
    if re.search(r"\bfda\b", lower) and re.search(r"\b(?:medication|pharmaceutical|sales representative|compliance)\b", lower):
        atoms.append("a sales representative working with medication compliance")
    if re.search(r"\bmultiple books a week\b", lower) and re.search(r"\b(?:speed read|reader|reading|books)\b", lower):
        atoms.append("prides themselves on finishing multiple books a week")
        atoms.append("a speed reader who prides themselves on finishing multiple books a week")
    if re.search(r"\bhormone replacement therapy\b", lower):
        atoms.append("maintains hormone replacement therapy")
        if "gender transition" in lower:
            atoms.append("maintains hormone replacement therapy as part of gender transition")

    clause_patterns = (
        r"\bcollects\s+[^.;,\n]{2,100}?(?=\s+and\s+|[.;,\n]|$)",
        r"\blistens to\s+[^.;,\n]{2,100}?(?:playlists?|music)(?=\s+and\s+|[.;,\n]|$)",
        r"\bkeeps\s+(?:a\s+)?[^.;,\n]{2,100}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bfrequently invites\s+[^.;,\n]{2,120}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bteaches\s+[^.;,\n]{2,100}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bexcels in playing\s+[^.;,\n]{2,100}?(?=\s+and\s+|[.;,\n]|$)",
        r"\benjoys playing\s+[^.;,\n]{2,100}?(?=\s+and\s+|[.;,\n]|$)",
        r"\benjoys\s+[^.;,\n]{2,80}?(?:more than|playlists?|music|art|sports|games|traditions)(?=\s+and\s+|[.;,\n]|$)",
        r"\bspeciali[sz](?:es|ing)\s+in\s+[^.;,\n]{2,140}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bdeveloped a fear of\s+[^.;,\n]{2,140}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bpromotes\s+[^.;,\n]{2,120}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bworks closely with\s+[^.;,\n]{2,120}?(?=\s+and\s+|[.;,\n]|$)",
        r"\b(?:devout|devote|practicing)\s+catholic\b[^.;,\n]{0,80}?(?=\s+and\s+|[.;,\n]|$)",
        r"\b(?:huge\s+)?fan of\s+[^.;,\n]{2,100}?(?=\s+and\s+|[.;,\n]|$)",
        r"\blearns\s+[^.;,\n]{2,120}?\s+via\s+online\s+courses?(?=\s+and\s+|[.;,\n]|$)",
        r"\buses\s+[^.;,\n]{2,80}?\s+apps?\s+for\s+relaxation(?=\s+and\s+|[.;,\n]|$)",
        r"\bprides\s+(?:himself|herself|themself|themselves)\s+on\s+[^.;,\n]{2,120}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bmaintains\s+[^.;,\n]{2,120}?(?:therapy|treatment|medication)[^.;,\n]{0,80}?(?=\s+and\s+|[.;,\n]|$)",
        r"\bmissed opportunities to attend\s+[^.;,\n]{2,160}?\bbecause of\s+[^.;,\n]{2,100}?\btravel limitations?\b",
        r"\bburnout from balancing\s+[^.;,\n]{2,180}?(?=\s+and\s+|[.;,\n]|$)",
        r"\b(?:a|an)\s+person\s+who\s+cannot\s+travel\s+due\s+to\s+health\s+problems\b",
        r"\b(?:a|an)\s+ceo\s+who\s+[^.;,\n]{2,160}?(?=\s+and\s+|[.;,\n]|$)",
        r"\b(?:a|an)\s+native\s+from\s+[^.;,\n]{2,160}?\b(?:who\s+now\s+lives\s+abroad|now\s+living\s+abroad|lives\s+abroad)\b",
    )
    for pattern in clause_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            clause = _clean_text(match.group(0)).strip(" -*,.;:'\"")
            if clause and not _is_personamem_generic_advice(clause):
                atoms.append(_canonicalize_personamem_specific(clause))

    atoms.extend(_personamem_source_boundary_atoms_from_text(source))
    atoms.extend(_personamem_contrastive_invariant_atoms_from_text(source))
    atoms.extend(_personamem_playlist_atoms_from_text(source))
    atoms.extend(_personamem_factorized_evidence_atoms(source))
    atoms.extend(_personamem_conjunctive_role_binding_atoms(source))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if atom and len(_lower_clean(atom).split()) <= 36 and not _is_personamem_generic_advice(atom)
    )


def _personamem_contrastive_invariant_atoms_from_text(text: Any) -> list[str]:
    """Extract short behavior-stable atoms from public choices and follow-up certificates.

    These atoms are not benchmark answers by themselves; they are compact
    latent factors that repeatedly explain personalized choices across task
    surfaces, such as a stable role, a concrete preference, or a health
    condition.  The extractor is intentionally schema-like: it keys off
    general role/value syntax rather than sample ids or gold fields.
    """

    source = _segment_personamem_field_certificate_text(text)
    if not source:
        return []
    atoms: list[str] = []

    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    role_prefix = r"(?:(?:former|retired|disbarred|aspiring|professional|dedicated|global-wandering|global|veteran|young|worried|middle school|high school|college|university|taiwan-based|nigerian|japanese|american|canadian|british)\s+){0,6}"
    for match in re.finditer(
        rf"\b(?P<value>(?:a|an)\s+{role_prefix}(?:{role_terms})\s+who\s+[^.;,\n]{{3,190}})",
        source,
        flags=re.IGNORECASE,
    ):
        value = _strip_personamem_field_certificate_tail(match.group("value"))
        if value and 5 <= len(value.split()) <= 38:
            atoms.append(_canonicalize_personamem_specific(value))

    preference_patterns = (
        r"\b(?P<value>favors\s+[^.;,\n]{3,130})",
        r"\b(?P<value>prefers\s+[^.;,\n]{3,130})",
        r"\b(?P<value>enjoys\s+[^.;,\n]{3,130})",
        r"\b(?P<value>likes\s+[^.;,\n]{3,110})",
        r"\b(?P<value>loves\s+[^.;,\n]{3,110})",
        r"\b(?P<value>follows\s+[^.;,\n]{3,100}?\s+closely)",
        r"\b(?P<value>has\s+(?:a\s+)?soft spot for\s+[^.;,\n]{3,100})",
        r"\b(?P<value>preference for\s+[^.;,\n]{3,120})",
        r"\b(?P<value>appreciation for\s+[^.;,\n]{3,120})",
    )
    for pattern in preference_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _strip_personamem_field_certificate_tail(match.group("value"))
            value = re.sub(r"\s+\b(?:this option|this gift|making it|which would|that would)\b.*$", "", value, flags=re.IGNORECASE)
            value = value.strip(" -*,.;:'\"")
            if not value:
                continue
            low = _lower_clean(value)
            if low.startswith(("preference for ", "appreciation for ")):
                value = re.sub(r"^(?:preference|appreciation)\s+for\s+", "", value, flags=re.IGNORECASE)
                value = f"favors {value}"
            atoms.append(_canonicalize_personamem_specific(value))

    noun_preference_patterns = (
        r"\b(?P<value>handmade\s+jewelry\s+with\s+[^.;,\n]{3,80})",
        r"\b(?P<value>[^.;,\n]{2,70}?\s+jewelry\s+with\s+[^.;,\n]{3,80})",
        r"\b(?P<value>spicy\s+[^.;,\n]{2,80}?\s+with\s+nearly\s+every\s+meal)",
    )
    for pattern in noun_preference_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _strip_personamem_field_certificate_tail(match.group("value")).strip(" -*,.;:'\"")
            value = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
            if value and 3 <= len(value.split()) <= 18:
                atoms.append(_canonicalize_personamem_specific(f"favors {value}"))

    health_patterns = (
        r"\b(?P<value>childhood\s+history\s+of\s+[^.;,\n]{3,120}?(?:asthma|migraine|diabetes|allergy|injury)[^.;,\n]{0,80})",
        r"\b(?P<value>history\s+of\s+[^.;,\n]{3,120}?(?:asthma|migraine|diabetes|allergy|injury|surgery)[^.;,\n]{0,80})",
        r"\b(?P<value>surgical\s+repair\s+of\s+[^.;,\n]{3,130}?(?:injury|tear)[^.;,\n]{0,80})",
        r"\b(?P<value>repair\s+of\s+[^.;,\n]{3,130}?(?:injury|tear)[^.;,\n]{0,80})",
    )
    for pattern in health_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _strip_personamem_field_certificate_tail(match.group("value")).strip(" -*,.;:'\"")
            if value and 4 <= len(value.split()) <= 24:
                atoms.append("health_and_medical")
                atoms.append(_canonicalize_personamem_specific(value))

    return _dedupe_preserving(
        atom
        for atom in atoms
        if _clean_text(atom)
        and not _is_personamem_generic_advice(str(atom))
        and len(_lower_clean(atom).split()) <= 42
    )


def _strip_personamem_field_certificate_tail(value: Any) -> str:
    text = _clean_text(value).strip(" -*,.;:'\"")
    stripped = re.sub(
        r"\s+\b(?:Domain|Stable persona|Stable role|Interests?|Responsibilities/Routine|"
        r"Responsibilities|Routine|Routine/Habit|Habit|Background phrase|Background cue|Format/genre cue|Preference phrase|"
        r"Source phrase|Lossless cue|Recurring preference|Selected archetype|Background cue|"
        r"Value/Concern|Values/Concerns|Concern|Concerns|"
        r"Underlying reason|Concrete condition|Health/Diet constraint|Dietary/Health constraint|"
        r"Health constraint|Contact/Account detail|Contact detail|Account detail|"
        r"Privacy constraint|Constraint|Disclosure-safe detail|Sensitive/Private field|"
        r"Private field|Correction/Avoidance|Correction|Avoidance|Memory topic|"
        r"Health/Wellness cue|Work/School cue|Hobby/Home cue|Media/Sports cue|"
        r"Favorite team/person/genre|Current project or sector|Concrete collection or object|Facet|"
        r"Prior interaction example|Raw prior interaction|Prior example|Chosen cue|Concrete preference|Reusable cue|"
        r"Reusable personal cause|Personal cue|Source detail|Topic/Domain)\s*[:=].*$",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip(" -*,.;:'\"")
    stripped = re.sub(
        r"\s+\b(?:Constraints?|Facts?|Preferences?|Relations?|Tool_state|Tool state)\b\s*$",
        "",
        stripped,
        flags=re.IGNORECASE,
    )
    stripped = re.sub(r"\s+\bChoice\s*=\s*[A-Za-z0-9_-]+\b.*$", "", stripped, flags=re.IGNORECASE)
    stripped = re.sub(r"\s+\b(?:Plan item|Why this fits)\s*[:=].*$", "", stripped, flags=re.IGNORECASE)
    return stripped.strip(" -*,.;:'\"")


def _segment_personamem_field_certificate_text(value: Any) -> str:
    text = _clean_text(value)
    label = (
        r"Domain|Stable persona|Stable role|Role/Background|Background/Role|Identity/Background|Background/Identity|"
        r"Interests?|Responsibilities/Routine|"
        r"Responsibilities|Routine|Routine/Habit|Habit|Background phrase|Format/genre cue|Preference phrase|"
        r"Source phrase|Lossless cue|Recurring preference|Selected archetype|Background cue|"
        r"Value/Concern|Values/Concerns|Concern|Concerns|"
        r"Underlying reason|Concrete condition|Health/Diet constraint|Dietary/Health constraint|"
        r"Health constraint|Contact/Account detail|Contact detail|Account detail|"
        r"Privacy constraint|Constraint|Disclosure-safe detail|Sensitive/Private field|"
        r"Private field|Correction/Avoidance|Correction|Avoidance|Memory topic|"
        r"Health/Wellness cue|Work/School cue|Hobby/Home cue|Media/Sports cue|"
        r"Favorite team/person/genre|Current project or sector|Concrete collection or object|Facet|"
        r"Prior interaction example|Raw prior interaction|Prior example|Chosen cue|Concrete preference|Reusable cue|"
        r"Reusable personal cause|Personal cue|Source detail|Topic/Domain"
    )
    text = re.sub(
        rf"(?P<prefix>^|[\s{{,])['\"]?(?P<label>{label})['\"]?\s*:\s*",
        lambda match: f"{match.group('prefix')}{match.group('label')}=",
        text,
        flags=re.IGNORECASE,
    )
    return re.sub(
        rf"\s+\b['\"]?(?P<label>{label})['\"]?\s*[:=]",
        lambda match: f". {match.group('label')}=",
        text,
        flags=re.IGNORECASE,
    )


def _personamem_factorized_evidence_atoms(text: str) -> list[str]:
    """Close a recovered evidence span under stable profile factors.

    One PersonaMem evidence span often acts like a noisy observation generated
    by several latent user-state variables.  This closure enumerates only
    high-support factors that are directly witnessed in the same span.
    """

    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    lower = source.lower()
    atoms: list[str] = []

    atoms.extend(_personamem_contact_atoms_from_text(source))
    atoms.extend(_personamem_health_constraint_atoms_from_text(source))

    if re.search(
        r"\b(?:sensitive_info|sensitive information|privacy|redact|masked|secret|credential|"
        r"social_security_number|ssn|physical_address|drivers_license_number|driver_license_number|"
        r"bank_account_number|credit_card_number|email_address|llm[_ -]?api[_ -]?key|api[_ -]?key)\b",
        lower,
    ):
        atoms.append("sensitive_info")

    topic_support = _infer_personamem_topics([source])
    atoms.extend(topic for topic in topic_support[:2] if topic in _PERSONAMEM_TOPIC_LABELS)

    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    role_modifier = r"(?:[a-z][a-z'-]*\s+){0,4}"
    for match in re.finditer(
        rf"\b(?P<role>(?:a|an)\s+{role_modifier}(?:{role_terms}))\b"
        rf"(?P<body>\s+(?:who|that|working on|focused on|speciali[sz](?:es|ing)?\s+in|with)\s+[^.;\n]{{3,180}})",
        source,
        flags=re.IGNORECASE,
    ):
        phrase = _strip_personamem_field_certificate_tail(f"{match.group('role')} {match.group('body')}")
        phrase = re.sub(r"\s+-\s+", " ", phrase)
        phrase = re.sub(r"\s{2,}", " ", phrase)
        if 4 <= len(phrase.split()) <= 34:
            atoms.append(_canonicalize_personamem_specific(phrase))

    for match in re.finditer(
        rf"\b(?P<role>{role_modifier}(?:{role_terms}))\b"
        rf"\s+(?:working on|focused on|speciali[sz](?:es|ing)?\s+in)\s+"
        rf"(?P<object>[^.;,\n]{{3,130}})",
        source,
        flags=re.IGNORECASE,
    ):
        role = _clean_text(match.group("role")).strip(" -*,.;:'\"")
        role = re.sub(r"^(?:a|an)\s+", "", role, flags=re.IGNORECASE).strip()
        obj = _strip_personamem_field_certificate_tail(match.group("object"))
        obj = re.sub(r"\s+\b(?:while|because|during)\b.*$", "", obj, flags=re.IGNORECASE).strip()
        if not role or not obj:
            continue
        article = "an" if re.match(r"^[aeiou]", role, flags=re.IGNORECASE) else "a"
        atoms.append(_canonicalize_personamem_specific(f"{article} {role} who works on {obj}"))
        addon_match = re.search(
            r"(?P<domain>[a-z][a-z -]{2,80}?)\s+add-?ons?\s+and\s+mods\b",
            obj,
            flags=re.IGNORECASE,
        )
        if addon_match and "engineer" in role.lower():
            domain = _clean_text(addon_match.group("domain")).strip(" -*,.;:'\"")
            domain = re.sub(r"\bsim\b", "simulator", domain, flags=re.IGNORECASE)
            domain = re.sub(r"\s+", " ", domain).strip()
            if domain:
                atoms.append(
                    _canonicalize_personamem_specific(
                        f"{article} {role} who develops add-ons and mods to enhance the {domain} experience"
                    )
                )

    return _dedupe_preserving(
        atom
        for atom in atoms
        if atom and not _is_personamem_generic_advice(atom) and len(_lower_clean(atom).split()) <= 48
    )


def _personamem_conjunctive_role_binding_atoms(text: str) -> list[str]:
    """Bind co-occurring role and predicate factors into complete persona atoms.

    PersonaMem often stores the joint factor, e.g. role + recurring activity,
    while posterior summaries expose the two factors separately.  Binding is
    allowed only inside the same recovered evidence span.
    """

    source = _segment_personamem_field_certificate_text(text)
    if not source:
        return []
    roles = _personamem_binding_role_candidates(source)
    predicates = _personamem_binding_predicate_candidates(source)
    atoms: list[str] = []
    atoms.extend(predicates)
    for role in roles[:4]:
        role_low = _lower_clean(role)
        for predicate in predicates[:8]:
            pred = _clean_text(predicate).strip(" -*,.;:'\"")
            pred_low = _lower_clean(pred)
            if not pred or pred_low in role_low or role_low in pred_low:
                continue
            if len(pred.split()) > 20:
                continue
            if pred_low.startswith(("prefer ", "prefers ", "avoids ", "attends ", "shops ", "plays ", "watches ", "listens ", "volunteers ", "challenges ", "struggling ", "struggles ")):
                atoms.append(_canonicalize_personamem_specific(f"{role} who {_personamem_who_predicate(pred)}"))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if atom and len(_lower_clean(atom).split()) <= 42 and not _is_personamem_generic_advice(atom)
    )


_PERSONAMEM_SOURCE_PATH_RE = re.compile(
    r"(?P<path>/(?:users|home|workspace|projects?)/[A-Za-z0-9_./-]+\.(?:py|js|ts|json|md|txt))"
)
_PERSONAMEM_CODE_FILE_PATH_RE = re.compile(
    r"\bcode_file_path\s*[:=]\s*"
    r"(?P<path>/(?:users|home|workspace|projects?)/[A-Za-z0-9_./-]+\.(?:py|js|ts|json|md|txt))",
    flags=re.IGNORECASE,
)


def _personamem_source_semantic_bridge_atoms(text: Any) -> list[str]:
    source = _segment_personamem_field_certificate_text(text)
    return list(_personamem_source_semantic_bridge_atoms_cached(source))


@lru_cache(maxsize=4096)
def _personamem_source_semantic_bridge_atoms_cached(source: str) -> tuple[str, ...]:
    return tuple(_personamem_source_semantic_bridge_atoms_uncached(source))


def _personamem_source_semantic_bridge_atoms_uncached(source: str) -> list[str]:
    low = _lower_clean(source)
    if not low:
        return []
    atoms: list[str] = []
    atoms.extend(_personamem_contrastive_invariant_atoms_from_text(source))

    fields = _personamem_field_certificate_map(source)
    stable_role = fields.get("stable role") or fields.get("stable persona")
    background = fields.get("background phrase") or fields.get("underlying reason")
    if stable_role and background:
        role = _canonicalize_personamem_specific(stable_role)
        bg = _clean_text(background).strip(" -*,.;:'\"")
        if role and bg and len(role.split()) <= 20 and len(bg.split()) <= 18:
            atoms.append(_canonicalize_personamem_specific(f"{role}, {bg}"))

    if re.search(r"\b(?:children|kids)\b", low) and re.search(r"\b(?:growing older|becoming more independent|needing me less|need me less)\b", low):
        atoms.append("parenting")
        atoms.append("adjusting emotionally to his children growing older and becoming more independent")

    if re.search(r"\bclosest friend moved\b|\bfriend moved away\b", low) and re.search(r"\b(?:isolat|lonely|loneliness|alone|adrift)\b", low):
        atoms.append("loneliness")
        atoms.append("feeling isolated after friend moved away")
    if re.search(r"\b(?:former best friend|best friend|close friend)\b", low) and re.search(
        r"\b(?:misunderstanding|falling out|fell out|trust issues?|learn to trust|hurt)\b",
        low,
    ):
        atoms.append("friendship")
        atoms.append("had a falling out with a former best friend over a misunderstanding, creating trust issues")
    if re.search(r"\b(?:military widow|widow)\b", low) and re.search(
        r"\b(?:listening ear|coping with grief|grief|post[- ]traumatic growth|healing from something painful)\b",
        low,
    ):
        atoms.append("grief")
        atoms.append("another military widow who provides a listening ear and shares tips for coping with grief")
    if re.search(r"\b(?:butterfly\s+photograph(?:er|y)|photograph(?:er|y))\b", low) and re.search(
        r"\b(?:cloud forests?|ecuador|buenos aires|global(?:ly)?|wandering|travel(?:ing|led)?|journey|natural environments?|nature)\b",
        low,
    ):
        atoms.append("a dedicated, global-wandering butterfly photographer")
        atoms.append("nature")
    if re.search(r"\b(?:disconnection|disconnected|sense of disconnection|away from natural environments?)\b", low) and re.search(
        r"\b(?:cities|city|urban|buenos aires|natural environments?|nature|cloud forests?|forest breeze)\b",
        low,
    ):
        atoms.append("feels a sense of disconnection during longer stays in cities, away from natural environments")

