def _personamem_choice_set_bridge_atoms(text: Any) -> list[str]:
    """Map supported choice-set cues into compact latent-state atoms.

    This bridge only fires on concrete cue phrases, not on copied option menus.
    """

    source = _clean_text(text).strip(" -*,.;:'\"")
    low = _lower_clean(source)
    if not low or re.search(r"\b(?:general|unknown|none|not supported|not specified|no clear)\b", low):
        return []
    option_menu_like = low.count(" or ") >= 2 and not re.search(
        r"\b(?:my|me|i|user|known|favorite|family history|paternal|maternal|"
        r"nightmares?|anxiety|traumatic|difficult experience|quality control|"
        r"bioinformatics|hospital|library|plants?|football|team|club|theatre|theater|vinyl|licensing)\b",
        low,
    )
    if option_menu_like:
        return []

    atoms: list[str] = []
    if re.search(r"\b(?:nightmares?|anxiety|traumatic|difficult experience|stress|recovery)\b", low):
        atoms.append("health_and_medical")
        if re.search(r"\b(?:child|young)\b", low):
            atoms.append("young child with nightmares and anxiety after a difficult experience")
        else:
            atoms.append("struggles with nightmares and anxiety after a difficult experience")
    if re.search(r"\b(?:former best friend|best friend|close friend|friendship)\b", low) and re.search(
        r"\b(?:misunderstanding|falling out|fell out|trust issues?|learn to trust|hurt)\b",
        low,
    ):
        atoms.append("friendship")
        atoms.append("had a falling out with a former best friend over a misunderstanding, creating trust issues")
    if re.search(r"\b(?:military widow|widow|grief|post[- ]traumatic growth|healing from something painful)\b", low) and re.search(
        r"\b(?:listening ear|coping|grief|growth|healing)\b",
        low,
    ):
        atoms.append("grief")
        if "widow" in low:
            atoms.append("another military widow who provides a listening ear and shares tips for coping with grief")
    if re.search(r"\b(?:family history|blood sugar|diabetes|metabolic|insulin)\b", low):
        atoms.append("health_and_medical")
        if re.search(r"\bpaternal|father|dad\b", low):
            atoms.append("family history of type 2 diabetes on paternal side")
        elif re.search(r"\bmaternal|mother|mom\b", low):
            atoms.append("family history of type 2 diabetes on maternal side")
        elif "type 2 diabetes" in low or "diabetes" in low:
            atoms.append("family history of type 2 diabetes")
    if re.search(r"\b(?:school|student|coding|code|python|research project|technical collaboration)\b", low) or re.search(
        r"\b(?:school|science|coding|research)\s+club\b",
        low,
    ):
        if re.search(r"\b(?:student|school)\b", low) or re.search(r"\b(?:school|science|coding|research)\s+club\b", low):
            atoms.append("student working on a school project")
        if re.search(r"\b(?:privacy|sensitive|file path|identifier|redact)\b", low):
            atoms.append("sensitive_info")
    if re.search(r"\b(?:manufacturing|quality control|supplier|operations|small business)\b", low):
        atoms.append("business")
        if re.search(r"\b(?:small business|owner|manufacturing|quality control)\b", low):
            atoms.append("small business owner focused on manufacturing quality control")
    if re.search(r"\b(?:hospital|healthcare|bioinformatics|personalized medicine|medical informatics)\b", low):
        atoms.append("health_and_medical")
        if "bioinformatics" in low:
            atoms.append("interested in bioinformatics and personalized medicine")
        if re.search(r"\b(?:cio|chief information|leadership|leader)\b", low):
            atoms.append("hospital cio interested in healthcare data")
    if re.search(r"\b(?:library|books?|reading|genres?|poetry|novels?)\b", low):
        atoms.append("reading")
        if re.search(r"\b(?:home library|varied genres|books? collection|reading collection)\b", low):
            atoms.append("keeps a home library of varied genres")
    if re.search(r"\b(?:yard sales?|garage sales?|flea markets?)\b", low):
        atoms.append("shopping")
        if re.search(r"\b(?:wakes? up|up early|early (?:on )?(?:weekend|saturday|sunday)|weekend mornings?)\b", low):
            atoms.append("wakes up early for weekend yard sales")
    if re.search(r"\b(?:gender|gendered|male[- ]dominated|female[- ]dominated|women's|womens?|men's|mens?)\b", low):
        atoms.append("gender")
    if re.search(r"\b(?:plants?|indoor garden|indoor jungle|greenery|botanical)\b", low):
        atoms.append("home")
        if re.search(r"\b(?:indoor jungle|exotic plants?|plant collection)\b", low):
            atoms.append("keeps an indoor jungle of exotic plants")
    if re.search(r"\b(?:football|soccer|sports|team|club|athlete|match[- ]day|fan)\b", low):
        atoms.append("sports")
        if re.search(r"\b(?:die[- ]hard|passionate|huge fan|fan of)\b", low):
            atoms.append(_canonicalize_personamem_specific(source))
    if re.search(r"\b(?:theatre|theater|live performance|melbourne|music|vinyl|licensing|production|reissues?)\b", low):
        atoms.append("theater" if re.search(r"\b(?:theatre|theater|live performance|melbourne)\b", low) else "music")
        if re.search(r"\b(?:vinyl|licensing|production|reissues?)\b", low):
            atoms.append("media professional involved in licensing and production of vinyl reissues")
        if re.search(r"\b(?:live theatre|live theater|theatre performances?|theater performances?|melbourne)\b", low):
            atoms.append("enjoys live theatre performances in melbourne")
    if re.search(r"\b(?:collectibles?|memorabilia|display objects?|collection)\b", low):
        atoms.append("collectibles")

    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(atom)
    )


_PERSONAMEM_CHOICE_SET_LABELS = (
    "Selected archetype",
    "Background cue",
    "Health/Wellness cue",
    "Work/School cue",
    "Hobby/Home cue",
    "Media/Sports cue",
    "Favorite team/person/genre",
    "Current project or sector",
    "Concrete collection or object",
    "Facet",
)


def _personamem_choice_set_labeled_atoms(text: Any) -> list[str]:
    source = _segment_personamem_field_certificate_text(text)
    if not source:
        return []
    boundary_labels = (
        *_PERSONAMEM_CHOICE_SET_LABELS,
        "Stable persona",
        "Stable role",
        "Interest",
        "Interests",
        "Routine/Habit",
        "Value/Concern",
        "Values/Concerns",
        "Constraint",
        "Prior example",
        "Prior interaction example",
        "Raw prior interaction",
    )
    label_pattern = "|".join(re.escape(label) for label in boundary_labels)
    marker_re = re.compile(rf"(?P<label>{label_pattern})\s*[:=]", flags=re.IGNORECASE)
    matches = list(marker_re.finditer(source))
    if not matches:
        return []
    choice_label_set = {_lower_clean(label) for label in _PERSONAMEM_CHOICE_SET_LABELS}
    atoms: list[str] = []
    for index, match in enumerate(matches):
        label = _lower_clean(match.group("label"))
        if label not in choice_label_set:
            continue
        end = matches[index + 1].start() if index + 1 < len(matches) else len(source)
        body = _clean_text(source[match.end() : end]).strip(" -*,.;:'\"")
        if not body or body.lower() in {"unknown", "none", "not available", "not specified", "general/unknown"}:
            continue
        if re.search(r"\b(?:no explicit|no known|none noted|not mentioned|unknown)\b", body, flags=re.IGNORECASE):
            continue
        atoms.extend(_personamem_choice_set_bridge_atoms(body))
        topic_label = _canonical_personamem_topic_label(body)
        if topic_label:
            atoms.append(topic_label)
        if label not in {"selected archetype", "facet"} and len(_lower_clean(body).split()) >= 2:
            atoms.append(_canonicalize_personamem_specific(body))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(atom)
    )


def _personamem_field_certificate_map(text: Any) -> dict[str, str]:
    source = _segment_personamem_field_certificate_text(text)
    if not source:
        return {}
    label = (
        r"Domain|Stable persona|Stable role|Role/Background|Background/Role|Identity/Background|Background/Identity|"
        r"Interests?|Responsibilities/Routine|"
        r"Responsibilities|Routine|Routine/Habit|Habit|Background phrase|Format/genre cue|Preference phrase|"
        r"Source phrase|Lossless cue|Recurring preference|Value/Concern|Values/Concerns|Concern|Concerns|"
        r"Underlying reason|Concrete condition|Health/Diet constraint|Dietary/Health constraint|"
        r"Health/Wellness cue|Health constraint|Contact/Account detail|Contact detail|Account detail|"
        r"Privacy constraint|Constraint|Disclosure-safe detail|Sensitive/Private field|"
        r"Private field|Correction/Avoidance|Correction|Avoidance|Memory topic|"
        r"Prior interaction example|Raw prior interaction|Prior example|Chosen cue|Concrete preference|Reusable cue|"
        r"Reusable personal cause|Personal cue|Source detail|Topic/Domain"
    )
    source = re.sub(rf"[.;,|]+\s+(?=(?:{label})\s*[:=])", " ", source, flags=re.IGNORECASE)
    pattern = re.compile(
        rf"\b(?P<label>{label})\s*[:=]\s*(?P<body>.*?)(?=(?:\s|[.;,|]\s)+(?:{label})\s*[:=]|$)",
        flags=re.IGNORECASE | re.DOTALL,
    )
    fields: dict[str, str] = {}
    for match in pattern.finditer(source):
        key = _lower_clean(match.group("label"))
        value = _strip_personamem_field_certificate_tail(match.group("body"))
        if value and value.lower() not in {"unknown", "none", "not available", "not specified"}:
            current = fields.get(key)
            if current is None or _personamem_field_certificate_value_prefer(
                key,
                value,
                current,
                source_text=source,
            ):
                fields[key] = value
    return fields


def _personamem_revision_duplicate_tail_normal_form(value: Any) -> str:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text:
        return ""
    words = text.split()
    while len(words) >= 2 and _lower_clean(words[-1]) == _lower_clean(words[-2]):
        words.pop()
    return " ".join(words).strip(" -*,.;:'\"")


def _personamem_revision_target_variants(value: Any) -> list[str]:
    """Return signed-belief target variants implied by a visible correction."""

    target = _personamem_revision_duplicate_tail_normal_form(
        _clean_personamem_negative_target(_clean_text(value))
    )
    if not target:
        return []
    target = re.sub(r"^love\s+", "loves ", target, flags=re.IGNORECASE)
    target = re.sub(r"^like\s+", "likes ", target, flags=re.IGNORECASE)
    target = re.sub(r"^enjoy\s+", "enjoys ", target, flags=re.IGNORECASE)
    target = re.sub(r"^prefer\s+", "prefers ", target, flags=re.IGNORECASE)
    target = re.sub(r"^choose\s+", "chooses ", target, flags=re.IGNORECASE)
    target = re.sub(r"^choosing\s+", "chooses ", target, flags=re.IGNORECASE)
    variants: list[str] = [target]
    low = _lower_clean(target)
    verb_match = re.match(
        r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|chooses|values|supports)\s+(.+)$",
        low,
    )
    if verb_match:
        obj = _personamem_revision_duplicate_tail_normal_form(verb_match.group(1))
        if obj and len(_lower_clean(obj).split()) >= 2:
            variants.append(obj)
    return _dedupe_preserving(
        _personamem_revision_duplicate_tail_normal_form(variant)
        for variant in variants
        if _personamem_revision_duplicate_tail_normal_form(variant)
    )


def _personamem_correction_targets_from_text(text: Any) -> list[str]:
    source = _clean_text(text)
    if not source:
        return []
    targets: list[str] = []
    direct_target = _negative_memory_target(source)
    if direct_target:
        targets.extend(_personamem_revision_target_variants(direct_target))
    patterns = (
        r"(?:previously|formerly|earlier)\s+chose\s+(.+?)\s+but\s+(?:asked|requested)\s+(?:me\s+|you\s+)?to\s+forget",
        r"(?:previously\s+mentioned\s+)?(?:preference|interest|focus|detail)\s+(?:for|on|about)\s+(.+?)\s+(?:has\s+been|was|is)\s+(?:corrected|removed|withdrawn|updated|forgotten|set\s+aside)",
        r"(?:prior|previous|earlier)\s+(?:preference|interest|focus|detail)\s+(?:for|on|about)\s+(.+?)\s+(?:should\s+not|shouldn't|must\s+not|does\s+not)\s+(?:be\s+)?(?:considered|used|applied|relied\s+on)",
        r"(?:should\s+not|shouldn't|must\s+not|do\s+not|don't)\s+(?:be\s+)?(?:considered|used|applied|relied\s+on)\s+(?:the\s+)?(?:preference\s+for\s+|interest\s+in\s+|focus\s+on\s+)?([^.;]+)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            targets.extend(_personamem_revision_target_variants(match.group(1)))
    low = _lower_clean(source)
    if re.search(r"\b(?:avoid|avoids|avoiding|prefer(?:s)?\s+to\s+avoid)\s+(?:that|this)\s+(?:region|topic|preference|detail)\b", low):
        targets.append("__field_preference__")
    return _dedupe_preserving(targets)


def _personamem_revision_preference_anchors_from_fields(fields: Mapping[str, str]) -> list[str]:
    anchors: list[str] = []
    for key in (
        "recurring preference",
        "concrete preference",
        "preference phrase",
        "interests",
        "interest",
        "routine/habit",
        "routine",
        "habit",
    ):
        value = fields.get(key)
        if not value:
            continue
        for atom in _personamem_orthogonal_preference_atoms(value):
            atoms = _personamem_revision_target_variants(atom) or [atom]
            anchors.extend(atoms)
        first_clause = re.split(
            r",|\bparticularly\b|\bespecially\b|\bbut\b|\bwhile\b|\bwith\b",
            _clean_text(value),
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0].strip(" -*,.;:'\"")
        if 1 <= len(_lower_clean(first_clause).split()) <= 5:
            anchors.append(_personamem_revision_duplicate_tail_normal_form(first_clause))
    return _dedupe_preserving(
        _canonicalize_personamem_specific(anchor)
        for anchor in anchors
        if _clean_text(anchor) and not _is_personamem_generic_advice(anchor)
    )


def _personamem_temporal_revision_atoms_from_fields(fields: Mapping[str, str]) -> list[str]:
    """Compose visible correction fields into a signed temporal belief episode.

    The model follows a truth-maintenance view: a correction is evidence about
    both the prior positive fluent and the later terminating/forget event.
    """

    correction_sources = [
        fields.get(key, "")
        for key in ("correction/avoidance", "correction", "avoidance")
        if fields.get(key)
    ]
    if not correction_sources:
        return []
    anchors = _personamem_revision_preference_anchors_from_fields(fields)
    atoms: list[str] = []
    for correction in correction_sources:
        targets = _personamem_correction_targets_from_text(correction)
        if not targets and _is_personamem_negative_carrier(correction):
            targets = _personamem_revision_target_variants(_negative_memory_target(correction))
        if not targets:
            direct_avoidance_target = _clean_text(correction).strip(" -*,.;:'\"")
            if (
                2 <= len(_lower_clean(direct_avoidance_target).split()) <= 12
                and not re.search(
                    r"\b(?:unknown|none|not specified|not applicable|general|preference home|asked for|recommendations?|suggestions?)\b",
                    _lower_clean(direct_avoidance_target),
                )
            ):
                targets = _personamem_revision_target_variants(direct_avoidance_target)
        if "__field_preference__" in targets:
            targets = [target for target in targets if target != "__field_preference__"]
            targets.extend(anchors)
        expanded_targets: list[str] = []
        for target in targets:
            expanded_targets.extend(_personamem_revision_target_variants(target) or [target])
            target_low = _lower_clean(target)
            for anchor in anchors:
                anchor_low = _lower_clean(anchor)
                if not anchor_low or not target_low:
                    continue
                anchor_tokens = _contentish_tokens(_semantic_compact_adapter(anchor))
                target_tokens = _contentish_tokens(_semantic_compact_adapter(target))
                if anchor_tokens & target_tokens:
                    expanded_targets.append(anchor)
                    continue
                if (
                    len(anchor_low.split()) <= 3
                    and anchor_low not in target_low
                    and target_low not in anchor_low
                    and not re.match(
                        r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|chooses|values|supports)\b",
                        anchor_low,
                    )
                ):
                    expanded_targets.append(f"{anchor_low} {target_low}")
        for target in _dedupe_preserving(expanded_targets):
            clean_target = _personamem_revision_duplicate_tail_normal_form(target)
            if not clean_target or not _personamem_valid_negative_target(clean_target):
                continue
            atoms.append(clean_target)
            atoms.append(f"do not remember {clean_target} in memory")
    prior = fields.get("raw prior interaction") or fields.get("prior interaction example") or fields.get("prior example")
    if prior and "user:" in prior.lower() and "assistant:" in prior.lower():
        prior_low = _lower_clean(prior)
        target_keys = [
            _semantic_compact_adapter(_negative_memory_target(atom))
            for atom in atoms
            if _is_personamem_negative_carrier(atom)
        ]
        if any(key and key in _semantic_compact_adapter(prior_low) for key in target_keys) or re.search(
            r"\b(?:forget|corrected|should not be considered)\b",
            prior_low,
        ):
            atoms.append(prior)
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom)
    )


def _personamem_field_certificate_value_prefer(
    key: str,
    candidate: Any,
    current: Any,
    *,
    source_text: Any,
) -> bool:
    """Prefer the most informative repeated visible field-certificate value."""

    return (
        _personamem_field_certificate_value_score(key, candidate, source_text=source_text),
        len(_lower_clean(candidate).split()),
        _lower_clean(candidate),
    ) > (
        _personamem_field_certificate_value_score(key, current, source_text=source_text),
        len(_lower_clean(current).split()),
        _lower_clean(current),
    )


def _personamem_field_certificate_value_score(key: str, value: Any, *, source_text: Any) -> int:
    field = _personamem_field_posterior_label(key)
    text = _lower_clean(value)
    score = _personamem_field_observation_reliability_bonus(key, value, source_text)
    score += _personamem_field_specificity_score(field or "specific", value)
    if field == "role":
        if re.search(r"\b(?:who|coached by|focusing on|focused on|speciali[sz](?:es|ing)|of the|of [a-z])\b", text):
            score += 86
        if re.search(r"\b(?:choice\s*=|plan item|why this fits|current task|recommendation)\b", text):
            score -= 96
        if _personamem_surface_task_role_atom(value):
            score -= 80
    elif field == "prior":
        score += min(160, len(text.split()) // 6)
        if re.search(r"\b(?:choice\s*=|plan item|why this fits)\b", text):
            score -= 120
    elif field == "preference":
        if _personamem_compact_exact_preference_atom(value) or _personamem_preference_comparison_atom(value):
            score += 60
    return score


def _personamem_r007_direct_field_certificate_atoms(text: Any) -> list[str]:
    """Recover independent latent atoms directly named by a typed profile card.

    R007 treats compact field-card values as high-reliability observations of
    latent variables.  This extractor is intentionally field-generic: it uses
    the public field label and admissibility checks, not benchmark row ids or
    memorized values.
    """

    fields = _personamem_field_certificate_map(text)
    if not fields:
        return []
    atoms: list[str] = []

    def add(candidate: Any, *, field: str = "") -> None:
        raw = _strip_personamem_field_certificate_tail(candidate).strip(" -*,.;:'\"")
        if not raw:
            return
        low = _lower_clean(raw)
        if low in {"none", "unknown", "not specified", "not available", "general/unknown"}:
            return
        if _is_personamem_field_certificate_source(raw) or _is_personamem_generic_advice(raw):
            return
        if _personamem_placeholder_prior_text(raw):
            return
        canonical = _canonicalize_personamem_specific(raw)
        if not canonical:
            return
        if len(_lower_clean(canonical).split()) > 42 and not _is_personamem_conversation(canonical):
            return
        if field == "role":
            role_atoms = _personamem_field_posterior_atoms("role", canonical, chosen_topic="")
            atoms.extend(role_atoms)
            atoms.extend(_personamem_r007_role_core_atoms(canonical))
            if (
                (_is_personamem_persona_carrier(canonical) or _PERSONAMEM_STABLE_ROLE_TERM_RE.search(_lower_clean(canonical)))
                and not _personamem_low_information_role_atom(canonical)
            ):
                atoms.append(canonical)
            return
        if field == "topic":
            topic = _canonical_personamem_topic_label(canonical) or _lower_clean(canonical)
            if topic in _PERSONAMEM_TOPIC_LABELS:
                atoms.append(topic)
            return
        if field == "health":
            atoms.extend(_personamem_health_constraint_atoms_from_text(canonical))
            atoms.extend(_personamem_polarity_preserving_atoms(canonical))
            if _personamem_r007_direct_health_atom(canonical):
                atoms.append(canonical)
                atoms.append("health_and_medical")
            return
        if field == "sensitive":
            atoms.extend(_personamem_contact_atoms_from_text(canonical))
            atoms.extend(_personamem_health_constraint_atoms_from_text(canonical))
            atoms.extend(_personamem_polarity_preserving_atoms(canonical))
            if _is_personamem_sensitive_carrier(canonical):
                atoms.append(canonical)
                atoms.append("sensitive_info")
            return
        if field == "correction":
            atoms.extend(_personamem_negative_atoms_from_text(canonical))
            atoms.extend(_personamem_polarity_preserving_atoms(canonical))
            if _personamem_valid_negative_intervention_atom(canonical):
                atoms.append(canonical)
            return
        if field in {"preference", "routine", "value"}:
            topic = _canonical_personamem_topic_label(canonical)
            if topic in _PERSONAMEM_TOPIC_LABELS:
                atoms.append(topic)
                if _lower_clean(canonical) == topic or field == "value":
                    return
            atoms.extend(_personamem_field_posterior_atoms("preference", canonical, chosen_topic=""))
            if (
                field == "value"
                or _personamem_projection_typed_field_atom_admissible(canonical)
                or _personamem_r007_direct_health_atom(canonical)
            ):
                atoms.append(canonical)
            return
        if _personamem_projection_typed_field_atom_admissible(canonical):
            atoms.append(canonical)

    for label, value in fields.items():
        field = _personamem_field_posterior_label(label)
        add(value, field=field)
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom)
        and not _is_personamem_generic_advice(atom)
        and not _is_personamem_field_certificate_source(atom)
    )


def _personamem_r007_direct_health_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    if len(text.split()) > 24:
        return False
    return bool(
        re.search(
            r"\b(?:acid reflux|reflux|heartburn|indigestion|gastritis|food poisoning|"
            r"allerg\w*|intolerance|asthma|migraine|diabetes|eczema|pain|injury|"
            r"strain|sprain|surgery|therapy|medication|prescription|cholesterol|"
            r"dietary restriction|dietary constraint|health condition|medical condition)\b",
            text,
        )
    )


def _personamem_r007_role_core_atoms(value: Any) -> list[str]:
    """Split stable identity cores away from appended interest/activity tails."""

    raw = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
    if not raw or _is_personamem_conversation(raw):
        return []
    low = _lower_clean(raw)
    role_terms = "|".join(re.escape(role) for role in _PERSONAMEM_STABLE_ROLE_TERMS_SORTED)
    tail_patterns = (
        rf"^(?P<core>(?:(?:a|an)\s+)?[^.;,\n]{{3,220}}\b(?:{role_terms})\b[^.;,\n]{{0,180}}?)\s+with\s+(?:a|an|the)?\s*"
        r"(?:passion|interest|preference|love|fondness|enthusiasm)\s+for\b",
        rf"^(?P<core>(?:(?:a|an)\s+)?[^.;,\n]{{3,220}}\b(?:{role_terms})\b[^.;,\n]{{0,180}}?)\s+(?:and|who)\s+"
        r"(?:enjoys?|likes?|loves?|prefers?|plays?|attends?|collects?|uses?|practices?|watches?|reads?|listens?\s+to)\b",
    )
    atoms: list[str] = []
    for pattern in tail_patterns:
        match = re.match(pattern, raw, flags=re.IGNORECASE)
        if not match:
            continue
        core = _clean_text(match.group("core")).strip(" -*,.;:'\"")
        if not core:
            continue
        if not re.match(r"^(?:a|an)\s+", _lower_clean(core)):
            core = f"{_personamem_indefinite_article(core)} {core}"
        core = _canonicalize_personamem_specific(core)
        core_low = _lower_clean(core)
        if (
            3 <= len(core_low.split()) <= 34
            and "role" in _personamem_projection_field_labels(core)
            and not _personamem_low_information_role_atom(core)
            and not _personamem_role_preference_fusion(core)
            and not _personamem_nonpersona_nominal_summary(core)
        ):
            atoms.append(core)
    return _dedupe_preserving(atoms)


def _personamem_role_value_pair_atoms(text: Any) -> list[str]:
    """Extract typed atoms from visible `Role: ... | Value: ...` evidence pairs."""

    source = _clean_text(text)
    if not source:
        return []
    pattern = re.compile(
        r"\bRole\s*:\s*(?P<role>[^|:]{2,220})\s*\|\s*Value\s*:\s*"
        r"(?P<value>.*?)(?=\s+(?:Role\s*:|Stable persona\b|Stable role\b|Memory topic\b|"
        r"Recurring preference\b|Routine/Habit\b|Value/Concern\b|Health constraint\b|"
        r"Sensitive/Private field\b|Correction/Avoidance\b|Prior interaction example\b|$))",
        flags=re.IGNORECASE | re.DOTALL,
    )
    atoms: list[str] = []
    for match in pattern.finditer(source):
        role = _clean_text(match.group("role")).strip(" -*,.;:'\"")
        value = _clean_text(match.group("value")).strip(" -*,.;:'\"")
        if role and role.lower() not in {"unknown", "none", "not available", "not specified"}:
            role_topic = _canonical_personamem_topic_label(role)
            if role_topic:
                atoms.append(role_topic)
            else:
                explicit_role = _personamem_explicit_role_field_atom(role)
                if explicit_role:
                    atoms.append(explicit_role)
                else:
                    atoms.extend(_personamem_orthogonal_role_atoms(role))
                    canonical_role = _canonicalize_personamem_specific(role)
                    if _is_personamem_persona_carrier(canonical_role) and not _personamem_low_information_role_atom(canonical_role):
                        atoms.append(canonical_role)
        if value and value.lower() not in {"unknown", "none", "not available", "not specified"}:
            value_topic = _canonical_personamem_topic_label(value)
            if value_topic:
                atoms.append(value_topic)
            atoms.extend(_personamem_field_posterior_atoms("preference", value, chosen_topic=""))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if _clean_text(atom)
        and not _is_personamem_generic_advice(str(atom))
        and not _is_personamem_field_certificate_source(atom)
    )


def _personamem_orthogonal_field_certificate_atoms(text: Any) -> list[str]:
    """Emit independent typed atoms from a profile-field certificate.

    A visible profile card often places role, preference, topic, and prior
    evidence next to each other.  The latent variables are separate, so this
    step prevents one field from borrowing words from its neighbor.
    """

    pair_atoms = _personamem_role_value_pair_atoms(text)
    fields = _personamem_field_certificate_map(text)
    if not fields and not pair_atoms:
        return []
    atoms: list[str] = [
        *pair_atoms,
        *_personamem_r007_direct_field_certificate_atoms(text),
        *_personamem_temporal_revision_atoms_from_fields(fields),
    ]
    topic_values = [
        fields.get("topic/domain", ""),
        fields.get("domain", ""),
        fields.get("memory topic", ""),
    ]
    for value in topic_values:
        topic = _canonical_personamem_topic_label(value)
        if topic:
            atoms.append(topic)
    for key in ("stable role", "stable persona", "identity/background", "background/identity", "role/background", "background/role"):
        value = fields.get(key)
        if value:
            atoms.extend(_personamem_orthogonal_role_atoms(value))
    for key in (
        "recurring preference",
        "concrete preference",
        "preference phrase",
        "reusable cue",
        "reusable personal cause",
        "personal cue",
    ):
        value = fields.get(key)
        if value:
            if key == "reusable cue" and _is_personamem_persona_carrier(value):
                atoms.extend(_personamem_orthogonal_role_atoms(value))
            else:
                atoms.extend(_personamem_orthogonal_preference_atoms(value))
    for key in ("routine/habit", "routine", "habit", "responsibilities/routine"):
        value = fields.get(key)
        if value:
            atoms.append(_canonicalize_personamem_specific(value))
    for key in ("value/concern", "values/concerns", "concern", "concerns", "underlying reason"):
        value = fields.get(key)
        if value:
            atoms.append(_canonicalize_personamem_specific(value))
            atoms.extend(
                topic
                for topic in _infer_personamem_topics([value])[:2]
                if topic in _PERSONAMEM_TOPIC_LABELS
            )
    for key in ("sensitive/private field", "private field", "contact/account detail", "contact detail", "account detail", "privacy constraint"):
        value = fields.get(key)
        if value and _lower_clean(value) not in {"none", "unknown", "not available", "not specified"}:
            contact_atoms = _personamem_contact_atoms_from_text(value)
            atoms.extend(contact_atoms)
            atoms.extend(_personamem_polarity_preserving_atoms(value))
            canonical = _canonicalize_personamem_specific(value)
            if canonical and _is_personamem_sensitive_carrier(canonical):
                atoms.append(canonical)
            if any(_is_personamem_sensitive_carrier(atom) for atom in [canonical, *contact_atoms]):
                atoms.append("sensitive_info")
    for key in ("health constraint", "health/diet constraint", "dietary/health constraint"):
        value = fields.get(key)
        if value and _lower_clean(value) not in {"none", "unknown", "not available", "not specified"}:
            health_atoms = _personamem_health_constraint_atoms_from_text(value)
            atoms.extend(health_atoms)
            atoms.extend(_personamem_polarity_preserving_atoms(value))
            canonical = _canonicalize_personamem_specific(value)
            if canonical:
                atoms.append(canonical)
            if health_atoms or re.search(
                r"\b(?:allerg|injury|strain|medical|health|surgery|condition|medication|therapy|diabetes|asthma|migraine)\b",
                value,
                flags=re.IGNORECASE,
            ):
                atoms.append("health_and_medical")
    for key in ("correction/avoidance", "correction", "avoidance"):
        value = fields.get(key)
        if value and _lower_clean(value) not in {"none", "unknown", "not available", "not specified"}:
            atoms.extend(_personamem_negative_atoms_from_text(value))
            canonical = _canonicalize_personamem_specific(value)
            if canonical and not _is_personamem_generic_advice(canonical):
                atoms.append(canonical)
    avoidance_value = fields.get("avoidance") or fields.get("correction/avoidance") or fields.get("correction")
    if avoidance_value and _lower_clean(avoidance_value) not in {"none", "unknown", "not available", "not specified"}:
        avoidance_tokens = _contentish_tokens(_semantic_compact_adapter(avoidance_value))
        for key in ("recurring preference", "concrete preference", "preference phrase"):
            value = fields.get(key)
            if not value:
                continue
            for pref_atom in _personamem_orthogonal_preference_atoms(value):
                pref_tokens = _contentish_tokens(_semantic_compact_adapter(pref_atom))
                if not pref_tokens or not avoidance_tokens:
                    continue
                if pref_tokens & avoidance_tokens:
                    atoms.append(f"do not remember {pref_atom} in memory")
    prior = fields.get("raw prior interaction") or fields.get("prior interaction example") or fields.get("prior example")
    if prior:
        if "user:" in prior.lower() and "assistant:" in prior.lower():
            atoms.append(prior)
        else:
            atoms.extend(_personamem_orthogonal_preference_atoms(prior))
            atoms.extend(_personamem_negative_atoms_from_text(prior))
            canonical_prior = _canonicalize_personamem_specific(prior)
            if (
                canonical_prior
                and not _is_personamem_generic_advice(canonical_prior)
                and not _is_personamem_field_certificate_source(canonical_prior)
                and len(_lower_clean(canonical_prior).split()) <= 28
            ):
                atoms.append(canonical_prior)
    for key in ("recurring preference", "concrete preference", "preference phrase", "routine/habit", "routine", "habit", "responsibilities/routine"):
        value = fields.get(key)
        if value:
            atoms.extend(
                topic
                for topic in _infer_personamem_topics([value])[:2]
                if topic in _PERSONAMEM_TOPIC_LABELS
            )
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom)
        and not _is_personamem_generic_advice(str(atom))
        and not _is_personamem_field_certificate_source(atom)
    )


def _personamem_indefinite_article(value: Any) -> str:
    low = _lower_clean(value)
    if low.startswith(("uni", "user", "euro", "one ")):
        return "a"
    return "an" if low[:1] in {"a", "e", "i", "o", "u"} else "a"


def _personamem_orthogonal_role_atoms(value: Any) -> list[str]:
    role = _strip_personamem_field_certificate_tail(value).strip(" -*,.;:'\"")
    if not role:
        return []
    role = re.sub(r"^(?:is\s+)?(?:a|an)\s+", "", role, flags=re.IGNORECASE).strip(" -*,.;:'\"")
    atoms: list[str] = []
    relation_match = re.match(
        r"(?P<base>[^.;,\n]{3,120}?)\s+and\s+(?P<relation>(?:distant|close|long[- ]time|childhood|family|professional)\s+friend\s+of\s+[^.;,\n]{2,100})$",
        role,
        flags=re.IGNORECASE,
    )
    if relation_match:
        base = _clean_text(relation_match.group("base")).strip(" -*,.;:'\"")
        relation = _clean_text(relation_match.group("relation")).strip(" -*,.;:'\"")
        if base and relation:
            atoms.append(f"{_personamem_indefinite_article(base)} {base} who is also a {relation}")
            atoms.append(f"{_personamem_indefinite_article(base)} {base}")
            atoms.append(relation)
            return atoms
    if _is_personamem_persona_carrier(role) or re.search(
        r"\b(?:professor|student|anthropologist|teacher|scientist|researcher|officer|attorney|lawyer|historian|engineer|doctor|nurse|artist|writer|coach|manager|developer|designer|representative|neighbor|friend)\b",
        _lower_clean(role),
    ):
        atoms.append(f"{_personamem_indefinite_article(role)} {role}")
    else:
        atoms.append(role)
    return atoms


def _personamem_orthogonal_preference_atoms(value: Any) -> list[str]:
    pref = _strip_personamem_field_certificate_tail(value).strip(" -*,.;:'\"")
    if not pref:
        return []
    low = _lower_clean(pref)
    atoms = [
        *_personamem_polarity_preserving_atoms(pref),
        *_personamem_preference_core_variants(pref),
        _canonicalize_personamem_specific(pref),
    ]
    habitual_match = re.match(
        r"^(?P<freq>occasionally|sometimes|regularly|often|frequently|usually)\s+"
        r"(?P<verb>enjoy|like|love|prefer|favor|watch|read|play|listen to|attend|visit|use|collect)\s+"
        r"(?P<object>.+)$",
        pref,
        flags=re.IGNORECASE,
    )
    if habitual_match:
        freq = _lower_clean(habitual_match.group("freq"))
        verb = _lower_clean(habitual_match.group("verb"))
        obj = _clean_text(habitual_match.group("object")).strip(" -*,.;:'\"")
        verb_map = {
            "enjoy": "enjoys",
            "like": "likes",
            "love": "loves",
            "prefer": "prefers",
            "favor": "favors",
            "watch": "watches",
            "read": "reads",
            "play": "plays",
            "listen to": "listens to",
            "attend": "attends",
            "visit": "visits",
            "use": "uses",
            "collect": "collects",
        }
        if obj:
            atoms.append(f"{verb_map.get(verb, verb)} {obj} {freq}")
            if re.search(r"\bmusic\b", _lower_clean(obj)):
                atoms.append(f"listening to {obj} {freq}")
    if re.search(r"\bschool project\b", low) and re.search(r"\btown'?s history\b|\btown history\b", low):
        atoms.append("a young student doing a school project on the towns history")
        atoms.append("friendship")
    if re.match(r"^(?:prefer|prefers|enjoys|likes|loves|favors|avoids|values|supports|attends|participates|contributes|volunteers|takes|collects|uses|reads|watches|plays|listens to)\b", low):
        return _dedupe_preserving(atoms)
    if re.match(
        r"^(?:experiences|experienced|feels|has|needs|seeks|struggles with|is concerned about|"
        r"is passionate about|passionate about|believes?|advocates?|advocating|fights?|fighting|is more interested in|more interested in)\b",
        low,
    ):
        return _dedupe_preserving(atoms)
    if re.match(r"^(?:regularly|often|frequently|usually)\s+(?:attends|visits|reads|watches|plays|listens to|uses|collects)\b", low):
        return _dedupe_preserving(atoms)
    if re.search(r"\bover\b", low) or re.search(r"\b(?:decor|tone|communication|clarity|podcasts?|genre|style|layout)\b", low):
        atoms.append(f"prefer {pref}")
    elif re.search(r"\b(?:music|events?|shows?|books?|courses?|games?|sports?|food|jewelry|photography|architecture)\b", low):
        atoms.append(f"enjoys {pref}")
    else:
        atoms.append(f"prefers {pref}")
    return _dedupe_preserving(atoms)


def _personamem_preference_core_variants(value: Any) -> list[str]:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text:
        return []
    variants: list[str] = [*_personamem_preference_comparison_atoms(text)]
    action_prefix = r"(?:enjoys?|likes?|loves?|prefers?|favors?|avoids?|values?|supports?|attends?|takes?|reads?|watches?|plays?|listens to|uses?|collects?|drinks?|eats?|wears?|buys?)"
    for splitter in (
        r"\s+\b(?:Constraints?|Facts?|Preferences?)\b\s*:?",
        r"\s+\band\s+(?:appreciates?|values?|prefers?|favors?|enjoys?)\b",
        r"\s+-\s+(?=(?:prefers?|favors?|enjoys?|appreciates?|values?)\b)",
        r"\s+\|\s+",
    ):
        part = re.split(splitter, text, maxsplit=1, flags=re.IGNORECASE)[0].strip(" -*,.;:'\"")
        if part and part != text and re.match(rf"^{action_prefix}\b", _lower_clean(part)):
            variants.append(_canonicalize_personamem_specific(part))
    return _dedupe_preserving(
        item
        for item in variants
        if item and not _personamem_low_information_preference_atom(item)
    )


def _personamem_polarity_preserving_atoms(value: Any) -> list[str]:
    """Extract compact atoms whose meaning changes if polarity is dropped.

    The visible behavior often exposes short high-value clauses such as
    preference comparisons, negative memory instructions, or health constraints.
    These are not more privileged than other evidence; they are just fragile
    under summarization, so the posterior treats them as separate typed atoms.
    """

    source = _clean_text(value)
    if not source:
        return []
    atoms: list[str] = []
    atoms.extend(_personamem_preference_comparison_atoms(source))
    atoms.extend(_personamem_negative_atoms_from_text(source))
    low = _lower_clean(source)
    if re.search(r"\ballerg(?:y|ies|ic)\b", low):
        atoms.append("allergies")
    if re.search(r"\bseasonal allergic rhinitis(?:\s+during\s+spring)?\b", low):
        atoms.append("seasonal allergic rhinitis during spring")
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if atom and not _is_personamem_generic_advice(atom)
    )


def _personamem_preference_comparison_atoms(value: Any) -> list[str]:
    source = _clean_text(value)
    if not source:
        return []
    atoms: list[str] = []
    patterns = (
        r"\bprefer(?:s|red)?\s+(?P<a>[^.;|\n]{2,100}?)\s+over\s+(?P<b>[^.;|\n]{2,90})",
        r"\bpreference\s+for\s+(?P<a>[^.;|\n]{2,100}?)\s+over\s+(?P<b>[^.;|\n]{2,90})",
        r"\bprefers?\s+(?P<a>[^.;|\n]{2,100}?)\s+(?:rather than|instead of)\s+(?P<b>[^.;|\n]{2,90})",
        r"\bprefers?\s+(?P<a>[^.;|\n]{2,100}?)\s+to\s+(?P<b>[^.;|\n]{2,90})",
        r"\bmore\s+interested\s+in\s+(?P<a>[^.;|\n]{2,100}?)\s+than\s+(?P<b>[^.;|\n]{2,90})",
        r"\binterested\s+in\s+(?P<a>[^.;|\n]{2,100}?)\s+more\s+than\s+(?P<b>[^.;|\n]{2,90})",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            left = _clean_personamem_comparison_side(match.group("a"))
            right = _clean_personamem_comparison_side(match.group("b"))
            if not left or not right:
                continue
            if _personamem_comparison_side_bad(left) or _personamem_comparison_side_bad(right):
                continue
            atoms.append(f"prefer {left} over {right}")
    return _dedupe_preserving(atoms)


def _clean_personamem_comparison_side(value: Any) -> str:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text:
        return ""
    text = re.split(
        r"\s+-\s+|\s+\b(?:given|because|while|which|where|that|and\s+(?:offers|lets|allows|provides|would)|assistant|user|memory topic|stable role|recurring preference|routine/habit|value/concern|health constraint|sensitive/private field|avoidance|prior interaction example)\b",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    text = re.sub(r"^(?:a\s+preference\s+for|preference\s+for|your\s+preference\s+for|their\s+preference\s+for)\s+", "", text, flags=re.IGNORECASE)
    text = re.sub(r"^(?:particularly|especially|very)\s+", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+", " ", text).strip(" -*,.;:'\"")
    return text[:120]


def _personamem_comparison_side_bad(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return True
    if len(text.split()) > 14:
        return True
    if _is_personamem_generic_advice(text):
        return True
    if text in {"it", "this", "that", "them", "that detail", "this detail"}:
        return True
    if re.search(
        r"\b(?:this|that|current|request|assistant|surface request|why this fits|plan item|"
        r"small\s+(?:club|cafe|restaurant|venue)|downtown|old brick buildings?|tucked between|"
        r"place was|email|post|note|draft)\b",
        text,
    ):
        return True
    return bool(re.search(r"\b(?:recommendation|assistant|surface request|why this fits|plan item)\b", text))


def _personamem_preference_comparison_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    atoms = _personamem_preference_comparison_atoms(value)
    return len(atoms) == 1 and text == _lower_clean(atoms[0])


def _personamem_polarity_preserving_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    return bool(
        _personamem_preference_comparison_atom(value)
        or _is_personamem_negative_carrier(value)
        or re.search(r"\b(?:allergies|seasonal allergic rhinitis)\b", text)
    )


def _personamem_who_predicate(value: Any) -> str:
    pred = _clean_text(value).strip(" -*,.;:'\"")
    pred = re.sub(r"^prefer\s+", "prefers ", pred, flags=re.IGNORECASE)
    pred = re.sub(r"^struggling\s+", "is struggling ", pred, flags=re.IGNORECASE)
    return pred


def _personamem_binding_role_candidates(text: Any) -> list[str]:
    source = _clean_text(text)
    if not source:
        return []
    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    descriptor = r"(?:(?!(?:a|an|as|who|role|stable|recurring|preference|memory)\b)(?:[a-z][a-z'-]*|middle school|high school|university|college)\s+){0,4}"
    candidates: list[str] = []
    for match in re.finditer(
        rf"\b(?P<role>(?:a|an)\s+{descriptor}(?:{role_terms}))\b",
        source,
        flags=re.IGNORECASE,
    ):
        role = _clean_text(match.group("role")).strip(" -*,.;:'\"")
        role = re.sub(r"^(?:a|an)\s+", "", role, flags=re.IGNORECASE).strip()
        if role:
            article = "an" if re.match(r"^[aeiou]", role, flags=re.IGNORECASE) else "a"
            candidates.append(_canonicalize_personamem_specific(f"{article} {role}"))
    for match in re.finditer(
        rf"\b(?P<role>{descriptor}(?:{role_terms}))\b",
        source,
        flags=re.IGNORECASE,
    ):
        role = _clean_text(match.group("role")).strip(" -*,.;:'\"")
        role = re.sub(r"^(?:a|an)\s+", "", role, flags=re.IGNORECASE).strip()
        if re.search(r"\b(?:volunteers?|attends?|prefers?|plays?|watches?|shops?|challenges?)\b", role, flags=re.IGNORECASE):
            continue
        if not role:
            continue
        article = "an" if re.match(r"^[aeiou]", role, flags=re.IGNORECASE) else "a"
        candidates.append(_canonicalize_personamem_specific(f"{article} {role}"))
    deduped = _dedupe_preserving(candidates)
    clean_candidates = [
        candidate for candidate in deduped if not _personamem_role_preference_fusion(candidate)
    ]
    return sorted(
        clean_candidates or deduped,
        key=_personamem_sufficient_atom_sort_key,
    )


def _personamem_binding_predicate_candidates(text: Any) -> list[str]:
    source = _clean_text(text)
    if not source:
        return []
    predicates: list[str] = []
    patterns = (
        r"\b(?P<pred>plays\s+[^.;,\n]{2,80}?\bmusic\b[^.;,\n]{0,80}?\bwhile\s+working)\b",
        r"\b(?P<pred>often\s+plays\s+[^.;,\n]{2,80}?\bmusic\b[^.;,\n]{0,80}?\bwhile\s+working)\b",
        r"\b(?P<pred>challenges?\s+(?:the\s+)?readers?\s+analysis\s+skills?\s+(?:with|through)\s+book\s+recommendations?)\b",
        r"\b(?P<pred>struggl(?:es|ing)\s+to\s+communicate\s+in\s+both\s+[^.;,\n]{2,80})\b",
        r"\b(?P<pred>volunteers?\s+as\s+[^.;,\n]{2,120})\b",
        r"\b(?P<pred>attends?\s+[^.;,\n]{2,100}?\bpanels?\s+at\s+conferences?)\b",
        r"\b(?P<pred>shops?\s+at\s+[^.;,\n]{2,100}?\bsupermarkets?\s+for\s+specialty\s+ingredients?)\b",
        r"\b(?P<pred>prefers?\s+[^.;,\n]{2,120}?\bover\s+[^.;,\n]{2,120})\b",
        r"\b(?P<pred>prefer\s+[^.;,\n]{2,120}?\bover\s+[^.;,\n]{2,120})\b",
        r"\b(?P<pred>watches?\s+[^.;,\n]{2,80}?\bwhen\s+possible)\b",
        r"\b(?P<pred>likes?\s+[^.;,\n]{2,100}?\bwhen\s+[^.;,\n]{2,80})\b",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            pred = _strip_personamem_field_certificate_tail(match.group("pred"))
            pred = re.sub(r"^(?:often\s+)", "often ", pred, flags=re.IGNORECASE)
            pred = re.sub(r"\s+\b(?:because|so that|which|for example)\b.*$", "", pred, flags=re.IGNORECASE).strip(" -*,.;:'\"")
            if pred and not _is_personamem_generic_advice(pred):
                predicates.append(_canonicalize_personamem_specific(pred))
    return _dedupe_preserving(predicates)


def _personamem_workplace_role_habit_atoms(text: Any) -> list[str]:
    """Bind a workplace-derived role to a habitual visible predicate.

    When visible evidence says someone works at a place and repeatedly performs
    a stable action there, the latent role is usually the workplace identity
    plus the habit, not a free-form task explanation.
    """

    source = _clean_text(text)
    if not source:
        return []
    atoms: list[str] = []
    workplace_patterns = (
        r"\b(?:works?|working|employed)\s+(?:at|in|for)\s+(?:a|an|the)?\s*(?P<place>coffee shop|cafe|caf[eé]|bookstore|library|museum|restaurant|school|arts center|community center|office|shop|store)\b",
        r"\b(?:our|my|their)\s+(?P<place>coffee shop|cafe|caf[eé]|bookstore|library|museum|restaurant|school|arts center|community center|office|shop|store)\b",
    )
    predicate_patterns = (
        r"\b(?P<pred>(?:often|regularly|usually|sometimes)?\s*plays\s+[^.;,\n]{2,80}?\bmusic\b(?:\s+in\s+the\s+background)?(?:\s+while\s+working)?)\b",
        r"\b(?P<pred>(?:often|regularly|usually|sometimes)?\s*(?:hosts?|organizes?|serves?|recommends?|curates?)\s+[^.;,\n]{2,100})\b",
    )
    places: list[str] = []
    for pattern in workplace_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            place = _clean_text(match.group("place")).strip(" -*,.;:'\"")
            place = re.sub(r"\bcaf[eé]\b", "cafe", place, flags=re.IGNORECASE)
            if place:
                places.append(place)
    predicates: list[str] = []
    for pattern in predicate_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            pred = _clean_text(match.group("pred")).strip(" -*,.;:'\"")
            pred = re.sub(r"^(?:often|regularly|usually|sometimes)\s+", "often ", pred, flags=re.IGNORECASE)
            pred = re.sub(r"\s+\b(?:because|so that|which|for example|and\s+(?:it|this|that))\b.*$", "", pred, flags=re.IGNORECASE)
            if pred and not _is_personamem_generic_advice(pred):
                predicates.append(pred)
    for place in _dedupe_preserving(places)[:3]:
        role = f"{place} employee"
        article = _personamem_indefinite_article(role)
        atoms.append(_canonicalize_personamem_specific(f"{article} {role}"))
        for pred in _dedupe_preserving(predicates)[:4]:
            atoms.append(_canonicalize_personamem_specific(f"{article} {role} who {_personamem_who_predicate(pred)}"))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if atom and not _is_personamem_generic_advice(atom) and len(_lower_clean(atom).split()) <= 28
    )


def _personamem_source_boundary_atoms_from_text(text: str) -> list[str]:
    """Preserve rare source-boundary phrases instead of lossy summaries."""

    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    atoms: list[str] = []
    lower = source.lower()

    prior_boundary = (
        "Selected archetype",
        "Background cue",
        "Health/Wellness cue",
        "Work/School cue",
        "Hobby/Home cue",
        "Media/Sports cue",
        "Favorite team/person/genre",
        "Current project or sector",
        "Concrete collection or object",
        "Facet",
        "Stable persona",
        "Stable role",
        "Interest",
        "Interests",
        "Routine/Habit",
        "Value/Concern",
        "Values/Concerns",
        "Constraint",
        "Prior example",
        "Prior interaction example",
        "Raw prior interaction",
        "Memory topic",
        "Topic/Domain",
    )
    boundary_re = "|".join(re.escape(label) for label in prior_boundary)
    prior_pattern = re.compile(
        rf"(?:\b(?:Raw prior interaction|Prior interaction example|Prior example|Earlier example|Earlier conversation|Visible conversation)\s*[:=]\s*)?"
        rf"(?P<prior>\bUser\s*:\s*.+?\bAssistant\s*:\s*.+?)"
        rf"(?=\s+(?:{boundary_re})\s*[:=]|$)",
        flags=re.IGNORECASE,
    )
    for match in prior_pattern.finditer(source):
        prior = _clean_text(match.group("prior")).strip(" -*,.;:'\"")
        prior = _strip_earlier_example_prefix(prior)
        if not prior or _personamem_placeholder_prior_text(prior):
            continue
        if not re.search(r"\buser\s*:\s*\S+", prior, flags=re.IGNORECASE):
            continue
        if not re.search(r"\bassistant\s*:\s*\S+", prior, flags=re.IGNORECASE):
            continue
        if re.fullmatch(r"user\s*:\s*\.{2,}\s+assistant\s*:\s*\.{2,}", prior, flags=re.IGNORECASE):
            continue
        atoms.append(prior)

    spice_pattern = r"(?:spices?\s+(?:like|such as)\s+|with\s+spices?\s+like\s+)(?P<spices>[a-z][a-z ,/&-]{2,80})"
    if "family recipes" in lower:
        for match in re.finditer(spice_pattern, source, flags=re.IGNORECASE):
            spices = _clean_text(match.group("spices")).strip(" -*,.;:'\"")
            spices = re.sub(r"\s+\b(?:in|for|when|while|and has|and values)\b.*$", "", spices, flags=re.IGNORECASE).strip(" -*,.;:'\"")
            if spices:
                atoms.append(f"cooks family recipes with spices like {spices}")
    for match in re.finditer(
        r"\b(?:skilled\s+)?gardener\b[^.;\n]{0,140}?\bdesign(?:s|ing)?\s+and\s+maintain(?:s|ing)?\s+(?P<object>[^.;\n]{3,140})",
        source,
        flags=re.IGNORECASE,
    ):
        obj = _clean_text(match.group("object")).strip(" -*,.;:'\"")
        obj = re.sub(r"\s+for\s+events?\b.*$", "", obj, flags=re.IGNORECASE).strip()
        obj = re.sub(r"\s+\b(?:for|at|during)\b\s+(?:events?|receptions?|requests?|recommendations?)\b.*$", "", obj, flags=re.IGNORECASE).strip()
        if obj:
            atoms.append(f"a skilled gardener who designs and maintains {obj}")
    for match in re.finditer(
        r"\b(?:design(?:s|ing)?\s+and\s+maintain(?:s|ing)?|maintain(?:s|ing)?\s+and\s+design(?:s|ing)?)\s+(?P<object>outdoor\s+[^.;\n]{3,120})",
        source,
        flags=re.IGNORECASE,
    ):
        obj = _clean_text(match.group("object")).strip(" -*,.;:'\"")
        if obj and "garden" in lower:
            atoms.append(f"a skilled gardener who designs and maintains {obj}")
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if atom and not _is_personamem_generic_advice(atom)
    )


def _personamem_playlist_atoms_from_text(text: str) -> list[str]:
    lower = _lower_clean(text)
    atoms: list[str] = []
    for match in re.finditer(r"\b(?P<genre>[a-z][a-z/& -]{2,60}?)\s+playlists?\b", lower):
        genre = _clean_text(match.group("genre")).strip(" -*,.;:'\"")
        genre = re.sub(r"^.*\blistens to\s+", "", genre)
        genre = re.sub(r"^(?:the user|user|usual|my)\s+", "", genre).strip()
        if not genre or any(
            marker in genre
            for marker in ("this", "that", "personalized", "ordinary", "paired with", "with ", "snacks", "games")
        ):
            continue
        genre_parts = [part.strip() for part in re.split(r"[/&]|\band\b", genre) if part.strip()]
        for part in genre_parts or [genre]:
            part = re.sub(r"\s+", " ", part).strip()
            if not part or len(part.split()) > 5:
                continue
            label = part if part.endswith("music") else f"{part} music"
            atoms.append(f"listens to {label} playlists")
    return _dedupe_preserving(atoms)


def _personamem_music_event_atoms_from_text(text: str) -> list[str]:
    source = _lower_clean(text)
    if not source:
        return []
    atoms: list[str] = []
    if re.search(r"\b(?:live\s+(?:show|shows|concert|concerts|event|events)|concerts?)\b", source):
        atoms.append("music")
        if re.search(r"\b(?:favorite|favourite)\s+artists?\b", source) or "live show" in source:
            atoms.append("like attending live concerts of favorite artists")
        elif "artist" in source:
            atoms.append("like attending live concerts by artists")
        else:
            atoms.append("like attending live concerts")
    return _dedupe_preserving(atoms)


def _personamem_contact_atoms_from_text(text: str) -> list[str]:
    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    atoms: list[str] = []
    concrete_identifier = False
    exact_key_pattern = re.compile(
        r"\b(?P<key>social_security_number|ssn|physical_address|drivers_license_number|"
        r"driver_license_number|bank_account_number|credit_card_number|email_address|"
        r"phone_number|passport_number|real_id_number|vehicle_plate_number|"
        r"llm_api_key|code_file_path|user_code_file_path)\s*[:=]\s*"
        r"(?P<value>[A-Za-z0-9@._/+() -]{6,120})",
        flags=re.IGNORECASE,
    )
    for match in exact_key_pattern.finditer(source):
        key = _personamem_canonical_sensitive_identifier_key(match.group("key"))
        value = _clean_personamem_identifier_value(match.group("value"))
        value = re.split(
            r"\s+(?:memory topic|stable role|stable persona|recurring preference|routine/habit|"
            r"value/concern|health constraint|sensitive/private field|private field|avoidance|"
            r"prior interaction example|raw prior interaction|prior example|transaction|description|"
            r"subject|dear|sincerely|email|phone|address)\b",
            value,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0]
        value = value.strip(" -*,.;:'\"")
        atom = f"{key}: {value}" if key and value else ""
        if atom and _personamem_exact_sensitive_identifier_atom(atom):
            atoms.append(atom)
            concrete_identifier = True
    for match in re.finditer(r"\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b", source):
        value = _clean_personamem_identifier_value(match.group(0).replace("@", " "))
        if value:
            atoms.append(f"email_address: {value}")
            concrete_identifier = True
    identifier_patterns = (
        (
            "driver_license_number",
            r"\b(?:driver'?s?\s+)?license(?:\s+number|\s+details)?\s*(?:is|:|\(|#)?\s*"
            r"(?P<value>(?=[A-Z0-9-]{6,28}\b)(?=[A-Z0-9-]*[0-9])[A-Z0-9-]{6,28}(?:-[A-Z]{2,4})?)",
        ),
        (
            "phone_number",
            r"\b(?:phone(?:\s+number)?|mobile(?:\s+number)?|cell(?:\s+number)?|telephone(?:\s+number)?)\s*(?:is|:|#)?\s*(?P<value>\+?[0-9][0-9() .-]{6,24}[0-9])",
        ),
        (
            "passport_number",
            r"\b(?:passport(?:\s+(?:number|no\.?))?|passport\s*#)\s*(?:is|:|#)?\s*(?P<value>(?=[A-Za-z0-9-]{6,20}\b)(?=[A-Za-z0-9-]*[0-9])[A-Za-z][A-Za-z0-9-]{5,20})",
        ),
        (
            "vehicle_plate_number",
            r"\b(?:vehicle\s+)?(?:plate|licen[cs]e\s+plate)(?:\s+(?:number|no\.?))?\s*(?:is|:|#)?\s*"
            r"(?P<value>(?=[A-Z0-9 -]{5,16}\b)(?=[A-Z0-9 -]*[0-9])[A-Z0-9][A-Z0-9 -]{3,14}[A-Z0-9])",
        ),
        ("bank_account_number", r"\bbank\s+account\s+number\s*(?:is|:|#)?\s*(?P<value>[0-9][0-9 -]{7,30})"),
        (
            "credit_card_number",
            r"\b(?:credit\s+card(?:\s+(?:number|data|details))?|business\s+credit\s+card|"
            r"full\s+(?:credit\s+)?card\s+number|card\s+number)\s*(?:is|:|#|\()?\s*"
            r"(?P<value>[0-9][0-9 -]{11,24})",
        ),
        ("social_security_number", r"\b(?:social\s+security\s+number|ssn)\s*(?:is|:|#)?\s*(?P<value>[0-9]{3}-?[0-9]{2}-?[0-9]{4})"),
        ("real_id_number", r"\b(?:real\s+id(?:\s+number)?|realid)\s*(?:number\s*)?(?:is|:|#)?\s*(?P<value>[A-Z]{1,4}-?REALID-[0-9-]{6,24}|[A-Z]{1,4}-[A-Z0-9-]{8,28})"),
        ("llm_api_key", r"\b(?:llm[_ -]?api[_ -]?key|api[_ -]?key)\s*(?:is|:|=|\()\s*(?P<value>[A-Za-z0-9_-]{12,80})\)?"),
    )
    for label, pattern in identifier_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _clean_personamem_identifier_value(match.group("value"))
            atom = f"{label}: {value}" if value else ""
            if atom and _personamem_exact_sensitive_identifier_atom(atom):
                atoms.append(atom)
                concrete_identifier = True
                if label == "social_security_number":
                    atoms.append(f"ssn: {value}")
    for path_literal in _personamem_path_literals_from_text(source):
        atoms.append(path_literal)
        atoms.append(f"code_file_path: {path_literal}")
        concrete_identifier = True
    concrete_sensitive_hint = concrete_identifier or bool(
        re.search(
            r"\b(?:redact(?:ed)?|masked|sensitive data|personal sensitive|secret|credential|"
            r"license(?:\s+number)?|license plate|vehicle plate|plate number|passport|ssn|social security|credit card|bank account|"
            r"api[_ -]?key|email address|phone number|file path|computer at|saved on)\b",
            source,
            flags=re.IGNORECASE,
        )
    )
    if concrete_sensitive_hint:
        atoms.append("sensitive_info")
    if concrete_identifier or re.search(r"\b(?:data privacy|privacy constraint|redact(?:ed)?|masked|credential)\b", source, flags=re.IGNORECASE):
        atoms.append("Values data privacy")
    return _dedupe_preserving(atoms)


def _personamem_path_literals_from_text(text: Any) -> list[str]:
    """Extract exact local path literals as typed high-information carriers."""

    source = str(text or "")
    if not source:
        return []
    atoms: list[str] = []
    path_patterns = (
        r"(?P<path>/(?:Users|home|var|tmp|opt|mnt|srv|Volumes|projects?|workspace|data)/[A-Za-z0-9._+/@ -]+(?:/[A-Za-z0-9._+@ -]+){1,}/?)",
        r"(?P<path>[A-Za-z]:\\(?:Users|Documents|Projects|Workspace|Data|Temp|tmp)\\[A-Za-z0-9._+@() -]+(?:\\[A-Za-z0-9._+@() -]+){1,}\\?)",
    )
    for pattern in path_patterns:
        for match in re.finditer(pattern, source):
            path = _clean_text(match.group("path")).strip(" -*,.;:'\"()[]{}")
            path = re.sub(r"\s+", "", path)
            if not path:
                continue
            if len(path) < 8 or len(path) > 180:
                continue
            if re.search(r"\b(?:http|https|www)\b", path, flags=re.IGNORECASE):
                continue
            atoms.append(path)
    return _dedupe_preserving(atoms)


def _personamem_path_literal_atom(value: Any) -> bool:
    text = _clean_text(value).strip(" -*,.;:'\"()[]{}")
    if not text:
        return False
    return bool(
        re.match(r"^/(?:Users|home|var|tmp|opt|mnt|srv|Volumes|projects?|workspace|data)/.+/.+", text)
        or re.match(r"^[A-Za-z]:\\(?:Users|Documents|Projects|Workspace|Data|Temp|tmp)\\.+\\.+", text)
    )


def _personamem_source_factor_graph_atoms(text: Any) -> list[str]:
    """Factor one visible prior into independent latent-state variables.

    The source prior is a joint observation: it may reveal a role, a stable
    activity, an affective constraint, and a topical support variable at once.
    This extractor keeps those factors separate so the final small projection
    can maximize coverage instead of retaining only a single verbose paraphrase.
    """

    source = _segment_personamem_field_certificate_text(_clean_text(text))
    low = _lower_clean(source)
    if not low:
        return []
    atoms: list[str] = []

    atoms.extend(_personamem_contact_atoms_from_text(source))
    atoms.extend(_personamem_negative_atoms_from_text(source))
    atoms.extend(_personamem_health_constraint_atoms_from_text(source))
    atoms.extend(_personamem_choice_certificate_atoms_from_text(source))
    atoms.extend(_personamem_lossless_typed_certificate_atoms_from_text(source))

    if re.search(r"\b(?:clear night skies?|night skies?|stargazing|constellations?|astronomy)\b", low):
        atoms.append("astronomy")
        if re.search(r"\b(?:appreciates?|favors?|enjoys?|likes?|loves?)\b", low):
            atoms.append("appreciates clear night skies for stargazing")

    if re.search(r"\b(?:improv(?:isation)?|improv classes?|performers?|character arc|theatre|theater)\b", low):
        atoms.append("theatre")
        if re.search(r"\b(?:participat(?:e|es|ing)|attends?|takes?|enjoys?|likes?|loves?)\b", low):
            atoms.append("enjoys participating in improv classes")

    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    retirement_match = re.search(
        rf"\b(?P<role>(?:a|an)\s+[^.;,\n]{{0,110}}\b(?:{role_terms})\b)"
        r"(?P<tail>[^.;,\n]{0,120}\b(?:planning|plans?|hopes?)\s+to\s+retire\s+soon\b)",
        source,
        flags=re.IGNORECASE,
    )
    if retirement_match:
        role = _clean_text(retirement_match.group("role")).strip(" -*,.;:'\"")
        if role:
            atoms.append(f"{role} who is planning to retire soon")

    for match in re.finditer(
        r"\b(?P<role>(?:a|an)\s+[^.;,\n]{0,90}\b(?:student|artist|designer|photographer|writer|researcher|teacher)\b)"
        r"[^.;,\n]{0,180}\b(?:is\s+)?(?:constantly\s+)?(?:inspired|influenced|motivated)\s+by\s+"
        r"(?P<object>[^.;,\n]{3,180})",
        source,
        flags=re.IGNORECASE,
    ):
        role = _clean_text(match.group("role")).strip(" -*,.;:'\"")
        obj = _clean_text(match.group("object")).strip(" -*,.;:'\"")
        if role and obj and len(obj.split()) <= 22:
            atoms.append(f"{role} who is constantly inspired by {obj}")

    if re.search(r"\b(?:coding|hackathons?|bootcamps?|tech solutions?|technology)\b", low):
        atoms.append("technology")
        if re.search(r"\b(?:loves?|enjoys?|attends?|attending|participates?|joining)\b", low):
            atoms.append("loves attending technology hackathons and coding bootcamps")

    if re.search(r"\b(?:virtual listening parties?|streaming setlists?|listening parties?)\b", low):
        atoms.append("organizes virtual listening parties and discussions on social media")
        fan_match = re.search(
            r"\b(?P<fan>(?:dedicated|huge|longtime|long-time|devoted)?\s*[^.;,\n]{0,40}?\bfan)\b",
            source,
            flags=re.IGNORECASE,
        )
        artist_match = re.search(r"\b(?:outkast|jazz|blues|hip[- ]hop|indie|folk|classical)\b", low)
        if fan_match and artist_match:
            fan = _clean_text(fan_match.group("fan")).strip(" -*,.;:'\"")
            if "outkast" in low:
                atoms.append("a dedicated outkast fan who organizes virtual listening parties and discussions on social media")
            elif fan:
                atoms.append(f"{_personamem_article_for(fan)} {fan} who organizes virtual listening parties and discussions on social media")

    if re.search(r"\b(?:harsh|gray|grey|gloomy|constant gray skies|barely going outside)\b", low) and re.search(
        r"\b(?:winter|winters|chicago|cold weather)\b",
        low,
    ) and re.search(r"\b(?:mood|motivation|down|creative drive|adapt)\b", low):
        city = "chicago" if "chicago" in low else ""
        if city:
            atoms.append(f"found it difficult to adapt to harsh {city} winters, affecting mood and motivation")
        else:
            atoms.append("found it difficult to adapt to harsh winters, affecting mood and motivation")

    if re.search(r"\b(?:homesick|homesickness|miss(?:es|ing)? home|familiarity of home|quiet from back home|far from home)\b", low):
        origin = _personamem_source_factor_place_after(source, r"\bfrom\s+")
        destination = _personamem_source_factor_place_after(source, r"\b(?:to|in|here in)\s+")
        if origin and destination and origin.lower() != destination.lower():
            atoms.append(f"coping with homesickness after moving far from {origin} to {destination}")
        else:
            atoms.append("coping with homesickness after moving far from home")

    if re.search(r"\bexchange student\b", low):
        atoms.append("an exchange student")
        if re.search(r"\b(?:explore the world|exploring the world|world while maintaining|high gpa|maintaining a high gpa)\b", low):
            atoms.append("another exchange student who decided to explore the world while maintaining a high gpa")

    if re.search(r"\bnative from\b", low) and re.search(r"\b(?:lives abroad|living abroad|now lives abroad|now lives)\b", low):
        native_match = re.search(
            r"\bnative from\s+(?P<place>[^.;,\n]{3,120}?)(?:\s+who\s+now\s+lives|\s+who\s+lives|\s+and\s+now\s+lives|\s*,)",
            source,
            flags=re.IGNORECASE,
        )
        if native_match:
            place = _clean_text(native_match.group("place")).strip(" -*,.;:'\"")
            atoms.append(f"a native from {place}, who now lives abroad")

    if re.search(r"\b(?:suspicious mole|mole on (?:her|his|their) arm|skin lesion)\b", low):
        atoms.append("a young woman concerned about a suspicious mole on her arm")
        atoms.append("health_and_medical")

    if re.search(r"\bcomputer science professor\b", low) and re.search(
        r"\bskeptical\b.+\bai detection tools?\b|\bai detection tools?\b.+\bskeptical\b",
        low,
    ):
        atoms.append("a computer science professor skeptical about ai detection tools")

    if re.search(r"\b(?:action[- ]packed\s+)?superhero movies?\b", low):
        if re.search(r"\baction[- ]packed\b", low):
            atoms.append("watches action-packed superhero movies")
        else:
            atoms.append("watches superhero movies")

    if re.search(r"\b(?:openly\s+)?proud\s+gay\s+business(?:man|woman|person)\b", low) and re.search(
        r"\b(?:lgbtq|gay|queer|support(?:ing|s)?|cause)\b",
        low,
    ):
        atoms.append("an openly proud gay businessman who funds and promotes gay and lgbtq-related causes")

    if re.search(r"\b(?:hiv|aids)\b", low) and re.search(
        r"\b(?:close friend|friend|loss|lost|grief|survivor)\b",
        low,
    ):
        atoms.append("lost a close friend to hiv/aids,which triggered unresolved grief and survivors guilt")

    if re.search(r"\b(?:spring food festival|food festival|culinary collective|juice bar|local food vendors?|freshness and local products)\b", low):
        atoms.append("food")

    if re.search(r"\b(?:front desk|hotel availability|secured (?:him|her|them)?\s*(?:a\s+)?(?:king\s+)?room|lodging coordination|partner hotels?|accommodation)\b", low) and re.search(
        r"\b(?:traveling salesman|jon pardi|tour locations?|reno events center)\b",
        low,
    ):
        atoms.append("a front desk staff member at various hotels who assists the traveling salesman in finding accommodation near Jon Pardi's tour locations")

    if re.search(r"\b(?:fork[- ]and[- ]knife|fork and knife|forks and knives)\b", low):
        if re.search(r"\bchopsticks\b", low) or re.search(r"\bmore often than\b", low):
            atoms.append("uses a fork and knife more often than chopsticks at home")
        else:
            atoms.append("uses forks and knives at home often")

    if re.search(r"\b(?:law enforcement officer|local law enforcement|officer from georgia|police officer)\b", low):
        if re.search(r"\bgeorgia\b", low) and re.search(r"\b(?:professional development|continuous professional|training|development)\b", low):
            atoms.append("a local law enforcement officer from georgia,usa who seeks continuous professional development")
        if re.search(r"\b(?:close colleague|partner|colleague)\b", low) and re.search(r"\bline of duty\b", low):
            atoms.append("experienced the death of a close colleague in the line of duty,prompting deep grief and survivors guilt")

    if re.search(r"\b(?:death of a close colleague|colleague'?s death|colleague in the line of duty)\b", low) and re.search(
        r"\b(?:line of duty|deep grief|survivors guilt|survivor'?s guilt)\b",
        low,
    ):
        atoms.append("experienced the death of a close colleague in the line of duty,prompting deep grief and survivors guilt")

    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(atom)
    )


def _personamem_source_factor_place_after(source: str, prefix_pattern: str) -> str:
    match = re.search(
        prefix_pattern + r"(?P<place>[A-Z][A-Za-z .'-]{2,80}?)(?=\s*(?:,|\.|;|and|to|from|for|with|$))",
        source,
        flags=re.IGNORECASE,
    )
    if not match:
        return ""
    place = _clean_text(match.group("place")).strip(" -*,.;:'\"")
    place = re.sub(r"\b(?:classes|internship|work|home|school|university|college)$", "", place, flags=re.IGNORECASE).strip()
    if not place or len(place.split()) > 6:
        return ""
    return place


def _personamem_source_factor_graph_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or _is_personamem_conversation(value):
        return False
    if _personamem_lossless_typed_certificate_atom(value):
        return True
    if _is_personamem_sensitive_carrier(value) or _is_personamem_negative_carrier(value):
        return True
    if _personamem_truncated_projection_fragment(value):
        return False
    if not _personamem_sufficient_factor_complete_clause(value):
        return False
    if _is_personamem_topic_atom(text):
        return text in {"technology", "health_and_medical", "music", "loneliness", "sports", "literature", "astronomy", "theatre"}
    return bool(
        re.search(
            r"\b(?:virtual listening parties?|harsh .*winters|affecting mood and motivation|"
            r"homesickness|moving far from|exchange student|explore the world|high gpa|"
            r"technology hackathons?|coding bootcamps?|native from\b.+\blives abroad|"
            r"suspicious mole|law enforcement officer from georgia|officer from georgia|"
            r"continuous professional development|close colleague in the line of duty|"
            r"death of a close colleague|survivors guilt|front desk staff|"
            r"finding accommodation|lodging coordination|fork and knife|forks and knives|"
            r"food festival|juice bar|local food vendors?|clear night skies?|stargazing|"
            r"astronomy|improv classes?|participating in improv|planning to retire soon|"
            r"computer science professor|ai detection tools?|superhero movies?|"
            r"openly proud gay business(?:man|woman|person)|lgbtq-related causes?|"
            r"close friend to hiv/aids|unresolved grief over losing a close friend|"
            r"inspired by|history of .*?(?:accident|fall|strain|sprain)|"
            r"(?:accident|fall|strain|sprain).*?(?:stiffness|pain|ache|injury))\b",
            text,
        )
    )


def _personamem_source_factor_graph_score(value: Any) -> int:
    text = _lower_clean(value)
    score = 0
    if _is_personamem_sensitive_carrier(value):
        score += 520
    if _is_personamem_negative_carrier(value):
        score += 500 + _personamem_negative_intervention_quality_score(value)
    if text in {"technology", "health_and_medical", "music", "loneliness", "sports", "literature", "astronomy", "theatre"}:
        score += 180
    if re.search(r"\b(?:harsh .*winters|affecting mood and motivation|homesickness|moving far from)\b", text):
        score += 330
    if re.search(r"\b(?:found it difficult|difficulty adapting|difficult to adapt|coping with homesickness after moving far)\b", text):
        score += 70
    if re.search(r"\b(?:virtual listening parties?|discussions on social media|technology hackathons?|coding bootcamps?)\b", text):
        score += 300
    if re.search(r"\b(?:exchange student|native from\b.+\blives abroad|suspicious mole)\b", text):
        score += 260
    if re.search(r"\bcomputer science professor\b", text) and re.search(r"\bai detection tools?\b", text):
        score += 430
    if re.search(r"\b(?:action[- ]packed\s+)?superhero movies?\b", text):
        score += 380
    if re.search(r"\b(?:openly\s+)?proud\s+gay\s+business(?:man|woman|person)\b", text):
        score += 340
    if re.search(r"\b(?:lgbtq|gay|queer)[- ]related causes?\b|\bsupports? lgbtq\b", text):
        score += 330
    if re.search(r"\b(?:close friend to hiv/aids|unresolved grief over losing a close friend|survivors guilt)\b", text):
        score += 430
    if _personamem_lossless_typed_certificate_atom(value):
        score += 520
    if re.search(r"\b(?:law enforcement officer from georgia|officer from georgia|continuous professional development)\b", text):
        score += 320
    if re.search(r"\b(?:law enforcement officer|officer from georgia)\b", text) and re.search(r"\bcontinuous professional development\b", text):
        score += 130
    if re.search(r"\b(?:death of a close colleague|line of duty|survivors guilt)\b", text):
        score += 340
    if re.search(r"\b(?:death of a close colleague|line of duty)\b", text) and re.search(r"\bsurvivors guilt\b", text):
        score += 120
    if re.search(r"\b(?:front desk staff|finding accommodation|lodging coordination|hotel availability|partner hotels?)\b", text):
        score += 430
    if re.search(r"\b(?:fork and knife|forks and knives|chopsticks)\b", text):
        score += 360
    if text == "food" or re.search(r"\b(?:food festival|juice bar|local food vendors?)\b", text):
        score += 260
    if re.search(r"\b(?:clear night skies?|stargazing|astronomy)\b", text):
        score += 360
    if re.search(r"\b(?:improv classes?|participating in improv|theatre)\b", text):
        score += 360
    if re.search(r"\bplanning to retire soon\b", text):
        score += 340
    if re.search(r"\binspired by\b", text):
        score += 300
    if re.search(r"\b(?:history of .*?(?:accident|fall|strain|sprain)|(?:accident|fall|strain|sprain).*?(?:stiffness|pain|ache|injury))\b", text):
        score += 360
    score += max(0, 30 - len(text.split()))
    return score


def _personamem_typed_program_factor_atoms_from_text(text: Any) -> list[str]:
    """Split visible PersonaMem evidence into independently selectable atoms."""

    source = _segment_personamem_field_certificate_text(_clean_text(text))
    low = _lower_clean(source)
    if not low:
        return []
    atoms: list[str] = []

    atoms.extend(_personamem_contact_atoms_from_text(source))
    atoms.extend(_personamem_causal_sufficient_profile_atoms_from_text(source))

    for match in re.finditer(
        r"\b(?:sensitive/private field|private field|sensitive field)\s*[:=]\s*(?P<value>[0-9][0-9 -]{7,30})",
        source,
        flags=re.IGNORECASE,
    ):
        value = _clean_personamem_identifier_value(match.group("value"))
        if not value:
            continue
        if re.search(r"\b(?:credit card|card number|full card|payment card)\b", low):
            atoms.append(f"credit_card_number: {value}")
        elif re.search(r"\b(?:bank account|account number)\b", low):
            atoms.append(f"bank_account_number: {value}")
        elif re.search(r"\b(?:phone|mobile|cell)\b", low):
            atoms.append(f"phone_number: {value}")
        atoms.append("sensitive_info")

    if re.search(r"\b(?:evening|usual)\s+walk\b|\bwalk around (?:the|your|my|his|her)?\s*neighbou?rhood\b", low) and re.search(
        r"\b(?:unwind|clear(?:s|ing)? (?:my|your|his|her|their)?\s*mind|clear(?:s)? (?:my|your|his|her|their)?\s*head|decompress|relax)\b",
        low,
    ):
        atoms.append("takes evening walks to unwind")

    if re.search(r"\bsoftware engineer\b", low) and re.search(r"\bflight simulator\b", low) and re.search(
        r"\b(?:add[- ]ons?|mods?|enhance|enhancement|instrumentation|glare shield|night[- ]lighting|terrain mesh)\b",
        low,
    ):
        atoms.append("a software engineer who develops add-ons and mods to enhance the flight simulator experience")

    baseball_context = re.search(r"\b(?:baseball|braves|hank aaron|hammerin hank|ballpark)\b", low)
    if baseball_context:
        atoms.append("sports")
        if re.search(r"\b(?:hank aaron|hammerin hank)\b", low) and re.search(
            r"\b(?:fan|adores?|admires?|loves?|love for|stories? my dad told|familys love)\b",
            low,
        ):
            atoms.append("a passionate baseball fan who adores hank aaron")
        if re.search(r"\b(?:collects?|collecting|collection|display|shadow box|centerpiece|memorabilia)\b", low) and re.search(
            r"\b(?:baseball cards?|card collection|hank aaron card|sports memorabilia|ticket stubs?|programs?)\b",
            low,
        ):
            atoms.append("collects sports memorabilia, especially baseball cards")

    if re.search(r"\bsports memorabilia\b", low) and re.search(r"\bbaseball cards?\b", low):
        atoms.append("sports")
        atoms.append("collects sports memorabilia, especially baseball cards")

    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(atom)
    )


def _personamem_causal_sufficient_profile_atoms_from_text(text: Any) -> list[str]:
    """Extract compact atoms that causally explain repeated personalized behavior."""

    source = _segment_personamem_field_certificate_text(_clean_text(text))
    low = _lower_clean(source)
    if not low:
        return []
    atoms: list[str] = []

    child_language = re.search(
        r"\b(?:child|daughter|son|kid|student)\b(?P<span>[^.;\n]{0,240}?"
        r"(?:read(?:ing)?|write|writing)[^.;\n]{0,160}?"
        r"\b(?P<lang>hindi|spanish|french|english|mandarin|chinese|japanese|korean|arabic|german|italian)\b)",
        low,
    )
    if not child_language:
        child_language = re.search(
            r"\b(?P<lang>hindi|spanish|french|english|mandarin|chinese|japanese|korean|arabic|german|italian)\b"
            r"[^.;\n]{0,180}\b(?:read(?:ing)?|write|writing)\b[^.;\n]{0,180}\b(?:child|daughter|son|kid|student)\b",
            low,
        )
    if child_language and re.search(r"\b(?:teach(?:es|ing)?|help(?:ing)?|develop|practice|learn(?:ing)?)\b", low):
        atoms.append(f"teaches child to read and write in {child_language.group('lang')}")

    if (
        re.search(r"\b(?:worried|urgent|rush(?:es|ed|ing)?|immediate|sudden(?:ly)?)\b", low)
        and re.search(r"\b(?:daughter|son|child|kid)\b", low)
        and re.search(r"\b(?:allerg(?:y|ic)|allergist|reaction|treatment)\b", low)
    ):
        atoms.append("a worried mother who rushes to find an allergist to provide immediate treatment")
        atoms.append("allergies")
        atoms.append("health_and_medical")

    if re.search(r"\bworried mother\b", low) and re.search(r"\b(?:allergist|allerg(?:y|ic)|immediate treatment|urgent)\b", low):
        atoms.append("a worried mother who rushes to find an allergist to provide immediate treatment")

    if re.search(r"\bsprained\s+ankle\b", low):
        atoms.append("injury")
        atoms.append("health_and_medical")
        if re.search(r"\b(?:basketball|recreational game|shooting sessions?|half[- ]court)\b", low):
            atoms.append("past sprained ankle from a recreational basketball game")

    if re.search(r"\bnorth american football\b", low) and re.search(r"\b(?:ice hockey|hockey)\b", low):
        if re.search(r"\b(?:follows?|following|fan|closely|winter sports|sporting events?)\b", low):
            atoms.append("follows north american football and ice hockey closely")
        atoms.append("sports")

    if re.search(r"\b(?:human resources|hr director|diversity and inclusion|inclusion initiatives?)\b", low) and re.search(
        r"\b(?:policies|policy|dignity|autonomy|personal freedoms?|individual freedom|infring(?:e|es|ing))\b",
        low,
    ):
        atoms.append("a human resources director who doesnt like policies that infringe upon personal freedoms")

    if re.search(r"\b(?:book clubs?|literature group|literary group)\b", low) and re.search(r"\b(?:women|womens|women's|systemic barriers)\b", low):
        atoms.append("participates in book clubs focused on womens literature")
        atoms.append("literature")

    if re.search(r"\b(?:vinyl reissues?|record label|labels online posts?)\b", low) and re.search(
        r"\b(?:licensing|production|vinyl|reissues?|record label)\b",
        low,
    ):
        atoms.append("a seasoned industry professional who oversees the licensing and production of vinyl reissues")

    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(str(atom))
    )


def _clean_personamem_identifier_value(value: str) -> str:
    cleaned = str(value or "").strip(" -*,.;:'\"()[]{}")
    cleaned = re.sub(r"\s+", " ", cleaned)
    if not cleaned or re.fullmatch(r"0{5,}|x{3,}|redacted", cleaned, flags=re.IGNORECASE):
        return ""
    return cleaned[:120]


def _personamem_health_constraint_atoms_from_text(text: str) -> list[str]:
    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    atoms: list[str] = []
    patterns = (
        r"\b(?P<value>(?:past\s+)?(?:episode|history)\s+of\s+[^.;,\n]{0,80}?(?:gastritis|food poisoning|sinus issues?)[^.;,\n]{0,80})",
        r"\b(?P<value>[^.;,\n]{2,100}?\ballergy\b[^.;,\n]{0,80}?\bmanaged with [^.;,\n]{2,80})",
        r"\b(?P<value>[^.;,\n]{2,100}?\b(?:cannot|can't|unable to)\s+travel\b[^.;,\n]{0,100}?\b(?:health|medical)[^.;,\n]{0,80})",
        r"\b(?P<value>(?:has\s+)?struggled\s+with\s+physical\s+exhaustion\s+after\s+pushing\s+through\s+illness(?:\s+to\s+complete\s+[^.;,\n]{2,120})?)",
        r"\b(?P<value>(?:uses?|using|on)\s+low-dose\s+testosterone\s+therapy(?:\s+with\s+regular\s+monitoring)?)",
        r"\b(?P<value>(?:confronting|harbors?|carrying|has|dealing with)\s+(?:the\s+)?unresolved\s+grief\s+over\s+(?:my|her|his|their)?\s*father[’']?s\s+assassination[^.;,\n]{0,120})",
        r"\b(?P<value>(?:the\s+)?unresolved\s+grief\s+over\s+(?:my|her|his|their)?\s*father[’']?s\s+assassination[^.;,\n]{0,120})",
        r"\b(?P<value>childhood\s+history\s+of\s+[^.;,\n]{3,120}?(?:asthma|migraine|diabetes|allergy|injury)[^.;,\n]{0,80})",
        r"\b(?P<value>surgical\s+repair\s+of\s+[^.;,\n]{3,130}?(?:injury|tear)[^.;,\n]{0,80})",
        r"\b(?P<value>repair\s+of\s+[^.;,\n]{3,130}?(?:injury|tear)[^.;,\n]{0,80})",
        r"\b(?P<value>history\s+of\s+[^.;,\n]{3,120}?(?:accident|fall|strain|sprain)[^.;,\n]{0,120}?(?:stiffness|pain|ache|injury)[^.;,\n]{0,80})",
        r"\b(?P<value>[^.;,\n]{3,120}?(?:accident|fall|strain|sprain)[^.;,\n]{0,120}?(?:stiffness|pain|ache|injury)[^.;,\n]{0,80})",
        r"\b(?P<value>(?:mild\s+)?seasonal\s+allerg(?:y|ies)(?:\s+to\s+[^.;,\n]{2,80})?)",
        r"\b(?P<value>(?:tree|grass|ragweed|spring|flower)\s+pollen(?:\s+allerg(?:y|ies))?)",
        r"\bfamily history of (?P<value>[^.;,\n]{2,100})",
        r"\b(?:diagnosed with|manages|has|deals with|lives with)\s+(?P<value>(?:a |an )?[^.;,\n]{2,100}?(?:condition|allergy|intolerance|asthma|migraine|cholesterol|diabetes|eczema|pain|injury|prescription|medication)[^.;,\n]{0,80})",
        r"\b(?P<value>[A-Za-z][A-Za-z -]{1,60}\s+(?:allergy|intolerance))\b",
        r"\ballergic to (?P<value>[^.;,\n]{2,80})",
        r"\bintolerant to (?P<value>[^.;,\n]{2,80})",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _strip_personamem_field_certificate_tail(match.group("value"))
            if not value:
                continue
            value = re.sub(r"\s+\b(?:while|and)\s+(?:enjoying|maintaining|looking for)\b.*$", "", value, flags=re.IGNORECASE).strip(" -*,.;:'\"")
            if re.search(r"\blow-dose\s+testosterone\s+therapy\b", value, flags=re.IGNORECASE):
                value = re.sub(r"^(?:using|on)\s+", "uses ", value, flags=re.IGNORECASE)
            if re.search(r"\bunresolved\s+grief\b", value, flags=re.IGNORECASE) and re.search(r"\bfather[’']?s\s+assassination\b", value, flags=re.IGNORECASE):
                atoms.append("harbors unresolved grief over her fathers assassination and its role in shaping her path")
            if pattern.startswith(r"\bfamily history"):
                atoms.append(f"family history of {value}")
            elif "allergic to" in pattern:
                atoms.append(f"allergic to {value}")
            elif "intolerant to" in pattern:
                atoms.append(f"intolerant to {value}")
            else:
                atoms.append(value)
    if re.search(
        r"\b(?:spring|seasonal|pollen|maple|oak|blossom|new leaves|tree pollen)\b",
        source,
        flags=re.IGNORECASE,
    ) and re.search(
        r"\b(?:tickle in (?:the )?nose|itchy eyes|watery eyes|dab at (?:the )?(?:corners of )?(?:my |her |his |their )?eyes|"
        r"brush at (?:my |her |his |their )?eyes|sneez(?:e|ing)|season working its mischief)\b",
        source,
        flags=re.IGNORECASE,
    ):
        atoms.append("mild seasonal allergies to tree pollen")
    if re.search(r"\b(?:medical|health(?:/diet)?|dietary(?:/health)?)\s+constraint\b", source, flags=re.IGNORECASE):
        for match in re.finditer(r"\b(?:medical|health(?:/diet)?|dietary(?:/health)?)\s+constraint\s*[:=]\s*(?P<value>[^.;\n]{3,160})", source, flags=re.IGNORECASE):
            atoms.append(_strip_personamem_field_certificate_tail(match.group("value")))
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if atom and _lower_clean(atom) not in {"health/diet", "dietary/health"} and not _is_personamem_generic_advice(atom)
    )


_PERSONAMEM_FIELD_CERTIFICATE_SOURCE_RE = re.compile(
    r"\b(?:Domain|Stable persona|Stable role|Role/Background|Background/Role|Identity/Background|Background/Identity|"
    r"Interests?|Responsibilities/Routine|"
    r"Responsibilities|Routine|Routine/Habit|Habit|Background phrase|Preference phrase|"
    r"Source phrase|Lossless cue|Recurring preference|Value/Concern|Values/Concerns|Concern|Concerns|"
    r"Underlying reason|Concrete condition|Health/Diet constraint|Dietary/Health constraint|"
    r"Health constraint|Contact/Account detail|Contact detail|Account detail|"
    r"Privacy constraint|Constraint|Disclosure-safe detail|Sensitive/Private field|"
    r"Private field|Correction/Avoidance|Correction|Avoidance|Memory topic|"
    r"Prior interaction example|Raw prior interaction|Prior example|Chosen cue|Concrete preference|Reusable cue|"
    r"Reusable personal cause|Personal cue|Source detail|Topic/Domain)\s*[:=]",
    flags=re.IGNORECASE,
)


def _is_personamem_field_certificate_source(value: Any) -> bool:
    text = _segment_personamem_field_certificate_text(value)
    if not text:
        return False
    return _is_personamem_field_certificate_source_text(text)


@lru_cache(maxsize=4096)
def _is_personamem_field_certificate_source_text(text: str) -> bool:
    return bool(_PERSONAMEM_FIELD_CERTIFICATE_SOURCE_RE.search(text))


def _personamem_certificate_priority_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _is_personamem_conversation(value):
        return False
    if _is_personamem_negative_carrier(value) or _is_personamem_sensitive_carrier(value):
        return True
    if _is_personamem_topic_atom(text):
        return text in {
            "health_and_medical",
            "sensitive_info",
            "entertainment",
            "literature",
            "culture",
            "grief",
            "depression",
            "technology",
            "sports",
        }
    if _is_personamem_persona_carrier(value) and len(text.split()) >= 5:
        return True
    if re.search(
        r"\b(?:migraine|allerg|intoleran|deficien|pregnan|medical episode|mood|grief|workplace|"
        r"musicals?|novels?|technical domain|software|coding|sports?|training|"
        r"stress|burnout|exhaustion|travel limitation|cannot travel|unable to attend|"
        r"screen time|health condition|medical|privacy|credential)\b",
        text,
    ):
        return True
    return _personamem_high_precision_specific_atom(value)


def _regularize_personamem_posterior(model: Mapping[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    """Apply posterior cardinality constraints induced by PersonaMem's public carrier layout."""

    regularized = copy.deepcopy(dict(model))
    original_facts = [item for item in _clean_text_list(regularized.get("facts", []))]
    regularized["facts"] = original_facts[:1]

    preferences = _clean_text_list(regularized.get("preferences", []))
    unwrapped_preferences = _dedupe_preserving(
        value
        for item in preferences
        for value in _backend_projection_unwrapped_values(item)
    )
    preferences = _dedupe_preserving([*preferences, *unwrapped_preferences])
    posterior_profile_sources = [
        *preferences,
        *original_facts[1:],
        *_clean_text_list(regularized.get("constraints", [])),
        _clean_text(regularized.get("raw_text", "")),
    ]
    metadata = regularized.get("metadata", {})
    reservoir_field_map = (
        metadata.get("personamem_reservoir_field_map", {})
        if isinstance(metadata, Mapping)
        else {}
    )
    reservoir_field_cover_atoms = (
        _clean_text_list(reservoir_field_map.get("field_cover_atoms", []))
        if isinstance(reservoir_field_map, Mapping)
        else []
    )
    reservoir_sufficient_field_atoms = (
        _clean_text_list(reservoir_field_map.get("sufficient_field_atoms", []))
        if isinstance(reservoir_field_map, Mapping)
        else []
    )
    if isinstance(metadata, Mapping):
        reservoir_sufficient_field_atoms = _dedupe_preserving(
            [
                *reservoir_sufficient_field_atoms,
                *_clean_text_list(metadata.get("personamem_monotone_sufficient_atoms", [])),
            ]
        )
    reservoir_choice_certificate_atoms = (
        _clean_text_list(metadata.get("personamem_choice_certificate_atoms", []))
        if isinstance(metadata, Mapping)
        else []
    )
    reservoir_lossless_certificate_atoms = (
        _clean_text_list(metadata.get("personamem_lossless_certificate_atoms", []))
        if isinstance(metadata, Mapping)
        else []
    )
    if reservoir_choice_certificate_atoms or reservoir_lossless_certificate_atoms:
        reservoir_field_cover_atoms = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving([*reservoir_choice_certificate_atoms, *reservoir_lossless_certificate_atoms, *reservoir_field_cover_atoms])
        )
    reservoir_field_atoms = (
        _clean_text_list(reservoir_field_map.get("field_atoms", []))
        if isinstance(reservoir_field_map, Mapping)
        else []
    )
    if reservoir_choice_certificate_atoms or reservoir_lossless_certificate_atoms:
        reservoir_field_atoms = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving([*reservoir_choice_certificate_atoms, *reservoir_lossless_certificate_atoms, *reservoir_field_atoms])
        )
    reservoir_ledger_atoms = (
        _clean_text_list(reservoir_field_map.get("ledger_atoms", []))
        if isinstance(reservoir_field_map, Mapping)
        else []
    )
    posterior_profile_atoms = _personamem_profile_atoms_from_posterior_texts(
        posterior_profile_sources
    )
    field_certificate_sources = [
        item for item in posterior_profile_sources if _is_personamem_field_certificate_source(item)
    ]
    field_certificate_atoms = _personamem_profile_atoms_from_posterior_texts(field_certificate_sources)
    field_certificate_priority_atoms = sorted(
        _dedupe_preserving(
            _canonicalize_personamem_specific(item)
            for item in field_certificate_atoms
            if _personamem_certificate_priority_atom(item)
            and not _is_personamem_field_certificate_source(item)
        ),
        key=_personamem_sufficient_atom_sort_key,
    )
    preferences = _dedupe_preserving([*preferences, *posterior_profile_atoms])
    topic_atoms = [item for item in preferences if _is_personamem_topic_atom(item)]
    conversations = [_strip_earlier_example_prefix(item) for item in preferences if _is_personamem_conversation(item)]
    personas = [
        _canonicalize_personamem_specific(item)
        for item in preferences
        if _is_personamem_persona_carrier(item) and not _is_personamem_conversation(item)
    ]
    negative_items = [item for item in preferences if _is_personamem_negative_carrier(item)]
    sensitive_items = [
        item
        for item in preferences
        if _is_personamem_sensitive_carrier(item) and not _is_personamem_negative_carrier(item)
    ]
    causal_spine_items = [
        _canonicalize_personamem_specific(item)
        for item in preferences
        if _personamem_causal_spine_atom(item)
        and not _is_personamem_conversation(item)
        and not _is_personamem_negative_carrier(item)
        and not _is_personamem_sensitive_carrier(item)
        and not _is_personamem_topic_atom(item)
    ]
    causal_spine_items = sorted(
        _dedupe_preserving(causal_spine_items),
        key=_personamem_causal_spine_sort_key,
    )
    specific_items = [
        item
        for item in preferences
        if not (
            _is_personamem_topic_atom(item)
            or _is_personamem_conversation(item)
            or _is_personamem_persona_carrier(item)
            or _is_personamem_negative_carrier(item)
            or _is_personamem_sensitive_carrier(item)
            or _is_personamem_field_certificate_source(item)
        )
    ]
    specific_candidates = [
        _canonicalize_personamem_specific(item)
        for item in specific_items
        if _personamem_specific_support_score(item) > 0
    ]
    specific_candidates = sorted(
        _dedupe_preserving(specific_candidates),
        key=lambda item: (-_personamem_specific_support_score(item), -len(item)),
    )

    topic_support: list[str] = []
    if negative_items:
        topic_support.extend(negative_items)
        for item in negative_items:
            target = _negative_memory_target(item)
            if target:
                topic_support.append(target)
    topic_support.extend(sensitive_items)
    topic_support.extend(specific_candidates[:2])
    inferred_topics = _infer_personamem_topics(topic_support)
    chosen_topic = ""
    if original_facts:
        chosen_topic = _preference_topic_from_fact(original_facts[0])
    if inferred_topics and specific_candidates and (
        not chosen_topic or chosen_topic != inferred_topics[0]
    ):
        chosen_topic = inferred_topics[0]
    if not chosen_topic and inferred_topics:
        chosen_topic = inferred_topics[0]
    elif not chosen_topic and topic_atoms:
        chosen_topic = _clean_text(topic_atoms[0]).lower()
    ledger_atoms, ledger_audit = _personamem_bayesian_evidence_ledger_atoms(
        sources=posterior_profile_sources,
        structured_atoms=posterior_profile_atoms,
        field_certificate_atoms=field_certificate_atoms,
        chosen_topic=chosen_topic,
    )
    field_posterior_atoms, field_posterior_audit = _personamem_factorized_field_posterior_atoms(
        sources=posterior_profile_sources,
        chosen_topic=chosen_topic,
    )

    kept_preferences: list[str] = []
    if chosen_topic and not causal_spine_items:
        kept_preferences.append(chosen_topic)
    secondary_topics = [
        topic
        for topic in _dedupe_preserving(topic_atoms)
        if topic != chosen_topic and topic not in {"communication", "event", "events", "home"}
    ]
    if not causal_spine_items:
        kept_preferences.extend(secondary_topics[:1])
    else:
        kept_preferences.extend(topic for topic in secondary_topics[:1] if topic in {"health_and_medical", "sensitive_info", "culture"})
    diagnostic_topic_atoms = _personamem_diagnostic_topic_atoms(
        [*inferred_topics, *topic_atoms],
        chosen_topic=chosen_topic,
    )
    kept_preferences.extend(diagnostic_topic_atoms[:2])
    field_cover_atoms = _personamem_field_cover_atoms(
        field_posterior_audit.get("selected_by_field", {})
        if isinstance(field_posterior_audit.get("selected_by_field"), Mapping)
        else {}
    )
    if reservoir_field_cover_atoms:
        field_cover_atoms = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving([*reservoir_field_cover_atoms, *field_cover_atoms])
        )
    if reservoir_sufficient_field_atoms:
        field_cover_atoms = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving([*reservoir_sufficient_field_atoms, *field_cover_atoms])
        )
    if reservoir_field_atoms:
        field_posterior_atoms = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving([*reservoir_field_atoms, *field_posterior_atoms])
        )
    if reservoir_ledger_atoms:
        ledger_atoms = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving([*reservoir_ledger_atoms, *ledger_atoms])
        )
    field_cover_topics = _personamem_diagnostic_topics_from_atoms(field_cover_atoms, chosen_topic=chosen_topic)
    for topic in field_cover_topics:
        if topic not in diagnostic_topic_atoms:
            diagnostic_topic_atoms.append(topic)
            kept_preferences.append(topic)
    kept_preferences.extend(field_cover_atoms)
    kept_preferences.extend(
        item
        for item in field_posterior_atoms[:12]
        if _semantic_compact_adapter(item)
        not in {_semantic_compact_adapter(atom) for atom in field_cover_atoms}
    )
    kept_preferences.extend(ledger_atoms[:8])
    conversation_item = max(conversations, key=len) if conversations else ""
    if conversation_item:
        kept_preferences.append(conversation_item)
    if personas:
        direct_personas = [item for item in personas if "earlier example" not in _lower_clean(item)]
        persona_limit = 1 if conversation_item else 2
        kept_preferences.extend(
            sorted(
                direct_personas or personas,
                key=_personamem_sufficient_atom_sort_key,
            )[:persona_limit]
        )
    kept_preferences.extend(
        item
        for item in field_certificate_priority_atoms[:5]
        if not _is_personamem_conversation(item)
    )
    kept_preferences.extend(causal_spine_items[:6])
    for item in negative_items:
        kept_preferences.append(item)
        target = _negative_memory_target(item)
        if target:
            matching_target = next((candidate for candidate in preferences if _lower_clean(candidate) == target.lower()), "")
            kept_preferences.append(matching_target or target)
    kept_preferences.extend(sensitive_items)
    high_precision_specific = [
        item for item in specific_candidates if _personamem_high_precision_specific_atom(item)
    ]
    if not negative_items and not sensitive_items and high_precision_specific:
        specific_limit = 2 if conversation_item else 3
        kept_preferences.extend(
            item for item in high_precision_specific[:specific_limit] if item not in causal_spine_items
        )

    preference_budget = 7 if causal_spine_items and conversation_item else (6 if negative_items or causal_spine_items else 5)
    if ledger_atoms or field_certificate_atoms or field_posterior_atoms or conversation_item:
        evidence_units = (
            len([item for item in field_cover_atoms if not _is_personamem_topic_atom(item)])
            + len([item for item in field_posterior_atoms[:12] if not _is_personamem_topic_atom(item)])
            + len([item for item in ledger_atoms[:8] if not _is_personamem_topic_atom(item)])
            + len([item for item in field_certificate_priority_atoms[:5] if not _is_personamem_conversation(item)])
            + len(diagnostic_topic_atoms[:2])
            + (1 if conversation_item else 0)
            + (1 if chosen_topic else 0)
        )
        preference_budget = max(preference_budget, min(12, evidence_units))
    if field_cover_atoms:
        preference_budget = max(preference_budget, min(12, len(field_cover_atoms) + (1 if conversation_item else 0)))
    if conversation_item and (personas or high_precision_specific):
        preference_budget = max(preference_budget, 8)

    typed_priority_atoms = _dedupe_preserving(
        [
            *field_certificate_priority_atoms,
            *field_cover_atoms,
            *field_posterior_atoms[:12],
            *ledger_atoms[:8],
            *([conversation_item] if conversation_item else []),
        ]
    )
    regularized["preferences"] = _budget_personamem_preferences(
        _dedupe_preserving(kept_preferences),
        cap=preference_budget,
        priority_items=[
            *diagnostic_topic_atoms,
            *field_cover_atoms,
            *field_posterior_atoms,
            *field_certificate_priority_atoms,
        ],
    )
    regularized["metadata"] = {
        **dict(regularized.get("metadata", {}) if isinstance(regularized.get("metadata"), Mapping) else {}),
        "personamem_typed_priority_atoms": typed_priority_atoms[:24],
        "personamem_hard_field_cover_atoms": field_cover_atoms[:12],
    }
    regularized["raw_text"] = _render_layered_raw_text(regularized)
    return regularized, {
        "status": "applied",
        "model": "schema_role_raw_evidence_regularization_v3",
        "carrier_families": {
            "facts_before": len(original_facts),
            "facts_after": len(regularized["facts"]),
            "topic_candidates": len(topic_atoms),
            "inferred_topics": inferred_topics[:3],
            "specific_candidates": len(specific_candidates),
            "posterior_profile_atoms": len(posterior_profile_atoms),
            "field_certificate_sources": len(field_certificate_sources),
            "field_certificate_atoms": len(field_certificate_atoms),
            "field_certificate_priority_atoms": len(field_certificate_priority_atoms),
            "causal_spine_candidates": len(causal_spine_items),
            "backend_unwrapped_preference_candidates": len(unwrapped_preferences),
            "high_precision_specific_candidates": len(high_precision_specific),
            "persona_candidates": len(personas),
            "conversation_candidates": len(conversations),
            "negative_candidates": len(negative_items),
            "sensitive_candidates": len(sensitive_items),
            "bayesian_ledger_candidates": ledger_audit.get("candidate_count", 0),
            "bayesian_ledger_selected": ledger_audit.get("selected_count", 0),
            "bayesian_ledger_top": ledger_audit.get("top_atoms", []),
            "reservoir_field_cover_atoms": reservoir_field_cover_atoms,
            "reservoir_sufficient_field_atoms": reservoir_sufficient_field_atoms[:16],
            "reservoir_field_atoms": reservoir_field_atoms[:12],
            "reservoir_ledger_atoms": reservoir_ledger_atoms[:10],
            "field_posterior_candidates": field_posterior_audit.get("candidate_count", 0),
            "field_posterior_selected": field_posterior_audit.get("selected_count", 0),
            "field_posterior_top": field_posterior_audit.get("top_atoms", []),
            "field_posterior_by_field": field_posterior_audit.get("selected_by_field", {}),
            "field_cover_atoms": field_cover_atoms,
            "diagnostic_topic_atoms": diagnostic_topic_atoms[:2],
            "preferences_before": len(preferences),
            "preferences_after": len(regularized["preferences"]),
            "preference_budget": preference_budget,
            "selection_model": "factorized_field_posterior_truth_discovery_v2",
        },
    }


def _budget_personamem_preferences(
    items: Sequence[str],
    *,
    cap: int,
    priority_items: Sequence[str] = (),
) -> list[str]:
    """Keep structurally diagnostic evidence inside backend projection caps."""

    priority_keys = {
        _semantic_compact_adapter(item)
        for item in priority_items
        if _semantic_compact_adapter(item)
    }

    def priority(item: str) -> tuple[int, int, int]:
        text = _lower_clean(item)
        if _semantic_compact_adapter(item) in priority_keys:
            return (-1, -_personamem_invariant_support_score(item), -len(text))
        if _is_personamem_conversation(item):
            return (0, -min(len(text), 900), len(text))
        if _is_personamem_persona_carrier(item):
            return (1, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_source_like_exact_atom(item):
            return (2, -_personamem_invariant_support_score(item), -len(text))
        if _is_personamem_negative_carrier(item):
            return (3, -_personamem_invariant_support_score(item), -len(text))
        if _is_personamem_sensitive_carrier(item):
            return (4, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_bayesian_ledger_atom(item):
            return (5, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_causal_spine_atom(item) and _is_personamem_persona_carrier(item) and re.search(
            r"\b(?:idolizes|looks up to|inspired by|seeks to learn from|learns from)\b",
            text,
        ):
            return (6, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_causal_spine_atom(item) and _is_personamem_persona_carrier(item):
            return (7, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_invariant_choice_atom(item):
            return (8, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_causal_spine_atom(item):
            return (9, -_personamem_invariant_support_score(item), -len(text))
        if _personamem_high_precision_specific_atom(item):
            return (10, -_personamem_invariant_support_score(item), len(text))
        if _is_personamem_topic_atom(item):
            return (11, -_personamem_invariant_support_score(item), len(text))
        return (12, -_personamem_invariant_support_score(item), len(text))

    deduped = [item for item in _dedupe_preserving(items) if _personamem_final_preference_admissible(item)]
    if len(deduped) <= cap:
        return _personamem_remove_subsumed_ledger_atoms(deduped)
    return _personamem_remove_subsumed_ledger_atoms(sorted(deduped, key=priority))[: max(0, cap)]


def _personamem_bayesian_evidence_ledger_atoms(
    *,
    sources: Sequence[Any],
    structured_atoms: Sequence[Any],
    field_certificate_atoms: Sequence[Any],
    chosen_topic: str,
    limit: int = 12,
) -> tuple[list[str], dict[str, Any]]:
    """Approximate posterior over PersonaMem latent atoms from noisy observations.

    The evidence units are visible answer text, ordinary follow-up responses,
    profile-card fields, and public-choice atoms.  A candidate atom receives
    likelihood mass when it appears as a reusable, source-like factor across
    these observations; broad paraphrases and task-surface suggestions are
    penalized.  This is a lightweight Bayesian ledger rather than a hard parser:
    candidates with independent evidence survive the projection budget.
    """

    scores: Counter[str] = Counter()
    display: dict[str, str] = {}

    def add(value: Any, weight: int, *, reason: str) -> None:
        canonical = _canonicalize_personamem_specific(_clean_text(value)).strip(" -*,.;:'\"")
        if not canonical:
            return
        if _is_personamem_field_certificate_source(canonical):
            return
        if not _personamem_ledger_atom_admissible(canonical):
            return
        low = _lower_clean(canonical)
        if _is_personamem_topic_atom(low) and chosen_topic and low != _lower_clean(chosen_topic) and low not in {
            "health_and_medical",
            "sensitive_info",
            "religion",
            "culture",
            "sports",
            "fashion",
            "food",
        }:
            return
        key = _semantic_compact_adapter(canonical)
        if not key:
            return
        token_count = len(_lower_clean(canonical).split())
        length_prior = 14 if 4 <= token_count <= 24 else (-12 if token_count > 42 else 0)
        scores[key] += weight + length_prior + _personamem_ledger_prior(canonical)
        if key not in display or len(canonical) < len(display[key]) or reason == "field_certificate":
            display[key] = canonical

    for item in structured_atoms:
        add(item, 34, reason="structured_atom")
    for item in field_certificate_atoms:
        add(item, 62, reason="field_certificate")
    for source in sources:
        text = _clean_text(source)
        if not text:
            continue
        source_weight = 42 if _is_personamem_field_certificate_source(text) else 18
        for atom in _personamem_profile_atoms_from_posterior_texts([text]):
            add(atom, source_weight, reason="source_profile_atom")
        for atom in _personamem_source_semantic_bridge_atoms(text):
            add(atom, max(22, source_weight - 4), reason="semantic_bridge")
        if chosen_topic and _personamem_topic_hint_present(chosen_topic, _lower_clean(text)):
            add(chosen_topic, 20, reason="topic_support")

    ranked = sorted(
        (display[key] for key, score in scores.items() if score > 0),
        key=lambda item: (-scores[_semantic_compact_adapter(item)], _personamem_ledger_sort_key(item)),
    )
    selected = _personamem_remove_subsumed_ledger_atoms(_dedupe_preserving(ranked))[:limit]
    return selected, {
        "candidate_count": len(scores),
        "selected_count": len(selected),
        "top_atoms": selected[:6],
        "top_scores": {
            atom: int(scores[_semantic_compact_adapter(atom)])
            for atom in selected[:6]
        },
    }


def _personamem_factorized_field_posterior_atoms(
    *,
    sources: Sequence[Any],
    chosen_topic: str,
    limit: int = 14,
) -> tuple[list[str], dict[str, Any]]:
    """Track PersonaMem profile fields as separate latent variables.

    Mixed-text extraction loses exact slot values when later observations
    paraphrase earlier profile cards.  This ledger treats each schema field as a
    latent variable and each visible profile-card field as a noisy observation.
    The MAP value per field is then projected back into ordinary preference
    atoms.
    """

    field_scores: dict[str, Counter[str]] = {}
    field_display: dict[str, dict[str, str]] = {}
    field_reasons: dict[str, dict[str, set[str]]] = {}
    pseudo_observation_count = 0
    pseudo_observation_reasons: Counter[str] = Counter()

    def add(field: str, value: Any, weight: int, *, reason: str) -> None:
        canonical_field = _personamem_field_posterior_label(field)
        if not canonical_field:
            return
        atoms = _personamem_field_posterior_atoms(canonical_field, value, chosen_topic=chosen_topic)
        for atom in atoms:
            if not _personamem_field_posterior_atom_admissible(canonical_field, atom):
                continue
            key = _semantic_compact_adapter(atom)
            if not key:
                continue
            field_scores.setdefault(canonical_field, Counter())
            field_display.setdefault(canonical_field, {})
            field_reasons.setdefault(canonical_field, {})
            field_scores[canonical_field][key] += (
                weight
                + _personamem_field_posterior_prior(canonical_field, atom)
                + min(36, _personamem_specific_support_score(atom))
            )
            current = field_display[canonical_field].get(key)
            if current is None or _personamem_field_display_prefer(atom, current):
                field_display[canonical_field][key] = atom
            field_reasons[canonical_field].setdefault(key, set()).add(reason)

    for source_index, source in enumerate(sources):
        text = _clean_text(source)
        if not text:
            continue
        fields = _personamem_field_certificate_map(text)
        source_bonus = 42 if _is_personamem_field_certificate_source(text) else 12
        if re.search(r"\bmemory topic\s*[:=].+\bstable role\s*[:=].+\brecurring preference\s*[:=]", text, flags=re.IGNORECASE | re.DOTALL):
            source_bonus += 28
        if re.search(r"\bchoice\s*[:=]", text, flags=re.IGNORECASE):
            source_bonus -= 12
        if re.search(r"\bsurface request detail\b|\bplan item\b|\bwhy this fits\b", text, flags=re.IGNORECASE):
            source_bonus -= 18
        for label, value in fields.items():
            add(
                label,
                value,
                _personamem_field_posterior_field_weight(label)
                + source_bonus
                + _personamem_field_observation_reliability_bonus(label, value, text)
                + max(0, 8 - source_index // 2),
                reason=f"field:{_personamem_field_posterior_label(label) or label}",
            )
        for label, value, reason in _personamem_pseudo_field_observations(text):
            pseudo_observation_count += 1
            pseudo_observation_reasons[reason] += 1
            pseudo_weight = max(20, _personamem_field_posterior_field_weight(label) // 2)
            pseudo_weight += _personamem_pseudo_observation_reason_bonus(reason)
            if fields:
                pseudo_weight = max(16, pseudo_weight - 16)
            add(
                label,
                value,
                pseudo_weight + max(0, source_bonus // 3) + max(0, 5 - source_index // 3),
                reason=f"pseudo:{reason}",
            )

    selected: list[str] = []
    selected_by_field: dict[str, list[str]] = {}
    for field in _PERSONAMEM_FIELD_POSTERIOR_ORDER:
        scores = field_scores.get(field)
        if not scores:
            continue
        displays = field_display.get(field, {})
        rankable: list[tuple[str, int]] = []
        for key, score in scores.items():
            if score <= 0 or key not in displays:
                continue
            atom = displays[key]
            selection_score = _personamem_field_posterior_selection_score(
                field,
                atom,
                int(score),
                field_reasons.get(field, {}).get(key, set()),
            )
            if selection_score < _personamem_field_posterior_acceptance_threshold(field):
                continue
            rankable.append((atom, selection_score))
        ranked = sorted(
            rankable,
            key=lambda atom: (
                -atom[1],
                _personamem_field_posterior_sort_key(field, atom[0]),
            ),
        )
        ranked_atoms = _personamem_field_dominance_order(
            field,
            [atom for atom, _ in ranked],
        )
        cap = _PERSONAMEM_FIELD_POSTERIOR_CAPS.get(field, 1)
        field_selected = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving(ranked_atoms)
        )[:cap]
        if field_selected:
            selected_by_field[field] = field_selected
            selected.extend(field_selected)

    selected = _personamem_remove_subsumed_ledger_atoms(_dedupe_preserving(selected))[:limit]
    return selected, {
        "candidate_count": sum(len(counter) for counter in field_scores.values()),
        "selected_count": len(selected),
        "selected_by_field": selected_by_field,
        "top_atoms": selected[:8],
        "field_count": len(field_scores),
        "pseudo_observation_count": pseudo_observation_count,
        "pseudo_observation_reasons": dict(pseudo_observation_reasons),
    }


def _personamem_monotone_sufficient_field_atoms(
    *,
    sources: Sequence[Any],
    chosen_topic: str,
    limit: int = 16,
) -> tuple[list[str], dict[str, Any]]:
    """Keep sufficient typed field observations before noisy paraphrases merge.

    Repeated ordinary follow-ups are noisy sensors over the same latent profile.
    A later paraphrase may have more surface support than an earlier typed
    field-card value, but it is not more sufficient for exact recovery.  This
    reservoir therefore keeps the best direct field observation per semantic
    field/cluster and only then applies the projection budget.
    """

    records_by_field_cluster: dict[str, dict[str, dict[str, Any]]] = {}
    direct_source_count = 0

    def cluster_key(field: str, atom: str) -> str:
        if field == "role":
            return _personamem_role_signature(atom) or _semantic_compact_adapter(atom)
        if field == "preference":
            return _personamem_preference_signature(atom) or _semantic_compact_adapter(atom)
        if field == "prior":
            return "conversation" if _is_personamem_conversation(atom) else _semantic_compact_adapter(atom)
        return _semantic_compact_adapter(atom)

    def record_prefer(candidate: dict[str, Any], current: dict[str, Any] | None, field: str) -> bool:
        if current is None:
            return True
        cand_atom = _clean_text(candidate.get("atom", ""))
        cur_atom = _clean_text(current.get("atom", ""))
        if field in {"role", "preference", "prior"}:
            ordered = _personamem_field_dominance_order(field, [cand_atom, cur_atom])
            if ordered:
                if _lower_clean(ordered[0]) == _lower_clean(cand_atom) and _lower_clean(cand_atom) != _lower_clean(cur_atom):
                    return True
                if _lower_clean(ordered[0]) == _lower_clean(cur_atom) and _lower_clean(cand_atom) != _lower_clean(cur_atom):
                    return False
        cand_score = int(candidate.get("score", 0) or 0)
        cur_score = int(current.get("score", 0) or 0)
        if cand_score != cur_score:
            return cand_score > cur_score
        return _personamem_field_display_prefer(cand_atom, cur_atom)

    for source_index, source in enumerate(sources):
        text = _clean_text(source)
        if not text:
            continue
        fields = _personamem_field_certificate_map(text)
        if not fields:
            continue
        direct_source_count += 1
        source_bonus = 88 if _is_personamem_field_certificate_source(text) else 22
        if re.search(
            r"\bmemory topic\s*[:=].+\bstable role\s*[:=].+\brecurring preference\s*[:=]",
            text,
            flags=re.IGNORECASE | re.DOTALL,
        ):
            source_bonus += 52
        if re.search(r"\bchoice\s*[:=]|\bplan item\b|\bwhy this fits\b", text, flags=re.IGNORECASE):
            source_bonus -= 48
        temporal_bonus = max(0, 18 - source_index // 2)
        for label, value in fields.items():
            field = _personamem_field_posterior_label(label)
            if not field:
                continue
            value_score = _personamem_field_certificate_value_score(label, value, source_text=text)
            base_score = (
                source_bonus
                + temporal_bonus
                + _personamem_field_posterior_field_weight(label)
                + _personamem_field_observation_reliability_bonus(label, value, text)
                + value_score
            )
            reasons = {f"field:{field}", "direct_field_certificate"}
            for atom in _personamem_field_posterior_atoms(field, value, chosen_topic=chosen_topic):
                atom = _canonicalize_personamem_specific(atom)
                if not atom or not _personamem_field_posterior_atom_admissible(field, atom):
                    continue
                key = cluster_key(field, atom)
                if not key:
                    continue
                score = _personamem_field_posterior_selection_score(
                    field,
                    atom,
                    base_score + _personamem_field_posterior_prior(field, atom),
                    reasons,
                )
                if score < _personamem_field_posterior_acceptance_threshold(field):
                    continue
                record = {
                    "atom": atom,
                    "score": int(score),
                    "label": _clean_text(label),
                    "source_index": source_index,
                }
                field_records = records_by_field_cluster.setdefault(field, {})
                if record_prefer(record, field_records.get(key), field):
                    field_records[key] = record

    selected: list[str] = []
    selected_by_field: dict[str, list[str]] = {}
    top_scores: dict[str, int] = {}
    for field in _PERSONAMEM_FIELD_POSTERIOR_ORDER:
        records = list(records_by_field_cluster.get(field, {}).values())
        if not records:
            continue
        ranked = sorted(
            records,
            key=lambda record: (
                -int(record.get("score", 0) or 0),
                _personamem_field_posterior_sort_key(field, _clean_text(record.get("atom", ""))),
            ),
        )
        ranked_atoms = _personamem_field_dominance_order(
            field,
            [_clean_text(record.get("atom", "")) for record in ranked],
        )
        cap = max(
            _PERSONAMEM_FIELD_COVER_CAPS.get(field, 1),
            1 if field != "preference" else 2,
        )
        field_selected = _personamem_remove_subsumed_ledger_atoms(
            _dedupe_preserving(ranked_atoms)
        )[:cap]
        if not field_selected:
            continue
        selected_by_field[field] = field_selected
        selected.extend(field_selected)
        score_lookup = {
            _lower_clean(_clean_text(record.get("atom", ""))): int(record.get("score", 0) or 0)
            for record in records
        }
        for atom in field_selected:
            top_scores[atom] = score_lookup.get(_lower_clean(atom), 0)

    selected = _personamem_remove_subsumed_ledger_atoms(_dedupe_preserving(selected))[:limit]
    return selected, {
        "model": "monotone_sufficient_field_reservoir_v1",
        "direct_source_count": direct_source_count,
        "candidate_count": sum(len(records) for records in records_by_field_cluster.values()),
        "selected_count": len(selected),
        "selected_by_field": selected_by_field,
        "top_atoms": selected[:10],
        "top_scores": {atom: top_scores.get(atom, 0) for atom in selected[:10]},
    }


def _personamem_pseudo_field_observations(text: Any) -> list[tuple[str, str, str]]:
    """Convert unlabeled visible behavior into weak profile-field evidence.

    Real-agent answers often expose a profile factor in prose instead of a
    structured field card, e.g. "since you enjoy X" or "as a teacher".  These
    are lower-confidence observations for the same field posterior, not direct
    access to hidden benchmark state.
    """

    source = _clean_text(text)
    if not source:
        return []
    observations: list[tuple[str, str, str]] = []

    def add(field: str, value: Any, reason: str) -> None:
        cleaned = _trim_personamem_pseudo_observation_value(value)
        if not cleaned:
            return
        observations.append((field, cleaned, reason))

    for atom in _personamem_contact_atoms_from_text(source):
        add("sensitive/private field", atom, "contact_identifier")
    for atom in _personamem_health_constraint_atoms_from_text(source):
        add("health constraint", atom, "health_constraint")
    for atom in _personamem_polarity_preserving_atoms(source):
        field = "correction" if _is_personamem_negative_carrier(atom) else "recurring preference"
        if _lower_clean(atom) in {"allergies", "seasonal allergic rhinitis during spring"}:
            field = "health constraint"
        add(field, atom, "polarity_clause")

    structured_source = _is_personamem_field_certificate_source(source)
    if not structured_source:
        role_source = re.sub(
            r"\b(dedicated|professional|veteran|young|worried|global-wandering|global|aspiring|retired|former)\s*,\s+",
            r"\1 ",
            source,
            flags=re.IGNORECASE,
        )
        role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
        role_prefix = r"(?:(?:former|retired|aspiring|professional|dedicated|global-wandering|global|veteran|young|worried|middle school|high school|college|university|taiwan-based|nigerian|japanese|american|canadian|british)\s+){0,6}"
        role_patterns = (
            rf"\b(?:as|being|because you are|since you are|given you are|you're|you are)\s+(?P<role>(?:a|an)\s+{role_prefix}(?:{role_terms})(?:\s+who\s+[^.;,\n]{{3,180}}|[^.;,\n]{{0,120}}))",
            rf"\b(?P<role>(?:i\s+am|i'm)\s+(?:a|an)\s+{role_prefix}(?:{role_terms})(?:\s+who\s+[^.;,\n]{{3,180}}|[^.;,\n]{{0,120}}))",
            rf"\b(?P<role>(?:a|an)\s+{role_prefix}(?:{role_terms})\s+who\s+[^.;,\n]{{3,180}})",
            rf"\b(?P<role>(?:a|an)\s+{role_prefix}(?:{role_terms}))\b",
        )
        for pattern in role_patterns:
            for match in re.finditer(pattern, role_source, flags=re.IGNORECASE):
                add("stable role", match.group("role"), "role_phrase")

        for match in re.finditer(
            r"\b(?P<routine>(?:unwind(?:ing)?|relax(?:ing)?|recover(?:ing)?|decompress(?:ing)?)\s+after\s+[^.;,\n]{3,90})",
            source,
            flags=re.IGNORECASE,
        ):
            add("routine/habit", match.group("routine"), "routine_phrase")

        action_verbs = (
            "enjoy",
            "like",
            "love",
            "prefer",
            "favor",
            "appreciate",
            "read",
            "drink",
            "eat",
            "wear",
            "buy",
            "use",
            "collect",
            "watch",
            "play",
            "attend",
            "seek",
            "avoid",
            "listen to",
        )
        action_pattern = "|".join(re.escape(verb) for verb in sorted(action_verbs, key=len, reverse=True))
        for match in re.finditer(
            rf"\b(?:since|because|given|knowing that|as)\s+you\s+(?P<verb>{action_pattern})\s+(?P<object>[^.;\n]{{3,150}})",
            source,
            flags=re.IGNORECASE,
        ):
            add("recurring preference", _personamem_third_person_action_atom(match.group("verb"), match.group("object")), "second_person_cause")
        for match in re.finditer(
            rf"\byou\s+(?P<verb>{action_pattern})\s+(?P<object>[^.;\n]{{3,140}})",
            source,
            flags=re.IGNORECASE,
        ):
            add("recurring preference", _personamem_third_person_action_atom(match.group("verb"), match.group("object")), "second_person_preference")
        for match in re.finditer(
            r"\b(?:your|their)\s+(?:preference|fondness|taste|love|interest|appreciation)\s+(?:for|in)\s+(?P<object>[^.;\n]{3,140})",
            source,
            flags=re.IGNORECASE,
        ):
            add("recurring preference", f"favors {match.group('object')}", "noun_preference")
        for match in re.finditer(
            r"\b(?P<value>(?:enjoys|likes|loves|prefers|favors|avoids|reads|drinks|eats|wears|buys|uses|collects|watches|plays|attends|appreciates|seeks|listens to)\s+[^.;,\n]{3,130})",
            source,
            flags=re.IGNORECASE,
        ):
            add("recurring preference", match.group("value"), "third_person_preference")

    deduped: list[tuple[str, str, str]] = []
    seen: set[tuple[str, str]] = set()
    for field, value, reason in observations:
        key = (_personamem_field_posterior_label(field) or _lower_clean(field), _lower_clean(value))
        if value and key not in seen:
            deduped.append((field, value, reason))
            seen.add(key)
    return deduped


def _personamem_field_dominance_order(field: str, atoms: Sequence[str]) -> list[str]:
    """Prefer specific MAP hypotheses over generic same-field summaries.

    Frequency is useful but can over-favor short summaries.  Under a typed
    latent-field model, two atoms with the same role signature or preference
    head compete for one latent variable; the more constrained atom should
    dominate unless it is a fusion/placeholder.
    """

    deduped = _dedupe_preserving(_clean_text(atom) for atom in atoms if _clean_text(atom))
    if field == "role":
        return sorted(
            deduped,
            key=lambda atom: (
                0 if _personamem_specific_role_dominates_generic(atom) else 1,
                1 if _personamem_role_preference_fusion(atom) else 0,
                _personamem_role_signature(atom),
                -_personamem_field_specificity_score(field, atom),
                -len(_lower_clean(atom).split()),
                _lower_clean(atom),
            ),
        )
    if field == "preference":
        return sorted(
            deduped,
            key=lambda atom: (
                0 if _personamem_specific_preference_dominates_generic(atom) else 1,
                _personamem_preference_signature(atom),
                -_personamem_field_specificity_score(field, atom),
                -len(_lower_clean(atom).split()),
                _lower_clean(atom),
            ),
        )
    if field == "prior":
        return sorted(
            [
                atom
                for atom in deduped
                if not _personamem_placeholder_prior_text(atom)
            ],
            key=lambda atom: (
                0 if _is_personamem_conversation(atom) else 1,
                -len(_clean_text(atom)),
                _lower_clean(atom),
            ),
        )
    return deduped


def _personamem_specific_role_dominates_generic(atom: Any) -> bool:
    text = _lower_clean(atom)
    return bool(
        not _personamem_role_preference_fusion(atom)
        and (
            _personamem_identity_bound_role_modifier(atom)
            or re.search(
            r"\b(?:who is also|who was|who is|interested in|looking for|specializing|specializes|friend of|part of|working as|works as|based in|from|at)\b",
            text,
            )
        )
    )


def _personamem_preference_signature(atom: Any) -> str:
    text = _lower_clean(atom)
    text = re.sub(r"^(?:prefer|prefers|enjoys|likes|like|loves|favors|attends|participates|contributes|volunteers|supports|practices|practice|practicing|swims|swimming|regularly|often|frequently|usually|is passionate about|passionate about|believes that|believes|advocates for|advocating for|fights for|fighting for)\s+", "", text)
    if " over " in text:
        return re.sub(r"\s+over\s+.+$", "", text).strip()
    for topic in sorted(_PERSONAMEM_TOPIC_LABELS, key=len, reverse=True):
        if topic in text:
            return topic
    tokens = [tok for tok in re.split(r"[^a-z0-9]+", text) if len(tok) > 2]
    return " ".join(tokens[:4])


def _personamem_specific_preference_dominates_generic(atom: Any) -> bool:
    text = _lower_clean(atom)
    return bool(
        re.match(r"^prefer\s+.+\bover\b", text)
        or re.match(r"^(?:regularly|often|frequently|usually)\s+(?:attends|visits|reads|watches|plays|listens to|uses|collects)\b", text)
        or (
            re.match(
            r"^(?:enjoys|likes|like|loves|prefers|favors|avoids|values|supports|attends|participates|contributes|volunteers|takes|practices|practice|practicing|swims|swimming|reads|watches|plays|listens to|uses|collects|drinks|eats|wears|buys|is passionate about|passionate about|believes|advocates|advocating|fights|fighting)\b",
                text,
            )
            and 3 <= len(text.split()) <= 9
            and " and " not in text
            and " - " not in str(atom)
            and "|" not in str(atom)
        )
        or re.search(r"\b(?:instead of|rather than|more than)\b", text)
    )


def _personamem_pseudo_observation_reason_bonus(reason: str) -> int:
    reason_key = _lower_clean(reason)
    if reason_key == "second_person_cause":
        return 104
    if reason_key == "second_person_preference":
        return 78
    if reason_key in {"contact_identifier", "health_constraint"}:
        return 56
    if reason_key == "role_phrase":
        return 48
    if reason_key == "noun_preference":
        return 36
    if reason_key == "routine_phrase":
        return 28
    return 12


def _personamem_field_observation_reliability_bonus(label: Any, value: Any, source_text: Any) -> int:
    """Reliability prior for field-card observations.

    A direct typed field such as `Stable role=` is treated as a higher-quality
    sensor than a generated `Stable persona=` summary.  This is a source model,
    not a benchmark-answer shortcut: the decision uses only the visible field
    label, the visible value shape, and placeholder/generic markers.
    """

    label_key = _lower_clean(label)
    value_text = _lower_clean(value)
    source = _lower_clean(source_text)
    bonus = 0
    if "stable role" in label_key or "role/background" in label_key or "identity/background" in label_key:
        bonus += 80
    if "stable persona" in label_key:
        bonus -= 28
    if "recurring preference" in label_key:
        bonus += 72
    if "raw prior" in label_key:
        bonus += 180
    elif "prior interaction" in label_key or "prior example" in label_key:
        bonus += 44
    if "memory topic" in label_key:
        bonus -= 12
    if "choice" in source or "plan item" in source or "why this fits" in source:
        bonus -= 20
    if "certificate fields generated based on the request context and memory" in source:
        bonus -= 18
    if _personamem_placeholder_prior_text(value):
        bonus -= 260
    if "stable persona" in label_key and re.search(r"\b(?:enthusiast|with a focus|interest in|interests=)\b", value_text):
        bonus -= 34
    if "stable role" in label_key and re.search(r"\b(?:specializing|who is also|friend of|working as|works as|professor|historian|scientist|teacher|student|officer|attorney|engineer|doctor|manager)\b", value_text):
        bonus += 44
    if "stable role" in label_key and _personamem_identity_bound_role_modifier(value):
        bonus += 82
    if "recurring preference" in label_key and re.search(r"\b(?:over|regularly|often|frequently|usually|attends|podcasts?|avoids|prefers?)\b", value_text):
        bonus += 36
    if _personamem_polarity_preserving_atom(value):
        bonus += 72
    if "raw prior" in label_key and _personamem_polarity_preserving_atoms(value):
        bonus += 34
    return bonus


def _trim_personamem_pseudo_observation_value(value: Any) -> str:
    text = _strip_personamem_field_certificate_tail(value)
    if not text:
        return ""
    text = re.split(
        r"\s+\b(?:identifiability-layered state estimate|reservoir observations|facts\s*[-:]|preferences\s*[-:]|constraints\s*[-:]|tool_state\s*[-:])\b",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    text = re.split(
        r"\s+\b(?:you could|you might|consider|try|this option|this gift|which would|that would|making it|so that|while still|for example|here are)\b",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    text = re.sub(r"\s+\b(?:and|or)\s+(?:you could|you might|consider|try)\b.*$", "", text, flags=re.IGNORECASE)
    text = re.sub(r",\s+(?:this|that|it)\b.*$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+\band\s+you\b.*$", "", text, flags=re.IGNORECASE)
    text = re.sub(r"\s+", " ", text).strip(" -*,.;:'\"")
    if not text or len(text.split()) > 42:
        return ""
    low = _lower_clean(text)
    if low in {"mine", "yours", "hers", "his", "theirs", "this", "that", "it", "me", "us"}:
        return ""
    if len(low.split()) <= 2 and re.search(r"\b(?:mine|yours|hers|his|theirs|this|that|it|me|us)\b", low):
        return ""
    if "<preference" in low or "should not be reused" in low:
        return ""
    if _is_personamem_generic_advice(text):
        return ""
    return text


def _personamem_third_person_action_atom(verb: Any, obj: Any) -> str:
    verb_key = _lower_clean(verb)
    obj_text = _trim_personamem_pseudo_observation_value(obj)
    if not obj_text:
        return ""
    obj_text = re.sub(r"^(?:to\s+)?", "", obj_text, count=1, flags=re.IGNORECASE).strip(" -*,.;:'\"")
    if re.match(r"^(?:me|us)\s+to\b", obj_text, flags=re.IGNORECASE):
        return ""
    verb_map = {
        "enjoy": "enjoys",
        "like": "likes",
        "love": "loves",
        "prefer": "prefers",
        "favor": "favors",
        "appreciate": "appreciates",
        "read": "reads",
        "drink": "drinks",
        "eat": "eats",
        "wear": "wears",
        "buy": "buys",
        "use": "uses",
        "collect": "collects",
        "watch": "watches",
        "play": "plays",
        "attend": "attends",
        "seek": "seeks",
        "avoid": "avoids",
        "listen to": "listens to",
    }
    return f"{verb_map.get(verb_key, verb_key)} {obj_text}".strip()


_PERSONAMEM_FIELD_POSTERIOR_ORDER = (
    "role",
    "preference",
    "routine",
    "prior",
    "sensitive",
    "correction",
    "health",
    "value",
    "topic",
)
_PERSONAMEM_FIELD_POSTERIOR_CAPS = {
    "role": 2,
    "preference": 3,
    "routine": 2,
    "prior": 1,
    "sensitive": 3,
    "correction": 2,
    "health": 2,
    "value": 1,
    "topic": 1,
}
_PERSONAMEM_FIELD_COVER_ORDER = (
    "role",
    "preference",
    "sensitive",
    "health",
    "correction",
    "prior",
    "routine",
    "value",
    "topic",
)
_PERSONAMEM_FIELD_COVER_CAPS = {
    "role": 1,
    "preference": 2,
    "sensitive": 2,
    "health": 1,
    "correction": 1,
    "prior": 1,
    "routine": 1,
    "value": 1,
    "topic": 1,
}


def _personamem_field_cover_atoms(selected_by_field: Mapping[str, Any]) -> list[str]:
    """Reserve one MAP value per reliable field before flat budget sorting.

    Follow-up responses are noisy views of the same latent profile.  The final
    projection should cover distinct fields instead of letting one verbose field
    consume all available slots.
    """

    covered: list[str] = []
    for field in _PERSONAMEM_FIELD_COVER_ORDER:
        values = selected_by_field.get(field, [])
        if not isinstance(values, Sequence) or isinstance(values, (str, bytes, bytearray)):
            continue
        cap = _PERSONAMEM_FIELD_COVER_CAPS.get(field, 1)
        for value in values[:cap]:
            atom = _clean_text(value)
            if not atom:
                continue
            if not _personamem_field_cover_admissible(field, atom):
                continue
            if field == "topic":
                if _is_personamem_topic_atom(atom):
                    covered.append(_lower_clean(atom))
                continue
            if _personamem_final_preference_admissible(atom):
                covered.append(atom)
    return _personamem_remove_subsumed_ledger_atoms(_dedupe_preserving(covered))


def _personamem_field_cover_admissible(field: str, atom: Any) -> bool:
    if field == "topic":
        return _is_personamem_topic_atom(atom)
    if field == "role" and _personamem_low_information_role_atom(atom):
        return False
    if field == "preference" and _personamem_low_information_preference_atom(atom):
        return False
    return (
        _personamem_field_specificity_score(field, atom)
        >= _personamem_field_posterior_acceptance_threshold(field)
    )


def _personamem_field_posterior_label(label: Any) -> str:
    key = _lower_clean(label)
    if not key:
        return ""
    if "memory topic" in key or key in {"domain", "topic domain"}:
        return "topic"
    if "stable role" in key or "stable persona" in key or "role background" in key or "identity background" in key:
        return "role"
    if "recurring preference" in key or "concrete preference" in key or "preference phrase" in key or "chosen cue" in key:
        return "preference"
    if "routine" in key or "habit" in key or "responsibil" in key:
        return "routine"
    if "prior interaction" in key or "prior example" in key or "raw prior" in key:
        return "prior"
    if "sensitive" in key or "private" in key or "contact" in key or "account" in key or "privacy" in key or "disclosure" in key:
        return "sensitive"
    if "correction" in key or "avoidance" in key or key == "avoidance":
        return "correction"
    if "health" in key or "dietary" in key or "condition" in key:
        return "health"
    if "value" in key or "concern" in key or "underlying" in key or "background phrase" in key or "background cue" in key:
        return "value"
    if "interest" in key or "personal cue" in key or "reusable cue" in key or "source detail" in key:
        return "preference"
    return ""


def _personamem_field_posterior_field_weight(label: Any) -> int:
    key = _lower_clean(label)
    if "stable role" in key or "role background" in key or "identity background" in key:
        return 132
    if "stable persona" in key:
        return 72
    if "recurring preference" in key:
        return 124
    if "concrete preference" in key or "preference phrase" in key:
        return 88
    if "raw prior" in key:
        return 260
    if "prior interaction" in key or "prior example" in key:
        return 92
    if "interest" in key:
        return 34
    if "reusable" in key or "personal cue" in key or "source detail" in key:
        return 48
    field = _personamem_field_posterior_label(label)
    return {
        "preference": 92,
        "role": 88,
        "prior": 86,
        "sensitive": 90,
        "correction": 78,
        "routine": 70,
        "health": 74,
        "value": 48,
        "topic": 34,
    }.get(field, 0)


_PERSONAMEM_ACTION_STATE_HEAD_RE = re.compile(
    r"^(?:"
    r"enjoys?|likes?|loves?|prefers?|favors?|favours?|appreciates?|avoids?|values?|supports?|"
    r"attends?|takes?|reads?|watches?|plays?|listens?\s+to|uses?|collects?|"
    r"drinks?|eats?|wears?|buys?|volunteers?|travels?|visits?|cooks?|keeps?|"
    r"maintains?|follows?\s+up|follow\s+up|practic(?:e|es|ing)|swims?|swimming|go(?:es)?\s+to|do|does"
    r")\b",
    re.IGNORECASE,
)


def _personamem_strip_spurious_action_article(value: Any) -> str:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text:
        return ""
    match = re.match(
        r"^(?:a|an)\s+(?P<body>"
        r"(?:enjoys?|likes?|loves?|prefers?|favors?|favours?|appreciates?|avoids?|values?|supports?|"
        r"attends?|takes?|reads?|watches?|plays?|listens?\s+to|uses?|collects?|"
        r"drinks?|eats?|wears?|buys?|volunteers?|travels?|visits?|cooks?|keeps?|"
        r"maintains?|follows?\s+up|follow\s+up|practic(?:e|es|ing)|swims?|swimming|go(?:es)?\s+to|do|does)\b.*)$",
        text,
        flags=re.IGNORECASE,
    )
    return _clean_text(match.group("body")).strip(" -*,.;:'\"") if match else text


def _personamem_verb_headed_action_atom(value: Any) -> bool:
    text = _lower_clean(_personamem_strip_spurious_action_article(value))
    if not text:
        return False
    return bool(_PERSONAMEM_ACTION_STATE_HEAD_RE.match(text))


def _personamem_coordination_title_list(value: Any) -> bool:
    """Detect title-like enumerations that are not a single latent role atom."""

    text = _clean_text(value).strip(" -*,.;:'\"")
    low = _lower_clean(text)
    if not text or "," not in text:
        return False
    if re.search(r"\b(?:who|works? as|working as|speciali[sz](?:es|ing)|from|based in|responsible for)\b", low):
        return False
    parts = [
        _clean_text(part).strip(" -*,.;:'\"")
        for part in re.split(r"\s*,\s*", text)
        if _clean_text(part).strip(" -*,.;:'\"")
    ]
    if len(parts) < 2:
        return False
    short_parts = sum(1 for part in parts if len(_lower_clean(part).split()) <= 5)
    if short_parts < 2:
        return False
    if any(_personamem_verb_headed_action_atom(part) for part in parts):
        return False
    return bool(
        re.search(r"\b(?:swim|event|preparation|collaboration|artist|plan|choice|project|idea|topic)\b", low)
    )


def _personamem_nonpersona_nominal_summary(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _personamem_role_signature(value):
        return False
    if _personamem_coordination_title_list(value):
        return True
    if text.startswith("a user:") or text.startswith("an user:") or re.match(r"^(?:a|an)\s+(?:my|our|your)\b", text):
        return True
    if re.match(r"^(?:a|an)\s+(?:one|two|three|four|five|six|seven|eight|nine|ten|\d+)\b", text):
        return True
    return bool(
        re.match(
            r"^(?:a|an)\s+[^.;,\n]{0,90}\b(?:sessions?|days?|plans?|activities?|options?|recommendations?|workouts?|routines?|choices?)\b",
            text,
        )
    )


def _personamem_action_state_normal_form(value: Any) -> str:
    """Map visible action/predicate evidence into a typed preference-state atom."""

    text = _personamem_strip_spurious_action_article(value)
    if not text:
        return ""
    text = _canonicalize_personamem_specific(text).strip(" -*,.;:'\"")
    low = _lower_clean(text)
    if not low or not _personamem_verb_headed_action_atom(text):
        return ""
    if _is_personamem_generic_advice(low) or _personamem_truncated_projection_fragment(text):
        return ""
    if re.search(r"\b(?:plan item|why this fits|recommendations?|current task|surface request)\b", low):
        return ""
    exercise_match = re.match(
        r"^(?:prefers?|likes?|enjoys?)\s+(?P<activity>[a-z][a-z -]{2,80}ing)\s+as\s+a\s+form\s+of\s+exercise\b",
        text,
        flags=re.IGNORECASE,
    )
    if exercise_match:
        activity = _clean_text(exercise_match.group("activity")).strip(" -*,.;:'\"")
        text = f"like {activity} as a form of exercise"
    text = re.sub(r"\s+", " ", text).strip(" -*,.;:'\"")
    if not (3 <= len(_lower_clean(text).split()) <= 24):
        return ""
    return text


def _personamem_action_state_core_variants(value: Any) -> list[str]:
    text = _personamem_action_state_normal_form(value)
    if not text:
        return []
    variants = [text]
    low = _lower_clean(text)
    split = re.split(
        r"\s+\band\s+(?=(?:engages?|connects?|aligns?|supports?|keeps?|maintains?|uses?|includes?)\b)",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )
    if len(split) > 1 and 3 <= len(_lower_clean(split[0]).split()) <= 12:
        variants.append(split[0].strip(" -*,.;:'\""))
    match = re.match(
        r"^(?:prefers?|likes?|enjoys?)\s+(?P<activity>[a-z][a-z -]{2,80})\s+as\s+a\s+form\s+of\s+exercise\b",
        text,
        flags=re.IGNORECASE,
    )
    if match:
        activity = _clean_text(match.group("activity")).strip(" -*,.;:'\"")
        if activity:
            variants.append(f"like {activity} as a form of exercise")
    if re.search(r"\bpractic(?:e|es|ing)\s+powerlifting\s+at\s+the\s+gym\b", low):
        variants.append("practices powerlifting at the gym")
    return _dedupe_preserving(
        _canonicalize_personamem_specific(item)
        for item in variants
        if item and not _is_personamem_generic_advice(item)
    )


def _personamem_role_residual_identity_variants(value: Any) -> list[str]:
    text = _canonicalize_personamem_specific(value).strip(" -*,.;:'\"")
    low = _lower_clean(text)
    if not text or not _personamem_role_signature(text):
        return []
    if _personamem_nonpersona_nominal_summary(text):
        return []
    action_head = (
        r"(?:enjoys?|likes?|loves?|prefers?|favors?|avoids?|values?|supports?|"
        r"attends?|takes?|practice|practices|practicing|swims?|swimming|reads?|"
        r"watches?|plays?|listens?\s+to|uses?|collects?|volunteers?|travels?)"
    )
    identity_predicate = (
        r"(?:relies?\s+on|credits?|teaches?|works?\s+(?:as|with|in|for)|"
        r"speciali[sz](?:es|ing)\s+in|is\s+passionate\s+about|is\s+a\s+fan\s+of|"
        r"is\s+also\s+a\s+fan\s+of|fan\s+of|has\s+[^.;,\n]{2,80})"
    )
    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    match = re.match(
        rf"^(?P<head>(?:(?:a|an)\s+)?[^.;,\n]{{2,90}}\b(?:{role_terms}))\s+who\s+"
        rf"{action_head}\b[^.;,\n]{{2,140}}\s+\band\s+(?P<pred>{identity_predicate}\b[^.;,\n]{{2,180}})$",
        text,
        flags=re.IGNORECASE,
    )
    variants: list[str] = []
    if match:
        head = _clean_text(match.group("head")).strip(" -*,.;:'\"")
        pred = _clean_text(match.group("pred")).strip(" -*,.;:'\"")
        if head and pred:
            if not re.match(r"^(?:a|an)\s+", _lower_clean(head)):
                head = f"{_personamem_indefinite_article(head)} {head}"
            variants.append(f"{head} who {pred}")
    if re.match(r"^as\s+a\s+", low):
        variants.append(re.sub(r"^as\s+", "", text, flags=re.IGNORECASE).strip(" -*,.;:'\""))
    return _dedupe_preserving(
        _canonicalize_personamem_specific(item)
        for item in variants
        if item and len(_lower_clean(item).split()) <= 34 and not _is_personamem_generic_advice(item)
    )


def _personamem_explicit_role_field_atom(value: Any) -> str:
    text = _strip_personamem_field_certificate_tail(value).strip(" -*,.;:'\"")
    if not text:
        return ""
    text = re.sub(r"^i\s+am\s+", "", text, flags=re.IGNORECASE).strip(" -*,.;:'\"")
    # Some visible field cards accidentally continue with the downstream
    # answer after a short role sentence.  Keep the identity sentence only.
    split = re.split(r"(?<=[.!?])\s+(?=(?:on|for|based on|you might|you could|consider|try)\b)", text, maxsplit=1, flags=re.IGNORECASE)
    if split:
        text = split[0].strip(" -*,.;:'\"")
    low = _lower_clean(text)
    if not low or _is_personamem_generic_advice(low):
        return ""
    if _personamem_placeholder_prior_text(text):
        return ""
    if _personamem_action_nominal_role_atom(text):
        return ""
    if _personamem_verb_headed_action_atom(text) or _personamem_nonpersona_nominal_summary(text):
        return ""
    if _PERSONAMEM_ROLE_PREF_HEAD_RE.match(low):
        return ""
    if _PERSONAMEM_ROLE_STATE_HEAD_RE.match(low):
        return ""
    if _PERSONAMEM_WORK_AT_RE.match(low):
        return ""
    if _PERSONAMEM_FIELD_CARD_NOISE_RE.search(low):
        return ""
    tokens = low.split()
    if len(tokens) < 3 or len(tokens) > 30:
        return ""
    stable_shape = bool(
        re.search(
            r"\b(?:who|interested in|looking for|part of|working as|works as|at a|at an|at the|from|with|"
            r"specializing|specializes|focusing on|focused on|responsible for|returning to school|"
            r"back to school|additional training|coached by|trained by|mentored by|creating a documentary|"
            r"making a documentary|producing a documentary|working on a documentary|oversees the licensing|"
            r"manages the licensing)\b",
            low,
        )
        or re.match(r"^(?:a|an)\s+(?:retired|former|wealthy|peer|local|senior|junior|professional|executive|graduate|university|college)\b", low)
    )
    if not stable_shape:
        return ""
    if not re.match(r"^(?:a|an)\s+", low):
        article = _personamem_indefinite_article(text)
        text = f"{article} {text}"
    return _canonicalize_personamem_specific(text)


def _personamem_action_nominal_role_atom(value: Any) -> bool:
    """Detect ordinary activity phrases that should not occupy the role slot."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    if _personamem_role_signature(text):
        return False
    if re.match(
        r"^(?:a|an)\s+"
        r"(?:brewing|savoring|sitting|walking|cycling|running|swimming|hiking|"
        r"cooking|baking|reading|watching|playing|listening|using|collecting|"
        r"attending|visiting|translating|drafting|writing|reviewing|planning|"
        r"preparing|managing|handling|disputing|setting|seeking|creating|making)\b",
        text,
    ):
        return True
    return bool(
        re.match(r"^(?:a|an)\s+[^.;,\n]{2,80}\bwhile\s+(?:i|you|they|we)\b", text)
        and not _is_personamem_persona_carrier(text)
    )


def _personamem_field_posterior_atoms(field: str, value: Any, *, chosen_topic: str) -> list[str]:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text or text.lower() in {"none", "unknown", "not specified", "not available"}:
        return []
    atoms: list[str] = []
    if field == "topic":
        topic = _canonical_personamem_topic_label(text) or _lower_clean(text)
        if topic and (not chosen_topic or topic == _lower_clean(chosen_topic) or topic in {"health_and_medical", "sensitive_info", "culture", "sports", "food", "fashion"}):
            atoms.append(topic)
    elif field == "role":
        explicit_role = _personamem_explicit_role_field_atom(text)
        if explicit_role:
            atoms.append(explicit_role)
        atoms.extend(_personamem_orthogonal_role_atoms(text))
        atoms.extend(_personamem_role_spine_atoms_from_value(text))
        canonical = _canonicalize_personamem_specific(text)
        low = _lower_clean(canonical)
        if re.match(r"^i\s+am\s+(?:a|an)\s+", low):
            atoms.append(canonical)
            normalized_role = re.sub(r"^i\s+am\s+", "", canonical, flags=re.IGNORECASE).strip()
            if normalized_role:
                atoms.append(normalized_role)
                canonical = normalized_role
                low = _lower_clean(canonical)
        if canonical and not _is_personamem_topic_atom(low):
            if _is_personamem_persona_carrier(canonical) and not re.match(r"^(?:a|an)\s+", low):
                article = "an" if re.match(r"^[aeiou]", low) else "a"
                canonical = f"{article} {canonical}"
            if _is_personamem_persona_carrier(canonical) or re.search(r"\bwho\b", low):
                atoms.append(canonical)
    elif field == "prior":
        prior = _strip_earlier_example_prefix(text)
        if _personamem_placeholder_prior_text(prior):
            return []
        if prior and ("user:" in _lower_clean(prior) or len(prior.split()) >= 8):
            atoms.append(prior)
        atoms.extend(_personamem_polarity_preserving_atoms(prior))
    elif field == "sensitive":
        atoms.extend(_personamem_contact_atoms_from_text(text))
        atoms.extend(_personamem_health_constraint_atoms_from_text(text))
        atoms.extend(_personamem_polarity_preserving_atoms(text))
        if re.search(r"\b(?:sensitive|private|privacy|license|ssn|address|api[_ -]?key|credit card|bank account)\b", text, flags=re.IGNORECASE):
            atoms.append("sensitive_info")
        if _is_personamem_sensitive_carrier(text):
            atoms.append(_canonicalize_personamem_specific(text))
    elif field == "health":
        atoms.extend(_personamem_health_constraint_atoms_from_text(text))
        atoms.extend(_personamem_polarity_preserving_atoms(text))
        if not atoms:
            atoms.append(_canonicalize_personamem_specific(text))
    elif field == "correction":
        atoms.extend(_personamem_negative_atoms_from_text(text))
        atoms.extend(_personamem_health_constraint_atoms_from_text(text))
        atoms.extend(_personamem_polarity_preserving_atoms(text))
        if re.search(r"\b(?:avoid|avoids|do not|don't|forget|no longer|without)\b", text, flags=re.IGNORECASE):
            atoms.append(_canonicalize_personamem_specific(text))
    else:
        if field == "preference":
            atoms.extend(_personamem_orthogonal_preference_atoms(text))
        atoms.extend(_personamem_polarity_preserving_atoms(text))
        atoms.extend(_personamem_causal_spine_atoms_from_labeled_value(field, text))
        atoms.extend(_personamem_contact_atoms_from_text(text))
        atoms.extend(_personamem_health_constraint_atoms_from_text(text))
        atoms.append(_canonicalize_personamem_specific(text))
    return _dedupe_preserving(
        atom
        for atom in atoms
        if _clean_text(atom) and not _is_personamem_generic_advice(atom)
    )


def _personamem_field_posterior_atom_admissible(field: str, atom: Any) -> bool:
    text = _lower_clean(atom)
    if not text:
        return False
    if _personamem_placeholder_prior_text(atom):
        return False
    if field == "role":
        if re.match(r"^(?:a\s+)?(?:helper|traveler|planner|recommender|gift seeker|gift giver|personalized gifting|travel planning|event planner)\b", text):
            return False
        if _personamem_low_information_role_atom(atom):
            return False
        if _personamem_role_preference_fusion(atom):
            return False
        return (
            _is_personamem_persona_carrier(atom)
            or bool(re.search(r"\bwho\b", text))
            or bool(_personamem_explicit_role_field_atom(atom))
        )
    if field == "topic":
        return _is_personamem_topic_atom(text) and text not in {"communication", "event", "events", "home"}
    if field == "prior":
        return _is_personamem_conversation(atom) or len(text.split()) >= 8
    if field == "sensitive":
        return text == "sensitive_info" or _is_personamem_sensitive_carrier(atom) or ":" in str(atom)
    if field == "correction":
        return (
            _is_personamem_negative_carrier(atom)
            or re.search(r"\b(?:avoid|forget|do not|don't|no longer|without)\b", text) is not None
            or re.search(r"\b(?:unresolved grief|father[’']?s assassination|low-dose testosterone)\b", text) is not None
        )
    if field == "preference" and _personamem_low_information_preference_atom(atom):
        return False
    return _personamem_final_preference_admissible(atom)


def _personamem_field_posterior_prior(field: str, atom: Any) -> int:
    text = _lower_clean(atom)
    score = 0
    if _personamem_placeholder_prior_text(atom):
        score -= 240
    if field == "role" and _is_personamem_persona_carrier(atom):
        score += 32
        if "who is also" in text or re.search(r"\b(?:specializing|specializes|distant friend|close friend|long[- ]time friend)\b", text):
            score += 70
        if re.search(r"\b(?:who participated|participated in|attended|conference|symposium|in 19\d{2}|in 20\d{2})\b", text):
            score += 54
        if _personamem_identity_bound_role_modifier(atom):
            score += 86
        if _personamem_role_preference_fusion(atom):
            score -= 120
    if field == "preference" and _personamem_bayesian_ledger_atom(atom):
        score += 34
    if field == "preference" and re.match(r"^(?:experiences|feels|has|needs|seeks|struggles with|is concerned about)\b", text):
        score += 76
    if field == "preference" and re.search(r"\b(?:over|regularly attends|often attends|frequently attends)\b", text):
        score += 46
    if field == "preference" and _personamem_preference_comparison_atom(atom):
        score += 84
    if field == "prior" and _is_personamem_conversation(atom):
        score += 30
    if field == "sensitive" and (text == "sensitive_info" or ":" in str(atom)):
        score += 34
    if field in {"health", "sensitive"} and re.search(r"\b(?:allergies|seasonal allergic rhinitis)\b", text):
        score += 58
    if field == "correction" and _is_personamem_negative_carrier(atom):
        score += 62
    if re.search(r"\b(?:helper|planner|traveler|recommendation|surface request|plan item|why this fits)\b", text):
        score -= 45
    return score


def _personamem_field_posterior_acceptance_threshold(field: str) -> int:
    return {
        "role": 28,
        "preference": 22,
        "routine": 12,
        "prior": 0,
        "sensitive": 4,
        "correction": 4,
        "health": 4,
        "value": 12,
        "topic": 0,
    }.get(field, 10)


def _personamem_low_information_role_atom(atom: Any) -> bool:
    text = _lower_clean(atom)
    if not text:
        return True
    if _personamem_action_nominal_role_atom(atom):
        return True
    if _personamem_nonpersona_nominal_summary(atom):
        return True
    if re.match(r"^(?:a|an)\s+(?:prefer|prefers|enjoys?|likes?|loves?|favors?|values?|supports?)\b", text):
        return True
    if re.match(
        r"^(?:a|an|is a|is an)\s+(?:professional|person|someone|student|artist|manager|"
        r"employee|enthusiast|owner|representative|specialist|agent|guru|expert|youth|teenager|"
        r"player|officer|manufacturer|photographer|researcher)\b$",
        text,
    ):
        return True
    if re.match(
        r"^(?:(?:a|an)\s+)?(?:past|history of|health|medical|knee|ligament|injury|strain|surgery)\b",
        text,
    ):
        return True
    if re.match(r"^(?:(?:a|an)\s+)?(?:works?|working)\s+(?:at|in|for)\b", text):
        return True
    if re.match(r"^(?:a|an)\s+expressed\s+interest\s+in\b", text):
        return True
    if re.match(r"^(?:a|an)\s+(?:seeking|connects?|connection|interest|preference)\b", text):
        return True
    if re.search(r"\b(?:connects to personal and professional|seeking intellectually stimulating content)\b", text):
        return True
    signature = _personamem_role_signature(atom)
    return bool(signature in {"professional", "person", "someone", "individual"} and len(text.split()) <= 8)


def _personamem_low_information_preference_atom(atom: Any) -> bool:
    text = _lower_clean(atom)
    if not text:
        return True
    if _personamem_placeholder_prior_text(atom):
        return True
    if _personamem_truncated_projection_fragment(atom):
        return True
    if "<pref" in text or "should not be reused" in text:
        return True
    if "unknown" in text and ("|" in str(atom) or "unknown mango" in text or "unknown iced" in text):
        return True
    if re.search(r"\b(?:constraints?|facts?|preferences?)$", text):
        return True
    if "preference note:" in text:
        return True
    if re.match(r"^\[[a-z_ -]{3,40}\]\)", text):
        return True
    if re.search(r"\b(?:pci dss|environment variables|secure vault|end-to-end encryption|regulatory compliance)\b", text):
        return True
    if len(text.split()) <= 2 and re.search(r"\b(?:mine|yours|hers|his|theirs|this|that|it|me|us)\b", text):
        return True
    if text in {
        "alienation",
        "fascination",
        "anxiety",
        "calmness",
        "nostalgia",
        "sadness",
        "stress",
        "burnout",
        "exhaustion",
        "health",
        "values data privacy",
        "prefers administrative tasks",
        "prefer administrative tasks",
    }:
        return True
    if re.match(r"^prefers?\s+(?:administrative tasks|masking sensitive information|address verification)\b", text):
        return True
    if re.search(
        r"\b(?:likes|enjoys|prefers|favors|loves|uses|reads|watches|listens to)\s+"
        r"(?:mine|mins?|yours|hers|his|theirs|this|that|it|me|us)\b",
        text,
    ):
        return True
    if re.match(
        r"^(?:likes|enjoys|prefers|favors|loves|uses|reads|watches|listens to)\s+"
        r"(?:mine|mins?|yours|hers|his|theirs|this|that|it|me|us)\b",
        text,
    ):
        return True
    if re.match(r"^(?:likes|enjoys|prefers|favors|loves|uses|reads|watches|listens to)\s+such as\b", text):
        return True
    if re.match(r"^(?:prefers?|favors?|enjoys?|likes?)\s+(?:scre|hands-on|screen|non|personalized|ordinary)\b$", text):
        return True
    if re.match(r"^(?:prefers?|favors?|enjoys?|likes?)\s+appreciates?\b", text):
        return True
    if re.search(r"\b(?:prefers|favors|likes|enjoys)\s+(?:subtle|accurate|fluid|vivid)\b", text):
        return True
    if re.match(r"^(?:supports?|favors?|prefers?)\s+preference\s+for\b", text):
        return True
    if re.search(r"\brecommendations?\s+(?:for|based on)\b", text):
        return True
    if re.search(r"\balign with academic and intellectual pursuits\b", text):
        return True
    return False


def _personamem_field_posterior_selection_score(
    field: str,
    atom: Any,
    base_score: int,
    reasons: set[str] | frozenset[str],
) -> int:
    """Combine noisy-view evidence with field-level source reliability."""

    return (
        int(base_score)
        + _personamem_field_reason_reliability_bonus(field, reasons)
        + _personamem_field_specificity_score(field, atom)
    )


def _personamem_field_reason_reliability_bonus(field: str, reasons: set[str] | frozenset[str]) -> int:
    bonus = 0
    reason_keys = {_lower_clean(reason) for reason in reasons}
    if any(reason.startswith("field:") for reason in reason_keys):
        bonus += 72
    if f"field:{field}" in reason_keys:
        bonus += 36
    if "pseudo:second_person_cause" in reason_keys:
        bonus += 46
    if "pseudo:second_person_preference" in reason_keys:
        bonus += 32
    if "pseudo:role_phrase" in reason_keys:
        bonus += 30
    if "pseudo:contact_identifier" in reason_keys or "pseudo:health_constraint" in reason_keys:
        bonus += 34
    if "pseudo:third_person_preference" in reason_keys:
        bonus += 14
    return bonus


def _personamem_concrete_evidence_bonus(atom: Any) -> int:
    """Reward reusable, inspectable evidence over abstract explanations."""

    raw = _clean_text(atom)
    text = _lower_clean(raw)
    if not text:
        return 0
    bonus = 0
    if _is_personamem_conversation(atom):
        return 0
    if re.search(r"\b(?:19|20)\d{2}\b|\b\d{2,}\b", raw):
        bonus += 14
    if re.search(r"\b[A-Z][A-Za-z0-9'_-]{2,}\b", raw):
        bonus += 10
    if re.search(
        r"\b(?:airlines?|flights?|train|bus|hotel|restaurant|stand[- ]up comedy|comedy shows?|"
        r"school project|town'?s history|local history|street art|graffiti|muralists?|public spaces?|"
        r"development team|onboarding|jargon|colleague|file paths?|code paths?|main\.py|"
        r"api[_ -]?key|healthcare app|budget|short trips?|supplier|suppliers?|student|students?|"
        r"teaching|curriculum|lessons?|translation|russian|french|java|mass spectrometry)\b",
        text,
    ):
        bonus += 54
    if re.search(
        r"\b(?:attends?|travels?|uses?|keeps?|volunteers?|coping with|placed in|expanding|supports?|"
        r"credits?|learn(?:s|ing)?|returning to school|doing a school project|"
        r"without sufficient|live stand[- ]up|budget airlines?)\b",
        text,
    ):
        bonus += 34
    if re.match(
        r"^(?:attends?|travels?|supports?|volunteers?|coping with|was placed in|expanding|credits?)\b",
        text,
    ):
        bonus += 62
    if re.search(r"\b(?:who|that|because|after|during|without|for short trips|on campus|at work)\b", text):
        bonus += 18
    return bonus


def _personamem_generic_abstraction_penalty(atom: Any) -> int:
    text = _lower_clean(atom)
    if not text:
        return 0
    penalty = 0
    if re.search(
        r"\b(?:solutions?|practices?|awareness|guidance|emphasis|culture|cultural exploration|local culture|community|"
        r"cost[- ]effective|affordable destinations?|meaningful cultural interactions|"
        r"secure software development|security-focused|data privacy|sensitive information|"
        r"social dynamics|feeling isolated in social groups|creative public spaces health|"
        r"protecting sensitive information health|relaxed exploration)\b",
        text,
    ):
        penalty += 54
    if re.search(r"\b(?:preference for|interest in|with a preference for|focused on)\b", text):
        penalty += 22
    if re.match(r"^prefers?\s+(?:live stand[- ]up comedy|street art|school project)\b", text):
        penalty += 42
    if len(text.split()) <= 4 and re.search(r"\b(?:culture|community|privacy|security|health|art|work)\b", text):
        penalty += 36
    return penalty


def _personamem_field_specificity_score(field: str, atom: Any) -> int:
    text = _lower_clean(atom)
    if not text:
        return -100
    token_count = len(text.split())
    score = 0
    if _is_personamem_generic_advice(text):
        score -= 90
    if any(marker in text for marker in _PERSONAMEM_SPECIFIC_BAD_MARKERS):
        score -= 120
    if _personamem_placeholder_prior_text(atom):
        score -= 240
    score += _personamem_concrete_evidence_bonus(atom)
    score -= _personamem_generic_abstraction_penalty(atom)
    if re.search(r"\b(?:identifiability-layered state estimate|reservoir observations|facts\s*[-:]|preferences\s*[-:]|constraints\s*[-:]|tool_state\s*[-:])\b", text):
        score -= 160
    if 4 <= token_count <= 30:
        score += 24
    elif token_count <= 2:
        score -= 18
    elif token_count > 46:
        score -= 36
    score += min(50, max(-50, _personamem_invariant_support_score(str(atom)) // 2))

    if field == "role":
        if _personamem_verb_headed_action_atom(atom):
            score -= 120
        score += min(80, _personamem_identifiability_anchor_score(atom))
        score -= min(120, _personamem_role_abstraction_penalty(atom))
        if _is_personamem_persona_carrier(str(atom)):
            score += 42
        if _personamem_explicit_role_field_atom(atom):
            score += 64
        if "who is also" in text:
            score += 74
        if _personamem_identity_bound_role_modifier(atom):
            score += 104
        if re.search(r"\b(?:who participated|participated in|attended|conference|symposium|in 19\d{2}|in 20\d{2})\b", text):
            score += 62
        if re.search(r"\b(?:specializing|specializes)\s+in\b", text):
            score += 60
        if re.search(r"\b(?:distant|close|long[- ]time|childhood|family|professional)\s+friend\s+of\b", text):
            score += 58
        if _personamem_role_preference_fusion(atom):
            score -= 140
        if re.search(
            r"\b(?:who|working|works|focusing|specializing|passionate|believes|advocating|fighting|ensures|promoting|"
            r"dreams|involved|with|at|in|from)\b",
            text,
        ):
            score += 26
        broad_signatures = {
            "professional",
            "person",
            "someone",
            "student",
            "artist",
            "manager",
            "employee",
            "owner",
            "representative",
            "specialist",
            "enthusiast",
            "neighbor",
            "parent",
            "child",
            "agent",
            "guru",
            "youth",
            "teenager",
            "player",
            "officer",
            "manufacturer",
            "photographer",
            "researcher",
            "expert",
        }
        signature = _personamem_role_signature(atom)
        if signature in broad_signatures and token_count <= 5:
            score -= 64
        if re.match(r"^(?:a|an)\s+(?:professional|person|someone|student|artist|manager|employee|enthusiast)\b$", text):
            score -= 80
    elif field == "preference":
        if _personamem_verb_headed_action_atom(atom):
            score += 74
        if re.match(r"^(?:experiences|feels|has|needs|seeks|struggles with|is concerned about)\b", text):
            score += 66
        if re.match(
            r"^(?:enjoys|likes|loves|prefers|favors|avoids|reads|drinks|eats|wears|buys|"
            r"uses|collects|watches|plays|attends|participates|contributes|volunteers|appreciates|seeks|listens to|thrives in)\b",
            text,
        ):
            score += 34
        if re.match(r"^(?:volunteers|travels|attends|collects|uses|listens to|reads|watches|plays)\b", text):
            score += 46
        if re.match(r"^supports\s+(?:ensuring|ethical|aspiring)\b", text):
            score -= 46
        if re.match(r"^prefer\s+.+\bover\b", text):
            score += 108
        if re.match(r"^(?:regularly|often|frequently|usually)\s+attends\b", text):
            score += 54
        if re.search(r"\b(?:choice|option|recommendation|gift idea|plan item|why this fits)\b", text):
            score -= 48
    elif field == "prior":
        if _is_personamem_conversation(str(atom)):
            score += 60
    elif field == "routine":
        if re.match(r"^(?:volunteers|travels|attends|collects|uses|listens to|reads|watches|plays)\b", text):
            score += 74
        if re.match(r"^supports\s+(?:ensuring|ethical|aspiring)\b", text):
            score -= 46
    elif field in {"sensitive", "health"}:
        if _is_personamem_sensitive_carrier(str(atom)) or ":" in str(atom):
            score += 50
        if _personamem_high_precision_specific_atom(str(atom)):
            score += 36
        if re.search(r"\b(?:allergies|seasonal allergic rhinitis)\b", text):
            score += 70
    elif field == "correction":
        if _is_personamem_negative_carrier(str(atom)):
            score += 92
    return score


def _personamem_field_display_prefer(candidate: str, current: str) -> bool:
    cand = _clean_text(candidate)
    cur = _clean_text(current)
    if _is_personamem_conversation(cand) and not _is_personamem_conversation(cur):
        return True
    if _is_personamem_conversation(cand) == _is_personamem_conversation(cur):
        return len(cand) > len(cur) and len(cand) <= 5000
    return len(cand) < len(cur)


def _personamem_field_posterior_sort_key(field: str, atom: str) -> tuple[Any, ...]:
    text = _lower_clean(atom)
    if field == "prior":
        return (0, -min(len(text), 3500), text)
    if field == "role":
        return (
            0 if _is_personamem_persona_carrier(atom) else 1,
            -_personamem_field_specificity_score(field, atom),
            -min(len(text), 260),
            text,
        )
    if field == "preference":
        return (
            0 if _personamem_bayesian_ledger_atom(atom) else 1,
            -_personamem_field_specificity_score(field, atom),
            text,
        )
    if field == "sensitive":
        return (0 if ":" in str(atom) else 1, -_personamem_field_specificity_score(field, atom), text)
    return (0, -_personamem_field_specificity_score(field, atom), text)


def _personamem_ledger_atom_admissible(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or _is_personamem_generic_advice(text):
        return False
    if _personamem_low_information_preference_atom(value) and not _personamem_choice_certificate_projected_atom(value):
        return False
    if _personamem_final_preference_admissible(value) is False and not _is_personamem_topic_atom(text):
        return False
    if re.match(r"^(?:a\s+)?(?:helper|traveler|planner|recommender|gift seeker|gift giver|personalized gifting|travel planning)\b", text):
        return False
    if re.search(r"\b(?:choice=[a-d]|plan item=|why this fits=|decision=|surface request detail|column 1|column 2)\b", text):
        return False
    if " - " in str(value) and len(text.split()) > 14:
        return False
    if _is_personamem_conversation(value):
        return len(text.split()) >= 12
    if _is_personamem_topic_atom(text):
        return text not in {"communication", "event", "events", "home"}
    return bool(
        _is_personamem_persona_carrier(value)
        or _personamem_invariant_choice_atom(value)
        or _personamem_high_precision_specific_atom(value)
        or _is_personamem_negative_carrier(value)
        or _is_personamem_sensitive_carrier(value)
    )


def _personamem_ledger_prior(value: Any) -> int:
    text = _lower_clean(value)
    score = 0
    if _is_personamem_persona_carrier(value):
        score += 34
    if _personamem_invariant_choice_atom(value):
        score += 34
    if _personamem_high_precision_specific_atom(value):
        score += 26
    if _is_personamem_conversation(value):
        score += 20
    if _is_personamem_topic_atom(text):
        score += 12
    if re.search(r"\b(?:user|assistant|stable role|recurring preference|memory topic)\b", text):
        score += 8
    if re.search(r"\b(?:generic|helper|surface|downstream recommendation|ordinary answer)\b", text):
        score -= 40
    return score


def _personamem_ledger_sort_key(value: str) -> tuple[int, int, str]:
    text = _lower_clean(value)
    if _personamem_invariant_choice_atom(value):
        family = 0
    elif _is_personamem_persona_carrier(value):
        family = 1
    elif _is_personamem_conversation(value):
        family = 2
    elif _is_personamem_topic_atom(text):
        family = 3
    else:
        family = 4
    return (family, abs(len(text.split()) - 12), text)


def _personamem_remove_subsumed_ledger_atoms(items: Sequence[str]) -> list[str]:
    selected: list[str] = []
    selected_keys: list[str] = []
    selected_token_sets: list[set[str]] = []
    for item in items:
        key = _semantic_compact_adapter(item)
        if not key:
            continue
        if _is_personamem_topic_atom(_lower_clean(item)):
            tokens = {tok for tok in key.split() if len(tok) > 1}
            selected.append(item)
            selected_keys.append(key)
            selected_token_sets.append(tokens)
            continue
        tokens = {tok for tok in key.split() if len(tok) > 1}
        token_count = len(tokens)
        if token_count <= 4 and any(key in prior for prior in selected_keys):
            continue
        if any(key != prior and key in prior and len(key) / max(len(prior), 1) < 0.7 for prior in selected_keys):
            continue
        if token_count <= 12 and any(tokens and tokens == prior_tokens for prior_tokens in selected_token_sets):
            continue
        if token_count <= 12 and any(
            tokens
            and tokens.issubset(prior_tokens)
            and len(tokens) / max(len(prior_tokens), 1) < 0.95
            for prior_tokens in selected_token_sets
        ):
            continue
        selected.append(item)
        selected_keys.append(key)
        selected_token_sets.append(tokens)
    return selected


def _personamem_bayesian_ledger_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or _is_personamem_conversation(value) or _is_personamem_topic_atom(text):
        return False
    if " - " in str(value) and len(text.split()) > 14:
        return False
    if (
        3 <= len(text.split()) <= 24
        and re.match(
            r"^(?:drinks?|eats?|buys?|loves?|likes?|prefers?|favors?|avoids?|invests?|wears?|uses?|appreciates?|thrives?|listens?|seeks?|collects?|watches?|reads?|plays?|attends?|frequently|often|usually)\b",
            text,
        )
        and _personamem_specific_support_score(value) >= 18
    ):
        return True
    return bool(
        (_is_personamem_persona_carrier(value) and 4 <= len(text.split()) <= 32)
        or (_personamem_invariant_choice_atom(value) and 3 <= len(text.split()) <= 24)
        or _personamem_high_precision_specific_atom(value)
    )


def _personamem_final_preference_admissible(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _personamem_placeholder_prior_text(value):
        return False
    if _is_personamem_field_certificate_source(value):
        return False
    if _personamem_low_information_preference_atom(value):
        return False
    if _is_personamem_conversation(value):
        return True
    if " - " in str(value) and len(text.split()) > 18:
        return False
    if " - " in str(value):
        suffix_parts = [
            _canonical_personamem_topic_label(part) or _lower_clean(part)
            for part in str(value).split(" - ")[1:]
        ]
        suffix_parts = [part for part in suffix_parts if part]
        if suffix_parts and all(part in _PERSONAMEM_TOPIC_LABELS for part in suffix_parts):
            return False
    if re.search(r"\bin memory\s+-\s+", text):
        return False
    tokens = text.split()
    if (
        len(tokens) >= 4
        and tokens[-1] in _PERSONAMEM_TOPIC_LABELS
        and tokens[-2] in _PERSONAMEM_TOPIC_LABELS
    ):
        return False
    if _is_personamem_negative_carrier(value) or _is_personamem_sensitive_carrier(value):
        return True
    if re.search(r"\b(?:stable persona|interests?|routine/habit|value/concern|values/concerns|role/background)\s*=", text):
        return False
    if re.search(r"\b(?:identifiability-layered state estimate|reservoir observations|facts\s*[-:]|preferences\s*[-:]|constraints\s*[-:]|tool_state\s*[-:])\b", text):
        return False
    if text.startswith("supports to ") or "preference for initiatives that align" in text:
        return False
    if any(
        marker in text
        for marker in (
            "smoother phrasing",
            "more polished narratives",
            "maintain emotional depth",
            "keeps that heartfelt tone",
            "preserve the heart",
            "surface request detail",
        )
    ):
        return False
    if any(
        marker in text
        for marker in (
            "organizations like",
            "brands values",
            "make a tangible difference",
            "host charity",
            "partner with",
            "offering workshops",
            "use your platform",
            "creating accessible opportunities",
        )
    ):
        return False
    return not _is_personamem_generic_advice(text)


def _regularize_personalens_posterior(model: Mapping[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
    """Keep structured profile carriers and discard generic recommendation prose."""

    regularized = copy.deepcopy(dict(model))
    facts = [_rewrite_locomo_answer_evidence(item) for item in _clean_text_list(regularized.get("facts", []))]
    preferences = _clean_text_list(regularized.get("preferences", []))
    raw_preference_texts = list(preferences)
    raw_text = _clean_text(regularized.get("raw_text", ""))
    raw_context_texts = [raw_text] if raw_text else []
    role_source_texts = _dedupe_preserving([*facts, *raw_preference_texts, *raw_context_texts])
    extracted_facts, extracted_preferences = _personalens_profile_context_atoms(facts)
    preference_context_facts, preference_context_preferences = _personalens_profile_context_atoms(
        [*raw_preference_texts, *raw_context_texts]
    )
    if extracted_facts or extracted_preferences:
        facts.extend(extracted_facts)
        preferences.extend(extracted_preferences)
    if preference_context_facts or preference_context_preferences:
        facts.extend(preference_context_facts)
        preferences.extend(preference_context_preferences)
    compound_preferences = _personalens_compound_keyvalue_preferences(
        [*raw_preference_texts, *raw_context_texts]
    )
    if compound_preferences:
        preferences.extend(compound_preferences)

    structured_facts = [
        _canonicalize_personalens_fact_item(item)
        for item in facts
        if _personalens_profile_fact_like(item) and _personalens_fact_admissible(item)
    ]
    structured_facts = _personalens_rewrite_fact_atoms(structured_facts)
    structured_preferences = [
        _personalens_rewrite_preference_atom(item)
        for item in preferences
        if _personalens_profile_preference_like(item) and _personalens_preference_admissible(item)
    ]
    structured_preferences = [item for item in structured_preferences if item]
    structured_preferences = [
        item
        for item in structured_preferences
        if not _personalens_not_specified_preference(item)
        and _personalens_preference_type_compatible(item)
    ]
    if structured_facts or structured_preferences:
        facts = structured_facts
        preferences = structured_preferences

    regularized["facts"] = _dedupe_preserving(facts)
    regularized["preferences"] = _dedupe_preserving(preferences)
    regularized["raw_text"] = _render_layered_raw_text(regularized)
    metadata = dict(regularized.get("metadata", {}) if isinstance(regularized.get("metadata"), Mapping) else {})
    if role_source_texts:
        metadata["personalens_role_source_texts"] = role_source_texts[:48]
    regularized["metadata"] = metadata
    return regularized, {
        "status": "applied",
        "model": "r006_personalens_structured_carrier_projection_v1",
        "carrier_families": {
            "facts_before": len(_clean_text_list(model.get("facts", []))),
            "facts_after": len(regularized["facts"]),
            "preferences_before": len(_clean_text_list(model.get("preferences", []))),
            "preferences_after": len(regularized["preferences"]),
            "profile_context_fact_atoms": len(extracted_facts),
            "profile_context_preference_atoms": len(extracted_preferences),
            "preference_context_fact_atoms": len(preference_context_facts),
            "preference_context_preference_atoms": len(preference_context_preferences),
            "compound_preference_atoms": len(compound_preferences),
            "raw_context_sources": len(raw_context_texts),
        },
    }


def _personalens_profile_context_atoms(facts: Sequence[str]) -> tuple[list[str], list[str]]:
    fact_atoms: list[str] = []
    preference_atoms: list[str] = []
    for item in facts:
        text = _clean_text(item)
        lowered = text.lower()
        if not lowered.startswith(("profile context:", "time=", "compact alarm defaults checklist:")):
            continue
        normalized = re.sub(r"\s*-\s*", ": ", text)
        normalized = re.sub(r"\s+", " ", normalized)
        key_patterns: tuple[tuple[str, str, str], ...] = (
            ("Marital Status", "fact", "marital_status"),
            ("marital_status", "fact", "marital_status"),
            ("English Proficiency", "fact", "english_proficiency"),
            ("english_proficiency", "fact", "english_proficiency"),
            ("Gender", "fact", "gender"),
            ("Education", "fact", "education"),
            ("Religion", "fact", "religion"),
            ("Language", "fact", "english_proficiency"),
            ("Country", "fact", "reside_country"),
            ("Active Interests", "fact", "interest"),
            ("Alarm Sound Preference", "preference", "Alarm Sound Preference"),
            ("Favorite Alarm Sound", "preference", "Alarm Sound Preference"),
            ("Sound", "preference", "Alarm Sound Preference"),
            ("Alarm Time Preference", "preference", "Alarm Time Preference"),
            ("Time", "preference", "Alarm Time Preference"),
            ("Alarm Recurring Preference", "preference", "Alarm Recurring Preference"),
            ("Recurrence", "preference", "Alarm Recurring Preference"),
            ("Location Preference", "preference", "Location Preference"),
            ("Additional Feature Preference", "preference", "Additional Feature Preference"),
            ("Additional Feature", "preference", "Additional Feature Preference"),
            ("Media", "preference", "Favorite Media"),
            ("Favorite Media", "preference", "Favorite Media"),
            ("Team", "preference", "Favorite Team"),
            ("Favorite Team", "preference", "Favorite Team"),
            ("Budget or Price", "preference", "Price Range"),
            ("Price Range", "preference", "Price Range"),
            ("Car or Brands", "preference", "Prefer Car Brand"),
            ("Car Brand", "preference", "Prefer Car Brand"),
            ("Preferred Car Brand", "preference", "Prefer Car Brand"),
            ("Sectors or Services", "preference", "Prefer Sectors"),
            ("Preferred Sectors", "preference", "Prefer Sectors"),
            ("Amenities", "preference", "Amenity Preference"),
            ("Amenity Preference", "preference", "Amenity Preference"),
            ("Frequency", "preference", "Service Frequency Preference"),
            ("Service Frequency Preference", "preference", "Service Frequency Preference"),
        )
        label_pattern = "|".join(re.escape(label) for label, _, _ in sorted(key_patterns, key=lambda row: len(row[0]), reverse=True))
        lookup = {label.lower(): (kind, canonical) for label, kind, canonical in key_patterns}
        for match in re.finditer(
            rf"\b(?P<label>{label_pattern})\s*(?::|=|is\s+)?\s*(?P<value>.*?)(?=\s+\b(?:{label_pattern})\s*(?::|=|is\s+)?|$)",
            normalized,
            flags=re.IGNORECASE,
        ):
            label = " ".join(match.group("label").lower().split())
            kind, canonical = lookup.get(label, ("", ""))
            value = _clean_text(match.group("value")).strip(" -*,.;:")
            value = re.sub(r"[\s.]+Current Task Choices\b.*$", "", value, flags=re.IGNORECASE).strip()
            if _personalens_bad_value(value):
                continue
            if kind == "fact":
                if canonical == "gender":
                    lowered_value = value.lower()
                    if "female" in lowered_value:
                        fact_atoms.append("gender=female")
                    elif "male" in lowered_value:
                        fact_atoms.append("gender=male")
                    continue
                if canonical == "marital_status":
                    lowered_value = value.lower()
                    if "never been married" in lowered_value:
                        fact_atoms.append("marital_status=never been married")
                        continue
                    fact_atoms.append(f"marital_status={value.lower()}")
                    continue
                if canonical == "interest":
                    for interest in re.split(r",|\band\b", value, flags=re.IGNORECASE):
                        cleaned = re.sub(
                            r"[\s.]+current task choices\b.*$",
                            "",
                            _clean_text(interest).lower(),
                            flags=re.IGNORECASE,
                        ).strip(" .;:")
                        if cleaned and cleaned not in {"active", "interests"}:
                            fact_atoms.append(f"Interest {cleaned}=active")
                else:
                    if canonical == "english_proficiency" and value.lower() in {"english", "en"}:
                        continue
                    fact_atoms.append(f"{canonical}={value.lower() if canonical != 'education' else value}")
            elif kind == "preference":
                if canonical == "Alarm Sound Preference":
                    value_l = value.lower()
                    if value_l.startswith(("recurrence=", "budget=", "brand=", "service=")) or "recurrence=" in value_l:
                        continue
                if canonical == "Price Range" and value and not value.startswith("$"):
                    value = "$" + value if re.match(r"^[0-9]", value) else value
                preference_atoms.append(f"personalens_affinity=Alarm|{canonical}={value}")
        profile_context_prefix = re.match(
            r"^profile context:\s*(.*?)(?:\s+active interests:|\s+current task choices:|$)",
            normalized,
            flags=re.IGNORECASE,
        )
        if profile_context_prefix:
            context = profile_context_prefix.group(1).lower()
            if "female" in context:
                fact_atoms.append("gender=female")
            elif "male" in context:
                fact_atoms.append("gender=male")
            if "never been married" in context:
                fact_atoms.append("marital_status=never been married")
            if "native english speaker" in context or "english (native speaker)" in context:
                fact_atoms.append("english_proficiency=english (native speaker)")
        for interest_match in re.finditer(
            r"\binterest\s+([a-z][a-z0-9 _/-]{2,40})\s*=\s*(active|inactive)\b",
            normalized,
            flags=re.IGNORECASE,
        ):
            fact_atoms.append(
                f"Interest {interest_match.group(1).strip().lower()}={interest_match.group(2).lower()}"
            )
    return _dedupe_preserving(fact_atoms), _dedupe_preserving(preference_atoms)


def _personalens_compound_keyvalue_preferences(items: Sequence[str]) -> list[str]:
    key_patterns: tuple[tuple[str, str], ...] = (
        ("additional feature preference", "Additional Feature Preference"),
        ("alarm recurring preference", "Alarm Recurring Preference"),
        ("alarm sound preference", "Alarm Sound Preference"),
        ("alarm time preference", "Alarm Time Preference"),
        ("amenity preference", "Amenity Preference"),
        ("communication style", "Prefer Communication Style"),
        ("event type preference", "Event Type Preference"),
        ("location preference", "Location Preference"),
        ("prefer communication style", "Prefer Communication Style"),
        ("service provider gender preference", "Service Provider Gender Preference"),
        ("theater type preference", "Theater Type Preference"),
    )
    label_pattern = "|".join(re.escape(label) for label, _ in sorted(key_patterns, key=lambda row: len(row[0]), reverse=True))
    lookup = {label: canonical for label, canonical in key_patterns}
    atoms: list[str] = []
    for item in items:
        text = _clean_text(item)
        if "=" not in text and ":" not in text:
            continue
        for match in re.finditer(
            rf"\b(?P<label>{label_pattern})\s*(?:=|:|is\s+)\s*(?P<value>.*?)(?=\s+\b(?:{label_pattern})\s*(?:=|:|is\s+)|$)",
            text,
            flags=re.IGNORECASE,
        ):
            canonical = lookup.get(match.group("label").lower())
            if not canonical:
                continue
            value_text = _clean_text(match.group("value")).strip(" -*,.;:")
            value_text = re.sub(r"\s+Current Task Choices:.*$", "", value_text, flags=re.IGNORECASE).strip()
            for value in re.split(r"\s*,\s*|\s+\band\b\s+", value_text, flags=re.IGNORECASE):
                cleaned = _clean_text(value).strip(" -*,.;:")
                if _personalens_bad_value(cleaned):
                    continue
                atoms.append(f"personalens_affinity=Alarm|{canonical}={cleaned}")
    return _dedupe_preserving(atoms)


def _personalens_rewrite_fact_atoms(items: Sequence[str]) -> list[str]:
    rewritten: list[str] = []
    for item in items:
        text = _clean_text(item)
        lower = text.lower()
        if lower in {"english_proficiency=english", "english_proficiency=en"}:
            continue
        rewritten.append(text)
        if lower == "reside_country=canada":
            rewritten.append("birth_country=canada")
    return _dedupe_preserving(rewritten)


def _personalens_rewrite_preference_atom(item: str) -> str:
    text = _clean_text(item)
    lower = text.lower()
    if "service provider gender preference=" in lower:
        tail = lower.rsplit("=", 1)[1].strip()
        if tail in {"male", "female"}:
            return ""
    if "favorite media=" in lower and _personalens_bad_media_value(lower.rsplit("=", 1)[1]):
        return ""
    game_titles = {
        "red dead redemption 2",
        "the legend of zelda:breath of the wild",
        "the legend of zelda breath of the wild",
        "civilization",
        "the sims",
    }
    if "favorite media=" in lower:
        prefix, _, value = text.rpartition("=")
        value_clean = _clean_text(value).lower()
        if value_clean in game_titles:
            return prefix.rsplit("|", 1)[0] + "|Prefer Game Name=" + _clean_text(value)
    return text


def _personalens_dedupe_unique_preference_keys(items: Sequence[str]) -> list[str]:
    unique_keys = {
        "additional feature preference",
        "alarm recurring preference",
        "alarm sound preference",
        "alarm time preference",
        "amenity preference",
        "communication style",
        "duration preference",
        "location preference",
        "prefer communication style",
        "service frequency preference",
        "service provider gender preference",
        "theater type preference",
        "viewing time preference",
    }
    kept: list[str] = []
    seen_unique: set[tuple[str, str]] = set()
    for item in items:
        text = _clean_text(item)
        lowered = text.lower()
        if "|" in lowered and "=" in lowered:
            prefix, value = lowered.rsplit("=", 1)
            domain_part, key_part = prefix.split("|", 1)
            key = key_part.strip()
            domain = domain_part.strip()
            if key in unique_keys:
                marker = (domain, key)
                if marker in seen_unique:
                    continue
                seen_unique.add(marker)
                if _personalens_bad_value(value):
                    continue
        kept.append(text)
    return _dedupe_preserving(kept)


