def _rank_role_coverage_prompt_candidates(
    candidates: Sequence[tuple[str, tuple[str, ...], str]],
    missing_roles: Sequence[str],
    *,
    posterior: Mapping[str, Any] | None = None,
) -> list[tuple[str, tuple[str, ...], str]]:
    missing = set(missing_roles)
    uncertainty = _posterior_role_uncertainty_weights(missing_roles, posterior or {})

    def score(candidate: tuple[str, tuple[str, ...], str]) -> tuple[float, int]:
        prompt, target_roles, family = candidate
        target_set = set(target_roles)
        gain = sum(uncertainty.get(role, 0.0) for role in target_set & missing)
        gain += 0.22 * sum(_role_information_gain_weight(role) for role in target_set - missing)
        gain += _prompt_family_information_prior(family)
        gain -= _prompt_noise_penalty(prompt, family)
        if target_set:
            gain += min(1.1, 0.18 * len(target_set))
        if not target_roles and missing:
            gain = 0.25
        return (gain - 0.0007 * estimate_token_count(prompt), -len(prompt))

    return sorted(candidates, key=score, reverse=True)


def _posterior_role_uncertainty_weights(
    missing_roles: Sequence[str],
    posterior: Mapping[str, Any],
) -> dict[str, float]:
    """Approximate Fisher-style value for asking about each role family.

    A role is valuable when it is still missing and the current posterior is
    either sparse or dominated by broad/generic evidence.  This keeps follow-up
    turns focused on ordinary tasks that can separate plausible latent causes.
    """

    text = _lower_clean(_behavior_model_text_blob(posterior))
    weights: dict[str, float] = {}
    for role in missing_roles:
        base = _role_information_gain_weight(role)
        role_key = _lower_clean(role)
        if not text:
            weights[role] = base + 0.4
            continue
        generic_pressure = _posterior_generic_pressure(text)
        role_hint_present = _role_hint_present_in_text(role_key, text)
        weights[role] = base + generic_pressure + (0.35 if not role_hint_present else -0.25)
    return weights


def _posterior_generic_pressure(text: str) -> float:
    markers = (
        "generic advice",
        "recommendation",
        "consider",
        "would be appropriate",
        "fits your preferences",
        "personalized suggestion",
        "values personal growth",
        "usual interests",
        "daily life",
    )
    hits = sum(1 for marker in markers if marker in text)
    return min(0.9, 0.18 * hits)


def _role_hint_present_in_text(role_key: str, text: str) -> bool:
    if not role_key or not text:
        return False
    aliases: dict[str, tuple[str, ...]] = {
        "persona_context": ("stable persona", "stable role", "role/background", "who "),
        "interest_preference": ("interest", "preference", "enjoys", "likes", "favorite"),
        "responsibility_or_routine": ("routine", "habit", "responsibil", "daily", "work", "school"),
        "values_or_concerns": ("value", "concern", "stress", "civic", "community"),
        "underlying_constraint_or_sensitive_detail": ("constraint", "condition", "health", "privacy", "sensitive"),
        "negative_or_correction": ("do not remember", "forget", "correction", "no longer"),
        "dialogue_example": ("user:", "assistant:", "raw prior interaction"),
        "complete_message": ("message:", "speaker:", "time:"),
    }
    return any(alias in text for alias in aliases.get(role_key, (role_key,)))


def _prompt_family_information_prior(family: Any) -> float:
    label = str(family or "").lower()
    if "public_choice_set_inversion" in label:
        return 7.0
    if (
        "r007_latent_abstraction" in label
        or "r007_personalens_transferable" in label
        or "r007_etapp_transferable" in label
    ):
        return 3.25
    if "verbatim_profile_card" in label or "source_copy" in label:
        return 3.0
    if "verbatim_user_background" in label:
        return 2.8
    if "choice_set_version_space" in label:
        return 2.65
    if "contrastive" in label or "separator" in label:
        return 2.4
    if "facet_disagreement" in label:
        return 2.05
    if "source_boundary" in label or "raw_evidence" in label:
        return 2.0
    if "field_certificate" in label or "minimal_sufficient" in label:
        return 1.8
    if label.startswith("abductive_"):
        return 1.45
    if "ledger" in label or "coverage" in label:
        return 0.85
    return 0.0


def _prompt_noise_penalty(prompt: Any, family: Any) -> float:
    text = _lower_clean(prompt)
    label = str(family or "").lower()
    penalty = 0.0
    if "recommendation and then" in text or "personalized recommendation" in text:
        penalty += 0.45
    if "generic advice" in text and "do not" not in text:
        penalty += 0.35
    if "all" in text and "if known" not in text and "skip unknown" not in text:
        penalty += 0.25
    if "fallback" in label:
        penalty += 0.6
    return penalty


def _role_information_gain_weight(role: str) -> float:
    role_key = _lower_clean(role)
    if role_key in {
        "complete_message",
        "negative_or_correction",
        "dialogue_example",
        "underlying_constraint_or_sensitive_detail",
        "price range",
        "location preference",
        "favorite media",
        "frequentlyplayedtracks",
        "preferartists",
    }:
        return 1.4
    if "preference" in role_key or "favorite" in role_key or "profile" in role_key:
        return 1.2
    return 1.0


def _dedupe_role_coverage_prompt_candidates(
    candidates: Sequence[tuple[str, tuple[str, ...], str]],
) -> list[tuple[str, tuple[str, ...], str]]:
    deduped: list[tuple[str, tuple[str, ...], str]] = []
    seen: set[str] = set()
    for prompt, target_roles, family in candidates:
        prompt_hash = _stable_prompt_hash(prompt)
        if prompt_hash in seen:
            continue
        seen.add(prompt_hash)
        deduped.append((prompt, tuple(target_roles), family))
    return deduped


def _behavior_display_role(role: str) -> str:
    return " ".join(str(role or "").replace("_", " ").split())


