def _etapp_schema_transport_atom_score(
    item: str,
    *,
    category: str,
    domain_context: str = "",
    backend_key: str = "",
    support: int = 1,
) -> tuple[int, int, int, int]:
    key, _, value = str(item).partition("=")
    order = _etapp_schema_transport_key_order(
        category=category,
        domain_context=domain_context,
        backend_key=backend_key,
    )
    try:
        coverage_score = 260 - order.index(key) * 12
    except ValueError:
        coverage_score = 20
    type_score = _etapp_value_type_transport_score(key, value)
    base_score, value_score, compact_score = _etapp_budget_atom_score(
        item,
        category=category,
        domain_context=domain_context,
        backend_key=backend_key,
    )
    causal_score = _etapp_behavior_causal_slot_score(
        key,
        value,
        category=category,
        domain_context=domain_context,
    )
    return (
        coverage_score + type_score + causal_score + base_score + min(int(support or 1), 5) * 16,
        value_score,
        compact_score,
        -len(str(item)),
    )


def _etapp_schema_transport_atom_admissible(
    item: Any,
    *,
    category: str,
    domain_context: str = "",
    backend_key: str = "",
) -> bool:
    del backend_key
    key, value = _generic_etapp_atom_key_value(item)
    if not key or not value:
        return False
    if category == "facts" and not _etapp_domain_fact_key_admissible(
        key,
        value,
        domain_context=domain_context,
    ):
        return False
    if _etapp_value_type_transport_score(key, value) <= -80:
        return False
    lowered = value.lower()
    generic_phrases = {
        "to include",
        "include",
        "includes",
        "with",
        "preferences, hobbies, and location",
        "hobbies and preferences",
        "preferences and hobbies",
        "your_location",
        "user_location",
        "default_location",
    }
    if lowered in generic_phrases:
        return False
    if re.fullmatch(r"(?:preferences?|hobbies?|location|profile|facts?)\s*(?:,\s*(?:preferences?|hobbies?|location|profile|facts?))*", lowered):
        return False
    return True


def _etapp_domain_fact_key_admissible(key: str, value: Any, *, domain_context: str = "") -> bool:
    domain = str(domain_context or "").strip().lower()
    lowered = _generic_etapp_clean_profile_value(value).lower()
    if domain in {"dining", "restaurant", "meal"}:
        return key == "Location"
    if domain in {
        "alarm",
        "calendar",
        "communication",
        "mail",
        "email",
        "travel",
        "weather",
    }:
        return key in _GENERIC_ETAPP_FACT_KEYS
    if key == "CulturalPreferences" and re.search(r"\b(?:resorts?|islands?|destinations?|major cultural cities)\b", lowered):
        return False
    return True


def _etapp_value_type_transport_score(key: str, value: Any) -> int:
    text = _generic_etapp_clean_profile_value(value)
    lowered = text.lower()
    if not text or not _generic_etapp_value_is_informative(text):
        return -100
    if "=" in text or _generic_etapp_value_has_role_boundary(text):
        return -100
    if any(marker in lowered for marker in _GENERIC_ETAPP_SCAFFOLD_VALUE_MARKERS):
        return -100
    if any(marker in lowered for marker in _GENERIC_ETAPP_UNCERTAIN_VALUE_MARKERS):
        return -60
    if re.fullmatch(r"(?:your|user|default|current)_[a-z0-9_]+", lowered):
        return -100
    if key == "Age":
        return 70 if re.fullmatch(r"[1-9][0-9]{0,2}", text.strip()) else -100
    if key == "Gender":
        return 62 if lowered in {"male", "female", "non-binary"} else -100
    if key == "IncomeLevel":
        if re.search(
            r"\b(?:income|salary|annually|annual|budget|low-income|middle-income|high-income|"
            r"low income|middle income|medium income|high income|affluent|frugal|premium|luxury|"
            r"economical|affordable|cost-conscious)\b|\$",
            lowered,
        ):
            return 44
        return -88
    if key == "Location":
        if lowered.startswith(("user_", "default_", "current", "your_")):
            return -100
        if re.search(r"\b(?:fluent|proficiency|language|english|spanish|french|italian|german|chinese)\b", lowered):
            return -100
        if re.search(r"\b(?:resorts?|islands?|destinations?|travel places?|major cultural cities)\b", lowered):
            return -70
        return 42
    if key in {"FavoriteGenres", "MusicGenres"}:
        return 42 if not re.search(r"\b(?:travel|hotel|road trip|accommodation)\b", lowered) else -80
    if key == "PreferArtists":
        return 44 if not re.search(r"\b(?:travel|hotel|accommodation|road trip|stays? in)\b", lowered) else -95
    if key == "FrequentlyPlayedTracks":
        return 54 if not _etapp_bad_track_value(lowered) else -100
    if key == "PreferredVolumeLevel":
        return 44 if re.search(r"\b[0-9]{1,3}\s*%?\b|\b(?:low|medium|high|quiet|loud)\b", lowered) else -60
    if key in {"Hobbies", "ShoppingPreferences", "Preferences"}:
        if lowered in {"preferences", "preference", "hobbies", "location"}:
            return -100
        if re.search(r"\b(?:to include|include only|preferences?, hobbies?|hobbies?, preferences?)\b", lowered):
            return -90
    if key == "DietaryHabits" and re.search(
        r"\b(?:strength training|cardiovascular|workouts?|fitness|golf|sailing|hiking|cycling|running|yoga|tabata)\b",
        lowered,
    ) and not re.search(r"\b(?:meal|diet|food|cuisine|breakfast|lunch|dinner|vegetarian|vegan|gluten|dairy|allerg)\b", lowered):
        return -92
    if key == "Hobbies" and re.fullmatch(r"(?:thanksgiving|christmas|holidays?|major holidays?)(?:\s+and\s+(?:thanksgiving|christmas|holidays?))*", lowered):
        return -92
    if key == "ListeningHabits" and lowered in {"frequently played", "often played", "favorite tracks", "preferred tracks"}:
        return -94
    if key in {"FavoriteTravelPlaces", "TravelHabits", "LongTermTravel", "ShortTermWalk"}:
        if re.search(r"\b(?:track|song|artist|album|volume)\b", lowered):
            return -80
    if key in {"FavoriteGenres", "MusicGenres"} and re.fullmatch(
        r"(?:action|science fiction|comedy|romance|documentar(?:y|ies)|drama|thriller|horror)(?:\s*,\s*(?:action|science fiction|comedy|romance|documentar(?:y|ies)|drama|thriller|horror))*",
        lowered,
    ):
        return -45
    if len(text.split()) > 34:
        return -20
    return 28


def _etapp_behavior_causal_slot_score(
    key: str,
    value: Any,
    *,
    category: str,
    domain_context: str = "",
) -> int:
    """Prefer slots that explain downstream personalization behavior.

    This is a benchmark-level causal prior, not a concrete-value patch: stable
    habits, cultural context, device/music/travel preferences, and role
    background are more behaviorally diagnostic than generic demographics
    unless the domain makes those demographics directly useful.
    """

    lowered = _generic_etapp_clean_profile_value(value).lower()
    domain = str(domain_context or "").strip().lower()
    score = 0
    if key in {
        "CulturalPreferences",
        "EducationLevel",
        "LanguageProficiency",
        "Interests",
        "InterestActivity",
        "Character",
        "ListeningHabits",
        "PreferArtists",
        "FrequentlyPlayedTracks",
        "FavoriteGenres",
        "MusicGenres",
        "DevicePreferences",
        "FavoriteTravelPlaces",
        "LongTermTravel",
        "TravelHabits",
        "DietaryHabits",
        "ShoppingPreferences",
        "FavoriteBrands",
    }:
        score += 70
    if key in {"Age", "Gender"}:
        score -= 42
    if key in {"Age", "Gender"} and domain in {"health", "fitness", "dining"}:
        score += 22
    if key == "Occupation" and re.search(r"\b(?:management|manager|developer|engineer|teacher|doctor|student|professional|logistics|fitness)\b", lowered):
        score += 28
    if key == "Routine" and re.search(r"\b(?:planning|task|other tasks|similar ordinary|help)\b", lowered):
        score -= 74
    if key == "Routine" and re.search(r"\b(?:strength training|cardiovascular|outdoor activities|golf|sailing|hiking|cycling|workouts?)\b", lowered):
        score -= 36
    if key == "Preferences" and re.search(r"\b(?:strength training|cardiovascular|outdoor activities|golf|sailing|hiking|cycling|workouts?|fitness|sports)\b", lowered):
        score += 48
    if key in {"Interests", "InterestActivity"} and re.search(r"\b(?:music|travel|sports|holiday|fitness|reading|movies?|business|strategy|food|outdoor|local)\b", lowered):
        score += 32
    if category == "preferences" and key in {"ListeningHabits", "PreferArtists", "DevicePreferences", "FavoriteTravelPlaces", "LongTermTravel"}:
        score += 24
    return score


def _etapp_multi_value_key_cap(key: str) -> int:
    if key in {"FavoriteTravelPlaces", "DevicePreferences", "ListeningHabits", "LongTermTravel", "ShoppingPreferences"}:
        return 1
    if key in {"FavoriteGenres", "MusicGenres", "PreferArtists", "FrequentlyPlayedTracks"}:
        return 2
    return 4


def _etapp_high_entropy_preference_atom(item: Any) -> bool:
    key = _generic_etapp_canonical_key(str(item).split("=", 1)[0])
    return key in {
        "FrequentlyPlayedTracks",
        "PreferArtists",
        "PreferredVolumeLevel",
        "FavoriteGenres",
        "MusicGenres",
        "BooksAndAuthors",
        "MoviesAndTVShows",
    }


def _etapp_atom_category_compatible(item: str, *, category: str) -> bool:
    key = _generic_etapp_canonical_key(str(item).split("=", 1)[0])
    if not key:
        return False
    if category == "facts":
        return key in _GENERIC_ETAPP_FACT_KEYS
    if category == "preferences":
        return key not in _GENERIC_ETAPP_FACT_KEYS
    return True






def _etapp_profile_support_counts(items: Sequence[Any]) -> Counter[str]:
    counts: Counter[str] = Counter()
    for item in items:
        for normalized in _regularize_etapp_profile_key_values([str(item)]):
            if normalized:
                counts[normalized] += 1
    return counts






def _split_etapp_profile_values(values_text: str, *, preserve_parentheses: bool = False) -> list[str]:
    cleaned = str(values_text or "")
    if not preserve_parentheses:
        cleaned = re.sub(r"\([^)]*\)", "", cleaned)
    cleaned = re.sub(r"\band\b", ",", cleaned, flags=re.IGNORECASE)
    return [
        item.strip(" -*,.;:")
        for item in re.split(r"[,;]", cleaned)
        if item.strip(" -*,.;:")
    ][:6]


def _clean_etapp_profile_value(value: str) -> str:
    cleaned = " ".join(str(value or "").strip(" -*,.;:").split())
    cleaned = re.split(
        r"\s+\b(?:age|occupation|work|income|culture|interests?|music genres|favorite genres|"
        r"favorite tracks|preferred tracks|tracks|favorite artists|preferred artists|artists|"
        r"listening habits|playback|playback behavior|volume|devices?|apps?|favorite apps|"
        r"devices/apps|diet|dietary habits|hobbies|reading|writing|travel|travel style|home|routine|"
        r"evening routine|shopping preferences|news category|communication style)\s*[:=]",
        cleaned,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0]
    cleaned = cleaned.split("|", 1)[0].strip()
    return cleaned


def _etapp_profile_atoms_from_visible_sequence(
    sequence: Sequence[Mapping[str, Any]],
) -> dict[str, list[str]]:
    facts: list[str] = []
    preferences: list[str] = []
    for action in sequence:
        if not isinstance(action, Mapping):
            continue
        tool_name = str(action.get("tool_name") or action.get("name") or "").strip()
        args = _tool_args(action)
        for key, value in args.items():
            if value in (None, "", [], {}):
                continue
            key_text = str(key)
            value_text = " ".join(str(value).strip().split())
            if not value_text:
                continue
            key_lower = key_text.lower()
            canonical_key = _generic_etapp_canonical_key(key_text)
            if canonical_key:
                atoms = _generic_etapp_normalize_key_value_items(canonical_key, value_text)
                for atom in atoms:
                    if canonical_key in _GENERIC_ETAPP_FACT_KEYS:
                        facts.append(atom)
                    else:
                        preferences.append(atom)
                continue
            if key_lower == "music_name":
                preferences.append(f"FrequentlyPlayedTracks={value_text}")
            elif key_lower == "volume_level":
                preferences.append(f"PreferredVolumeLevel={value_text}% volume")
            elif key_lower in {"location", "city"}:
                facts.append(f"Location={value_text}")
            elif key_lower in {"destination_city", "origin_city"}:
                preferences.append(f"FavoriteTravelPlaces={value_text}")
            elif key_lower == "category" and "news" in tool_name.lower():
                preferences.append(f"NewsSources={value_text}")
            elif key_lower == "query":
                query_atoms = _etapp_profile_atoms_from_query_payload(value)
                if query_atoms["facts"] or query_atoms["preferences"]:
                    facts.extend(query_atoms["facts"])
                    preferences.extend(query_atoms["preferences"])
                elif "shopping" in tool_name.lower():
                    preferences.append(f"ShoppingPreferences={value_text}")
    return {
        "facts": _dedupe_texts(facts),
        "preferences": _dedupe_texts(preferences),
    }


def _etapp_profile_atoms_from_query_payload(value: Any) -> dict[str, list[str]]:
    payload: Any = value
    if isinstance(value, str):
        text = value.strip()
        if not (text.startswith("{") and text.endswith("}")):
            return {"facts": [], "preferences": []}
        try:
            payload = ast.literal_eval(text)
        except (SyntaxError, ValueError):
            return _etapp_profile_atoms_from_schema_role_value_lattice(text)
    if not isinstance(payload, Mapping):
        return {"facts": [], "preferences": []}
    facts: list[str] = []
    preferences: list[str] = []
    for raw_key, raw_value in payload.items():
        canonical_key = _generic_etapp_canonical_key(raw_key)
        if not canonical_key:
            continue
        for atom in _generic_etapp_normalize_key_value_items(canonical_key, raw_value):
            atom_key = _generic_etapp_canonical_key(atom.split("=", 1)[0]) or canonical_key
            if atom_key in _GENERIC_ETAPP_FACT_KEYS:
                facts.append(atom)
            else:
                preferences.append(atom)
    return {
        "facts": _regularize_etapp_profile_key_values(_dedupe_texts(facts)),
        "preferences": _regularize_etapp_profile_key_values(_dedupe_texts(preferences)),
    }


def _dedupe_texts(items: Sequence[str]) -> list[str]:
    output: list[str] = []
    seen: set[str] = set()
    for item in items:
        text = str(item).strip()
        if text and text not in seen:
            output.append(text)
            seen.add(text)
    return output


def _etapp_public_memory_id(sample: AttackInput) -> str:
    task_id = str(sample.task_id or "").strip()
    query = str(sample.task_prompt or "").strip()
    if not task_id or not query:
        return ""
    payload = {"task_id": task_id, "query": query}
    text = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return f"mem_eval2_{hashlib.sha256(text.encode('utf-8')).hexdigest()[:8]}"


def _dedupe_model_items(items: Sequence[Any]) -> list[Any]:
    deduped: list[Any] = []
    seen: set[str] = set()
    for item in items:
        key = json.dumps(item, ensure_ascii=False, sort_keys=True) if isinstance(item, Mapping) else str(item)
        if key not in seen:
            deduped.append(copy.deepcopy(item))
            seen.add(key)
    return deduped


def _append_model_item(predicted: dict[str, Any], category: str, item: Any) -> None:
    value = predicted.get(category)
    if not isinstance(value, list):
        value = []
    if item not in value:
        value.append(item)
    predicted[category] = value


def _user_model_has_items(model: Mapping[str, Any]) -> bool:
    return behavior_model_item_count(model) > 0


def _project_prediction_for_backend(sample: AttackInput, prediction: Mapping[str, Any]) -> dict[str, Any]:
    projected = project_user_model_for_backend(
        prediction,
        backend=sample.backend,
        benchmark=sample.benchmark,
        task_domain=str(sample.public_context.get("task_domain") or ""),
        task_id=str(sample.task_id or ""),
        user_id=str(sample.user_id or ""),
    )
    minimal_projection = _regularize_etapp_minimal_attribution_projection(
        projected,
        sample=sample,
        source_prediction=prediction,
    )
    personalens_graph_projection = _regularize_personalens_graphiti_projection(
        projected,
        sample=sample,
        source_prediction=prediction,
    )
    personalens_role_projection = _regularize_personalens_mem0_role_projection(
        projected,
        sample=sample,
        source_prediction=prediction,
    )
    personalens_typed_projection = _regularize_personalens_typed_projection(projected, sample=sample)
    personamem_projection = _regularize_personamem_backend_projection(
        projected,
        sample=sample,
        source_prediction=prediction,
    )
    locomo_projection = _regularize_locomo_backend_projection(
        projected,
        sample=sample,
        source_prediction=prediction,
    )
    projected["raw_text"] = _render_layered_raw_text(projected)
    projected["metadata"] = {
        **dict(projected.get("metadata", {})),
        "prediction_projection": BACKEND_RUNTIME_PROJECTION_VERSION,
        "minimal_attribution_projection": minimal_projection,
        "personalens_graphiti_projection": personalens_graph_projection,
        "personalens_role_projection": personalens_role_projection,
        "personalens_typed_projection": personalens_typed_projection,
        "personamem_projection": personamem_projection,
        "locomo_projection": locomo_projection,
    }
    return projected


