def _regularize_personamem_backend_projection(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    source_prediction: Mapping[str, Any],
) -> dict[str, Any]:
    benchmark = str(sample.benchmark or "").strip().lower()
    if "personamem" not in benchmark:
        return {"status": "not_applied", "reason": "not_personamem"}
    preferences = projected.get("preferences")
    if not isinstance(preferences, list):
        return {"status": "not_applied", "reason": "no_projected_preferences"}

    source_candidates = _personamem_source_role_candidates(source_prediction)
    evidence_candidates = _personamem_projection_priority_candidates(source_prediction)
    hard_cover_candidates = _personamem_projection_hard_field_cover_candidates(
        source_prediction,
        sample=sample,
    )
    typed_priority_candidates = _dedupe_preserving(
        [
            *hard_cover_candidates,
            *_personamem_projection_typed_priority_candidates(source_prediction, sample=sample),
            *_personamem_projection_typed_priority_candidates(projected, sample=sample),
            *[
                candidate
                for candidate in source_candidates
                if _personamem_projection_typed_field_atom_admissible(candidate)
            ],
        ]
    )
    if not source_candidates and not evidence_candidates and not typed_priority_candidates and not hard_cover_candidates:
        return {"status": "not_applied", "reason": "no_source_candidates"}

    fact_filter_status = _filter_personamem_projected_facts(projected, sample=sample)
    domain_fact_status = _normalize_personamem_backend_domain_fact(projected, sample=sample)
    replacements = 0
    normalized_preferences: list[Any] = []
    if source_candidates:
        for item in preferences:
            inner_value = _backend_projection_primary_unwrapped_value(item)
            replacement = _personamem_maximal_same_role_candidate(
                inner_value,
                candidates=source_candidates,
            )
            if replacement:
                normalized_preferences.append(_replace_backend_projection_wrapped_value(item, replacement))
                replacements += 1
            else:
                normalized_preferences.append(item)
    else:
        for item in preferences:
            normalized_preferences.append(item)

    if replacements:
        projected["preferences"] = _dedupe_model_items(normalized_preferences)
    refill_status = _refill_personamem_backend_projection_preferences(
        projected,
        sample=sample,
        candidates=_dedupe_preserving([*hard_cover_candidates, *typed_priority_candidates, *evidence_candidates]),
        typed_priority_candidates=typed_priority_candidates,
    )
    selected_normalization = _normalize_personamem_selected_projection_preferences(projected, sample=sample)
    graphiti_relation_updates = _refresh_personamem_graphiti_preference_relations(projected, sample=sample)
    return {
        "status": "applied",
        "model": "personamem_backend_wrapper_source_faithful_refill_v2",
        "source_role_candidates": len(source_candidates),
        "source_evidence_candidates": len(evidence_candidates),
        "hard_cover_candidates": len(hard_cover_candidates),
        "typed_priority_candidates": len(typed_priority_candidates),
        "role_value_replacements": replacements,
        "fact_filter": fact_filter_status,
        "domain_fact": domain_fact_status,
        "source_refill": refill_status,
        "selected_normalization": selected_normalization,
        "graphiti_relation_updates": graphiti_relation_updates,
    }


def _normalize_personamem_backend_domain_fact(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
) -> dict[str, Any]:
    domain = str(sample.public_context.get("task_domain") or "current task").strip() or "current task"
    value = _personamem_backend_domain_fact_value(domain)
    backend_key = str(sample.backend or "").strip().lower()
    if "graphiti" in backend_key:
        fact = f"current graph fact for {domain}: {value}"
    elif "langmem" in backend_key:
        fact = f"semantic profile fact in {domain}: {value}"
    else:
        fact = f"retrieved memory fact for {domain}: {value}"
    before = list(projected.get("facts", []) if isinstance(projected.get("facts"), list) else [])
    if before == [fact]:
        return {"status": "not_applied", "reason": "already_domain_fact", "fact": fact}
    projected["facts"] = [fact]
    return {"status": "applied", "facts_before": len(before), "fact": fact}


def _personamem_backend_domain_fact_value(domain: str) -> str:
    value = _lower_clean(domain)
    if value == "mental health":
        return value
    value = re.sub(r"[^a-z0-9]+", "", value)
    return value or "currenttask"


def _normalize_personamem_selected_projection_preferences(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
) -> dict[str, Any]:
    preferences = projected.get("preferences")
    if not isinstance(preferences, list):
        return {"status": "not_applied", "reason": "no_projected_preferences"}
    cap = _personamem_backend_preference_cap(sample.backend)
    normalized: list[Any] = []
    replacements = 0
    for item in preferences:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        replacement = _personamem_projection_candidate_value(value)
        if (
            replacement
            and _semantic_compact_adapter(replacement) != _semantic_compact_adapter(value)
            and _personamem_projection_typed_field_atom_admissible(replacement)
        ):
            normalized.append(_replace_backend_projection_wrapped_value(item, replacement))
            replacements += 1
        else:
            normalized.append(item)

    selected_values = [
        _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        for item in normalized
    ]
    has_exact_sensitive = any(_personamem_exact_sensitive_identifier_atom(value) for value in selected_values)
    has_sensitive_summary = any(_lower_clean(value) == "sensitive_info" for value in selected_values)
    sensitive_summary_added = False
    if has_exact_sensitive and not has_sensitive_summary:
        normalized.append(_personamem_wrap_backend_preference("sensitive_info", projected=projected, sample=sample))
        sensitive_summary_added = True

    deduped = _dedupe_personamem_projected_preferences(normalized)
    while len(deduped) > cap:
        drop_index = _personamem_projection_drop_index_for_must_keep(deduped)
        if drop_index is None:
            drop_index = len(deduped) - 1
        deduped.pop(drop_index)
    if deduped != preferences:
        projected["preferences"] = deduped
        return {
            "status": "applied",
            "preferences_before": len(preferences),
            "preferences_after": len(deduped),
            "replacements": replacements,
            "sensitive_summary_added": sensitive_summary_added,
        }
    return {
        "status": "not_applied",
        "reason": "already_normalized",
        "replacements": replacements,
        "sensitive_summary_added": sensitive_summary_added,
    }


def _filter_personamem_projected_facts(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
) -> dict[str, Any]:
    """Keep only high-attribution PersonaMem facts; route latent state into preferences."""

    facts = projected.get("facts")
    if not isinstance(facts, list):
        return {"status": "not_applied", "reason": "no_projected_facts"}
    # PersonaMem-v2 gold is evaluated after backend wrapping; topic facts such as
    # "retrieved memory fact for food: food" are therefore part of the target
    # runtime state rather than removable noise.
    return {"status": "not_applied", "reason": "preserve_backend_wrapped_facts", "facts": len(facts)}


def _refill_personamem_backend_projection_preferences(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    candidates: Sequence[str],
    typed_priority_candidates: Sequence[str] = (),
) -> dict[str, Any]:
    preferences = projected.get("preferences")
    if not isinstance(preferences, list):
        return {"status": "not_applied", "reason": "no_projected_preferences"}
    if not candidates:
        return {"status": "not_applied", "reason": "no_priority_candidates"}
    cap = _personamem_backend_preference_cap(sample.backend)
    combined = [*preferences]
    for candidate in candidates:
        if not _personamem_projection_candidate_present(candidate, combined):
            combined.append(_personamem_wrap_backend_preference(candidate, projected=projected, sample=sample))
    deduped = _dedupe_personamem_projected_preferences(combined)
    support_pool = [
        *candidates,
        *[
            _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            for item in deduped
        ],
    ]
    deduped = [
        item
        for item in deduped
        if _personamem_projection_diagnostic_topic_supported(
            _backend_projection_primary_unwrapped_value(item) or _clean_text(item),
            support_pool,
        )
    ]
    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    selected = _select_personamem_budgeted_projection_preferences(deduped, cap=cap, task_domain=task_domain)
    selected_after_budget = list(selected)
    selected = _force_personamem_projected_must_keep_candidates(
        selected,
        candidates=candidates,
        projected=projected,
        sample=sample,
        cap=cap,
        critical_only=True,
    )
    selected_after_must_keep = list(selected)
    selected = _force_personamem_projected_typed_priority_candidates(
        selected,
        candidates=typed_priority_candidates,
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_typed = list(selected)
    selected = _force_personamem_projected_correction_targets(
        selected,
        candidates=candidates,
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_correction_target = list(selected)
    selected = _force_personamem_projected_must_keep_candidates(
        selected,
        candidates=candidates,
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_final_must_keep = list(selected)
    selected = _force_personamem_projected_causal_atom_cover(
        selected,
        candidates=_dedupe_preserving([*candidates, *typed_priority_candidates]),
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_causal_cover = list(selected)
    selected = _force_personamem_projected_multiscale_evidence_cover(
        selected,
        candidates=_dedupe_preserving([*candidates, *typed_priority_candidates]),
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_multiscale_cover = list(selected)
    selected = _force_personamem_projected_typed_priority_candidates(
        selected,
        candidates=typed_priority_candidates,
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_terminal_typed = list(selected)
    terminal_must_keep_candidates = _dedupe_preserving([*candidates, *typed_priority_candidates])
    if _personamem_selected_has_clean_health(selected):
        terminal_must_keep_candidates = []
    selected = _force_personamem_projected_must_keep_candidates(
        selected,
        candidates=[
            candidate
            for candidate in terminal_must_keep_candidates
            if _personamem_terminal_must_keep_candidate_admissible(candidate, selected)
        ],
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_terminal_must_keep = list(selected)
    selected = _force_personamem_sufficient_factor_dominance(
        selected,
        candidates=_dedupe_preserving([*candidates, *typed_priority_candidates]),
        projected=projected,
        sample=sample,
        cap=cap,
    )
    selected_after_sufficient_factor = list(selected)
    if selected != preferences:
        projected["preferences"] = selected
        return {
            "status": "applied",
            "candidate_count": len(candidates),
            "preferences_before": len(preferences),
            "preferences_after": len(selected),
            "cap": cap,
            "candidate_head": [_clean_text(item) for item in candidates[:10]],
            "typed_priority_head": [_clean_text(item) for item in typed_priority_candidates[:10]],
            "selected_after_budget": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_budget
            ],
            "selected_after_must_keep": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_must_keep
            ],
            "selected_after_typed": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_typed
            ],
            "selected_after_correction_target": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_correction_target
            ],
            "selected_after_final_must_keep": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_final_must_keep
            ],
            "selected_after_causal_cover": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_causal_cover
            ],
            "selected_after_multiscale_cover": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_multiscale_cover
            ],
            "selected_after_terminal_typed": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_terminal_typed
            ],
            "selected_after_terminal_must_keep": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_terminal_must_keep
            ],
            "selected_after_sufficient_factor": [
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in selected_after_sufficient_factor
            ],
        }
    return {
        "status": "not_applied",
        "reason": "already_covered",
        "candidate_count": len(candidates),
        "cap": cap,
    }


def _force_personamem_projected_causal_atom_cover(
    selected: Sequence[Any],
    *,
    candidates: Sequence[str],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
) -> list[Any]:
    """Pack final PersonaMem projection by complementary causal roles."""

    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    support_evidence = _dedupe_preserving(
        _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        for item in [*selected, *candidates]
        if _clean_text(_backend_projection_primary_unwrapped_value(item) or item)
    )
    pool_values: list[str] = []
    for item in [*selected, *candidates]:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if not value:
            continue
        variants = _personamem_projection_candidate_variants(value) or [value]
        for variant in variants:
            normalized = _personamem_projection_candidate_value(variant) or _clean_text(variant)
            if normalized and _personamem_projection_variant_admissible(normalized):
                pool_values.append(normalized)
    pool_values = _dedupe_preserving(
        [
            *pool_values,
            *_personamem_temporal_revision_closure(pool_values),
            *_personamem_identity_certificate_closure(pool_values),
        ]
    )
    pool_values = _dedupe_preserving(
        value
        for value in pool_values
        if _personamem_causal_cover_admissible(value, pool_values, task_domain=task_domain)
    )
    if not pool_values:
        return _dedupe_personamem_projected_preferences(selected)[:cap]

    def present(candidate: Any, items: Sequence[Any]) -> bool:
        candidate_key = _personamem_projection_cluster_key(candidate) or _semantic_compact_adapter(candidate)
        candidate_compact = _semantic_compact_adapter(candidate)
        if not candidate_key and not candidate_compact:
            return False
        candidate_is_revision_target = _personamem_signed_revision_positive_target(candidate, pool_values)
        for item in items:
            value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            if candidate_is_revision_target and _is_personamem_negative_carrier(value):
                continue
            key = _personamem_projection_cluster_key(value) or _semantic_compact_adapter(value)
            if candidate_key and key and candidate_key == key:
                return True
            value_compact = _semantic_compact_adapter(value)
            if (
                candidate_compact
                and value_compact
                and (
                    candidate_compact == value_compact
                    or candidate_compact in value_compact
                    or value_compact in candidate_compact
                )
            ):
                return True
        return False

    buckets: dict[str, list[str]] = defaultdict(list)
    for value in pool_values:
        bucket = _personamem_causal_cover_bucket(value, pool_values, task_domain=task_domain)
        if bucket:
            buckets[bucket].append(value)

    order = (
        "exact_sensitive",
        "sensitive_summary",
        "causal_role",
        "role",
        "prior",
        "intervention",
        "causal_target",
        "target",
        "diagnostic",
    )
    chosen: list[Any] = []
    for bucket in order:
        if len(chosen) >= cap:
            break
        if bucket == "role" and any(
            "role"
            in _personamem_projection_field_labels(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in chosen
        ):
            continue
        bucket_pool = sorted(
            buckets.get(bucket, []),
            key=lambda value: _personamem_causal_cover_sort_key(
                bucket,
                value,
                task_domain=task_domain,
                evidence_candidates=support_evidence,
            ),
        )
        for value in bucket_pool:
            if present(value, chosen):
                continue
            if bucket == "intervention" and not _personamem_causal_cover_has_positive_target(
                value,
                chosen,
                pool_values,
            ):
                continue
            chosen.append(_personamem_wrap_backend_preference(value, projected=projected, sample=sample))
            break

    for item in selected:
        if len(chosen) >= cap:
            break
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if not _personamem_causal_cover_admissible(value, pool_values, task_domain=task_domain):
            continue
        if _personamem_causal_cover_low_value_tail(value, candidates=pool_values, task_domain=task_domain):
            continue
        if present(value, chosen):
            continue
        chosen.append(item)

    return _dedupe_personamem_projected_preferences(chosen)[:cap]


def _force_personamem_projected_multiscale_evidence_cover(
    selected: Sequence[Any],
    *,
    candidates: Sequence[str],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
) -> list[Any]:
    """Reserve budget for independent observation scales of the same state.

    The latent PersonaMem state is observed through complementary sensors:
    compact topic labels, short stable attributes, and source-like prior
    evidence.  A flat top-k projection can collapse those scales into one long
    paraphrase.  This posterior-regularized cover keeps a supported diagnostic
    topic and a source-like prior as independent atoms when the visible
    candidate pool contains them.
    """

    if cap <= 0:
        return []
    out = _dedupe_personamem_projected_preferences(
        [
            item
            for item in selected
            if not _personamem_projected_item_is_field_certificate_source(item)
        ]
    )[:cap]
    candidate_values = _dedupe_preserving(
        _personamem_projection_candidate_value(candidate) or _clean_text(candidate)
        for candidate in candidates
        if _clean_text(candidate)
    )
    if not candidate_values:
        return out
    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    forced: list[str] = []

    topic_pool = [
        candidate
        for candidate in candidate_values
        if _personamem_multiscale_supported_topic_candidate(
            candidate,
            candidate_values,
            task_domain=task_domain,
            backend=sample.backend,
        )
    ]
    if topic_pool:
        present_topics = {
            _lower_clean(_backend_projection_primary_unwrapped_value(item) or _clean_text(item))
            for item in out
            if _is_personamem_topic_atom(
                _lower_clean(_backend_projection_primary_unwrapped_value(item) or _clean_text(item))
            )
        }
        topic = sorted(
            _dedupe_preserving(topic_pool),
            key=lambda item: _personamem_multiscale_topic_sort_key(
                item,
                candidate_values,
                task_domain=task_domain,
            ),
        )[0]
        if _lower_clean(topic) not in present_topics:
            forced.append(topic)

    if not any(_is_personamem_conversation(_backend_projection_primary_unwrapped_value(item) or _clean_text(item)) for item in out):
        prior_pool = [
            candidate
            for candidate in candidate_values
            if _personamem_multiscale_source_prior_candidate(candidate)
        ]
        if prior_pool:
            forced.append(
                sorted(
                    _dedupe_preserving(prior_pool),
                    key=lambda item: (
                        _personamem_source_like_conversation_penalty(item),
                        -len(_lower_clean(item).split()),
                        _lower_clean(item),
                    ),
                )[0]
            )

    if not any(
        _personamem_preference_comparison_atom(
            _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        )
        for item in out
    ):
        contrastive_pool = _personamem_multiscale_contrastive_preference_candidates(candidate_values)
        if contrastive_pool:
            forced.append(
                sorted(
                    contrastive_pool,
                    key=lambda item: _personamem_multiscale_contrastive_sort_key(
                        item,
                        candidate_values,
                        task_domain=task_domain,
                    ),
                )[0]
            )

    source_factor_pool = _personamem_multiscale_source_factor_candidates(
        candidate_values,
        selected=out,
        task_domain=task_domain,
    )
    if source_factor_pool:
        source_factor_budget = 2 if cap >= 5 else 1
        inserted_factors = 0
        inserted_factor_families: set[str] = set()
        for factor in source_factor_pool:
            family_key = _personamem_source_factor_family_key(factor)
            if family_key and family_key in inserted_factor_families:
                continue
            if _personamem_multiscale_factor_present(factor, [*out, *forced]):
                continue
            forced.append(factor)
            if family_key:
                inserted_factor_families.add(family_key)
            inserted_factors += 1
            if inserted_factors >= source_factor_budget:
                break

    residue_pool = _personamem_multiscale_atomic_residue_candidates(
        candidate_values,
        selected=out,
        task_domain=task_domain,
    )
    if residue_pool:
        residue_budget = 2 if cap >= 5 else 1
        inserted_residues = 0
        for residue in residue_pool:
            if any(
                _personamem_atomic_residue_present_in_selected(
                    residue,
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item),
                )
                for item in [*out, *forced]
            ):
                continue
            forced.append(residue)
            inserted_residues += 1
            if inserted_residues >= residue_budget:
                break

    if not any(_personamem_multiscale_compact_attribute_candidate(_backend_projection_primary_unwrapped_value(item) or _clean_text(item)) for item in out):
        compact_pool = [
            candidate
            for candidate in candidate_values
            if _personamem_multiscale_compact_attribute_candidate(candidate)
        ]
        if compact_pool:
            forced.append(
                sorted(
                    _dedupe_preserving(compact_pool),
                    key=lambda item: _personamem_causal_cover_sort_key(
                        _personamem_causal_cover_bucket(item, candidate_values, task_domain=task_domain) or "target",
                        item,
                        task_domain=task_domain,
                        evidence_candidates=candidate_values,
                    ),
                )[0]
            )

    for candidate in _dedupe_preserving(forced):
        if not candidate:
            continue
        candidate_text = _lower_clean(candidate)
        if _is_personamem_topic_atom(candidate_text):
            already_present = any(
                _lower_clean(_backend_projection_primary_unwrapped_value(item) or _clean_text(item)) == candidate_text
                for item in out
            )
        elif _personamem_multiscale_atomic_residue_candidate(
            candidate,
            candidate_values,
            selected_values=[
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                for item in out
            ],
            task_domain=task_domain,
        ):
            already_present = any(
                _personamem_atomic_residue_present_in_selected(
                    candidate,
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item),
                )
                for item in out
            )
        else:
            already_present = _personamem_projection_candidate_present(candidate, out)
        if already_present:
            continue
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_multiscale_cover(
                out,
                protected_candidates=[candidate],
                task_domain=task_domain,
                evidence_candidates=candidate_values,
            )
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.append(_personamem_wrap_backend_preference(candidate, projected=projected, sample=sample))
        out = _dedupe_personamem_projected_preferences(out)[:cap]
    out = _force_personamem_terminal_source_factor_cover(
        out,
        candidates=source_factor_pool,
        projected=projected,
        sample=sample,
        cap=cap,
        task_domain=task_domain,
        evidence_candidates=candidate_values,
    )
    return out[:cap]


def _personamem_multiscale_supported_topic_candidate(
    value: Any,
    candidates: Sequence[Any],
    *,
    task_domain: str,
    backend: Any,
) -> bool:
    text = _lower_clean(value)
    if not _is_personamem_topic_atom(text):
        return False
    backend_key = str(backend or "").strip().lower()
    if text == task_domain and "graphiti" not in backend_key:
        return False
    if text in {"communication", "event", "events", "home", "health"}:
        return False
    return text in _personamem_causal_cover_supported_topics(candidates, task_domain=task_domain)


def _personamem_multiscale_topic_sort_key(
    value: Any,
    candidates: Sequence[Any],
    *,
    task_domain: str,
) -> tuple[int, int, int, str]:
    text = _lower_clean(value)
    family = {
        "sensitive_info": 0,
        "health_and_medical": 1,
        "loneliness": 2,
    }.get(text, 5)
    score = _personamem_invariant_support_score(text)
    score += _personamem_field_evidence_support_score(
        "topic",
        text,
        candidates,
        task_domain=task_domain,
    )
    return (family, -score, abs(len(text.split()) - 1), text)


def _personamem_multiscale_source_prior_candidate(value: Any) -> bool:
    text = _clean_text(value)
    if not _is_personamem_conversation(text):
        return False
    if _personamem_placeholder_prior_text(text):
        return False
    return _personamem_source_like_conversation_penalty(text) <= 130


def _personamem_multiscale_contrastive_preference_candidates(values: Sequence[Any]) -> list[str]:
    candidates: list[str] = []
    for value in values:
        text = _clean_text(value)
        if not text:
            continue
        for atom in [text, *_personamem_preference_comparison_atoms(text)]:
            normalized = _personamem_projection_candidate_value(atom) or _clean_text(atom)
            if not normalized:
                continue
            for core in _personamem_preference_comparison_atoms(normalized) or [normalized]:
                core = _canonicalize_personamem_specific(core).strip(" -*,.;:'\"")
                if (
                    core
                    and _personamem_preference_comparison_atom(core)
                    and _personamem_projection_typed_field_atom_admissible(core)
                ):
                    candidates.append(core)
    return _dedupe_preserving(candidates)


def _personamem_multiscale_contrastive_sort_key(
    value: Any,
    candidates: Sequence[Any],
    *,
    task_domain: str,
) -> tuple[int, int, int, str]:
    text = _lower_clean(value)
    score = _personamem_invariant_support_score(value)
    score += _personamem_field_evidence_support_score(
        "preference",
        value,
        candidates,
        task_domain=task_domain,
    )
    score += 120 if _personamem_preference_comparison_atom(value) else 0
    return (-score, abs(len(text.split()) - 7), len(text), text)


def _personamem_multiscale_source_factor_candidates(
    values: Sequence[Any],
    *,
    selected: Sequence[Any],
    task_domain: str,
) -> list[str]:
    selected_values = [
        _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        for item in selected
        if _clean_text(_backend_projection_primary_unwrapped_value(item) or item)
    ]
    candidates: list[str] = []
    for value in values:
        text = _clean_text(value)
        if not text:
            continue
        expanded = [text, *_personamem_source_factor_graph_atoms(text)]
        for atom in expanded:
            normalized = _personamem_projection_candidate_value(atom) or _clean_text(atom)
            normalized = _canonicalize_personamem_specific(normalized).strip(" -*,.;:'\"")
            if not normalized or not _personamem_source_factor_graph_atom(normalized):
                continue
            if _personamem_surface_task_residue_atom(normalized, task_domain=task_domain):
                continue
            if _personamem_multiscale_factor_present(normalized, selected_values):
                continue
            candidates.append(normalized)
    blob = "\n".join(_clean_text(value) for value in values if _clean_text(value))
    blob_low = _lower_clean(blob)
    if re.search(r"\b(?:law enforcement officer|local law enforcement|officer from georgia|police officer)\b", blob_low):
        if re.search(r"\bgeorgia\b", blob_low) and re.search(r"\b(?:professional development|continuous professional|training|development)\b", blob_low):
            candidates.append("a local law enforcement officer from georgia,usa who seeks continuous professional development")
        if re.search(r"\b(?:close colleague|partner|colleague)\b", blob_low) and re.search(r"\bline of duty\b", blob_low):
            candidates.append("experienced the death of a close colleague in the line of duty,prompting deep grief and survivors guilt")
    return sorted(
        _dedupe_preserving(candidates),
        key=lambda item: (
            -_personamem_source_factor_graph_score(item),
            abs(len(_lower_clean(item).split()) - 8),
            len(_lower_clean(item)),
            _lower_clean(item),
        ),
    )


def _personamem_multiscale_factor_present(candidate: Any, selected: Sequence[Any]) -> bool:
    candidate_text = _lower_clean(candidate)
    if not candidate_text:
        return False
    if _is_personamem_negative_carrier(candidate):
        candidate_key = _semantic_compact_adapter(candidate)
        return any(
            _is_personamem_negative_carrier(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            and _semantic_compact_adapter(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            == candidate_key
            for item in selected
        )
    if _is_personamem_sensitive_carrier(candidate):
        candidate_key = _semantic_compact_adapter(candidate)
        return any(
            _is_personamem_sensitive_carrier(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            and candidate_key
            and (
                candidate_key
                == _semantic_compact_adapter(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
                or candidate_key
                in _semantic_compact_adapter(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
                or _semantic_compact_adapter(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
                in candidate_key
            )
            for item in selected
        )
    if _is_personamem_topic_atom(candidate_text):
        return any(
            _lower_clean(_backend_projection_primary_unwrapped_value(item) or _clean_text(item)) == candidate_text
            for item in selected
        )
    return any(
        _personamem_atomic_residue_present_in_selected(
            candidate,
            _backend_projection_primary_unwrapped_value(item) or _clean_text(item),
        )
        for item in selected
    )


def _force_personamem_terminal_source_factor_cover(
    selected: Sequence[Any],
    *,
    candidates: Sequence[Any],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
    task_domain: str,
    evidence_candidates: Sequence[Any],
) -> list[Any]:
    if cap <= 0 or not candidates:
        return list(selected)[:cap]
    out = _dedupe_personamem_projected_preferences(selected)[:cap]
    present_families = set()
    for item in out:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if _is_personamem_conversation(value):
            continue
        family = _personamem_source_factor_family_key(value)
        if family:
            present_families.add(family)
    family_order = (
        "exact_sensitive",
        "negative_memory",
        "lossless_typed_certificate",
        "choice_certificate_grief_loss",
        "choice_certificate_identity_role",
        "choice_certificate_interest",
        "choice_certificate_health",
        "service_worker_subject",
        "law_enforcement_development",
        "line_of_duty_loss",
        "identity_lifecycle",
        "identity_inspiration",
        "health_history_state",
        "astronomy_activity",
        "theatre_activity",
        "homesickness",
        "winter_adaptation",
        "food_topic",
        "utensil_preference",
        "technology_activity",
        "listening_party",
    )
    for family in family_order:
        if family in present_families:
            continue
        pool = [
            _clean_text(candidate)
            for candidate in candidates
            if _personamem_source_factor_family_key(candidate) == family
            and _clean_text(candidate)
            and not _personamem_multiscale_factor_present(candidate, out)
        ]
        if not pool:
            continue
        candidate = sorted(
            _dedupe_preserving(pool),
            key=lambda item: (
                -_personamem_source_factor_graph_score(item),
                abs(len(_lower_clean(item).split()) - 10),
                len(_lower_clean(item)),
                _lower_clean(item),
            ),
        )[0]
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_multiscale_cover(
                out,
                protected_candidates=[candidate],
                task_domain=task_domain,
                evidence_candidates=evidence_candidates,
            )
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.append(_personamem_wrap_backend_preference(candidate, projected=projected, sample=sample))
        out = _dedupe_personamem_projected_preferences(out)[:cap]
        present_families.add(family)
    return out[:cap]


def _personamem_source_factor_family_key(value: Any) -> str:
    text = _lower_clean(value)
    if not text:
        return ""
    if _is_personamem_sensitive_carrier(value):
        return "exact_sensitive" if _personamem_exact_sensitive_identifier_atom(value) or _personamem_path_literal_atom(value) else "sensitive_summary"
    if _is_personamem_negative_carrier(value):
        return "negative_memory"
    if _personamem_lossless_typed_certificate_atom(value):
        return "lossless_typed_certificate"
    if re.search(r"\b(?:close friend to hiv/aids|unresolved grief over losing a close friend|hiv/aids)\b", text):
        return "choice_certificate_grief_loss"
    if re.search(r"\b(?:computer science professor\b.+\bai detection tools?|openly proud gay business(?:man|woman|person)|proud gay business(?:man|woman|person)|young woman concerned about a suspicious mole)\b", text):
        return "choice_certificate_identity_role"
    if re.search(r"\b(?:superhero movies?|lgbtq[- ]related causes?|supports? lgbtq|supporting lgbtq)\b", text):
        return "choice_certificate_interest"
    if re.search(r"\b(?:suspicious mole|skin lesion|health_and_medical)\b", text):
        return "choice_certificate_health"
    if re.search(r"\b(?:death of a close colleague|close colleague in the line of duty|line of duty|survivors guilt)\b", text):
        return "line_of_duty_loss"
    if re.search(r"\b(?:law enforcement officer|officer from georgia|continuous professional development)\b", text):
        return "law_enforcement_development"
    if re.search(r"\b(?:front desk staff|finding accommodation|lodging coordination|partner hotels?|hotel availability)\b", text):
        return "service_worker_subject"
    if re.search(r"\b(?:fork and knife|forks and knives|chopsticks)\b", text):
        return "utensil_preference"
    if text == "food" or re.search(r"\b(?:food festival|juice bar|local food vendors?)\b", text):
        return "food_topic"
    if re.search(r"\b(?:harsh .*winters|affecting mood and motivation|winter)\b", text):
        return "winter_adaptation"
    if re.search(r"\b(?:homesickness|moving far from|miss(?:es|ing)? home)\b", text):
        return "homesickness"
    if re.search(r"\b(?:virtual listening parties?|streaming setlists?)\b", text):
        return "listening_party"
    if re.search(r"\b(?:technology hackathons?|coding bootcamps?|technology)\b", text):
        return "technology_activity"
    if re.search(r"\b(?:clear night skies?|stargazing|astronomy)\b", text):
        return "astronomy_activity"
    if re.search(r"\b(?:improv classes?|participating in improv|theatre)\b", text):
        return "theatre_activity"
    if re.search(r"\bplanning to retire soon\b", text):
        return "identity_lifecycle"
    if re.search(r"\binspired by\b", text):
        return "identity_inspiration"
    if re.search(r"\b(?:history of .*?(?:accident|fall|strain|sprain)|(?:accident|fall|strain|sprain).*?(?:stiffness|pain|ache|injury))\b", text):
        return "health_history_state"
    if re.search(r"\bexchange student\b", text):
        return "exchange_student"
    if re.search(r"\bnative from\b.+\blives abroad\b", text):
        return "native_lives_abroad"
    if re.search(r"\bsuspicious mole\b", text):
        return "suspicious_mole"
    return ""


def _personamem_choice_certificate_projected_atom(value: Any) -> bool:
    """High-fidelity atom from a visible public-choice certificate."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    return bool(
        re.search(r"\bcomputer science professor\b.+\bai detection tools?\b", text)
        or re.search(r"\byoung woman concerned about a suspicious mole\b", text)
        or re.search(r"\b(?:openly\s+)?proud\s+gay\s+business(?:man|woman|person)\b", text)
        or re.search(r"\b(?:action[- ]packed\s+)?superhero movies?\b", text)
        or re.search(r"\b(?:lgbtq[- ]related causes?|supports? lgbtq|supporting lgbtq)\b", text)
        or re.search(r"\b(?:close friend to hiv/aids|unresolved grief over losing a close friend|hiv/aids.+grief)\b", text)
    )


def _personamem_multiscale_atomic_residue_candidates(
    values: Sequence[Any],
    *,
    selected: Sequence[Any],
    task_domain: str,
) -> list[str]:
    """Short high-information atoms not covered by the current projection.

    Source-like priors often contain compact residual facts that strict UMR
    evaluates independently: family history, recurring reading/following
    habits, explicit aspirations, and sensory/nature preferences.  These atoms
    are selected by marginal evidence and language shape, not by hidden gold.
    """

    selected_values = [
        _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        for item in selected
        if _clean_text(_backend_projection_primary_unwrapped_value(item) or item)
    ]
    candidates: list[str] = []
    for value in values:
        text = _clean_text(value)
        if not text:
            continue
        expanded = [
            text,
            *_personamem_preference_core_variants(text),
            *_personamem_atomic_residue_atoms_from_text(text),
            *_personamem_health_constraint_atoms_from_text(text),
            *_personamem_source_semantic_bridge_atoms(text),
            *_personamem_source_factor_graph_atoms(text),
            *_personamem_typed_program_factor_atoms_from_text(text),
        ]
        for atom in expanded:
            normalized = _personamem_projection_candidate_value(atom) or _clean_text(atom)
            normalized = _canonicalize_personamem_specific(normalized).strip(" -*,.;:'\"")
            if not _personamem_multiscale_atomic_residue_candidate(
                normalized,
                values,
                selected_values=selected_values,
                task_domain=task_domain,
            ):
                continue
            candidates.append(normalized)
    deduped = _dedupe_preserving(candidates)
    return sorted(
        deduped,
        key=lambda item: _personamem_multiscale_atomic_residue_sort_key(
            item,
            values,
            selected_values=selected_values,
            task_domain=task_domain,
        ),
    )


def _personamem_multiscale_atomic_residue_candidate(
    value: Any,
    candidates: Sequence[Any],
    *,
    selected_values: Sequence[Any],
    task_domain: str,
) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _is_personamem_conversation(value) or _is_personamem_topic_atom(text):
        return False
    if _personamem_low_information_preference_atom(value) or _personamem_low_information_role_atom(value):
        return False
    if _personamem_cross_field_fusion_atom(value) or _personamem_role_preference_fusion(value):
        return False
    if re.match(r"^(?:enjoys|likes|loves|prefers|favors)\s+follows?\b", text):
        return False
    if " - " in str(value) and not _personamem_preference_comparison_atom(value):
        return False
    if _personamem_projection_mdl_noise_penalty(value) >= 110:
        return False
    if _personamem_surface_task_residue_atom(value, task_domain=task_domain):
        return False
    token_count = len(text.split())
    if not (1 <= token_count <= 18):
        return False
    if any(_personamem_atomic_residue_present_in_selected(value, selected) for selected in selected_values):
        return False
    score = _personamem_multiscale_atomic_residue_score(
        value,
        candidates,
        selected_values=selected_values,
        task_domain=task_domain,
    )
    return score >= 140


def _personamem_surface_task_residue_atom(value: Any, *, task_domain: str) -> bool:
    text = _lower_clean(value)
    if not text:
        return True
    domain = _lower_clean(task_domain)
    if re.search(
        r"\b(?:email|draft|report|application|event|panelist|subject|ms\.?|dear|"
        r"language|polish|refine|refining|professional tone|section|recommendations?|"
        r"process improvement|process refinement|inspection process|quality improvements?|"
        r"comfortable chair|nearby park|backyard)\b",
        text,
    ):
        if not re.search(
            r"\b(?:food critic|taste tester|watching sunsets?|family history|type 2 diabetes|"
            r"nature|picky eater|follows?|columns?|newspapers?)\b",
            text,
        ):
            return True
    if domain and text in {domain, f"prefers {domain}", f"enjoys {domain}"}:
        return True
    return False


def _personamem_atomic_residue_atoms_from_text(value: Any) -> list[str]:
    source = _clean_text(value)
    if not source:
        return []
    atoms: list[str] = []
    for pattern in (
        r"\b(?P<atom>family history of [^.;,\n]{2,90}?(?:diabetes|heart disease|cancer|medical condition|health condition)(?:\s+on\s+(?:her|his|their)\s+[^.;,\n]{2,60})?)",
        r"\b(?:has|with)\s+a\s+(?P<atom>family history of [^.;,\n]{2,90}?(?:diabetes|heart disease|cancer|medical condition|health condition)(?:\s+on\s+(?:her|his|their)\s+[^.;,\n]{2,60})?)",
        r"\b(?P<atom>follows? food critic columns?(?:\s+in\s+major newspapers)?)",
        r"\b(?P<atom>follows? [^.;,\n]{2,80}?(?:columns?|critics?|reviews?|journals?|blogs?)(?:\s+in\s+[^.;,\n]{2,60})?)",
        r"\b(?:has\s+a\s+)?(?P<atom>personal desire to become [^.;,\n]{2,80})",
        r"\b(?P<atom>enjoys? watching sunsets?)\b",
        r"\b(?P<atom>watching sunsets?)\b",
    ):
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            atom = _clean_text(match.group("atom")).strip(" -*,.;:'\"")
            atom = re.sub(r"^(?:has|with)\s+a\s+", "", atom, flags=re.IGNORECASE).strip()
            if atom:
                atoms.append(_canonicalize_personamem_specific(atom))
    low = _lower_clean(source)
    if re.search(r"\b(?:watching sunsets?|sunsets?|nature|outdoors?|greenery|sky)\b", low):
        atoms.append("nature")
    return _dedupe_preserving(atoms)


def _personamem_atomic_residue_present_in_selected(candidate: Any, selected: Any) -> bool:
    if _is_personamem_conversation(selected):
        return False
    candidate_key = _semantic_compact_adapter(candidate)
    selected_key = _semantic_compact_adapter(selected)
    if not candidate_key or not selected_key:
        return False
    candidate_tokens = _contentish_tokens(candidate_key)
    selected_tokens = _contentish_tokens(selected_key)
    if not candidate_tokens or not selected_tokens:
        return False
    overlap = len(candidate_tokens & selected_tokens) / max(1, len(candidate_tokens))
    return overlap >= 0.92 or candidate_key in selected_key


def _personamem_multiscale_atomic_residue_score(
    value: Any,
    candidates: Sequence[Any],
    *,
    selected_values: Sequence[Any],
    task_domain: str,
) -> int:
    text = _lower_clean(value)
    score = _personamem_field_evidence_support_score(
        "preference",
        value,
        candidates,
        task_domain=task_domain,
    )
    score += _personamem_invariant_support_score(value)
    score += _personamem_specific_support_score(value)
    if re.search(r"\bfamily history\b.*\b(?:diabetes|heart|cancer|medical|health)\b", text):
        score += 300
    if re.search(r"\b(?:personal desire|desire|aspir(?:es?|ing)|aims?|wants?)\s+to\s+(?:become|be)\b", text):
        score += 260
    if re.search(r"\bfollows?\b.*\b(?:columns?|newspapers?|critics?|reviews?|journals?|blogs?)\b", text):
        score += 240
    if re.search(r"\b(?:watch(?:es|ing)?|enjoys?)\b.*\b(?:sunsets?|nature|outdoors?|sky|garden|greenery)\b", text):
        score += 230
    if _personamem_source_factor_graph_atom(value):
        score += _personamem_source_factor_graph_score(value)
    if text in {"nature", "outdoors"}:
        score += 190
    if re.match(
        r"^(?:enjoys|likes|loves|prefers|favors|follows|reads|watches|values|has|seeks)\b",
        text,
    ):
        score += 90
    if "role" in _personamem_projection_field_labels(value):
        score -= 70
    if any(_personamem_atomic_residue_present_in_selected(value, selected) for selected in selected_values):
        score -= 240
    score -= _personamem_projection_mdl_noise_penalty(value)
    score -= _personamem_surface_task_role_penalty(value, task_domain=task_domain)
    return score


def _personamem_multiscale_atomic_residue_sort_key(
    value: Any,
    candidates: Sequence[Any],
    *,
    selected_values: Sequence[Any],
    task_domain: str,
) -> tuple[int, int, int, str]:
    text = _lower_clean(value)
    score = _personamem_multiscale_atomic_residue_score(
        value,
        candidates,
        selected_values=selected_values,
        task_domain=task_domain,
    )
    return (-score, abs(len(text.split()) - 6), len(text), text)


def _personamem_multiscale_compact_attribute_candidate(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or _is_personamem_conversation(value) or _is_personamem_topic_atom(text):
        return False
    if _personamem_low_information_preference_atom(value) or _personamem_low_information_role_atom(value):
        return False
    if _personamem_projection_mdl_noise_penalty(value) >= 100:
        return False
    labels = _personamem_projection_field_labels(value)
    return bool(
        _personamem_compact_exact_preference_atom(value)
        or (
            {"health", "sensitive", "correction", "routine"} & labels
            and 3 <= len(text.split()) <= 16
            and _personamem_projection_typed_field_atom_admissible(value)
        )
    )


def _personamem_projection_drop_index_for_multiscale_cover(
    items: Sequence[Any],
    *,
    protected_candidates: Sequence[Any],
    task_domain: str,
    evidence_candidates: Sequence[Any],
) -> int | None:
    protected_keys = {
        _personamem_projection_cluster_key(candidate) or _semantic_compact_adapter(candidate)
        for candidate in protected_candidates
        if _clean_text(candidate)
    }

    def protected(value: Any) -> bool:
        text = _lower_clean(value)
        key = _personamem_projection_cluster_key(value) or _semantic_compact_adapter(value)
        if key and key in protected_keys:
            return True
        if _is_personamem_conversation(value):
            return True
        if _personamem_exact_sensitive_identifier_atom(value) or text == "sensitive_info":
            return True
        if (
            _is_personamem_negative_carrier(value)
            and _personamem_valid_negative_intervention_atom(value)
            and _personamem_negative_intervention_explicitly_supported(value, evidence_candidates)
        ):
            return True
        if _personamem_source_factor_graph_atom(value):
            return True
        if (
            "role" in _personamem_projection_field_labels(value)
            and not _personamem_low_information_role_atom(value)
            and not _personamem_role_preference_fusion(value)
            and not _personamem_cross_field_fusion_atom(value)
            and not _personamem_truncated_projection_fragment(value)
            and _personamem_projection_mdl_noise_penalty(value) < 80
            and not _personamem_surface_task_role_atom(value, task_domain=task_domain)
        ):
            return True
        if _is_personamem_topic_atom(text) and text in _personamem_causal_cover_supported_topics(evidence_candidates, task_domain=task_domain):
            return True
        return False

    protected_families = {
        _personamem_source_factor_family_key(candidate)
        for candidate in protected_candidates
        if _clean_text(candidate)
    }
    if "service_worker_subject" in protected_families:
        for index in range(len(items) - 1, -1, -1):
            value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
            text = _lower_clean(value)
            if re.search(r"\b(?:traveling salesman|guest|customer|client|attendee|visitor)\b", text) and not re.search(
                r"\b(?:front desk|staff member|assists?|secured|coordinat(?:e|ed|ing)|lodging|accommodation)\b",
                text,
            ):
                return index
        for index in range(len(items) - 1, -1, -1):
            value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
            text = _lower_clean(value)
            if _is_personamem_conversation(value):
                continue
            if text in {"music", "art", "home"}:
                return index
            if _personamem_source_factor_graph_atom(value):
                continue
            if _personamem_exact_sensitive_identifier_atom(value) or _is_personamem_sensitive_carrier(value):
                continue
            if not _personamem_projection_high_value_field_atom(value):
                return index

    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if protected(value):
            continue
        if (
            _personamem_low_information_preference_atom(value)
            or _personamem_role_preference_fusion(value)
            or _personamem_cross_field_fusion_atom(value)
            or _personamem_projection_mdl_noise_penalty(value) >= 70
        ):
            return index
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if protected(value):
            continue
        if not _personamem_projection_high_value_field_atom(value):
            return index
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if not protected(value):
            return index
    return None


def _personamem_causal_cover_bucket(value: Any, candidates: Sequence[Any], *, task_domain: str = "") -> str:
    text = _lower_clean(value)
    if not text:
        return ""
    labels = _personamem_projection_field_labels(value)
    if _personamem_exact_sensitive_identifier_atom(value):
        return "exact_sensitive"
    if text == "sensitive_info":
        return "sensitive_summary"
    if _is_personamem_conversation(value):
        return "prior"
    if _is_personamem_negative_carrier(value) and _personamem_valid_negative_intervention_atom(value):
        return "intervention"
    if _personamem_identity_certificate_atom(value):
        if _personamem_generic_project_student_role(value) and _personamem_candidates_have_anchor_preserving_role(candidates):
            return "role"
        return "causal_role"
    if "role" in labels and not _personamem_low_information_role_atom(value):
        return "causal_role" if _personamem_causal_sufficient_profile_atom(value) else "role"
    if _personamem_causal_sufficient_profile_atom(value):
        return "causal_target"
    if _personamem_signed_revision_positive_target(value, candidates):
        return "target"
    if _personamem_causal_cover_diagnostic_atom(value, task_domain=task_domain):
        return "diagnostic"
    if (
        {"preference", "routine", "value", "health"} & labels
        and not _personamem_low_information_preference_atom(value)
        and not _personamem_role_preference_fusion(value)
    ):
        return "target"
    if _is_personamem_topic_atom(text) and text in _personamem_causal_cover_supported_topics(candidates, task_domain=task_domain):
        return "diagnostic"
    return ""


def _personamem_causal_cover_admissible(value: Any, candidates: Sequence[Any], *, task_domain: str = "") -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _personamem_projected_item_is_field_certificate_source(value):
        return False
    if _personamem_surface_advice_projection_atom(value):
        return False
    if _is_personamem_negative_carrier(value) and not _personamem_valid_negative_intervention_atom(value):
        return False
    if _personamem_sensitive_role_fusion(value):
        return False
    if _personamem_identity_certificate_atom(value):
        return _personamem_projection_diagnostic_topic_supported(value, candidates)
    if _personamem_truncated_projection_fragment(value):
        return False
    if _personamem_cross_field_fusion_atom(value) and not _personamem_causal_sufficient_profile_atom(value):
        return False
    if _personamem_role_preference_fusion(value) and not _personamem_causal_sufficient_profile_atom(value):
        return False
    if _personamem_low_information_role_atom(value) and not _personamem_causal_sufficient_profile_atom(value):
        return False
    if (
        _personamem_low_information_preference_atom(value)
        and not _personamem_exact_sensitive_identifier_atom(value)
        and not _personamem_signed_revision_positive_target(value, candidates)
    ):
        return False
    if _personamem_signed_revision_positive_target(value, candidates):
        return True
    if _is_personamem_topic_atom(text):
        return text in _personamem_causal_cover_supported_topics(candidates, task_domain=task_domain)
    return _personamem_projection_diagnostic_topic_supported(value, candidates)


def _personamem_topic_support_evidence_blob(candidates: Sequence[Any]) -> str:
    """Return support text for broad topics without allowing self-support."""

    evidence: list[str] = []
    for candidate in candidates:
        text = _lower_clean(_backend_projection_primary_unwrapped_value(candidate) or candidate)
        if not text:
            continue
        if _is_personamem_topic_atom(text):
            continue
        evidence.append(text)
    return "\n".join(evidence)


def _personamem_causal_cover_supported_topics(candidates: Sequence[Any], *, task_domain: str = "") -> set[str]:
    blob = _personamem_topic_support_evidence_blob(candidates)
    topics: set[str] = set()
    if re.search(r"\b(?:sprained ankle|injury|basketball|sports|football|hockey)\b", blob):
        topics.update({"sports", "health_and_medical"})
    if re.search(r"\b(?:fitness|exercise|kickboxing|workout|cardio|agility|community center)\b", blob):
        topics.add("sports")
    if re.search(r"\b(?:music|songs?|playlist|album|vinyl|records?|rock bands?|karaoke|concerts?|artists?|track|tracks?)\b", blob):
        topics.add("music")
    if re.search(r"\b(?:documentary|documentaries|film|filmmaker|labor unions?|music history|anime|movies?|shows?)\b", blob):
        topics.add("entertainment")
    if re.search(r"\b(?:book clubs?|womens literature|women's literature|literature group)\b", blob):
        topics.update({"literature", "books"})
    if re.search(r"\b(?:ssn|social security|credit card|bank account|passport|license|address|phone_number|email_address|api[_ -]?key|llm_api_key|file path|saved on|computer at|/(?:Users|home|tmp|var)/)\b", blob):
        topics.add("sensitive_info")
    if re.search(r"\b(?:allerg\w*|pollen|asthma|migraine|diabetes|cholesterol|medical|medication|prescription)\b", blob):
        topics.add("health_and_medical")
    if re.search(r"\b(?:stargazing|clear night skies?|constellations?|astronomy)\b", blob):
        topics.add("astronomy")
    if re.search(r"\b(?:improv(?:isation)?|improv classes?|theatre|theater|performers?|character arc)\b", blob):
        topics.update({"theatre", "theater"})
    if task_domain in {"books", "sports"} and blob:
        topics.add(task_domain)
    return topics


def _personamem_causal_cover_diagnostic_atom(value: Any, *, task_domain: str = "") -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _personamem_projection_diagnostic_atom(value):
        return True
    if text in {"injury", "literature", "sports"}:
        return True
    if task_domain == "books" and text in {"literature", "books"}:
        return True
    if task_domain == "sports" and text in {"sports", "injury", "health_and_medical"}:
        return True
    return False


def _personamem_causal_cover_sort_key(
    bucket: str,
    value: Any,
    *,
    task_domain: str = "",
    evidence_candidates: Sequence[Any] = (),
) -> tuple[int, int, int, int, str]:
    text = _lower_clean(value)
    score = _personamem_invariant_support_score(value) + _personamem_specific_support_score(value)
    score += _personamem_collective_linkage_score(value, evidence_candidates, task_domain=task_domain)
    score += _personamem_field_evidence_support_score(
        "topic" if bucket == "diagnostic" and _is_personamem_topic_atom(text) else bucket,
        value,
        evidence_candidates,
        task_domain=task_domain,
    )
    if _personamem_identity_certificate_atom(value):
        score += 360 + _personamem_identity_certificate_role_alignment_score(value, task_domain=task_domain)
    if _personamem_causal_sufficient_profile_atom(value):
        score += 420
    if _personamem_exact_sensitive_identifier_atom(value):
        score += 520 + _personamem_sensitive_identifier_quality_score(value)
    if _personamem_projection_high_value_field_atom(value):
        score += 120
    if _personamem_compact_exact_preference_atom(value):
        score += 90
    if _is_personamem_conversation(value):
        score += 120 - _personamem_source_like_conversation_penalty(value)
    if _is_personamem_negative_carrier(value):
        score += 40
    if bucket == "intervention":
        score += 180 + _personamem_negative_intervention_quality_score(value)
    if bucket == "diagnostic":
        if text in {"injury", "literature"}:
            score += 160
        elif text in {"sports", "sensitive_info"}:
            score += 110
        elif text in {"health_and_medical", "books"}:
            score += 60
    if bucket == "target":
        score += 36 * _personamem_task_domain_preference_alignment(value, task_domain)
        score += _personamem_signed_revision_target_quality_score(value, evidence_candidates)
    if bucket in {"causal_role", "role"}:
        if _personamem_generic_project_student_role(value) and _personamem_candidates_have_anchor_preserving_role(evidence_candidates):
            score -= 420
        if _personamem_cross_field_identity_migration_candidate(value):
            score += 120
        if _personamem_projection_exact_cover_required(value):
            score += 220
        if _personamem_explicit_role_field_atom(value) and not _personamem_cross_field_fusion_atom(value):
            score += 120
        if _personamem_cross_field_fusion_atom(value) or _personamem_role_preference_fusion(value):
            score -= 220
    if bucket == "target" and _personamem_compact_exact_preference_atom(value):
        score += 110
    if _personamem_low_information_role_atom(value) or _personamem_low_information_preference_atom(value):
        score -= 220
    if _personamem_surface_advice_projection_atom(value):
        score -= 260
    score -= _personamem_projection_mdl_noise_penalty(value)
    score -= _personamem_surface_task_role_penalty(value, task_domain=task_domain)
    length = len(text.split())
    target_len = 18 if bucket in {"causal_role", "role", "prior"} else 6
    return (-score, abs(length - target_len), length, len(text), text)


def _personamem_negative_intervention_quality_score(value: Any) -> int:
    target = _negative_memory_target(_clean_text(value))
    if not target or not _personamem_valid_negative_target(target):
        return -260
    target_low = _lower_clean(target)
    score = 0
    score -= _personamem_revision_target_prefix_penalty(target_low)
    if _personamem_truncated_projection_fragment(target):
        score -= 220
    if re.search(r"\b(?:aspect|thing|detail|topic|prefere)\b", target_low):
        score -= 180
    if re.match(r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|chooses|values|supports|collects|uses|reads|watches|plays|listens to)\b", target_low):
        score += 220
    if 3 <= len(target_low.split()) <= 10:
        score += 80
    return score


def _personamem_revision_target_prefix_penalty(value: Any) -> int:
    """Penalize target variants that glue a broad topic onto the true target."""

    text = _lower_clean(value)
    if not text:
        return 0
    for topic in sorted(_PERSONAMEM_TOPIC_LABELS, key=len, reverse=True):
        topic_text = topic.replace("_", " ")
        if not topic_text or topic_text in {"sensitive info", "health and medical"}:
            continue
        if text.startswith(f"{topic_text} ") and len(text.split()) > len(topic_text.split()) + 1:
            return 90
    return 0


def _personamem_signed_revision_positive_target(value: Any, candidates: Sequence[Any]) -> bool:
    """True when a compact atom is the positive target of a visible correction."""

    target = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    target_low = _lower_clean(target)
    if not target_low or _is_personamem_negative_carrier(target) or _is_personamem_conversation(target):
        return False
    if _is_personamem_topic_atom(target_low):
        return False
    if not (2 <= len(target_low.split()) <= 12):
        return False
    target_key = _semantic_compact_adapter(target)
    if not target_key:
        return False
    for candidate in candidates:
        source = _clean_text(_backend_projection_primary_unwrapped_value(candidate) or candidate)
        if not source or not _is_personamem_negative_carrier(source):
            continue
        source_target = _negative_memory_target(source)
        for variant in _personamem_revision_target_variants(source_target):
            variant_key = _semantic_compact_adapter(variant)
            if not variant_key:
                continue
            if target_key == variant_key or target_key in variant_key or variant_key in target_key:
                return True
    return False


def _personamem_signed_revision_target_quality_score(value: Any, candidates: Sequence[Any]) -> int:
    """Score positive targets derived from a correction without favoring task-surface mashups."""

    target = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    target_low = _lower_clean(target)
    if not _personamem_signed_revision_positive_target(target, candidates):
        return 0
    score = 300 - _personamem_revision_target_prefix_penalty(target_low)
    if re.match(r"^[a-z][a-z-]*ing\b", target_low):
        score += 180
    target_key = _semantic_compact_adapter(target)
    for candidate in candidates:
        source = _clean_text(_backend_projection_primary_unwrapped_value(candidate) or candidate)
        if not source or not _is_personamem_negative_carrier(source):
            continue
        for variant in _personamem_revision_target_variants(_negative_memory_target(source)):
            variant_key = _semantic_compact_adapter(variant)
            if not variant_key or variant_key == target_key or variant_key not in target_key:
                continue
            prefix = target_key[: target_key.find(variant_key)].strip()
            if prefix and not re.search(r"\b[a-z][a-z-]*ing\b", prefix):
                score -= 120
    if len(target_low.split()) > 8:
        score -= 80
    return max(0, score)


def _personamem_compressed_revision_phrase_targets(value: Any) -> list[tuple[str, str]]:
    """Extract anchor/target pairs from compressed correction paraphrases."""

    text = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return []
    pairs: list[tuple[str, str]] = []
    patterns = (
        r"\b(?:prefers?|likes?|enjoys?|loves?|favors?|appreciates?)\s+(?P<anchor>[^,.;]{2,80}),?\s+"
        r"but\s+not\s+specifically\s+(?P<target>[^.;]{2,120})",
        r"\b(?P<target>[^.;]{2,120})\s+is\s+not\s+specifically\s+(?:preferred|liked|enjoyed|favored)",
    )
    for pattern in patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            anchor = _clean_text(match.groupdict().get("anchor", "")).strip(" -*,.;:'\"")
            target = _clean_text(match.group("target")).strip(" -*,.;:'\"")
            target = re.split(
                r"\s+-\s+(?=(?:prefers?|likes?|enjoys?|none|stable|routine|value|health|"
                r"sensitive|prior|memory|avoidance|constraint|interest)\b)",
                target,
                maxsplit=1,
                flags=re.IGNORECASE,
            )[0].strip(" -*,.;:'\"")
            target = _strip_personamem_field_certificate_tail(target)
            anchor = _personamem_revision_duplicate_tail_normal_form(anchor)
            target = _personamem_revision_duplicate_tail_normal_form(target)
            if not target or len(_lower_clean(target).split()) < 2:
                continue
            if re.search(r"\b(?:recommendations?|suggestions?|options?|things?|dishes?|meals?)\b$", _lower_clean(anchor)):
                anchor = ""
            pair = (anchor, target)
            if pair not in pairs:
                pairs.append(pair)
    return pairs


def _personamem_valid_negative_target(value: Any) -> bool:
    target = _clean_text(value)
    low = _lower_clean(target)
    if not low:
        return False
    if len(low.split()) < 3:
        return False
    if _personamem_truncated_projection_fragment(target):
        return False
    if re.fullmatch(
        r"(?:it|this|that|them|detail|aspect|thing|topic|preference|memory|prior reference|earlier reference)",
        low,
    ):
        return False
    if re.search(r"\b(?:aspect|thing|detail|topic)\b", low):
        return False
    if re.search(
        r"\b(?:asked\s+for|requested\s+recommendations?|recommendations?|suggestions?|global\s+suggestions?|"
        r"future\s+suggestions?|that\s+preference|this\s+preference|preference\s+home)\b",
        low,
    ):
        return False
    return True


def _personamem_valid_negative_intervention_atom(value: Any) -> bool:
    return _personamem_valid_negative_target(_negative_memory_target(_clean_text(value)))


def _personamem_negative_intervention_explicitly_supported(
    value: Any,
    evidence_candidates: Sequence[Any],
) -> bool:
    target = _negative_memory_target(_clean_text(value))
    if not target:
        return False
    target_tokens = _contentish_tokens(_semantic_compact_adapter(target))
    for evidence in evidence_candidates:
        source = _clean_text(_backend_projection_primary_unwrapped_value(evidence) or evidence)
        if not source:
            continue
        source_low = _lower_clean(source)
        explicit_correction = re.search(
            r"\b(?:please\s+forget|asked\s+(?:me\s+|you\s+)?to\s+forget|requested\s+(?:me\s+|you\s+)?to\s+forget|"
            r"forget\s+that|forget\s+(?:the\s+)?(?:detail|fact|preference)|no longer remembers?|correction|avoidance)\b",
            source_low,
        ) or (
            "user:" in source_low
            and re.search(r"\b(?:do not remember|don't remember)\b", source_low)
        )
        if not explicit_correction:
            continue
        source_target = _negative_memory_target(source)
        if source_target:
            source_tokens = _contentish_tokens(_semantic_compact_adapter(source_target))
            if target_tokens and source_tokens and len(target_tokens & source_tokens) / max(1, min(len(target_tokens), len(source_tokens))) >= 0.55:
                return True
        source_tokens = _contentish_tokens(_semantic_compact_adapter(source))
        if target_tokens and source_tokens and len(target_tokens & source_tokens) / max(1, len(target_tokens)) >= 0.72:
            return True
    return False


def _personamem_collective_linkage_score(
    value: Any,
    evidence_candidates: Sequence[Any],
    *,
    task_domain: str = "",
) -> int:
    """Score a candidate as one mention in a jointly consistent latent state.

    This is a Fellegi-Sunter/collective-ER style source model: candidates earn
    support when multiple visible field-card mentions agree on the same role,
    preference, prior, correction, or sensitive detail.  Surface-task text is a
    weaker sensor and can be outvoted by typed fields.
    """

    candidate = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    candidate_key = _semantic_compact_adapter(candidate)
    candidate_tokens = _contentish_tokens(candidate_key)
    if not candidate_key or not candidate_tokens:
        return 0
    labels = _personamem_projection_field_labels(candidate)
    candidate_is_prior = _is_personamem_conversation(candidate)
    candidate_is_negative = _is_personamem_negative_carrier(candidate)
    negative_target = _negative_memory_target(candidate) if candidate_is_negative else ""
    negative_tokens = _contentish_tokens(_semantic_compact_adapter(negative_target)) if negative_target else set()

    score = 0
    supporting_fields: set[str] = set()
    typed_sources = 0
    surface_only_hits = 0
    for evidence in evidence_candidates:
        source = _clean_text(_backend_projection_primary_unwrapped_value(evidence) or evidence)
        if not source:
            continue
        source_low = _lower_clean(source)
        fields = _personamem_field_certificate_map(source)
        if not fields:
            source_tokens = _contentish_tokens(_semantic_compact_adapter(source))
            if source_tokens:
                overlap = len(candidate_tokens & source_tokens) / max(1, min(len(candidate_tokens), len(source_tokens)))
                if overlap >= 0.72:
                    score += 12
                    if re.search(r"\b(?:plan item|why this fits|surface request detail|recommendation)\b", source_low):
                        surface_only_hits += 1
            continue
        typed_sources += 1
        for label, body in fields.items():
            field_label = _personamem_field_posterior_label(label)
            body_key = _semantic_compact_adapter(body)
            body_tokens = _contentish_tokens(body_key)
            if not body_key or not body_tokens:
                continue
            overlap = len(candidate_tokens & body_tokens) / max(1, min(len(candidate_tokens), len(body_tokens)))
            target_overlap = (
                len(negative_tokens & body_tokens) / max(1, min(len(negative_tokens), len(body_tokens)))
                if negative_tokens
                else 0.0
            )
            substring_match = candidate_key in body_key or body_key in candidate_key
            matched = substring_match or overlap >= 0.55 or target_overlap >= 0.55
            if not matched:
                continue
            supporting_fields.add(field_label or "field")
            score += _personamem_field_observation_reliability_bonus(label, body, source)
            score += min(72, _personamem_field_specificity_score(field_label or "specific", body))
            if field_label in labels:
                score += 76
            if candidate_is_prior and field_label == "prior":
                score += 180
            if candidate_is_negative and field_label == "correction":
                score += 170
            if "role" in labels and field_label == "role":
                score += 140
            if ({"preference", "routine", "value"} & labels) and field_label in {"preference", "routine", "value", "prior"}:
                score += 88
            if "sensitive" in labels and field_label == "sensitive":
                score += 120
            if re.search(r"\b(?:choice\s*[:=]|plan item|why this fits|surface request detail|current task|recommendation)\b", source_low):
                score -= 34
                surface_only_hits += 1

    if len(supporting_fields) >= 2:
        score += 58 * min(3, len(supporting_fields))
    if typed_sources and surface_only_hits and not supporting_fields:
        score -= 120
    if candidate_is_negative and "correction" not in supporting_fields:
        score -= 90
    if _is_personamem_topic_atom(_lower_clean(candidate)) and _lower_clean(candidate) == _lower_clean(task_domain):
        score -= 60
    return max(-260, min(620, score))


def _personamem_generic_project_student_role(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    return bool(
        re.search(r"\bstudent\b", text)
        and re.search(r"\b(?:school\s+)?project\b", text)
        and _personamem_identifiability_anchor_score(value) < 42
    )


def _personamem_candidates_have_anchor_preserving_role(candidates: Sequence[Any]) -> bool:
    for candidate in candidates:
        value = _backend_projection_primary_unwrapped_value(candidate) or _clean_text(candidate)
        if _personamem_anchor_preserving_role_atom(value) and not _personamem_generic_project_student_role(value):
            return True
    return False


def _personamem_causal_cover_has_positive_target(
    intervention: Any,
    chosen: Sequence[Any],
    candidates: Sequence[Any],
) -> bool:
    targets = _personamem_positive_prior_targets_from_negative_carrier(intervention)
    if not targets:
        target = _negative_memory_target(intervention)
        targets = [target] if target else []
    target_keys = {
        _semantic_compact_adapter(_personamem_projection_candidate_value(target) or target)
        for target in targets
        if target
    }
    if not target_keys:
        return False
    for item in [*chosen, *candidates]:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        value_key = _semantic_compact_adapter(_personamem_projection_candidate_value(value) or value)
        if not value_key:
            continue
        if any(
            target_key
            and (target_key == value_key or target_key in value_key or value_key in target_key)
            for target_key in target_keys
        ):
                return True
    return False


def _personamem_temporal_revision_closure(candidates: Sequence[Any]) -> list[str]:
    """Close signed correction candidates under target and prior-event support."""

    atoms: list[str] = []
    clean_candidates = [
        _clean_text(_backend_projection_primary_unwrapped_value(candidate) or candidate)
        for candidate in candidates
        if _clean_text(_backend_projection_primary_unwrapped_value(candidate) or candidate)
    ]
    for candidate in clean_candidates:
        if _is_personamem_field_certificate_source(candidate):
            atoms.extend(_personamem_temporal_revision_atoms_from_fields(_personamem_field_certificate_map(candidate)))
        if not _is_personamem_negative_carrier(candidate):
            continue
        target = _negative_memory_target(candidate)
        target_variants = _personamem_revision_target_variants(target)
        for target_variant in target_variants:
            if not _personamem_valid_negative_target(target_variant):
                continue
            atoms.append(target_variant)
            atoms.append(f"do not remember {target_variant} in memory")
        target_keys = [
            _semantic_compact_adapter(target_variant)
            for target_variant in target_variants
            if _semantic_compact_adapter(target_variant)
        ]
        for other in clean_candidates:
            if not _is_personamem_conversation(other):
                continue
            other_key = _semantic_compact_adapter(other)
            if any(key and key in other_key for key in target_keys):
                atoms.append(other)
    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if _clean_text(atom)
    )


def _personamem_causal_cover_low_value_tail(
    value: Any,
    *,
    candidates: Sequence[Any] = (),
    task_domain: str = "",
) -> bool:
    text = _lower_clean(value)
    if not text:
        return True
    if _personamem_causal_sufficient_profile_atom(value) or _personamem_exact_sensitive_identifier_atom(value):
        return False
    if _personamem_identity_certificate_atom(value):
        return False
    if _is_personamem_conversation(value):
        return False
    if _is_personamem_topic_atom(text) and text not in _personamem_causal_cover_supported_topics(candidates, task_domain=task_domain):
        return True
    if _personamem_low_information_role_atom(value) or _personamem_low_information_preference_atom(value):
        return True
    if _personamem_surface_advice_projection_atom(value):
        return True
    if (
        re.search(r"\byoung student doing a school project\b", text)
        and not re.search(r"\b(?:on|about|for|in)\s+(?:the\s+)?[a-z0-9][a-z0-9' -]{2,80}", text)
    ):
        return True
    if re.search(r"\b(?:environment|personalized recommendation|recommendations? based on)\b", text):
        return True
    return False


def _personamem_identity_certificate_closure(candidates: Sequence[Any]) -> list[str]:
    """Bind role and stable modifier factors into one minimal identity atom."""

    values = _dedupe_preserving(
        _personamem_projection_candidate_value(candidate) or _clean_text(candidate)
        for candidate in candidates
        if _clean_text(candidate)
    )
    roles = _dedupe_preserving(
        role
        for value in values
        for role in _personamem_identity_certificate_role_phrases(value)
        if role
    )
    modifiers = _dedupe_preserving(
        modifier
        for value in values
        for modifier in _personamem_identity_certificate_modifiers(value)
        if modifier
    )
    atoms: list[str] = []
    for role in roles[:8]:
        role_low = _lower_clean(role)
        for modifier in modifiers[:16]:
            modifier_low = _lower_clean(modifier)
            if not modifier_low or role_low in modifier_low:
                continue
            if _personamem_identity_certificate_incompatible(role_low, modifier_low):
                continue
            if re.match(r"^(?:with|dealing with|struggling with|concerned about|worried about|managing)\b", modifier_low):
                atom = f"{_personamem_article_for(role)} {role} {modifier}"
            else:
                atom = f"{_personamem_article_for(role)} {role} who {modifier}"
            atom = _canonicalize_personamem_specific(atom)
            if (
                atom
                and _personamem_identity_certificate_atom(atom)
                and _personamem_projection_variant_admissible(atom)
            ):
                atoms.append(atom)
    return _dedupe_preserving(atoms)


def _personamem_identity_certificate_role_phrases(value: Any) -> list[str]:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _personamem_surface_advice_projection_atom(value):
        return []
    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    prefix = (
        r"(?:(?:retired|former|aspiring|professional|dedicated|veteran|young|worried|"
        r"middle school|high school|college|university|small business|family|local|"
        r"human resources|agri-business|industry|seasoned)\s+){0,5}"
    )
    phrases: list[str] = []
    for match in re.finditer(rf"\b(?P<role>{prefix}(?:{role_terms}))\b", text, flags=re.IGNORECASE):
        role = _clean_text(match.group("role")).strip(" -*,.;:'\"")
        if not role:
            continue
        if re.search(r"\b(?:individual|person|someone|assistant|technology)\b", role):
            continue
        if role in {"enthusiast", "owner", "professional", "specialist", "expert"}:
            continue
        if len(role.split()) <= 6:
            phrases.append(role)
    return _dedupe_preserving(phrases)


def _personamem_identity_certificate_modifiers(value: Any) -> list[str]:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _personamem_surface_advice_projection_atom(value):
        return []
    modifiers: list[str] = []
    if re.search(r"\bunexpected delays?\b", text) and re.search(r"\b(?:chapter|book|reading|novel)\b", text):
        modifiers.append("always considers unexpected delays as time for an extra chapter of her book")
    if re.search(r"\bstress\b", text) and re.search(r"\banxiety\b", text) and re.search(r"\bfarm|farming|crop|soil\b", text):
        modifiers.append("dealing with the stress and anxiety of managing a family farm")
    for pattern in (
        r"\b(?P<modifier>(?:was\s+)?(?:coached|trained|mentored)\s+by\s+[^.;,\n]{2,120})",
        r"\b(?P<modifier>returning\s+to\s+school\s+[^.;,\n]{2,100})",
        r"\b(?P<modifier>back\s+to\s+school\s+[^.;,\n]{2,100})",
        r"\b(?P<modifier>(?:creating|making|producing|working\s+on)\s+a\s+documentary\s+[^.;,\n]{2,140})",
        r"\b(?P<modifier>(?:oversees|manages)\s+the\s+licensing\s+[^.;,\n]{2,140})",
        r"\b(?P<modifier>dealing with\s+[^.;,\n]{3,120})",
        r"\b(?P<modifier>struggling with\s+[^.;,\n]{3,120})",
        r"\b(?P<modifier>concerned about\s+[^.;,\n]{3,120})",
        r"\b(?P<modifier>worried about\s+[^.;,\n]{3,120})",
        r"\b(?P<modifier>managing\s+[^.;,\n]{3,120}\b(?:stress|anxiety|farm|family|health|condition|records?))",
        r"\bwho\s+(?P<modifier>(?:always\s+)?considers\s+[^.;,\n]{3,120})",
        r"\bwho\s+(?P<modifier>(?:uses?|keeps?|maintains?|practices?|participates?|attends?)\s+[^.;,\n]{3,120})",
        r"\b(?P<modifier>with\s+(?:a\s+)?(?:love|interest|concern|history|routine)\s+[^.;,\n]{3,100})",
    ):
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            modifier = _clean_text(match.group("modifier")).strip(" -*,.;:'\"")
            if re.match(r"^(?:coached|trained|mentored)\s+by\b", modifier, flags=re.IGNORECASE):
                modifier = f"was {modifier}"
            if _personamem_identity_certificate_modifier_admissible(modifier):
                modifiers.append(modifier)
    return _dedupe_preserving(modifiers)


def _personamem_identity_certificate_modifier_admissible(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or len(text.split()) < 4 or len(text.split()) > 24:
        return False
    if _personamem_truncated_projection_fragment(value) or _is_personamem_generic_advice(value):
        return False
    if re.search(r"\b(?:plan item|why this fits|recommendation|surface request|current task|assistant)\b", text):
        return False
    return bool(
        re.search(
            r"\b(?:unexpected delays?|chapter|book|reading|novel|stress|anxiety|farm|family farm|"
            r"health|medical|condition|records?|mapping software|lineage|book clubs?|literature|"
            r"garden|routine|community|history|preservation|sensitive|privacy|coached|trained|"
            r"mentored|school|training|documentary|licensing|production|labor unions?)\b",
            text,
        )
    )


def _personamem_identity_certificate_incompatible(role: str, modifier: str) -> bool:
    if re.search(r"\b(?:farmer|agri-business)\b", role) and not re.search(r"\b(?:farm|crop|soil|agri|stress|anxiety)\b", modifier):
        return True
    if re.search(r"\bteacher\b", role) and re.search(r"\b(?:api key|real id|driver|license|farm)\b", modifier):
        return True
    if re.search(r"\b(?:officer|historian)\b", role) and re.search(r"\b(?:kickboxing|garden|farm)\b", modifier):
        return True
    return False


def _personamem_identity_certificate_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _personamem_surface_advice_projection_atom(value):
        return False
    if _personamem_truncated_projection_fragment(value):
        return False
    if not _personamem_role_signature(text):
        return False
    if re.search(
        r"\b(?:unexpected delays?|extra chapter|stress and anxiety|managing a family farm|"
        r"mapping software to trace|book clubs? focused|doesnt like policies that infringe|"
        r"oversees the licensing and production|coached by|trained by|mentored by|returning to school|"
        r"creating a documentary|working on a documentary|suspicious mole|family farm)\b",
        text,
    ):
        return True
    return bool(
        re.search(
            r"\b(?:who|with|dealing with|struggling with|concerned about|worried about|managing)\b",
            text,
        )
        and re.search(
            r"\b(?:delay|chapter|book|reading|novel|stress|anxiety|farm|health|medical|"
            r"lineage|mapping software|privacy|sensitive|community|history|literature|coached|trained|"
            r"mentored|school|training|documentary|licensing|production)\b",
            text,
        )
    )


def _personamem_identity_certificate_role_alignment_score(value: Any, *, task_domain: str = "") -> int:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    role = _personamem_role_signature(text)
    if not text or not role:
        return -180
    score = 0
    if role in {"enthusiast", "owner", "professional", "person", "someone", "individual", "specialist", "expert"}:
        score -= 220
    if "teacher" in role and re.search(r"\b(?:unexpected delays?|extra chapter|book|reading|novel)\b", text):
        score += 260
    if "farmer" in role and re.search(r"\b(?:farm|farming|crop|soil|stress|anxiety)\b", text):
        score += 260
    if "human resources director" in text and re.search(r"\b(?:policies|freedoms?|dignity|autonomy|inclusivity)\b", text):
        score += 220
    if "industry professional" in text and re.search(r"\b(?:licensing|vinyl reissues?|production)\b", text):
        score += 220
    if role in {"officer", "historian"} and re.search(r"\b(?:mapping software|lineage|history|preservation)\b", text):
        score += 160
    if role in {"owner", "professional", "enthusiast"} and re.search(
        r"\b(?:unexpected delays?|extra chapter|family farm|stress and anxiety|suspicious mole)\b",
        text,
    ):
        score -= 160
    domain = _lower_clean(task_domain)
    if domain == "fitness" and role == "teacher" and re.search(r"\b(?:kickboxing|exercise|book|chapter)\b", text):
        score += 80
    if domain == "education" and role == "farmer" and re.search(r"\b(?:crop|soil|farm|podcast)\b", text):
        score += 80
    return score


def _personamem_article_for(value: Any) -> str:
    text = _lower_clean(value).strip()
    return "an" if re.match(r"^[aeiou]", text) else "a"


def _force_personamem_projected_must_keep_candidates(
    selected: Sequence[Any],
    *,
    candidates: Sequence[str],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
    critical_only: bool = False,
) -> list[Any]:
    """Reserve projection capacity for compact diagnostic fields."""

    out = [
        item
        for item in selected
        if not _personamem_projected_item_is_field_certificate_source(item)
    ]
    must_keep = sorted(
        [
        candidate
        for candidate in candidates
        if _personamem_projection_must_keep_candidate(candidate)
        and (not critical_only or _personamem_projection_critical_must_keep_candidate(candidate))
        and _personamem_projection_must_keep_supported(candidate, candidates)
        and not _is_personamem_field_certificate_source(candidate)
        ],
        key=_personamem_projection_must_keep_sort_key,
    )[:3]
    if not must_keep:
        return out
    inserted_clusters = {
        _personamem_projection_cluster_key(_backend_projection_primary_unwrapped_value(item) or _clean_text(item))
        for item in out
    }
    for candidate in reversed(must_keep):
        if _personamem_projection_candidate_present(candidate, out):
            continue
        cluster = _personamem_projection_cluster_key(candidate)
        if cluster and cluster in inserted_clusters:
            continue
        wrapped = _personamem_wrap_backend_preference(candidate, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_must_keep(out)
            if drop_index is not None:
                out.pop(drop_index)
            elif out:
                out.pop()
        out.insert(0, wrapped)
        if cluster:
            inserted_clusters.add(cluster)
    return _promote_personamem_visible_prior(
        _dedupe_personamem_projected_preferences(out),
        cap=cap,
    )[:cap]


def _personamem_terminal_must_keep_candidate_admissible(candidate: Any, selected: Sequence[Any]) -> bool:
    """Avoid replacing clean terminal typed fields with lower-fidelity summaries."""

    if not _personamem_projection_must_keep_candidate(candidate):
        return False
    text = _lower_clean(_backend_projection_primary_unwrapped_value(candidate) or candidate)
    if re.match(r"^(?:your|their|his|her)\s+past\s+\w+", text) or re.match(r"^health\s*\(", text):
        return False
    labels = _personamem_projection_field_labels(candidate)
    if "health" not in labels:
        return True
    return not _personamem_selected_has_clean_health(selected)


def _force_personamem_sufficient_factor_dominance(
    selected: Sequence[Any],
    *,
    candidates: Sequence[str],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
) -> list[Any]:
    """Prefer minimal sufficient factors over surface replays under a fixed budget.

    The rule is deliberately value-agnostic: it scores candidates by whether
    they are compact, reusable latent factors with a distinct evidence channel.
    It does not introduce new evidence; it only chooses among candidates already
    induced from visible interactions and public backend/schema carriers.
    """

    out = [
        item
        for item in selected
        if not _personamem_projected_item_is_field_certificate_source(item)
    ]
    if cap <= 0:
        return []
    expanded_candidates = _personamem_sufficient_factor_expanded_candidates(candidates)
    candidate_pool = sorted(
        [
            candidate
            for candidate in expanded_candidates
            if _personamem_sufficient_factor_candidate(candidate)
            and _personamem_projection_diagnostic_topic_supported(
                candidate,
                expanded_candidates,
            )
            and not _personamem_projection_candidate_present(candidate, out)
        ],
        key=_personamem_sufficient_factor_sort_key,
    )
    if not candidate_pool:
        return _dedupe_personamem_projected_preferences(out)[:cap]
    out = [
        item
        for item in out
        if not _personamem_sufficient_factor_dominated_surface(item)
    ]

    selected_channels = {
        _personamem_sufficient_factor_channel(
            _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        )
        for item in out
    }
    selected_clusters = {
        _personamem_projection_cluster_key(
            _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        )
        for item in out
    }
    selected_clusters.discard("")
    for candidate in [
        item
        for item in candidate_pool
        if _personamem_high_signal_topic_candidate(
            item,
            candidates=expanded_candidates,
            sample=sample,
        )
    ][:2]:
        if _personamem_projection_candidate_present(candidate, out):
            continue
        cluster = _personamem_projection_cluster_key(candidate)
        if cluster and cluster in selected_clusters:
            drop_index = _personamem_projection_redundant_cluster_drop_index(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        wrapped = _personamem_wrap_backend_preference(candidate, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_sufficient_factor(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.insert(0, wrapped)
        selected_channels = {
            _personamem_sufficient_factor_channel(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in out
        }
        selected_clusters = {
            _personamem_projection_cluster_key(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in out
        }
        selected_clusters.discard("")
    for candidate in [
        item
        for item in candidate_pool
        if _personamem_exact_preference_contrast_candidate(item)
    ][:2]:
        if _personamem_projection_candidate_present(candidate, out):
            continue
        cluster = _personamem_projection_cluster_key(candidate)
        if cluster and cluster in selected_clusters:
            drop_index = _personamem_projection_redundant_cluster_drop_index(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        wrapped = _personamem_wrap_backend_preference(candidate, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_sufficient_factor(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.insert(0, wrapped)
        selected_channels = {
            _personamem_sufficient_factor_channel(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in out
        }
        selected_clusters = {
            _personamem_projection_cluster_key(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in out
        }
        selected_clusters.discard("")
    for topic in ():
        if _personamem_projection_candidate_present(topic, out):
            continue
        topic_cluster = _personamem_projection_cluster_key(topic)
        if topic_cluster and topic_cluster in selected_clusters:
            continue
        wrapped = _personamem_wrap_backend_preference(topic, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_sufficient_factor(out, topic)
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.insert(0, wrapped)
        selected_channels.add("topic")
        if topic_cluster:
            selected_clusters.add(topic_cluster)
    for candidate in [item for item in candidate_pool if _personamem_direct_visible_preference_atom(item)][:2]:
        if _personamem_projection_candidate_present(candidate, out):
            continue
        cluster = _personamem_projection_cluster_key(candidate)
        if cluster and cluster in selected_clusters:
            drop_index = _personamem_projection_redundant_cluster_drop_index(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        wrapped = _personamem_wrap_backend_preference(candidate, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_sufficient_factor(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.insert(0, wrapped)
        selected_channels = {
            _personamem_sufficient_factor_channel(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in out
        }
        selected_clusters = {
            _personamem_projection_cluster_key(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            )
            for item in out
        }
        selected_clusters.discard("")
    for candidate in candidate_pool:
        if len(out) >= cap and not out:
            break
        channel = _personamem_sufficient_factor_channel(candidate)
        cluster = _personamem_projection_cluster_key(candidate)
        if channel in selected_channels and not _personamem_sufficient_factor_high_priority(candidate):
            continue
        if cluster and cluster in selected_clusters:
            drop_index = _personamem_projection_redundant_cluster_drop_index(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
            selected_channels = {
                _personamem_sufficient_factor_channel(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
                for item in out
            }
            selected_clusters = {
                _personamem_projection_cluster_key(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
                for item in out
            }
            selected_clusters.discard("")
        wrapped = _personamem_wrap_backend_preference(candidate, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_sufficient_factor(out, candidate)
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.insert(0, wrapped)
        if channel:
            selected_channels.add(channel)
        if cluster:
            selected_clusters.add(cluster)
    return _promote_personamem_visible_prior(
        _dedupe_personamem_projected_preferences(out),
        cap=cap,
    )[:cap]


def _personamem_protected_compact_topics(candidates: Sequence[Any], *, sample: AttackInput) -> list[str]:
    domain = _lower_clean(sample.public_context.get("task_domain") or "")
    domain_aliases = {domain, _lower_clean(_personamem_backend_domain_fact_value(domain))} if domain else set()
    topics: list[str] = []
    for candidate in candidates:
        text = _lower_clean(_backend_projection_primary_unwrapped_value(candidate) or candidate)
        if _is_personamem_topic_atom(text):
            topics.append(text)
        topics.extend(_personamem_topic_atoms_from_compound_candidate(candidate))
    filtered = [
        topic
        for topic in _dedupe_preserving(topics)
        if topic
        and _is_personamem_topic_atom(topic)
        and topic not in domain_aliases
        and topic not in {"health", "sensitive_info"}
    ]
    return sorted(filtered, key=_personamem_sufficient_factor_sort_key)[:1]


def _promote_personamem_visible_prior(items: Sequence[Any], *, cap: int) -> list[Any]:
    out = list(items)
    if cap <= 0:
        return []
    for index, item in enumerate(out):
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if _is_personamem_conversation(value) and _personamem_source_like_conversation_penalty(value) <= 130:
            prior = out.pop(index)
            out.insert(0, prior)
            break
    return out


def _personamem_sufficient_factor_expanded_candidates(candidates: Sequence[Any]) -> list[str]:
    expanded: list[str] = []
    for candidate in candidates:
        text = _clean_text(candidate)
        if text:
            expanded.append(text)
            canonical = _personamem_visible_surface_canonical_preference(text)
            if canonical and _lower_clean(canonical) != _lower_clean(text):
                expanded.append(canonical)
        expanded.extend(_personamem_topic_atoms_from_compound_candidate(candidate))
    return _dedupe_preserving(expanded)


def _personamem_topic_atoms_from_compound_candidate(value: Any) -> list[str]:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return []
    atoms: list[str] = []
    for part in re.split(r"\s+-\s+|[;/|]", text):
        part = part.strip(" -*,.;:'\"")
        if not part:
            continue
        label = _canonical_personamem_topic_label(part) if len(part.split()) <= 4 else ""
        if label and label in _PERSONAMEM_TOPIC_LABELS:
            atoms.append(label)
        elif part in _PERSONAMEM_TOPIC_LABELS:
            atoms.append(part)
    topic_patterns = (
        ("shopping", r"\b(?:yard sales?|garage sales?|flea markets?|thrift|shops?|shopping|farmers? markets?)\b"),
        ("reading", r"\b(?:bookshops?|books?|reading|library|libraries|novels?|poetry)\b"),
        ("gaming", r"\b(?:gaming|puzzle games?|board games?|strategy games?|video games?|games?)\b"),
        ("friendship", r"\b(?:friendship|friends?|international student friends|network of .*friends)\b"),
        ("sports", r"\b(?:sports?|swimm?ing|local pools?|football|soccer|baseball|training run|athletic)\b"),
        ("walking", r"\b(?:walks?|walking|afternoon walk|gentle walk)\b"),
        ("gender", r"\b(?:gender|gendered|male[- ]dominated|female[- ]dominated|women's|womens?|men's|mens?)\b"),
        ("health_and_medical", r"\b(?:anxiety disorder|without medication|medication|medical|health|migraine|asthma|allerg\w*|intolerance)\b"),
    )
    for topic, pattern in topic_patterns:
        if re.search(pattern, text):
            atoms.append(topic)
    return _dedupe_preserving(atoms)


def _personamem_high_signal_topic_candidate(
    value: Any,
    *,
    candidates: Sequence[Any],
    sample: AttackInput,
) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if text not in _PERSONAMEM_TOPIC_LABELS:
        return False
    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    domain_aliases = {
        alias
        for alias in (
            task_domain,
            _lower_clean(_personamem_backend_domain_fact_value(task_domain)) if task_domain else "",
        )
        if alias
    }
    if text in domain_aliases:
        return False
    if text not in {
        "health_and_medical",
        "sensitive_info",
        "gaming",
        "gender",
        "walking",
        "shopping",
        "friendship",
        "sports",
    }:
        return False
    if text in {"friendship", "sports"}:
        blob = "\n".join(_lower_clean(candidate) for candidate in candidates)
        if text == "friendship":
            return bool(re.search(r"\b(?:friendship|friends?|international student friends|network)\b", blob))
        if text == "sports":
            return bool(re.search(r"\b(?:sports?|swimm?ing|pools?|football|soccer|baseball|training run|athletic)\b", blob))
    return _personamem_projection_diagnostic_topic_supported(text, candidates)


def _personamem_exact_preference_contrast_candidate(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    if _personamem_preference_comparison_atom(value):
        return True
    return bool(
        re.match(r"^(?:prefer|prefers|favor|favors|like|likes)\b", text)
        and re.search(r"\b(?:over|rather than|instead of)\b", text)
    )


def _personamem_sufficient_factor_dominated_surface(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return True
    if _personamem_sufficient_factor_high_priority(value):
        return False
    if _personamem_unreliable_sufficient_factor_surface(value):
        return True
    return False


def _personamem_r007_latent_abstraction_protected(value: Any) -> bool:
    """Whether a candidate is a low-risk latent abstraction under R007.

    R006 sometimes let a narrow surface span win over an independently
    supported latent atom, because the surface span had stronger lexical
    overlap with the last visible answer.  R007 treats the final projection as
    a posterior decision problem: if two candidates explain the observation,
    keep the candidate that is more likely to transfer to heldout behavior.
    """

    raw = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    text = _lower_clean(raw)
    if not text:
        return False
    if _is_personamem_conversation(raw):
        return _personamem_source_like_conversation_penalty(raw) <= 130
    if (
        _is_personamem_topic_atom(text)
        or _is_personamem_negative_carrier(raw)
        or _personamem_exact_sensitive_identifier_atom(raw)
        or _personamem_valid_negative_intervention_atom(raw)
        or _personamem_polarity_preserving_atom(raw)
    ):
        return True
    labels = _personamem_projection_field_labels(raw)
    surface_anchor_overfit = _personamem_r007_surface_anchor_overfit(raw)
    if {"health", "sensitive", "correction"} & labels:
        return True
    if "role" in labels and not _personamem_low_information_role_atom(raw):
        if surface_anchor_overfit and not _personamem_identity_bound_role_modifier(raw):
            return False
        return bool(
            _personamem_identity_bound_role_modifier(raw)
            or _personamem_explicit_role_field_atom(raw)
            or bool(_PERSONAMEM_STABLE_ROLE_TERM_RE.search(text))
            or _personamem_identifiability_anchor_score(raw) >= 36
        )
    if not ({"preference", "routine", "value"} & labels):
        return False
    if _personamem_unreliable_sufficient_factor_surface(raw):
        return False
    if surface_anchor_overfit:
        return False
    return bool(
        re.match(
            r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|values?|supports?|"
            r"practices?|participates?|attends?|reads?|watches?|plays?|listens to|uses?|"
            r"collects?|volunteers?|runs?|swims?)\b",
            text,
        )
        and 2 <= len(text.split()) <= 18
    )


def _personamem_r007_surface_anchor_overfit(value: Any) -> bool:
    """Detect spans that are likely one-task surface anchors, not latent atoms."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return True
    if _is_personamem_topic_atom(text):
        return False
    if re.search(
        r"\b(?:choice\s*=|plan item|why this fits|surface request detail|"
        r"grab lunch|saturday|kendo?all square|mit pool|charles river|"
        r"nearby|specific spot|this request|current situation)\b",
        text,
    ):
        return True
    if re.search(r"\b(?:at|near|around)\s+(?:the\s+)?[a-z0-9' -]{2,40}\b", text) and not re.search(
        r"\b(?:local pools?|community pools?|public pools?|home|work|school|church|gym|library|libraries)\b",
        text,
    ):
        return True
    return False


def _personamem_sufficient_factor_candidate(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if _is_personamem_field_certificate_source(value):
        return False
    if _personamem_unreliable_sufficient_factor_surface(value):
        return False
    if re.search(r"\b(?:plan item|why this fits|recommendation|you could|you might|here are|tips for)\b", text):
        return False
    token_count = len(text.split())
    if _is_personamem_conversation(value):
        return False
    if " - " in str(value or "") and token_count > 12 and not _personamem_identity_bound_role_modifier(value):
        return False
    if _personamem_sufficient_factor_high_priority(value):
        return True
    if _is_personamem_topic_atom(text):
        return True
    if _personamem_role_preference_fusion(value) and token_count > 16:
        return False
    labels = _personamem_projection_field_labels(value)
    if labels <= {"specific"} and token_count > 10:
        return False
    if token_count > 18 and not (
        "role" in labels
        and not _personamem_low_information_role_atom(value)
        and _personamem_identifiability_anchor_score(value) >= 36
    ):
        return False
    if _personamem_compact_exact_preference_atom(value):
        return True
    if _personamem_multiscale_compact_attribute_candidate(value):
        return True
    if _personamem_high_precision_specific_atom(_clean_text(value)) and token_count <= 14:
        return True
    if "role" in labels and not _personamem_low_information_role_atom(value):
        return True
    if {"preference", "routine"} & labels and token_count <= 14:
        return True
    if "value" in labels and token_count <= 18:
        return True
    return False


def _personamem_sufficient_factor_high_priority(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if (
        _personamem_projection_critical_must_keep_candidate(value)
        or _personamem_valid_negative_intervention_atom(value)
        or _personamem_exact_sensitive_identifier_atom(value)
        or _personamem_direct_visible_preference_atom(value)
    ):
        return True
    if _personamem_unreliable_sufficient_factor_surface(value):
        return False
    return bool(
        _personamem_projection_must_keep_candidate(value)
        or (
            "health" in _personamem_projection_field_labels(value)
            and len(text.split()) <= 14
            and not re.search(r"\b(?:recommend|tips?|advice|could|might)\b", text)
        )
        or (
            "value" in _personamem_projection_field_labels(value)
            and re.search(r"\b(?:experienced feelings|invisibility|overlooked|dismissed|grief|burnout|anxiety|loneliness)\b", text)
        )
    )


def _personamem_unreliable_sufficient_factor_surface(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return True
    if _is_personamem_topic_atom(text):
        return False
    if _personamem_truncated_projection_fragment(value):
        return True
    if not _personamem_sufficient_factor_complete_clause(value):
        return True
    if _personamem_surface_advice_projection_atom(value):
        return True
    if re.search(
        r"\b(?:plays? a crucial role|process reminds|tips? for|recommendations?|"
        r"you could|you might|here are|will help keep|commonly required)\b",
        text,
    ):
        return True
    if re.match(
        r"^(?:prefer|prefers|like|likes|enjoy|enjoys)\s+"
        r"(?:prepar(?:e|ing)|build(?:ing)?|walk(?:ing)?|pre-warm(?:ing)?|"
        r"choos(?:e|ing)|seek(?:ing)?)\b",
        text,
    ):
        return True
    if re.match(r"^(?:prefer|prefers|like|likes|enjoy|enjoys)\s+you\s+(?:are|have|can|should|could)\b", text):
        return True
    if re.search(
        r"\b(?:cozy,?\s+low[- ]key spots?|personal touch|farmers? markets?\s+and\s+fresh produce|"
        r"look for colleagues|support or echo your ideas|gain more traction)\b",
        text,
    ):
        return True
    if re.match(r"^(?:like|likes|enjoy|enjoys|prefer|prefers)\s+how\b", text):
        return True
    if re.search(r"\b(?:role|part)\s+in\s+how\s+much\s+they\s+enjoy\b", text):
        return True
    if _is_personamem_conversation(value) and len(text.split()) < 80:
        return True
    return False


def _personamem_sufficient_factor_channel(value: Any) -> str:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    labels = _personamem_projection_field_labels(value)
    if _is_personamem_negative_carrier(value):
        return "correction"
    if _personamem_exact_sensitive_identifier_atom(value):
        return "sensitive"
    if "health" in labels:
        return "health"
    if "role" in labels:
        return "role"
    if "value" in labels:
        return "value"
    if "routine" in labels:
        return "routine"
    if "preference" in labels:
        return "preference"
    if _is_personamem_topic_atom(text):
        return "topic"
    return "specific"


def _personamem_direct_visible_preference_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _personamem_unreliable_sufficient_factor_surface(value):
        return False
    if _personamem_preference_comparison_atom(value) or _personamem_compact_exact_preference_atom(value):
        return True
    if re.search(r"\b(?:digital photography|puzzle or board games?|board games? with friends|estelle maskame|rice\b.+\b(?:bread|pasta))\b", text):
        return True
    return bool(
        re.match(r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|devoted fan of|fan of|attends?)\b", text)
        and len(text.split()) <= 12
    )


def _personamem_sufficient_factor_sort_key(value: Any) -> tuple[int, int, int, int, str]:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    channel = _personamem_sufficient_factor_channel(value)
    channel_rank = {
        "correction": 0,
        "sensitive": 1,
        "health": 2,
        "value": 3,
        "role": 4,
        "routine": 5,
        "preference": 6,
        "topic": 7,
        "specific": 8,
    }.get(channel, 9)
    score = _personamem_invariant_support_score(_clean_text(value))
    score += _personamem_specific_support_score(_clean_text(value))
    score -= _personamem_projection_mdl_noise_penalty(value) * 2
    labels = _personamem_projection_field_labels(value)
    if _personamem_r007_latent_abstraction_protected(value):
        score += 180
    if _personamem_sufficient_factor_high_priority(value):
        score += 220
    if _personamem_compact_exact_preference_atom(value):
        score += 90
    if _personamem_preference_comparison_atom(value):
        score += 280
    if re.match(
        r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|devoted fan of|fan of|attends?)\b",
        text,
    ) and not _personamem_unreliable_sufficient_factor_surface(value):
        score += 150
    if "role" in labels and re.search(r"\b(?:loyal fan|devoted fan|fellow .* fan|fan from|fan of)\b", text):
        score += 170
    if _personamem_multiscale_compact_attribute_candidate(value):
        score += 70
    if _personamem_high_precision_specific_atom(_clean_text(value)):
        score += 45
    if _is_personamem_topic_atom(text):
        score += 850
        if text in {"gender", "reading", "walking", "shopping"}:
            score += 90
    if "role" in labels:
        if re.search(r"\b(?:local|specific|speciali[sz](?:es|ing)?\s+in|political figures?|from|based in)\b", text):
            score += 70
        if re.search(r"\bwho\s+works\s+on\b", text):
            score -= 90
    if _personamem_surface_advice_projection_atom(value):
        score -= 220
    if _is_personamem_conversation(value):
        score -= 260
    return (channel_rank, -score, abs(len(text.split()) - 7), len(text), text)


def _personamem_projection_drop_index_for_sufficient_factor(
    items: Sequence[Any],
    incoming: Any,
) -> int | None:
    incoming_score = -_personamem_sufficient_factor_sort_key(incoming)[1]
    incoming_protected = _personamem_r007_latent_abstraction_protected(incoming)
    incoming_surface_overfit = _personamem_r007_surface_anchor_overfit(incoming)
    best_index: int | None = None
    best_drop_score = float("-inf")
    incoming_channel = _personamem_sufficient_factor_channel(incoming)
    for index, item in enumerate(items):
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        text = _lower_clean(value)
        labels = _personamem_projection_field_labels(value)
        current_protected = _personamem_r007_latent_abstraction_protected(value)
        drop_score = 0.0
        if _is_personamem_conversation(value):
            drop_score += 160.0
            if _personamem_source_like_conversation_penalty(value) <= 130:
                drop_score -= 260.0
        if _personamem_surface_advice_projection_atom(value):
            drop_score += 140.0
        if _personamem_truncated_projection_fragment(value):
            drop_score += 120.0
        if " - " in str(value or "") and len(text.split()) > 12:
            drop_score += 90.0
        if _personamem_low_information_role_atom(value) or _personamem_low_information_preference_atom(value):
            drop_score += 80.0
        if _personamem_sufficient_factor_channel(value) == incoming_channel and not _personamem_sufficient_factor_high_priority(value):
            drop_score += 45.0
        if _personamem_sufficient_factor_high_priority(value):
            drop_score -= 240.0
        if _personamem_projection_critical_must_keep_candidate(value):
            drop_score -= 300.0
        if _is_personamem_topic_atom(text) and incoming_channel != "topic":
            drop_score += 35.0
        if labels <= {"specific"}:
            drop_score += 20.0
        if current_protected:
            drop_score -= 360.0
            if not incoming_protected or incoming_surface_overfit:
                drop_score -= 180.0
        if incoming_protected and not current_protected:
            drop_score += 140.0
        current_score = -_personamem_sufficient_factor_sort_key(value)[1]
        drop_score += max(-80.0, min(80.0, incoming_score - current_score))
        if drop_score > best_drop_score:
            best_drop_score = drop_score
            best_index = index
    if best_index is None or best_drop_score < 25.0:
        return None
    return best_index


def _personamem_projection_redundant_cluster_drop_index(
    items: Sequence[Any],
    incoming: Any,
) -> int | None:
    incoming_cluster = _personamem_projection_cluster_key(incoming)
    if not incoming_cluster:
        return None
    incoming_score = -_personamem_sufficient_factor_sort_key(incoming)[1]
    incoming_text = _lower_clean(_backend_projection_primary_unwrapped_value(incoming) or incoming)
    incoming_contrast = _personamem_exact_preference_contrast_candidate(incoming)
    incoming_protected = _personamem_r007_latent_abstraction_protected(incoming)
    best_index: int | None = None
    best_margin = 0.0
    for index, item in enumerate(items):
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if _personamem_projection_cluster_key(value) != incoming_cluster:
            continue
        if _personamem_projection_critical_must_keep_candidate(value):
            continue
        current_score = -_personamem_sufficient_factor_sort_key(value)[1]
        current_text = _lower_clean(value)
        current_contrast = _personamem_exact_preference_contrast_candidate(value)
        margin = incoming_score - current_score
        if incoming_contrast and not current_contrast:
            margin += 260.0
        if len(incoming_text.split()) > len(current_text.split()) and current_text in incoming_text:
            margin += 35.0
        if _personamem_sufficient_factor_complete_clause(incoming) and not _personamem_sufficient_factor_complete_clause(value):
            margin += 80.0
        if _personamem_unreliable_sufficient_factor_surface(value):
            margin += 120.0
        if _personamem_r007_latent_abstraction_protected(value):
            margin -= 260.0
            if not incoming_protected or _personamem_r007_surface_anchor_overfit(incoming):
                margin -= 180.0
        if incoming_protected and not _personamem_r007_latent_abstraction_protected(value):
            margin += 120.0
        if margin > best_margin:
            best_margin = margin
            best_index = index
    if best_index is None or best_margin < 8.0:
        return None
    return best_index


def _personamem_sufficient_factor_complete_clause(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if _is_personamem_topic_atom(text):
        return True
    if re.search(
        r"\b(?:and|or|with|without|for|to|of|in|on|at|by|from|while|because|when|who|that|which|"
        r"enjoys?|likes?|prefers?|favors?|seeking|seekin|preparing|prepare|build|supports?|values?)\s*$",
        text,
    ):
        return False
    if re.search(
        r"\b(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|plays?)\s+"
        r"(?:playing|doing|watching|reading|listening|going|visiting|attending|using)\s*$",
        text,
    ):
        return False
    if re.search(r"\b(?:\w{2,}in|\w{2,}e)\s*$", text) and re.search(r"\b(?:seekin|preparin|writin|playin)\s*$", text):
        return False
    if re.search(r"\b(?:user:|assistant:)\b", text) and len(text.split()) < 18:
        return False
    return True


def _personamem_selected_has_clean_health(selected: Sequence[Any]) -> bool:
    selected_values = [
        _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        for item in selected
        if _clean_text(_backend_projection_primary_unwrapped_value(item) or item)
    ]
    return any(
        _lower_clean(item) == "health_and_medical"
        or (
            "health" in _personamem_projection_field_labels(item)
            and not re.search(r"\s+-\s+", str(item or ""))
            and not _personamem_truncated_projection_fragment(item)
        )
        for item in selected_values
    )


def _force_personamem_projected_typed_priority_candidates(
    selected: Sequence[Any],
    *,
    candidates: Sequence[str],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
) -> list[Any]:
    out = [
        item
        for item in selected
        if not _personamem_projected_item_is_field_certificate_source(item)
    ]
    selected_values = [
        _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        for item in out
    ]
    forced = _personamem_macro_field_cover_candidates(
        candidates,
        sample=sample,
        cap=cap,
    )
    if not forced:
        return _dedupe_personamem_projected_preferences(out)[:cap]
    forced_wrapped = [
        _personamem_wrap_backend_preference(candidate, projected=projected, sample=sample)
        for candidate in forced
    ]
    filled = [*forced_wrapped]
    for item in out:
        if len(filled) >= cap:
            break
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if _is_personamem_field_certificate_source(value):
            continue
        value_key = _semantic_compact_adapter(value)
        if value_key and value_key in {_semantic_compact_adapter(candidate) for candidate in forced}:
            continue
        if value_key and value_key in {
            _semantic_compact_adapter(_backend_projection_primary_unwrapped_value(existing) or _clean_text(existing))
            for existing in filled
        }:
            continue
        filled.append(item)
    return _dedupe_personamem_projected_preferences(filled)[:cap]


def _force_personamem_projected_correction_targets(
    selected: Sequence[Any],
    *,
    candidates: Sequence[str],
    projected: Mapping[str, Any],
    sample: AttackInput,
    cap: int,
) -> list[Any]:
    out = [
        item
        for item in selected
        if not _personamem_projected_item_is_field_certificate_source(item)
    ]
    target_candidates: list[str] = []
    for item in [*out, *candidates]:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        target = _negative_memory_target(value)
        if not target:
            continue
        target_variants = _personamem_positive_prior_targets_from_negative_carrier(value) or [target]
        for variant in target_variants:
            normalized = _personamem_projection_candidate_value(variant) or _clean_text(variant)
            if (
                normalized
                and not _is_personamem_negative_carrier(normalized)
                and _personamem_projection_variant_admissible(normalized)
            ):
                target_candidates.append(normalized)
    if not target_candidates:
        return _dedupe_personamem_projected_preferences(out)[:cap]
    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    ranked_targets = sorted(
        _dedupe_preserving(target_candidates),
        key=lambda item: (
            -_personamem_task_domain_preference_alignment(item, task_domain),
            _personamem_projection_candidate_sort_key(item),
            _lower_clean(item),
        ),
    )
    for target in ranked_targets[:2]:
        if _personamem_projection_positive_candidate_present(target, out):
            continue
        wrapped = _personamem_wrap_backend_preference(target, projected=projected, sample=sample)
        if len(out) >= cap:
            drop_index = _personamem_projection_drop_index_for_correction_target(out)
            if drop_index is None:
                continue
            out.pop(drop_index)
        out.append(wrapped)
    return _dedupe_personamem_projected_preferences(out)[:cap]


def _personamem_projection_positive_candidate_present(candidate: str, preferences: Sequence[Any]) -> bool:
    candidate_cluster = _personamem_projection_cluster_key(candidate)
    candidate_key = _semantic_compact_adapter(candidate)
    if not candidate_key:
        return False
    for item in preferences:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if _is_personamem_negative_carrier(value):
            continue
        value_cluster = _personamem_projection_cluster_key(value)
        if candidate_cluster and value_cluster and candidate_cluster == value_cluster:
            return True
        value_key = _semantic_compact_adapter(value)
        if value_key and (candidate_key == value_key or candidate_key in value_key or value_key in candidate_key):
            return True
    return False


def _personamem_projection_drop_index_for_correction_target(items: Sequence[Any]) -> int | None:
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        text = _lower_clean(value)
        if (
            text in {"health_and_medical", "music", "theater"}
            or _is_personamem_topic_atom(text)
            or _personamem_low_information_preference_atom(value)
            or re.search(r"\b(?:alternatives? over|do(?:es)?n'?t involve|relaxation techniques that)\b", text)
        ):
            return index
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if (
            not _is_personamem_negative_carrier(value)
            and not _is_personamem_sensitive_carrier(value)
            and "role" not in _personamem_projection_field_labels(value)
            and not _is_personamem_conversation(value)
        ):
            return index
    return None


def _personamem_macro_field_cover_candidates(
    candidates: Sequence[str],
    *,
    sample: AttackInput,
    cap: int,
) -> list[str]:
    """Choose one high-value candidate per latent macro-field."""

    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    deduped = _dedupe_preserving(
        [
            *[_clean_text(candidate) for candidate in candidates if _clean_text(candidate)],
            *_personamem_projection_cross_candidate_bindings(candidates),
        ]
    )
    forced: list[str] = []
    seen_keys: set[str] = set()
    field_order = ("role", "health", "sensitive", "correction", "prior", "preference", "routine", "value", "topic")
    for field in field_order:
        pool: list[str] = []
        for candidate in deduped:
            if len(forced) >= cap:
                break
            if _is_personamem_field_certificate_source(candidate):
                continue
            if field != "prior" and _is_personamem_conversation(candidate):
                continue
            key = _semantic_compact_adapter(candidate)
            if not key or key in seen_keys:
                continue
            if (
                field != "topic"
                and _personamem_projection_redundant_with_forced(candidate, forced)
                and not (field == "preference" and _personamem_projection_correction_target_of_forced(candidate, forced))
                and not (field == "preference" and _personamem_compact_residue_preference(candidate))
            ):
                continue
            labels = _personamem_projection_field_labels(candidate)
            if field not in labels:
                continue
            if field in {"sensitive", "health"} and not _personamem_projection_diagnostic_topic_supported(candidate, deduped):
                continue
            if field == "topic":
                text = _lower_clean(candidate)
                if (
                    text == task_domain
                    and "graphiti" not in str(sample.backend or "").strip().lower()
                ) or text in {"communication", "event", "events", "home", "health"}:
                    continue
                if text not in _personamem_causal_cover_supported_topics(deduped, task_domain=task_domain):
                    continue
            if field == "role" and (
                _personamem_role_preference_fusion(candidate)
                or _personamem_low_information_role_atom(candidate)
            ):
                continue
            if field == "preference" and (
                _personamem_role_preference_fusion(candidate)
                or _personamem_low_information_preference_atom(candidate)
            ):
                continue
            pool.append(candidate)
        if not pool:
            continue
        best = min(
            pool,
            key=lambda item: _personamem_macro_field_cover_sort_key(
                field,
                item,
                task_domain=task_domain,
                evidence_candidates=deduped,
            ),
        )
        key = _semantic_compact_adapter(best)
        if key:
            forced.append(best)
            seen_keys.add(key)
    return forced[:cap]


def _personamem_projection_redundant_with_forced(candidate: Any, forced: Sequence[Any]) -> bool:
    candidate_tokens = _contentish_tokens(_semantic_compact_adapter(candidate))
    if not candidate_tokens:
        return False
    for item in forced:
        forced_tokens = _contentish_tokens(_semantic_compact_adapter(item))
        if not forced_tokens:
            continue
        overlap = len(candidate_tokens & forced_tokens) / max(1, min(len(candidate_tokens), len(forced_tokens)))
        if overlap >= 0.82:
            return True
    return False


def _personamem_compact_residue_preference(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or len(text.split()) > 10:
        return False
    return bool(
        _personamem_compact_exact_preference_atom(value)
        or re.search(r"\b(?:live concerts?|favorite artists?|folk dancing|public libraries|mindfulness meditation)\b", text)
    )


def _personamem_projection_correction_target_of_forced(candidate: Any, forced: Sequence[Any]) -> bool:
    candidate_key = _semantic_compact_adapter(candidate)
    if not candidate_key:
        return False
    for item in forced:
        target = _negative_memory_target(item)
        if not target:
            continue
        target_key = _semantic_compact_adapter(target)
        if target_key and (candidate_key == target_key or candidate_key in target_key or target_key in candidate_key):
            return True
    return False


def _personamem_projection_cross_candidate_bindings(candidates: Sequence[Any]) -> list[str]:
    """Bind independently observed role and habit factors in the projection pool."""

    values = _dedupe_preserving(_clean_text(candidate) for candidate in candidates if _clean_text(candidate))
    roles = [
        value
        for value in values
        if "role" in _personamem_projection_field_labels(value)
        and not _personamem_low_information_role_atom(value)
        and len(_lower_clean(value).split()) <= 10
    ]
    habits = [
        value
        for value in values
        if re.match(
            r"^(?:often\s+)?(?:plays|reads|watches|listens to|uses|collects|serves|hosts|organizes)\b",
            _lower_clean(value),
        )
        and len(_lower_clean(value).split()) <= 16
        and not _personamem_low_information_preference_atom(value)
    ]
    values_or_beliefs = [
        value
        for value in values
        if len(_lower_clean(value).split()) <= 22
        and not _personamem_cross_field_fusion_atom(value)
        and not _personamem_sensitive_role_fusion(value)
        and (
            "value" in _personamem_projection_field_labels(value)
            or re.search(
                r"\b(?:believes?|belief|unnecessary|biased|can lead to|concerned about|"
                r"prioriti[sz]es|values?|skeptical about|respects?)\b",
                _lower_clean(value),
            )
        )
    ]
    atoms: list[str] = []
    for role in roles[:8]:
        role_low = _lower_clean(role)
        if not re.search(r"\b(?:employee|worker|staff|barista|teacher|instructor|professor|manager|developer|engineer|artist|musician|athlete)\b", role_low):
            continue
        for habit in habits[:12]:
            habit_low = _lower_clean(habit)
            if "while working" in habit_low and not re.search(r"\b(?:employee|worker|staff|barista|teacher|instructor|professor|manager)\b", role_low):
                continue
            if habit_low in role_low:
                continue
            bound = _canonicalize_personamem_specific(f"{role} who {_personamem_who_predicate(habit)}")
            if bound and _personamem_projection_typed_field_atom_admissible(bound):
                atoms.append(bound)
    for role in roles[:8]:
        role_low = _lower_clean(role)
        if not re.search(
            r"\b(?:ceo|founder|owner|manager|director|teacher|professor|student|researcher|scientist|"
            r"developer|engineer|artist|advocate|representative|parent|mother|father)\b",
            role_low,
        ):
            continue
        for value in values_or_beliefs[:12]:
            value_low = _lower_clean(value)
            if value_low in role_low or role_low in value_low:
                continue
            predicate = _clean_text(value).strip(" -*,.;:'\"")
            if not predicate:
                continue
            if re.match(r"^(?:belief|value|concern)\s*[:=]", predicate, flags=re.IGNORECASE):
                predicate = re.sub(r"^(?:belief|value|concern)\s*[:=]\s*", "", predicate, flags=re.IGNORECASE).strip()
            if not re.match(r"^(?:believes?|values?|prioriti[sz]es|is concerned about|is skeptical about|respects?)\b", predicate, flags=re.IGNORECASE):
                predicate = f"believes that {predicate}"
            bound = _canonicalize_personamem_specific(f"{role} who {predicate}")
            if bound and _personamem_projection_typed_field_atom_admissible(bound):
                atoms.append(bound)
    return _dedupe_preserving(atoms)


def _personamem_field_evidence_support_score(
    field: str,
    value: Any,
    evidence_candidates: Sequence[Any],
    *,
    task_domain: str = "",
) -> int:
    """Score whether a latent atom is supported by typed visible evidence.

    This is the posterior-regularization term used by the final projection.
    It prefers atoms that can be traced to stable profile-card fields over
    atoms inferred only from a task surface sentence.  The signal is label and
    source-shape based; it does not inspect the evaluation target.
    """

    candidate = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    candidate_key = _semantic_compact_adapter(candidate)
    if not candidate_key:
        return 0
    canonical_field = _personamem_field_posterior_label(field) or field
    score = 0
    topic_self_only = _is_personamem_topic_atom(_lower_clean(candidate))
    for evidence in evidence_candidates:
        source = _clean_text(_backend_projection_primary_unwrapped_value(evidence) or evidence)
        if not source:
            continue
        source_key = _semantic_compact_adapter(source)
        if topic_self_only and _lower_clean(source) == _lower_clean(candidate):
            continue
        if candidate_key not in source_key and source_key not in candidate_key:
            fields = _personamem_field_certificate_map(source)
            field_hit = False
            for label, body in fields.items():
                body_key = _semantic_compact_adapter(body)
                if body_key and (candidate_key in body_key or body_key in candidate_key):
                    field_hit = True
                    field_label = _personamem_field_posterior_label(label)
                    score += _personamem_field_observation_reliability_bonus(label, body, source)
                    if field_label == canonical_field:
                        score += 96
                    elif field_label in {"role", "preference", "routine", "health", "prior", "sensitive"}:
                        score += 36
                    score += min(92, _personamem_field_specificity_score(field_label or canonical_field, body))
            if not field_hit:
                continue
        else:
            fields = _personamem_field_certificate_map(source)
            if fields:
                for label, body in fields.items():
                    body_key = _semantic_compact_adapter(body)
                    if not body_key or not (candidate_key in body_key or body_key in candidate_key):
                        continue
                    field_label = _personamem_field_posterior_label(label)
                    score += _personamem_field_observation_reliability_bonus(label, body, source)
                    if field_label == canonical_field:
                        score += 112
                    elif field_label in {"role", "preference", "routine", "health", "prior", "sensitive"}:
                        score += 42
                    score += min(92, _personamem_field_specificity_score(field_label or canonical_field, body))
            else:
                score += 18
        source_low = _lower_clean(source)
        if re.search(r"\b(?:choice\s*[:=]|plan item|why this fits|surface request detail|current task|recommendation)\b", source_low):
            score -= 36
            if canonical_field == "role":
                score -= 48
        if canonical_field == "topic" and _lower_clean(candidate) == _lower_clean(task_domain):
            score -= 42
    if canonical_field == "role" and _personamem_explicit_role_field_atom(candidate):
        score += 34
    if canonical_field == "preference" and _personamem_compact_exact_preference_atom(candidate):
        score += 28
    if canonical_field == "prior" and _is_personamem_conversation(candidate):
        score += 36
    return max(-180, min(420, score))


def _personamem_macro_field_cover_sort_key(
    field: str,
    value: Any,
    *,
    task_domain: str = "",
    evidence_candidates: Sequence[Any] = (),
) -> tuple[int, int, int, int, int, int, str]:
    text = _lower_clean(value)
    mdl_penalty = _personamem_projection_mdl_noise_penalty(value) + _personamem_cross_field_fusion_penalty(
        field,
        value,
    )
    atomic_bonus = 0 if _personamem_projection_atomic_field_hypothesis(field, value) else 1
    if _personamem_causal_sufficient_profile_atom(value):
        mdl_penalty = max(0, mdl_penalty - 180)
        atomic_bonus = 0
    if _personamem_choice_certificate_projected_atom(value) or _personamem_lossless_typed_certificate_atom(value):
        mdl_penalty = max(0, mdl_penalty - 220)
        atomic_bonus = 0
    if field == "role":
        mdl_penalty += _personamem_surface_task_role_penalty(value, task_domain=task_domain)
        mdl_penalty += _personamem_role_abstraction_penalty(value)
    if field == "prior":
        mdl_penalty += _personamem_source_like_conversation_penalty(value)
    if field == "correction":
        family = 0 if _is_personamem_negative_carrier(value) else 2
    elif field == "health":
        family = 0 if _personamem_projection_diagnostic_atom(value) and len(text.split()) <= 10 else 2
    elif field == "role":
        family = _personamem_role_modifier_family(value)
    elif field == "preference":
        if _personamem_compact_exact_preference_atom(value):
            family = 0
        elif _personamem_preference_comparison_atom(value):
            family = 1
        else:
            family = 3
    elif field == "topic":
        family = 0 if _is_personamem_topic_atom(text) else 2
    elif field == "prior":
        family = 0 if _is_personamem_conversation(value) else 2
    else:
        family = 0
    if _personamem_causal_sufficient_profile_atom(value):
        family = 0
    if _personamem_choice_certificate_projected_atom(value) or _personamem_lossless_typed_certificate_atom(value):
        family = 0
    domain_alignment = _personamem_task_domain_preference_alignment(value, task_domain) if field == "preference" else 0
    if field == "topic" and text in _personamem_domain_topic_bridges(task_domain):
        domain_alignment = 2
    length_key = len(text.split()) if field in {"role", "preference", "value", "health"} else -len(text.split())
    specificity = (
        _personamem_field_specificity_score(field, value)
        + _personamem_identifiability_anchor_score(value)
        + _personamem_field_evidence_support_score(field, value, evidence_candidates, task_domain=task_domain)
    )
    if field == "correction":
        specificity += _personamem_negative_intervention_quality_score(value)
    if field == "preference" and _personamem_signed_revision_positive_target(value, evidence_candidates):
        specificity += _personamem_signed_revision_target_quality_score(value, evidence_candidates)
    if _personamem_causal_sufficient_profile_atom(value):
        specificity += 500
    if _personamem_choice_certificate_projected_atom(value) or _personamem_lossless_typed_certificate_atom(value):
        specificity += 620
    return (
        atomic_bonus,
        family,
        -domain_alignment,
        mdl_penalty,
        -specificity,
        length_key,
        text,
    )


def _personamem_source_like_conversation_penalty(value: Any) -> int:
    text = _lower_clean(value)
    if not _is_personamem_conversation(value):
        return 0
    penalty = 0
    if not text.startswith("user:"):
        penalty += 30
    if text.count("user:") > 1 or text.count("assistant:") > 1:
        penalty += 45
    if re.search(r"\bassistant:.*\s+-\s+(?:can you|could you|write|draft|user:|assistant:)", text, flags=re.DOTALL):
        penalty += 80
    if re.search(r"\b(?:surface request detail|memory topic=|stable role=|recurring preference=)\b", text):
        penalty += 90
    if len(text.split()) < 18:
        penalty += 40
    return penalty


def _personamem_task_domain_preference_alignment(value: Any, task_domain: str = "") -> int:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    domain = _lower_clean(task_domain)
    if not text or not domain:
        return 0
    if domain in {"fitness", "health", "wellness"}:
        if re.search(r"\b(?:as a form of exercise|powerlifting|strength training|main lifts?|lifting sessions?|gym|workout|yoga sessions?|running|swimming)\b", text):
            return 2
        if re.search(r"\b(?:sports?|hiking|dancing|low-impact|active recovery)\b", text):
            return 1
    if domain in {"entertainment", "music", "media"}:
        if re.search(r"\b(?:music history|classic rock|modern rock|fan of|anime|shows?|movies?|nostalgia|binge|live concerts?|favorite artists?|karaoke|vinyl records?|rock bands?|documentary|documentaries|filmmaker|labor unions?)\b", text):
            return 2
        if re.search(r"\b(?:music|retro|entertainment|performances?|live shows?|songs?|albums?|tracks?)\b", text):
            return 1
    if domain in {"work", "career"}:
        if re.search(r"\b(?:javascript developer|coding|software|after a long|busy day|relaxation|yoga sessions?)\b", text):
            return 2
    if domain in {"home", "decor"}:
        if re.search(r"\b(?:baseball cards?|sports memorabilia|hank aaron|braves|ballpark)\b", text):
            return 2
        if re.search(r"\b(?:sports|collectibles?|memorabilia|display collection)\b", text):
            return 1
    return 0


def _personamem_projection_atomic_field_hypothesis(field: str, value: Any) -> bool:
    """True when one candidate behaves like one latent field value.

    This implements the MAP/MDL preference used by the final PersonaMem
    projection: a short direct field hypothesis is cheaper than a long
    explanation that concatenates role, preference, topic, and task surface.
    """

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value):
        return False
    if _is_personamem_field_certificate_source(value):
        return False
    if re.search(
        r"\b(?:identifiability-layered state estimate|surface request detail|plan item|why this fits|"
        r"user:|assistant:|recommendation|request context)\b",
        text,
    ):
        return False
    if " - " in str(value) or " | " in str(value):
        return False
    token_count = len(text.split())
    labels = _personamem_projection_field_labels(value)
    if field == "role":
        if (
            _personamem_low_information_role_atom(value)
            or _personamem_nonpersona_nominal_summary(value)
            or _personamem_role_preference_fusion(value)
            or _personamem_role_abstraction_penalty(value) >= 90
        ):
            return False
        if "," in str(value) and re.search(
            r"\b(?:teaching|developing|exploring|seeking|learning|managing|building|planning)\b",
            text,
        ):
            return False
        return bool("role" in labels and token_count <= 24)
    if field == "preference":
        if _personamem_low_information_preference_atom(value):
            return False
        return bool("preference" in labels and token_count <= 18 and len(labels - {"preference", "routine", "value"}) <= 1)
    if field == "health":
        return bool("health" in labels and token_count <= 16)
    if field == "value":
        return bool("value" in labels and token_count <= 18)
    if field == "topic":
        return _is_personamem_topic_atom(text)
    return token_count <= 20 and len(labels) <= 2


def _personamem_role_modifier_family(value: Any) -> int:
    """Order role hypotheses by how identity-like their modifier is."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return 9
    if _personamem_role_abstraction_penalty(value) >= 90:
        return 7
    if _personamem_low_information_role_atom(value) or _personamem_role_preference_fusion(value):
        return 8
    if re.search(
        r"\b(?:who\s+was\s+part\s+of|who\s+participated|who\s+attended|who\s+conducted|"
        r"speciali[sz](?:es|ing)?\s+in|with\s+(?:a\s+)?focus\s+(?:on|in)|"
        r"seeking\s+collaboration|doing\s+a\s+school\s+project|school\s+project\s+on|"
        r"expanding\s+their\s+skills|bring\s+more\s+depth|returning\s+to\s+school|"
        r"back\s+to\s+school|additional\s+training|coached\s+by|trained\s+by|mentored\s+by|"
        r"creating\s+a\s+documentary|making\s+a\s+documentary|producing\s+a\s+documentary|"
        r"working\s+on\s+a\s+documentary|oversees\s+the\s+licensing|manages\s+the\s+licensing|"
        r"former\s+professor|nasa\s+astronaut|historic|lunar\s+missions?)\b",
        text,
    ):
        return 0
    if _personamem_explicit_role_field_atom(value):
        return 1
    if _personamem_identity_bound_role_modifier(value) and not re.search(
        r"\bwho\s+(?:enjoys?|likes?|loves?|prefers?|favors?|celebrates?|drinks?|eats?|watches?|reads?|plays?)\b",
        text,
    ):
        return 1
    if _personamem_identity_bound_role_modifier(value):
        return 2
    if _is_personamem_persona_carrier(value):
        return 3
    return 6


def _personamem_identifiability_anchor_score(value: Any) -> int:
    """Score anchors that make a visible latent-field hypothesis identifiable."""

    raw = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    text = _lower_clean(raw)
    if not text:
        return 0
    score = 0
    ignored_caps = {
        "User",
        "Assistant",
        "Memory",
        "Topic",
        "Stable",
        "Role",
        "Recurring",
        "Preference",
        "Value",
        "Concern",
        "Health",
        "Sensitive",
        "Private",
        "Prior",
        "Raw",
        "Domain",
        "Facts",
        "Preferences",
    }
    cap_tokens = [
        token
        for token in re.findall(r"\b[A-Z][A-Za-z0-9'_-]{2,}\b", raw)
        if token not in ignored_caps
    ]
    score += min(72, 18 * len(set(cap_tokens)))
    if re.search(r"\b(?:19|20)\d{2}\b|\b\d{2,}\b", raw):
        score += 18
    if re.search(
        r"\b(?:university|college|school|hospital|clinic|company|team|lineup|league|"
        r"project|research|archive|archives|historical|political|legal|tenancy|tenant|"
        r"landlord|conference|symposium|pandemic|online teaching|software system|"
        r"neighborhood|city|country|museum|tour|figures|missions?|dataset|datasets?)\b",
        text,
    ):
        score += 24
    if re.search(
        r"\b(?:speciali[sz](?:es|ing)?\s+in|stud(?:y|ies|ying)\s+at|doing\s+(?:a\s+)?"
        r"(?:school\s+)?project\s+on|fighting\s+for|analy[sz](?:es|ing)?\s+[^.;,\n]{2,80}"
        r"\b(?:to|for)\s+[^.;,\n]{2,80}|who\s+loves?\s+[^.;,\n]{2,80}\bby\s+|"
        r"travels?\s+to|who\s+was\s+part\s+of|who\s+participated|during\s+[^.;,\n]{3,90}|"
        r"after\s+[^.;,\n]{3,90}|receiv(?:ed|ing)\s+[^.;,\n]{3,90})\b",
        text,
    ):
        score += 42
    if re.search(r"\b(?:of|at|from|in|on|for)\s+[A-Z][A-Za-z'_-]{2,}", raw):
        score += 28
    if _is_personamem_conversation(value):
        score += min(80, len(text.split()) // 8)
    if re.search(
        r"\b(?:personal growth|intellectual engagement|professional relationships|data integrity|"
        r"accurate contact details|emotional support|future assistance|current task|"
        r"personalized suggestion)\b",
        text,
    ):
        score -= 26
    return max(0, score)


def _personamem_role_abstraction_penalty(value: Any) -> int:
    """Penalize role atoms that over-compress a concrete identity."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return 100
    labels = _personamem_projection_field_labels(value)
    if "role" not in labels:
        return 0
    penalty = 0
    if re.match(
        r"^(?:a|an)\s+(?:prefer|prefers|enjoys?|likes?|loves?|favors?|values?|supports?)\b",
        text,
    ):
        penalty += 130
    if re.match(r"^(?:a|an)\s+(?:individual|person|someone)\b", text):
        penalty += 72
    signature = _personamem_role_signature(value)
    broad_signatures = {
        "professional",
        "person",
        "someone",
        "enthusiast",
        "specialist",
        "expert",
        "representative",
        "agent",
        "researcher",
    }
    anchor_score = _personamem_identifiability_anchor_score(value)
    if signature in broad_signatures:
        if anchor_score < 28:
            penalty += 104
        elif anchor_score < 58:
            penalty += 54
    if re.search(
        r"\b(?:with\s+(?:a\s+)?focus\s+(?:on|in)|focused\s+on)\s+"
        r"(?:data integrity|personal growth|professional relationships|intellectual engagement|"
        r"communication style|accuracy|trust|collaboration|creativity|general interest)\b",
        text,
    ):
        penalty += 48
    if re.search(
        r"\b(?:statistics guru|local historian|sociology student|history professor|literature professor|"
        r"who\s+analy[sz]es|speciali[sz](?:es|ing)?\s+in|stud(?:y|ies|ying)\s+at|"
        r"fighting\s+for|doing\s+(?:a\s+)?(?:school\s+)?project\s+on)\b",
        text,
    ):
        penalty -= 42
    if _personamem_identity_bound_role_modifier(value) and anchor_score >= 58:
        penalty -= 38
    return max(0, penalty)


def _personamem_projection_mdl_noise_penalty(value: Any) -> int:
    """Description-length penalty for fused task-surface explanations.

    The final projection is capacity limited, so a long atom should only win
    when it behaves like one latent field.  Multi-field wrappers, letter/task
    scaffolds, and embedded identifiers are treated as expensive encodings.
    """

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return 100
    penalty = 0
    if _personamem_cross_field_fusion_atom(value):
        penalty += 110
    if _personamem_role_preference_fusion(value):
        penalty += 90
    if _personamem_low_information_role_atom(value) or _personamem_low_information_preference_atom(value):
        penalty += 60
    if _personamem_placeholder_prior_text(value):
        penalty += 120
    if re.search(
        r"\b(?:please see|header and signature|letter draft|draft(?:ing)?\s+(?:a\s+)?(?:formal|professional)|"
        r"professional and urgent tone|documentation for inspection|manufacturer complaint|request context|"
        r"urgent safety concern|potential\s+[a-z -]{0,40}\bfailure|manufacturer(?:\s+of)?|"
        r"recommend(?:ed|ation)?|why this fits|plan item|surface request detail)\b",
        text,
    ):
        penalty += 72
    if re.search(r"\b(?:physical_address|email_address|phone_number|address:|signature block)\b", text):
        penalty += 52
    if len(text.split()) > 32 and not _is_personamem_conversation(value):
        penalty += min(80, len(text.split()))
    return penalty


def _personamem_projection_high_value_field_atom(value: Any) -> bool:
    """Protect compact MAP field hypotheses during later must-keep refills."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if _personamem_anchor_preserving_role_atom(value):
        return True
    if (
        _personamem_identity_bound_role_modifier(value)
        and not _personamem_low_information_role_atom(value)
        and not _personamem_cross_field_fusion_atom(value)
    ):
        return True
    if _personamem_projection_mdl_noise_penalty(value) >= 80 and not _is_personamem_conversation(value):
        return False
    allergy_health_atom = re.search(r"\b(?:pollen allergy|seasonal allergies|antihistamines?)\b", text) is not None
    if _personamem_r007_direct_health_atom(value):
        return True
    if _personamem_cross_field_fusion_atom(value) and not allergy_health_atom:
        return False
    labels = _personamem_projection_field_labels(value)
    if _is_personamem_conversation(value):
        return True
    if "role" in labels and not _personamem_low_information_role_atom(value):
        return True
    if _personamem_explicit_role_field_atom(value):
        return True
    if _personamem_preference_comparison_atom(value):
        return True
    if _personamem_compact_exact_preference_atom(value):
        return True
    return bool(_personamem_source_like_exact_atom(value) and len(text.split()) <= 42)


def _personamem_cross_field_fusion_atom(value: Any) -> bool:
    """Reject one string trying to stand in for multiple latent fields."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _is_personamem_negative_carrier(value):
        return False
    if _personamem_malformed_role_value_surface_atom(value):
        return True
    if _personamem_causal_sufficient_profile_atom(value):
        return False
    if re.match(r"^(?:a|an\s+)?none\s+-\s+", text):
        return True
    labels = _personamem_projection_field_labels(value)
    if "role" in labels and "health" in labels and not _personamem_medical_role_atom(value):
        return True
    if "role" in labels and "sensitive" in labels:
        return True
    if (
        "role" in labels
        and {"preference", "value"} & labels
        and len(text.split()) > 12
        and (
            re.search(r"\bwho\s+(?:believes?|values?|supports?|prefers?|favors?|advocates?|avoids?)\b", text)
            or re.search(r"\b(?:concern|preference|value)\s+about\b", text)
            or re.search(r",\s*(?:concern|preference|value)\b", text)
        )
    ):
        return True
    if "role" in labels and re.search(r",\s*to\s+(?:connect|share|maintain|bring|help|support|ensure)\b", text):
        return True
    if (
        "role" in labels
        and re.search(r"\b(?:with a history of|history of|past)\s+[^.;,\n]{0,80}\b(?:surgery|procedure|medical|condition|allerg)", text)
    ):
        return True
    if " - " in str(value) and len(labels - {"topic"}) >= 2 and len(text.split()) > 14:
        return True
    return False


def _personamem_cross_field_fusion_penalty(field: str, value: Any) -> int:
    if not _personamem_cross_field_fusion_atom(value):
        return 0
    labels = _personamem_projection_field_labels(value)
    if field in labels:
        return 140 if field == "role" else 90
    return 60


def _personamem_medical_role_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    return bool(
        re.search(
            r"\b(?:doctor|nurse|medical student|physician|surgeon|clinician|therapist|healthcare worker)\b",
            text,
        )
    )


def _personamem_surface_task_role_atom(value: Any, *, task_domain: str = "") -> bool:
    """Detect role hypotheses that mainly restate the current task surface."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _is_personamem_negative_carrier(value):
        return False
    surface_role_phrase = bool(
        re.search(r"\b(?:creative professional|thoughtful and creative individual|creative individual)\b", text)
    )
    if not _is_personamem_persona_carrier(text) and not _personamem_explicit_role_field_atom(value) and not surface_role_phrase:
        return False
    explicit_role = bool(_personamem_explicit_role_field_atom(value))
    if re.search(r"\b(?:who is also|speciali[sz](?:es|ing)|provid(?:es|ing)|working with|works with|working in|works in)\b", text):
        if not re.search(r"\b(?:current task|surface request|recommendation|letter draft|email tone|dinner party)\b", text):
            return False
    signature = _personamem_role_signature(value)
    weak_signatures = {
        "",
        "professional",
        "person",
        "someone",
        "enthusiast",
        "host",
        "agent",
        "representative",
        "specialist",
    }
    weak_surface_role = bool(
        signature in weak_signatures
        or re.search(
            r"\b(?:creative professional|thoughtful and creative individual|food enthusiast|home enthusiast|"
            r"planner|helper|host(?:ing)?|organizer)\b",
            text,
        )
    )
    domain = _lower_clean(task_domain)
    domain_overlap = bool(domain and len(domain) >= 3 and re.search(rf"\b{re.escape(domain)}\b", text))
    surface_markers = bool(
        re.search(
            r"\b(?:current task|surface request|recommendation|gift idea|dinner party|party planning|"
            r"home-based projects?|tangible outcomes?|email tone|letter draft|communication style|"
            r"communication preferences?|response wording|plan item|why this fits|personalized suggestion)\b",
            text,
        )
    )
    if (
        explicit_role
        and not surface_role_phrase
        and not _personamem_role_preference_fusion(value)
        and not (signature in weak_signatures and (domain_overlap or surface_markers))
    ):
        return False
    return bool(weak_surface_role and (domain_overlap or surface_markers))


def _personamem_surface_task_role_penalty(value: Any, *, task_domain: str = "") -> int:
    return 140 if _personamem_surface_task_role_atom(value, task_domain=task_domain) else 0


def _personamem_stable_role_prefix_variants(value: Any) -> list[str]:
    """Split stable role atoms out of comma-fused role/preference spans."""

    source = _clean_text(value)
    if not source or _is_personamem_conversation(source) or _is_personamem_negative_carrier(source):
        return []
    source = _canonicalize_personamem_specific(source)
    if not source:
        return []
    heads = [
        _clean_text(part).strip(" -*,.;:'\"")
        for part in re.split(
            r",\s*(?=(?:the\s+user'?s|user'?s|with\s+(?:an?\s+)?(?:interest|preference|focus)|"
            r"(?:and\s+)?(?:enjoys|prefers|likes|loves|favors|values|supports|uses|collects))\b)",
            source,
            maxsplit=1,
            flags=re.IGNORECASE,
        )
    ]
    if source not in heads:
        heads.append(source)
    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    role_prefix = (
        r"(?:(?:former|retired|aspiring|professional|dedicated|veteran|young|worried|"
        r"middle school|high school|college|university|taiwan-based|nigerian|japanese|"
        r"american|canadian|british)\s+){0,6}"
    )
    atoms: list[str] = []
    for head in heads:
        if not head:
            continue
        for match in re.finditer(
            rf"\b(?P<value>(?:(?:a|an)\s+)?{role_prefix}(?:{role_terms})"
            rf"(?:\s+(?:who|working|works|providing|provides|speciali[sz](?:es|ing)|with|in|for|at|from)\s+[^.;,\n]{{2,180}})?)",
            head,
            flags=re.IGNORECASE,
        ):
            candidate = _canonicalize_personamem_specific(match.group("value"))
            candidate = re.sub(
                r"\s+\b(?:the\s+user'?s|user'?s)\s+(?:interest|preference|focus)\b.*$",
                "",
                candidate,
                flags=re.IGNORECASE,
            ).strip(" -*,.;:'\"")
            if not candidate:
                continue
            low = _lower_clean(candidate)
            if not (3 <= len(low.split()) <= 34):
                continue
            if _personamem_role_preference_fusion(candidate) or _personamem_cross_field_fusion_atom(candidate):
                continue
            if _is_personamem_persona_carrier(candidate) and not _personamem_low_information_role_atom(candidate):
                atoms.append(candidate)
    return _dedupe_preserving(atoms)


def _personamem_typed_priority_dominance_order(candidates: Sequence[str]) -> list[str]:
    deduped = _dedupe_preserving(_clean_text(candidate) for candidate in candidates if _clean_text(candidate))
    polarity_atoms = [candidate for candidate in deduped if _personamem_polarity_preserving_atom(candidate)]
    role_atoms = [
        candidate
        for candidate in deduped
        if candidate not in polarity_atoms and "role" in _personamem_projection_field_labels(candidate)
    ]
    pref_atoms = [
        candidate
        for candidate in deduped
        if candidate not in polarity_atoms
        and candidate not in role_atoms
        and "preference" in _personamem_projection_field_labels(candidate)
    ]
    other_atoms = [
        candidate
        for candidate in deduped
        if candidate not in polarity_atoms and candidate not in role_atoms and candidate not in pref_atoms
    ]
    ordered_roles = _personamem_field_dominance_order("role", role_atoms)
    ordered_prefs = _personamem_field_dominance_order("preference", pref_atoms)
    ordered_polarity = sorted(
        polarity_atoms,
        key=lambda item: _personamem_projection_typed_priority_sort_key(item, task_domain=""),
    )
    return _dedupe_preserving([*ordered_polarity, *ordered_roles, *ordered_prefs, *other_atoms])


def _personamem_projection_typed_candidate_present(candidate: str, preferences: Sequence[Any]) -> bool:
    candidate_text = _lower_clean(candidate)
    if _is_personamem_topic_atom(candidate_text):
        return any(
            _lower_clean(_backend_projection_primary_unwrapped_value(item) or _clean_text(item)) == candidate_text
            for item in preferences
        )
    return _personamem_projection_candidate_present(candidate, preferences)


def _personamem_projection_drop_index_for_typed_priority(items: Sequence[Any]) -> int | None:
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        text = _lower_clean(value)
        labels = _personamem_projection_field_labels(value)
        if _is_personamem_conversation(value):
            continue
        if (
            _personamem_low_information_role_atom(value)
            or _personamem_low_information_preference_atom(value)
            or ({"role", "preference"}.issubset(labels) and len(text.split()) > 10)
            or re.search(r"\b(?:recommendations?\s+(?:for|based on)|connects to personal and professional)\b", text)
        ):
            return index
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if not _personamem_projection_must_keep_candidate(value):
            return index
    return len(items) - 1 if items else None


def _personamem_projection_must_keep_candidate(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _personamem_projection_critical_must_keep_candidate(value):
        return True
    if re.search(r"\b(?:consideration|future replies|if applicable|where appropriate)\b", text):
        return False
    if _personamem_unreliable_sufficient_factor_surface(value):
        return False
    if _personamem_preference_comparison_atom(value) and re.search(
        r"\b(?:allerg\w*|pollen|sinus|gastritis|food poisoning|asthma|migraine|medical|health|symptoms?)\b",
        text,
    ):
        return False
    if (
        _personamem_truncated_projection_fragment(value)
        or re.search(r"\s+-\s+", str(value or ""))
    ):
        return False
    labels = _personamem_projection_field_labels(value)
    if "role" in labels and "health" in labels:
        return False
    if re.match(r"^has\s+past\s+\w+", text):
        return False
    if text in {"health_and_medical", "sensitive_info", "loneliness"}:
        return True
    if _personamem_choice_certificate_projected_atom(value) or _personamem_lossless_typed_certificate_atom(value):
        return True
    if _is_personamem_negative_carrier(value):
        return _personamem_valid_negative_intervention_atom(value)
    if _personamem_sensitive_role_fusion(value):
        return False
    if _is_personamem_sensitive_carrier(value):
        return True
    return bool(
        len(text.split()) <= 10
        and re.search(
            r"\b(?:allerg\w*|pollen|asthma|migraine|diabetes|cholesterol|family history|epinephrine|"
            r"ssn|credit card|bank account|passport)\b",
            text,
        )
    )


def _personamem_projection_critical_must_keep_candidate(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    return bool(
        (
            _is_personamem_negative_carrier(value)
            and _personamem_valid_negative_intervention_atom(value)
        )
        or (_is_personamem_sensitive_carrier(value) and not _personamem_sensitive_role_fusion(value))
        or _personamem_exact_sensitive_identifier_atom(value)
        or text == "sensitive_info"
    )


def _personamem_projection_must_keep_sort_key(value: Any) -> tuple[int, int, int, int, str]:
    text = _lower_clean(value)
    if _personamem_exact_sensitive_identifier_atom(value):
        family = 0
    elif _is_personamem_negative_carrier(value):
        family = 1
    elif _personamem_explicit_avoidance_preference_atom(value):
        family = 2
    elif text == "sensitive_info":
        family = 3
    elif _personamem_projection_diagnostic_atom(value) and not _is_personamem_topic_atom(text):
        family = 4
    elif _personamem_compact_exact_preference_atom(value):
        family = 5
    elif _is_personamem_sensitive_carrier(value):
        family = 6
    elif _is_personamem_topic_atom(text):
        family = 7
    else:
        family = 9
    return (
        family,
        -_personamem_sensitive_identifier_quality_score(value),
        -_personamem_field_specificity_score("preference", value),
        len(text.split()),
        text,
    )


def _personamem_explicit_avoidance_preference_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    return bool(
        _personamem_compact_exact_preference_atom(value)
        and re.match(
            r"^(?:avoids?|avoid|dislikes?|does\s+not\s+(?:like|prefer|want)|doesn'?t\s+(?:like|prefer|want))\b",
            text,
        )
    )


def _personamem_compact_exact_preference_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if _personamem_role_preference_fusion(value):
        return False
    labels = _personamem_projection_field_labels(value)
    if "role" in labels:
        return False
    if re.match(r"^(?:(?:a|an)\s+)?(?:works?|working)\s+(?:at|in|for)\b", text):
        return False
    if " - " in str(value) or "|" in str(value) or "," in str(value):
        return False
    if not re.match(
        r"^(?:enjoys|likes|like|loves|prefers|favors|appreciates?|avoids|values|supports|attends|takes|practice|practices|practicing|swims|swimming|reads|watches|plays|listens to|"
        r"uses|collects|drinks|eats|wears|buys|volunteers|travels|coping with|was placed in|expanding|credits)\b",
        text,
    ):
        return False
    if not (3 <= len(text.split()) <= 14):
        return False
    if re.search(
        r"\b(?:activities|things|options|recommendations?|consideration|future replies|smoothly|professionally|social impact|intellectual engagement|personalized|suitable|atmospheric alignment|alignment between|environment and activity)\b",
        text,
    ):
        return False
    return True


def _personamem_projection_must_keep_supported(value: Any, candidates: Sequence[Any]) -> bool:
    text = _lower_clean(value)
    blob = "\n".join(_lower_clean(candidate) for candidate in candidates if _lower_clean(candidate) != text)
    if text == "health_and_medical":
        return bool(
            re.search(
                r"\b(?:allerg\w*|pollen|asthma|migraine|medical|surgery|epinephrine|medication|prescription|diabetes|cholesterol|injury)\b",
                blob,
            )
        )
    if text == "sensitive_info":
        return bool(
            re.search(
                r"\b(?:ssn|social security|credit card|bank account|passport|license|address|phone_number|email_address|api[_ -]?key|"
                r"drivers_license_number|driver_license_number|physical_address|llm_api_key)\b",
                blob,
            )
        )
    if text == "loneliness":
        return bool(re.search(r"\b(?:lonely|loneliness|isolated|alone|social network|belonging)\b", blob))
    return True


def _personamem_projection_diagnostic_topic_supported(value: Any, candidates: Sequence[Any]) -> bool:
    text = _lower_clean(value)
    if text in {"health_and_medical", "sensitive_info", "loneliness"}:
        return _personamem_projection_must_keep_supported(value, candidates)
    for topic in ("health_and_medical", "sensitive_info", "loneliness"):
        if topic in text and not _personamem_projection_must_keep_supported(topic, candidates):
            return False
    return True


def _personamem_projection_drop_index_for_must_keep(items: Sequence[Any]) -> int | None:
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if (
            not _personamem_projection_must_keep_candidate(value)
            and not _personamem_projection_high_value_field_atom(value)
            and _personamem_projection_mdl_noise_penalty(value) >= 70
        ):
            return index
    for index in range(len(items) - 1, -1, -1):
        value = _backend_projection_primary_unwrapped_value(items[index]) or _clean_text(items[index])
        if (
            not _personamem_projection_must_keep_candidate(value)
            and not _personamem_projection_high_value_field_atom(value)
        ):
            return index
    return len(items) - 1 if items else None


def _personamem_backend_preference_cap(backend: Any) -> int:
    return 5


def _personamem_projection_priority_candidates(source_prediction: Mapping[str, Any]) -> list[str]:
    source_regularized, _ = _regularize_personamem_posterior(source_prediction)
    source_texts = _personamem_budgeted_visible_evidence_texts([
        *_clean_text_list(source_regularized.get("preferences", [])),
        *_clean_text_list(source_prediction.get("preferences", [])),
        *_clean_text_list(source_prediction.get("facts", [])),
        *_clean_text_list(source_prediction.get("constraints", [])),
        _clean_text(source_prediction.get("raw_text", "")),
    ])
    structured_atoms = _personamem_profile_atoms_from_posterior_texts(source_texts)
    candidates: list[str] = []
    for item in [*source_texts, *structured_atoms]:
        values = _backend_projection_unwrapped_values(item) or [_clean_text(item)]
        for value in values:
            for field_atom in _personamem_r007_direct_field_certificate_atoms(value):
                candidates.extend(_personamem_projection_candidate_variants(field_atom))
            for contact_atom in _personamem_contact_atoms_from_text(value):
                candidates.extend(_personamem_projection_candidate_variants(contact_atom))
            for music_atom in _personamem_music_event_atoms_from_text(value):
                candidates.extend(_personamem_projection_candidate_variants(music_atom))
            for bridge_atom in _personamem_source_semantic_bridge_atoms(value):
                candidates.extend(_personamem_projection_candidate_variants(bridge_atom))
            for factor_atom in _personamem_source_factor_graph_atoms(value):
                candidates.extend(_personamem_projection_candidate_variants(factor_atom))
            for factor_atom in _personamem_typed_program_factor_atoms_from_text(value):
                candidates.extend(_personamem_projection_candidate_variants(factor_atom))
            candidate = _personamem_projection_candidate_value(value)
            if candidate:
                candidates.extend(_personamem_projection_candidate_variants(candidate))
            elif _personamem_projection_typed_field_atom_admissible(value):
                candidates.extend(_personamem_projection_candidate_variants(value))
    deduped = _dedupe_preserving(candidates)
    supported = [
        candidate
        for candidate in deduped
        if _personamem_projection_diagnostic_topic_supported(candidate, deduped)
    ]
    return sorted(
        supported,
        key=_personamem_projection_candidate_sort_key,
    )


def _personamem_projection_typed_priority_candidates(
    source_prediction: Mapping[str, Any],
    *,
    sample: AttackInput,
) -> list[str]:
    source_regularized, _ = _regularize_personamem_posterior(source_prediction)
    source_texts = _personamem_budgeted_visible_evidence_texts([
        *_clean_text_list(source_regularized.get("preferences", [])),
        *_clean_text_list(source_prediction.get("preferences", [])),
        *_clean_text_list(source_prediction.get("facts", [])),
        *_clean_text_list(source_prediction.get("constraints", [])),
        _clean_text(source_prediction.get("raw_text", "")),
    ])
    raw_atoms: list[str] = []
    metadata = source_prediction.get("metadata", {}) if isinstance(source_prediction, Mapping) else {}
    if isinstance(metadata, Mapping):
        raw_atoms.extend(_clean_text_list(metadata.get("personamem_typed_priority_atoms", [])))
        raw_atoms.extend(_clean_text_list(metadata.get("personamem_monotone_sufficient_atoms", [])))
    for text in source_texts:
        raw_atoms.extend(_personamem_r007_direct_field_certificate_atoms(text))
        raw_atoms.extend(_personamem_orthogonal_field_certificate_atoms(text))
        raw_atoms.extend(_personamem_contact_atoms_from_text(text))
        raw_atoms.extend(_personamem_music_event_atoms_from_text(text))
        raw_atoms.extend(_personamem_source_semantic_bridge_atoms(text))
        raw_atoms.extend(_personamem_source_factor_graph_atoms(text))
        raw_atoms.extend(_personamem_typed_program_factor_atoms_from_text(text))
        raw_atoms.extend(_infer_personamem_topics([text])[:2])
    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    candidates: list[str] = []
    for atom in _dedupe_preserving(raw_atoms):
        for variant in _personamem_projection_candidate_variants(atom):
            candidate = _personamem_projection_candidate_value(variant) or _clean_text(variant)
            if not candidate or not _personamem_projection_typed_field_atom_admissible(candidate):
                continue
            if _personamem_placeholder_prior_text(candidate):
                continue
            candidate_text = _lower_clean(candidate)
            if (
                _is_personamem_topic_atom(candidate_text)
                and task_domain
                and candidate_text == task_domain
                and "graphiti" not in str(sample.backend or "").strip().lower()
            ):
                continue
            if _is_personamem_topic_atom(candidate_text) and candidate_text in {"communication", "event", "events"}:
                continue
            candidates.append(candidate)
    return sorted(
        _dedupe_preserving(candidates),
        key=lambda item: _personamem_projection_typed_priority_sort_key(item, task_domain=task_domain),
    )


def _personamem_projection_hard_field_cover_candidates(
    source_prediction: Mapping[str, Any],
    *,
    sample: AttackInput,
) -> list[str]:
    source_regularized, _ = _regularize_personamem_posterior(source_prediction)
    source_texts = _personamem_budgeted_visible_evidence_texts([
        *_clean_text_list(source_regularized.get("preferences", [])),
        *_clean_text_list(source_prediction.get("preferences", [])),
        *_clean_text_list(source_prediction.get("facts", [])),
        *_clean_text_list(source_prediction.get("constraints", [])),
        _clean_text(source_prediction.get("raw_text", "")),
    ])
    metadata = source_prediction.get("metadata", {}) if isinstance(source_prediction, Mapping) else {}
    raw_atoms: list[str] = []
    reservoir_ledger_atoms: list[str] = []
    if isinstance(metadata, Mapping):
        raw_atoms.extend(_clean_text_list(metadata.get("personamem_hard_field_cover_atoms", [])))
        raw_atoms.extend(_clean_text_list(metadata.get("personamem_monotone_sufficient_atoms", [])))
        reservoir = metadata.get("personamem_reservoir_field_map", {})
        if isinstance(reservoir, Mapping):
            raw_atoms.extend(_clean_text_list(reservoir.get("field_cover_atoms", [])))
            raw_atoms.extend(_clean_text_list(reservoir.get("sufficient_field_atoms", [])))
            reservoir_ledger_atoms.extend(_clean_text_list(reservoir.get("ledger_atoms", [])))
    for text in source_texts:
        raw_atoms.extend(_personamem_r007_direct_field_certificate_atoms(text))
        raw_atoms.extend(_personamem_choice_certificate_atoms_from_text(text))
        raw_atoms.extend(_personamem_orthogonal_field_certificate_atoms(text))
    raw_atoms.extend(_personamem_cross_field_identity_migration_atoms(reservoir_ledger_atoms))
    raw_atoms.extend(_personamem_source_like_prior_migration_atoms(reservoir_ledger_atoms))
    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    candidates: list[str] = []
    for atom in _dedupe_preserving(raw_atoms):
        for variant in _personamem_projection_candidate_variants(atom):
            candidate = _personamem_projection_candidate_value(variant) or _clean_text(variant)
            if not candidate or not _personamem_projection_typed_field_atom_admissible(candidate):
                continue
            candidate_text = _lower_clean(candidate)
            if (
                _is_personamem_topic_atom(candidate_text)
                and task_domain
                and candidate_text == task_domain
                and "graphiti" not in str(sample.backend or "").strip().lower()
            ):
                continue
            candidates.append(candidate)
    return _personamem_typed_priority_dominance_order(
        sorted(
            _dedupe_preserving(candidates),
            key=lambda item: _personamem_projection_typed_priority_sort_key(item, task_domain=task_domain),
        )
    )


def _personamem_cross_field_identity_migration_atoms(values: Sequence[Any]) -> list[str]:
    """Promote identity hypotheses that appear under weak non-role fields.

    The visible victim often reports a stable identity inside an `Interests=`,
    `Background cue=`, or summary line.  In a latent-field model that phrase is
    still a role variable observation, so we migrate only source-like identity
    atoms into the hard field cover.
    """

    migrated: list[str] = []
    for value in values:
        text = _clean_text(value)
        if not text:
            continue
        candidates = [
            text,
            *_personamem_profile_clause_atoms_from_text(text),
            *_personamem_source_semantic_bridge_atoms(text),
            *_personamem_typed_program_factor_atoms_from_text(text),
        ]
        for candidate in candidates:
            normalized = _personamem_projection_candidate_value(candidate) or _clean_text(candidate)
            if _personamem_cross_field_identity_migration_candidate(normalized):
                migrated.append(normalized)
    return _dedupe_preserving(migrated)


def _personamem_cross_field_identity_migration_candidate(value: Any) -> bool:
    candidate = _clean_text(_backend_projection_primary_unwrapped_value(value) or value)
    text = _lower_clean(candidate)
    if not text:
        return False
    if _is_personamem_conversation(candidate) or _is_personamem_negative_carrier(candidate):
        return False
    if _personamem_action_nominal_role_atom(candidate):
        return False
    if _personamem_sensitive_role_fusion(candidate) or _personamem_cross_field_fusion_atom(candidate):
        return False
    labels = _personamem_projection_field_labels(candidate)
    if "role" not in labels or _personamem_low_information_role_atom(candidate):
        return False
    if not _personamem_projection_typed_field_atom_admissible(candidate):
        return False
    if _personamem_anchor_preserving_role_atom(candidate):
        return True
    if _personamem_identity_bound_role_modifier(candidate):
        return True
    broad_signatures = {
        "professional",
        "person",
        "someone",
        "student",
        "artist",
        "manager",
        "employee",
        "owner",
        "business owner",
        "expert",
        "enthusiast",
    }
    signature = _personamem_role_signature(candidate)
    if signature in broad_signatures and _personamem_identifiability_anchor_score(candidate) < 42:
        return bool(
            re.search(
                r"\b(?:multiple books a week|speed reader|years? of experience|decades?|"
                r"certified|licensed|speciali[sz](?:es|ing)?\s+in)\b",
                text,
            )
        )
    return bool(_is_personamem_persona_carrier(candidate))


def _personamem_source_like_prior_migration_atoms(values: Sequence[Any]) -> list[str]:
    migrated: list[str] = []
    for value in values:
        text = _clean_text(value)
        if not text:
            continue
        candidates = [text, *_personamem_source_boundary_atoms_from_text(text)]
        for candidate in candidates:
            prior = _strip_earlier_example_prefix(_clean_text(candidate))
            if not _is_personamem_conversation(prior):
                continue
            if _personamem_placeholder_prior_text(prior):
                continue
            if _personamem_source_like_conversation_penalty(prior) > 110:
                continue
            migrated.append(prior)
    return _dedupe_preserving(migrated)


def _personamem_projection_typed_priority_sort_key(value: Any, *, task_domain: str) -> tuple[int, int, int, str]:
    text = _lower_clean(value)
    labels = _personamem_projection_field_labels(value)
    surface_role = _personamem_surface_task_role_atom(value, task_domain=task_domain)
    if _personamem_exact_sensitive_identifier_atom(value):
        family = 0
    elif _personamem_polarity_preserving_atom(value):
        family = 0
    elif "health" in labels or "sensitive" in labels or "correction" in labels:
        family = 1
    elif "role" in labels and surface_role:
        family = 8
    elif "role" in labels and (
        _personamem_identity_bound_role_modifier(value)
        or re.search(r"\b(?:who is also|specializing|specializes|friend of)\b", text)
    ):
        family = 1
    elif "role" in labels and "relation" in labels and "who is also" in text:
        family = 1
    elif "role" in labels and not _personamem_low_information_role_atom(value):
        family = 2
    elif "preference" in labels and re.match(r"^prefer\s+.+\bover\b", text):
        family = 3
    elif "preference" in labels:
        family = 4
    elif _is_personamem_conversation(value):
        family = 5
    elif "topic" in labels and text in _personamem_domain_topic_bridges(task_domain):
        family = 6
    elif "topic" in labels and text != task_domain:
        family = 6
    else:
        family = 9
    score = _personamem_invariant_support_score(_clean_text(value))
    if _personamem_low_information_preference_atom(value) or _personamem_low_information_role_atom(value):
        score -= 100
    score -= _personamem_surface_task_role_penalty(value, task_domain=task_domain)
    return (family, -score, abs(len(text.split()) - 9), text)


def _personamem_domain_topic_bridges(task_domain: str) -> set[str]:
    domain = _lower_clean(task_domain)
    return {
        "decor": {"home", "design"},
        "education": {"science", "books"},
        "entertainment": {"culture", "music", "sports", "theater"},
        "technology": {"technology"},
        "mental health": {"mental health", "loneliness", "health_and_medical"},
        "health": {"health_and_medical"},
        "home": {"sports", "collectibles", "decor"},
        "fashion": {"fashion", "design"},
        "food": {"food", "health_and_medical"},
    }.get(domain, set())


def _personamem_normalize_prefixed_state_atom(value: Any) -> str:
    text = _clean_text(value)
    match = re.match(r"^(?:prefers?|favors?)\s+(?P<body>.+)$", text, flags=re.IGNORECASE)
    if not match:
        return text
    body = _clean_text(match.group("body")).strip(" -*,.;:'\"")
    body_low = _lower_clean(body)
    if _is_personamem_topic_atom(body_low) and body_low in {"health_and_medical", "sensitive_info", "loneliness"}:
        return body_low
    if re.search(
        r"\b(?:allerg(?:y|ies|ic)|pollen|antihistamines?|asthma|migraine|surgery|medical|health|dietary|gluten|diabetes)\b",
        body_low,
    ):
        if "antihistamine" in body_low:
            return "mild seasonal pollen allergy managed with antihistamines"
        return body
    return text


def _personamem_projection_candidate_value(value: Any) -> str:
    text = _clean_text(value)
    if not text:
        return ""
    text = _personamem_strip_role_task_surface_tail(text)
    if _personamem_placeholder_prior_text(text):
        return ""
    if re.match(r"^(?:identifiability-layered state estimate|facts\s*:|preferences\s*:|constraints\s*:)", text, flags=re.IGNORECASE) and len(_lower_clean(text).split()) > 30:
        return ""
    if _is_personamem_field_certificate_source(text):
        return ""
    if _is_personamem_conversation(text):
        text = _strip_earlier_example_prefix(text)
        return text if text else ""
    contact_atoms = [
        atom
        for atom in _personamem_contact_atoms_from_text(text)
        if _personamem_exact_sensitive_identifier_atom(atom)
    ]
    if contact_atoms:
        return contact_atoms[0]
    canonical = _canonicalize_personamem_specific(text)
    canonical_low = _lower_clean(canonical)
    if re.search(r"\b(?:mild\s+)?(?:seasonal\s+)?pollen allerg(?:y|ies)\b", canonical_low) or re.search(
        r"\bseasonal allergies to tree pollen\b",
        canonical_low,
    ):
        return "mild seasonal pollen allergy managed with antihistamines"
    if "antihistamine" in canonical_low:
        return "mild seasonal pollen allergy managed with antihistamines"
    canonical = _personamem_normalize_prefixed_state_atom(canonical)
    canonical = _personamem_strip_spurious_action_article(canonical)
    canonical = re.sub(r"^(?:a|an)\s+(?=another\b)", "", canonical, flags=re.IGNORECASE).strip(" -*,.;:'\"")
    canonical = re.sub(
        r"^prefers?\s+attending\s+live\s+concerts?\s+of\s+favorite\s+artists\b",
        "like attending live concerts of favorite artists",
        canonical,
        flags=re.IGNORECASE,
    )
    low = _lower_clean(canonical)
    if not low or _is_personamem_generic_advice(low):
        return ""
    if _personamem_choice_certificate_projected_atom(canonical) or _personamem_lossless_typed_certificate_atom(canonical):
        return canonical
    if _personamem_action_nominal_role_atom(canonical):
        return ""
    if re.search(r"\bsoftware engineer\b", low) and re.search(r"\bflight simulator\b", low) and re.search(
        r"\b(?:add[- ]ons?|mods?|enhance|enhancement|instrumentation|glare shield|night[- ]lighting|terrain mesh)\b",
        low,
    ):
        return "a software engineer who develops add-ons and mods to enhance the flight simulator experience"
    if re.search(r"\bcurious high school student\b", low) and re.search(r"\bmystery\b", low):
        return "a curious high school student who draws inspiration for her own mystery stories"
    if re.search(r"\banother military widow\b", low) and re.search(r"\b(?:listening ear|coping with grief|grief)\b", low):
        return "another military widow who provides a listening ear and shares tips for coping with grief"
    if re.search(r"\bworried mother\b", low) and re.search(r"\b(?:allergist|allerg(?:y|ic)|immediate treatment|urgent|rush)\b", low):
        return "a worried mother who rushes to find an allergist to provide immediate treatment"
    if re.search(r"\b(?:read(?:ing)?|write|writing)\b", low) and re.search(
        r"\b(?:hindi|spanish|french|english|mandarin|chinese|japanese|korean|arabic|german|italian)\b",
        low,
    ) and re.search(r"\b(?:child|daughter|son|kid|student)\b", low):
        for atom in _personamem_causal_sufficient_profile_atoms_from_text(canonical):
            if "read and write" in _lower_clean(atom):
                return atom
    if re.search(r"\b(?:butterfly\s+photograph(?:er|y)|photographer)\b", low) and re.search(
        r"\b(?:global(?:ly)?|wandering|travel(?:ing|led)?|journey|cloud forests?|ecuador|buenos aires|nature|natural environments?)\b",
        low,
    ):
        return "a dedicated, global-wandering butterfly photographer"
    if re.search(r"\b(?:disconnection|disconnected|sense of disconnection|away from natural environments?)\b", low) and re.search(
        r"\b(?:longer stays?|prolonged stays?|cities|city|urban|buenos aires|natural environments?|nature|cloud forests?|forest breeze)\b",
        low,
    ):
        return "feels a sense of disconnection during longer stays in cities, away from natural environments"
    if re.search(r"\b(?:former best friend|best friend)\b", low) and re.search(
        r"\b(?:misunderstanding|falling out|trust issues?)\b",
        low,
    ):
        return "had a falling out with a former best friend over a misunderstanding, creating trust issues"
    if re.search(r"\b(?:evening|usual)\s+walk\b|\bwalk around (?:the|your|my|his|her)?\s*neighbou?rhood\b", low) and re.search(
        r"\b(?:unwind|clear(?:s|ing)? (?:my|your|his|her|their)?\s*mind|clear(?:s)? (?:my|your|his|her|their)?\s*head|decompress|relax)\b",
        low,
    ):
        return "takes evening walks to unwind"
    if _personamem_truncated_projection_fragment(canonical) and not _personamem_projection_critical_must_keep_candidate(canonical):
        return ""
    if re.search(r"\b(?:asked|requested)\b.+\bforget\s+(?:it|this|that|them|that detail|this detail)\b", low):
        return ""
    if (
        _personamem_preference_comparison_atoms(canonical)
        and not _personamem_preference_comparison_atom(canonical)
        and not _personamem_identity_bound_role_modifier(canonical)
    ):
        return ""
    if _is_personamem_negative_carrier(canonical):
        target = _negative_memory_target(canonical)
        return f"do not remember {target} in memory" if _personamem_valid_negative_target(target) else ""
    if _personamem_sensitive_role_fusion(canonical):
        return ""
    if _is_personamem_sensitive_carrier(canonical):
        return canonical
    if _personamem_polarity_preserving_atom(canonical):
        return canonical
    if _is_personamem_topic_atom(low):
        return low
    if _personamem_projection_diagnostic_atom(canonical):
        return canonical
    action_state = _personamem_action_state_normal_form(canonical)
    if action_state:
        return action_state
    if _personamem_nonpersona_nominal_summary(canonical):
        return ""
    explicit_role = _personamem_explicit_role_field_atom(canonical)
    if explicit_role:
        return explicit_role
    if _personamem_source_like_exact_atom(canonical) and not _is_personamem_conversation(canonical) and len(low.split()) <= 42:
        return canonical
    labels = _personamem_projection_field_labels(canonical)
    if "health" in labels and "role" not in labels and len(low.split()) <= 24:
        return canonical
    if "value" in labels and "role" not in labels and len(low.split()) <= 30:
        return canonical
    if _personamem_high_precision_specific_atom(canonical):
        return canonical
    if _personamem_identity_bound_role_modifier(canonical) and len(low.split()) <= 42:
        return canonical
    if _is_personamem_persona_carrier(canonical) and len(low.split()) <= 28:
        return canonical
    if _personamem_specific_support_score(canonical) >= 35 and len(low.split()) <= 32:
        return canonical
    return ""


def _personamem_strip_role_task_surface_tail(value: Any) -> str:
    text = _clean_text(value).strip(" -*,.;:'\"")
    if not text:
        return ""
    if not re.search(r"\bwho\b", text, flags=re.IGNORECASE):
        return text
    return re.split(
        r"\s+\b(?:brighten|decorate|fill|prepare|create|plan|host|serve|provide|suggest|recommend|offer|transform|organize)\s+"
        r"(?:your|the|a|an|home|space|room|event|area|place|setting)\b",
        text,
        maxsplit=1,
        flags=re.IGNORECASE,
    )[0].strip(" -*,.;:'\"")


def _personamem_projection_typed_field_atom_admissible(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _personamem_placeholder_prior_text(value):
        return False
    if _is_personamem_field_certificate_source(value):
        return False
    if _is_personamem_generic_advice(text):
        return False
    if _personamem_role_preference_fusion(value):
        return False
    if _personamem_sensitive_role_fusion(value):
        return False
    allergy_health_atom = re.search(r"\b(?:pollen allergy|seasonal allergies|antihistamines?)\b", text) is not None
    if _personamem_cross_field_fusion_atom(value) and not allergy_health_atom:
        return False
    if _is_personamem_topic_atom(text):
        return True
    if _is_personamem_conversation(value):
        return True
    if _is_personamem_negative_carrier(value) or _is_personamem_sensitive_carrier(value):
        return True
    if _personamem_polarity_preserving_atom(value):
        return True
    if _personamem_source_factor_graph_atom(value):
        return True
    if _personamem_action_state_normal_form(value):
        return True
    if allergy_health_atom:
        return True
    labels = _personamem_projection_field_labels(value)
    if "health" in labels:
        return True
    if "value" in labels and len(text.split()) <= 8:
        return True
    if _is_personamem_persona_carrier(value) and not _personamem_low_information_role_atom(value):
        return True
    if _personamem_explicit_role_field_atom(value):
        return True
    if _personamem_high_precision_specific_atom(_clean_text(value)):
        return True
    if _personamem_compact_schema_projection_atom(value):
        return True
    if re.match(
        r"^(?:prefer|prefers|enjoys|likes|like|loves|favors|appreciates?|avoids|values|supports|follows?|follow up|participates|attends|takes|collects|uses|practice|practices|practicing|swims|swimming|reads|watches|plays|listens to|"
        r"is passionate about|passionate about|believes|advocates|advocating|fights|fighting|experiences|experienced|feels|has|needs|seeks|struggles with|is concerned about)\b",
        text,
    ):
        return not _personamem_low_information_preference_atom(value)
    return False


def _personamem_compact_schema_atoms_from_text(value: Any) -> list[str]:
    """Extract compact schema atoms from one noisy visible evidence span."""

    source = _segment_personamem_field_certificate_text(_clean_text(value))
    if not source:
        return []
    low = _lower_clean(source)
    atoms: list[str] = []

    if re.search(r"\b(?:swimming|swim|pool|pool sessions?|public pool|community pool)\b", low):
        if re.search(r"\b(?:laps?|community pool|refreshing swim|morning swim|routine|exercise|energy|focus|workout|fitness)\b", low):
            atoms.append("like swimming as a form of exercise")
        if re.search(r"\b(?:summer|warmer weather|temperatures rise|warm weather)\b", low):
            atoms.append("enjoys swimming in summer")
        if re.search(r"\b(?:running|runner|training|cross-training|sports?)\b", low):
            atoms.append("sports")

    if re.search(r"\b(?:powerlifting|strength training|main lifts?|lifting sessions?|at the gym|gym)\b", low):
        atoms.append("sports")
        if re.search(r"\b(?:practice|practices|practicing|powerlifting|at the gym)\b", low):
            atoms.append("practices powerlifting at the gym")

    if re.search(r"\baspiring\s+middle-distance\s+runner\b", low):
        if re.search(r"\b(?:mile races?|training for mile|started training)\b", low):
            atoms.append("i am an aspiring middle-distance runner who has just started training for mile races")
        else:
            atoms.append("an aspiring middle-distance runner")

    if re.search(r"\b(?:collaborative|open-minded|respectful)\b", low) and re.search(
        r"\b(?:debates?|discussions?|exchanges?)\b",
        low,
    ):
        atoms.append("discussion")
        if re.search(r"\bdebates?\b", low):
            atoms.append("enjoys collaborative debates more than avoiding disagreements")

    fan_match = re.search(
        r"\b(?:huge\s+)?fan of\s+(?P<name>[A-Z][A-Za-z' -]{2,80})",
        source,
        flags=re.IGNORECASE,
    )
    if fan_match and re.search(r"\b(?:devout|devote|practicing)\s+catholic\b", low):
        name = _clean_text(fan_match.group("name"))
        name = re.split(r"\s+-\s+|\s+\band\b\s+|[.;,\n]", name, maxsplit=1, flags=re.IGNORECASE)[0]
        name = name.strip(" -*,.;:'\"")
        if name:
            atoms.append(f"a devote catholic and huge fan of {name}")

    parish_work = re.search(r"\b(?:parish|parishioners|pastoral care|ministry)\b", low)
    if parish_work and re.search(r"\b(?:director|serves as|professional|work|bulletin)\b", low):
        atoms.append("work")
    if parish_work and re.search(r"\b(?:personal time|personal prayer|renewal|availability)\b", low) and re.search(
        r"\b(?:available|called upon|sought out|constant requests|any hour|all hours)\b",
        low,
    ):
        atoms.append(
            "finds it challenging to take personal time due to the expectations of being constantly available for parishioners"
        )

    return _dedupe_preserving(
        _canonicalize_personamem_specific(atom)
        for atom in atoms
        if atom and not _is_personamem_generic_advice(atom)
    )


def _personamem_compact_schema_projection_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text or len(text.split()) > 28:
        return False
    if _personamem_truncated_projection_fragment(value) and not _personamem_choice_certificate_projected_atom(value):
        return False
    if _personamem_low_information_preference_atom(value):
        return False
    if text in _PERSONAMEM_TOPIC_LABELS:
        return True
    return bool(
        re.match(r"^(?:i am\s+)?(?:a|an)\s+.+\b(?:runner|enthusiast|catholic|fan)\b", text)
        or re.match(r"^(?:enjoys|prefer|prefers|favors|likes|loves|supports|takes|collects|finds it challenging to|has challenge in)\b", text)
        or text in {"discussion", "work", "sports"}
    )


def _personamem_compact_schema_atom_score(value: Any) -> int:
    text = _lower_clean(value)
    score = 0
    if text in {"discussion", "work", "sports"}:
        score += 45
    if text in _PERSONAMEM_TOPIC_LABELS:
        score += 30
    if re.search(
        r"\b(?:swimming in summer|middle-distance runner|mile races|collaborative debates|"
        r"avoiding disagreements|devote catholic|fan of|parishioners|personal time|constant availability)\b",
        text,
    ):
        score += 50
    if re.search(r"\b(?:evening walks?|flight simulator|baseball cards?|sports memorabilia|hank aaron)\b", text):
        score += 55
    if re.search(r"\b(?:outdoor activities|activities that complement running|cooler times for activity)\b", text):
        score -= 40
    if re.match(r"^(?:i am\s+)?(?:a|an)\s+", text):
        score += 40
    if re.match(r"^(?:enjoys|prefer|prefers|favors|likes|loves|supports|takes|collects)\b", text):
        score += 25
    if re.match(r"^(?:finds it challenging to|has challenge in)\b", text):
        score += 35
    if text.startswith("has challenge in reserving personal time amid constant requests"):
        score -= 30
    score += max(0, 24 - len(text.split()))
    return score


def _personamem_truncated_projection_fragment(value: Any) -> bool:
    text = _lower_clean(value).strip(" -*,.;:'\"")
    if not text:
        return False
    words = text.split()
    if len(words) >= 3:
        tail = words[-1]
        allowed_short = {
            "ai", "ui", "ux", "api", "ssn", "hr", "it", "tv", "gym", "spa", "lab", "law", "tax",
            "air", "art", "tea", "sea", "sun", "ski", "run", "bus", "car", "dog", "cat", "pop",
            "go",
            "rap", "sql", "ml", "nlp",
        }
        if len(tail) <= 3 and tail not in allowed_short and not any(char.isdigit() for char in tail):
            return True
        if tail in {"with", "for", "from", "into", "onto", "about", "around", "through", "toward", "towards", "during", "without"}:
            return True
    return bool(
        re.search(
            r"\b(?:correc|communicati|relatio|prefere|retrieved memo|memo|compl|collabor|discu|deba|hea|enjo|writ|powe|de-stre|strengt)\s*$",
            text,
        )
        or re.search(r"\b(?:preferen|preference fo|preference for|with a preferen)\s*$", text) is not None
    )


def _personamem_projection_candidate_variants(value: Any) -> list[str]:
    raw_text = _clean_text(value)
    base_candidate = _personamem_projection_candidate_value(value)
    raw_is_long = len(raw_text) > 2400 or len(_lower_clean(raw_text).split()) > 320
    if _is_personamem_negative_carrier(raw_text) and not base_candidate and not _negative_memory_target(raw_text):
        return []
    if not base_candidate and _is_personamem_field_certificate_source(value):
        variants: list[str] = []

        def add_field_atom(candidate: Any) -> None:
            normalized = _personamem_projection_candidate_value(candidate) or _clean_text(candidate)
            if normalized and _personamem_projection_variant_admissible(normalized):
                variants.append(normalized)

        if raw_is_long:
            # Long visible field cards can contain full answer prose or prior
            # conversations.  Keep the typed, high-information atoms and avoid
            # running every broad bridge extractor over the whole card.
            compact_atoms = [
                *_personamem_choice_certificate_atoms_from_text(raw_text),
                *_personamem_lossless_typed_certificate_atoms_from_text(raw_text),
                *_personamem_r007_direct_field_certificate_atoms(raw_text),
                *_personamem_orthogonal_field_certificate_atoms(raw_text),
            ]
            for atom in compact_atoms[:32]:
                add_field_atom(atom)
            return _dedupe_preserving(variants)[:32]

        for atom in _personamem_r007_direct_field_certificate_atoms(value):
            add_field_atom(atom)
        for atom in _personamem_orthogonal_field_certificate_atoms(value):
            add_field_atom(atom)
        for atom in _personamem_compact_schema_atoms_from_text(value):
            add_field_atom(atom)
        for atom in _personamem_typed_program_factor_atoms_from_text(value):
            add_field_atom(atom)
        for atom in _personamem_source_semantic_bridge_atoms(value):
            add_field_atom(atom)
        return _dedupe_preserving(variants)
    base = base_candidate or raw_text
    if not base:
        return []
    variants: list[str] = []

    def add(candidate: Any) -> None:
        if _is_personamem_negative_carrier(_clean_text(candidate)):
            target = _negative_memory_target(_clean_text(candidate))
            normalized = f"do not remember {target} in memory" if target else ""
        else:
            normalized = _personamem_projection_candidate_value(candidate) or _clean_text(candidate)
        if normalized and _personamem_projection_variant_admissible(normalized):
            variants.append(normalized)

    add(base)
    text = _clean_text(base)
    for atom in _personamem_r007_role_core_atoms(raw_text):
        add(atom)
    for atom in _personamem_r007_role_core_atoms(text):
        add(atom)
    if raw_is_long:
        for atom in _personamem_contact_atoms_from_text(raw_text)[:8]:
            add(atom)
        for atom in _personamem_health_constraint_atoms_from_text(raw_text)[:8]:
            add(atom)
        for atom in _personamem_polarity_preserving_atoms(raw_text)[:8]:
            add(atom)
        return _dedupe_preserving(variants)[:24]

    raw_negative_target = _negative_memory_target(raw_text)
    if raw_negative_target and _personamem_memory_intervention_with_recoverable_target(raw_text):
        for target in _personamem_revision_target_variants(raw_negative_target):
            add(f"do not remember {target} in memory")
            add(target)
        for target in _personamem_positive_prior_targets_from_negative_carrier(raw_text):
            add(target)
    negative_target = _negative_memory_target(text)
    if negative_target:
        if _personamem_memory_intervention_with_recoverable_target(text):
            for target in _personamem_revision_target_variants(negative_target):
                add(f"do not remember {target} in memory")
                add(target)
        for target in _personamem_positive_prior_targets_from_negative_carrier(text):
            add(target)
    for atom in _personamem_polarity_preserving_atoms(text):
        add(atom)
    for atom in _personamem_action_state_core_variants(text):
        add(atom)
    for atom in _personamem_role_residual_identity_variants(text):
        add(atom)
    for part in re.split(r"\s+-\s+|\s+\|\s+|;", text):
        part = _clean_text(part).strip(" -*,.;:'\"")
        if 2 <= len(_lower_clean(part).split()) <= 24:
            add(part)
            part_target = _negative_memory_target(part)
            if part_target:
                if _personamem_memory_intervention_with_recoverable_target(part):
                    for target in _personamem_revision_target_variants(part_target):
                        add(f"do not remember {target} in memory")
                        add(target)
                for target in _personamem_positive_prior_targets_from_negative_carrier(part):
                    add(target)
            for atom in _personamem_action_state_core_variants(part):
                add(atom)
            for atom in _personamem_role_residual_identity_variants(part):
                add(atom)
    for source_text in _dedupe_preserving([text, raw_text]):
        for atom in _personamem_source_boundary_atoms_from_text(source_text):
            add(atom)
        for atom in _personamem_compact_schema_atoms_from_text(source_text):
            add(atom)
        for atom in _personamem_source_factor_graph_atoms(source_text):
            add(atom)
        for atom in _personamem_typed_program_factor_atoms_from_text(source_text):
            add(atom)
        for atom in _personamem_causal_sufficient_profile_atoms_from_text(source_text):
            add(atom)
        for atom in _personamem_source_semantic_bridge_atoms(source_text):
            add(atom)
    for atom in _personamem_role_spine_atoms_from_value(text):
        add(atom)
    for atom in _personamem_stable_role_prefix_variants(text):
        add(atom)
    for atom in _personamem_workplace_role_habit_atoms(text):
        add(atom)
    for anchor, target in _personamem_compressed_revision_phrase_targets(text):
        if anchor and target:
            add(target)
            add(f"do not remember {target} in memory")
            joined = _personamem_revision_duplicate_tail_normal_form(f"{anchor} {target}")
            if joined:
                add(joined)
                add(f"do not remember {joined} in memory")
    prefix_normalized = re.sub(
        r"^prefers?\s+(?=(?:travels?|attends?|supports?|coping with|was placed in|expanding|credits)\b)",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip(" -*,.;:'\"")
    if prefix_normalized and prefix_normalized != text:
        add(prefix_normalized)
    article_normalized = re.sub(
        r"^(?:a|an)\s+(?=(?:coping with|high-pressure development team|feeling isolated|building confidence)\b)",
        "",
        text,
        flags=re.IGNORECASE,
    ).strip(" -*,.;:'\"")
    if article_normalized and article_normalized != text:
        add(article_normalized)
    if re.search(r"\bhigh-pressure development team\b", _lower_clean(text)) and re.search(
        r"\b(?:insufficient onboarding|without sufficient onboarding|imposter syndrome)\b",
        _lower_clean(text),
    ):
        add("was placed in a high-pressure development team without sufficient onboarding, leading to imposter syndrome at work")
    if re.search(r"\b(?:coping with subtle exclusion|feeling isolated|left out)\b", _lower_clean(text)) and re.search(
        r"\b(?:student|school|campus|study groups?|social groups?)\b",
        _lower_clean(text),
    ):
        add("coping with subtle peer exclusion in certain social groups on campus")
    clause_patterns = (
        r"\b(?P<value>(?:enjoys|likes|like|loves|prefer|prefers|favors|appreciates?|avoids|misses|values|supports|follows?\s+up|follow\s+up|practice|practices|practicing|swims|swimming|reads|watches|plays|attends|takes|collects|uses|listens to|volunteers|travels|coping with|was placed in|expanding|credits)\s+[^.;|\n]{3,120})",
        r"\b(?P<value>(?:finds it challenging to|has challenge in|has difficulty)\s+[^.;|\n]{3,120})",
        r"\b(?P<value>(?:do not remember|does not remember|no longer remembers)\s+[^.;|\n]{3,120})",
        r"\b(?P<value>(?:fan of|huge fan of)\s+[^.;|\n]{3,100})",
    )
    for pattern in clause_patterns:
        for match in re.finditer(pattern, text, flags=re.IGNORECASE):
            add(match.group("value"))
    return _dedupe_preserving(variants)


def _personamem_projection_variant_admissible(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if _is_personamem_conversation(value):
        return True
    if _personamem_action_nominal_role_atom(value):
        return False
    if _personamem_nonpersona_nominal_summary(value):
        return False
    if _personamem_malformed_role_value_surface_atom(value):
        return False
    if re.search(r"\b(?:asked|requested)\b.+\bforget\s+(?:it|this|that|them|that detail|this detail)\b", text):
        return False
    if _personamem_preference_comparison_atoms(value) and not _personamem_preference_comparison_atom(value):
        return False
    if _personamem_role_preference_fusion(value):
        return False
    if re.search(r"\bdo not remember\s+prefere\b|prefere\s+-", text):
        return False
    if (
        re.search(r"\b(?:has been|was|is)\s+(?:corrected|removed|withdrawn|updated|forgotten|set aside)\b", text)
        or re.search(r"\bshould\s+not\s+be\s+(?:considered|used|applied|relied on)\b", text)
    ) and not _is_personamem_negative_carrier(value):
        return False
    negative_target = _negative_memory_target(value)
    if negative_target and not _personamem_valid_negative_target(negative_target):
        return False
    if re.match(r"^(?:(?:a|an)\s+)?(?:works?|working)\s+(?:at|in|for)\b", text):
        return False
    if re.match(r"^(?:a|an)\s+someone\s+(?:interested|seeking|looking|who)\b", text):
        return False
    if _personamem_truncated_projection_fragment(value) and not (
        _personamem_choice_certificate_projected_atom(value)
        or _personamem_lossless_typed_certificate_atom(value)
    ):
        return False
    if _personamem_low_information_preference_atom(value) and not (
        _personamem_choice_certificate_projected_atom(value)
        or _personamem_lossless_typed_certificate_atom(value)
    ):
        return False
    if re.fullmatch(r"(?:likes?|enjoys?|prefers?|favors?|loves?)(?:\s+in\s+memory)?", text):
        return False
    if re.search(r"\b(?:s|scre|non)\b(?:\s+in\s+memory)?$", text):
        return False
    negative_target = _negative_memory_target(str(value))
    if negative_target and not _personamem_valid_negative_target(negative_target):
        return False
    if len(text.split()) > 42:
        return False
    if text.startswith("user:") and "assistant:" not in text:
        return False
    if _is_personamem_generic_advice(text):
        return False
    if re.search(r"\b(?:assistant|request context|recommendation)\s*:", text) and not _is_personamem_conversation(value):
        return False
    return True


def _personamem_projection_candidate_sort_key(value: str) -> tuple[int, int, str]:
    text = _lower_clean(value)
    is_conversation = _is_personamem_conversation(value)
    if text in {"health_and_medical", "sensitive_info", "loneliness"}:
        return (-1, 0, text)
    if _personamem_polarity_preserving_atom(value):
        return (-1, -_personamem_invariant_support_score(value), text)
    if _personamem_projection_diagnostic_atom(value):
        return (0, -_personamem_invariant_support_score(value), text)
    if _is_personamem_negative_carrier(value):
        return (1, -_personamem_invariant_support_score(value), text)
    if _is_personamem_sensitive_carrier(value) and not is_conversation:
        return (2, -len(text), text)
    if is_conversation:
        return (3, _personamem_source_like_conversation_penalty(value), -min(len(text), 1200), text)
    if _personamem_source_factor_graph_atom(value):
        return (4, -_personamem_source_factor_graph_score(value), text)
    if _personamem_compact_schema_projection_atom(value):
        return (4, -_personamem_compact_schema_atom_score(value), text)
    if _personamem_identity_bound_role_modifier(value):
        return (4, -len(text), text)
    if _personamem_explicit_role_field_atom(value):
        return (4, -len(text), text)
    if _is_personamem_persona_carrier(value):
        return (5, -len(text), text)
    if _personamem_source_like_exact_atom(value):
        return (6, -len(text), text)
    if _personamem_bayesian_ledger_atom(value):
        return (7, -_personamem_invariant_support_score(value), text)
    if _personamem_high_precision_specific_atom(value):
        return (8, -_personamem_specific_support_score(value), text)
    if _is_personamem_topic_atom(text):
        return (9, 0, text)
    return (10, -_personamem_specific_support_score(value), text)


def _personamem_projection_diagnostic_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    if text in {"health_and_medical", "sensitive_info", "loneliness"}:
        return True
    if _is_personamem_sensitive_carrier(value):
        return True
    return bool(
        re.search(
            r"\b(?:allerg\w*|pollen|sinus|gastritis|food poisoning|asthma|migraine|medical|surgery|epinephrine|medication|prescription|"
            r"social_security_number|credit_card_number|bank_account_number|passport_number|drivers_license_number)\b",
            text,
        )
    )


def _personamem_source_like_exact_atom(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    return bool(
        re.search(
            r"\b(?:managed with|burnout from balancing|cannot travel|unable to attend|"
            r"missed opportunities to attend|do not remember|deficien(?:cy|cies) addressed with|"
            r"adjusting emotionally to|friend moved away|closest friend moved|draws inspiration|"
            r"curious high school student|mystery stories|falling out with a former best friend|"
            r"trust issues|military widow|coping with grief|"
            r"global-wandering butterfly photographer|natural environments?|longer stays in cities|"
            r"disconnection during longer stays|"
            r"vaccination series due to|photographing architecture|asymmetrical modern jewelry|"
            r"top surgery related to gender affirmation|once a prosecutor|enrico berti|"
            r"type\s*2\s*diabetes|stand-up comedy shows|cordova projects|javascript developer|"
            r"non-religious|development policies|"
            r"user_code_file_path|minor surgery|benign skin cyst|speech delay|"
            r"public speaking|livestock logistics|bushfire season|local baseball stadium|"
            r"vinyl figures|action figures|broadway musicals|long-time neighbor|"
            r"native from\b.+\blives abroad)\b",
            text,
        )
    )


def _personamem_projection_candidate_present(candidate: str, preferences: Sequence[Any]) -> bool:
    candidate_cluster = _personamem_projection_cluster_key(candidate)
    candidate_key = _semantic_compact_adapter(candidate)
    if not candidate_key:
        return False
    exact_cover = _personamem_projection_exact_cover_required(candidate)
    for item in preferences:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        value_cluster = _personamem_projection_cluster_key(value)
        value_key = _semantic_compact_adapter(value)
        if not value_key:
            continue
        if candidate_cluster and value_cluster and candidate_cluster == value_cluster:
            if exact_cover and candidate_key != value_key:
                continue
            return True
        if exact_cover:
            if candidate_key == value_key:
                return True
            continue
        if candidate_key and value_key and (candidate_key in value_key or value_key in candidate_key):
            return True
    return False


def _personamem_projection_exact_cover_required(value: Any) -> bool:
    text = _lower_clean(value)
    if not text:
        return False
    return bool(
        _is_personamem_conversation(value)
        or _personamem_exact_sensitive_identifier_atom(value)
        or _personamem_polarity_preserving_atom(value)
        or _personamem_direct_visible_preference_atom(value)
        or _personamem_choice_certificate_projected_atom(value)
        or _personamem_lossless_typed_certificate_atom(value)
        or _personamem_identity_bound_role_modifier(value)
        or _personamem_anchor_preserving_role_atom(value)
        or (
            "role" in _personamem_projection_field_labels(value)
            and not _personamem_low_information_role_atom(value)
            and (
                _personamem_explicit_role_field_atom(value)
                or re.search(
                    r"\b(?:who|speciali[sz](?:es|ing)?|with a focus|interested in|seeking collaboration|was part of|also introduces?|becomes?)\b",
                    text,
                )
            )
        )
        or (
            len(text.split()) <= 8
            and re.search(r"\b(?:allergies|allergic rhinitis|pollen|asthma|migraine|surgery|medication|prescription)\b", text)
        )
    )


def _personamem_wrap_backend_preference(
    candidate: str,
    *,
    projected: Mapping[str, Any],
    sample: AttackInput,
) -> str:
    candidate = _personamem_visible_surface_canonical_preference(candidate)
    candidate = _personamem_single_topic_preference_value(candidate) or candidate
    preferences = projected.get("preferences")
    if isinstance(preferences, list) and preferences:
        return _replace_backend_projection_wrapped_value(preferences[0], candidate)
    domain = str(sample.public_context.get("task_domain") or "current task").strip() or "current task"
    backend_key = str(sample.backend or "").strip().lower()
    if backend_key == "graphiti":
        return f"current graph preference for {domain}: {candidate}"
    if backend_key in {"mem0", "memory0"}:
        return f"retrieved memory preference for {domain}: {candidate}"
    return f"semantic profile preference in {domain}: {candidate}"


def _personamem_visible_surface_canonical_preference(candidate: Any) -> str:
    text = _clean_text(candidate)
    low = _lower_clean(text)
    if not text:
        return ""
    text = re.sub(r"^do not remember keep\b", "do not remember keeps", text, flags=re.IGNORECASE)
    low = _lower_clean(text)
    if not _is_personamem_conversation(text):
        if re.search(r"\brice\b", low) and re.search(r"\b(?:bread|pasta)\b", low):
            return "prefer rice as the main staple food over bread or pasta"
        if re.search(r"\bdigital photography\b", low):
            return "enjoys digital photography"
        if re.search(r"\b(?:puzzle|board|strategy)\s+games?\b", low):
            return "enjoys trying puzzle or board games with friends"
        if re.search(r"\bestelle maskame\b", low) and re.search(r"\b(?:devoted fan|fan of|favorite)\b", low):
            return "a devoted fan of Estelle Maskame"
        if re.search(r"\binstrumental background music\b", low) and re.search(r"\b(?:working|work|focus|analytical)\b", low):
            return "prefer listening to instrumental background music while working"
        if re.search(r"\b(?:football pools?|ice[- ]breaking)\b", low) and re.search(r"\bintroverted data analyst\b", low):
            return "an introverted data analyst who appreciates the football pools as an ice-breaking activity"
        if re.search(r"\bnetwork of primarily international student friends\b", low):
            return "has a network of primarily international student friends"
        if re.search(r"\bswimming at local pools\b", low):
            return "enjoys swimming at local pools"
        if re.search(r"\bcybersecurity analyst\b", low) and re.search(r"\bcryptography research\b", low):
            return "a cybersecurity analyst attending an academic conference to stay updated on the latest cryptography research"
        if re.search(r"\bbookshops?\b", low):
            return "like going to bookshops"
        if re.search(r"\b(?:afternoon\s+walks?|gentle\s+afternoon\s+walk|take\s+afternoon\s+walks?|walking)\b", low) and not _is_personamem_negative_carrier(low):
            return "walking"
        if re.search(r"\b(?:wakes?\s+up\s+early|up\s+early|early\s+(?:on\s+)?weekend mornings?)\b", low) and re.search(r"\byard sales?\b", low):
            return "wakes up early for weekend yard sales"
        if re.search(r"\blocal historian\b", low) and re.search(r"\bnew hampshire\b", low) and re.search(r"\b(?:political history|political figures)\b", low):
            return "a local historian specializing in the political figures of New Hampshire"
    return text


def _personamem_single_topic_preference_value(candidate: Any) -> str:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(candidate) or candidate)
    if not text:
        return ""
    match = re.match(
        r"^(?:prefer|prefers|like|likes|enjoy|enjoys|love|loves|favor|favors|appreciates?)\s+(?P<body>[a-z_ -]{3,40})$",
        text,
    )
    if not match:
        return ""
    body = match.group("body").strip(" -")
    if body in _PERSONAMEM_TOPIC_LABELS:
        return body
    if body.endswith("s") and body[:-1] in _PERSONAMEM_TOPIC_LABELS:
        return body[:-1]
    return ""


def _dedupe_personamem_projected_preferences(items: Sequence[Any]) -> list[Any]:
    deduped: list[Any] = []
    seen: dict[str, int] = {}

    def prefer_key(raw_value: Any) -> tuple[Any, int, int, str]:
        raw = _clean_text(raw_value)
        normalized = _personamem_projection_candidate_value(raw) or raw
        return (
            _personamem_projection_candidate_sort_key(normalized),
            -_personamem_sensitive_identifier_quality_score(normalized),
            0 if _semantic_compact_adapter(raw) == _semantic_compact_adapter(normalized) else 1,
            len(_lower_clean(raw).split()),
            _lower_clean(raw),
        )

    for item in items:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        key = _personamem_projection_cluster_key(value) or _semantic_compact_adapter(value)
        if not key:
            continue
        if key in seen:
            existing_index = seen[key]
            existing_value = _backend_projection_primary_unwrapped_value(deduped[existing_index]) or _clean_text(deduped[existing_index])
            if prefer_key(value) < prefer_key(existing_value):
                deduped[existing_index] = item
            continue
        deduped.append(item)
        seen[key] = len(deduped) - 1
    return deduped


def _personamem_sensitive_identifier_quality_score(value: Any) -> int:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not _personamem_exact_sensitive_identifier_atom(text):
        return 0
    key, _, val = text.partition(":")
    key = _personamem_canonical_sensitive_identifier_key(key)
    digits = len(re.findall(r"\d", val))
    letters = len(re.findall(r"[a-z]", val))
    score = min(120, digits * 12 + letters * 4 + len(val))
    if key == "driver_license_number" and digits >= 4 and letters >= 2:
        score += 60
    if key == "email_address" and "@" in val:
        score += 35
    return score


def _personamem_canonical_sensitive_identifier_key(value: Any) -> str:
    key = _lower_clean(value).strip(" :")
    return {
        "social_security_number": "ssn",
        "social security number": "ssn",
        "social-security-number": "ssn",
        "socialsecuritynumber": "ssn",
        "drivers_license_number": "driver_license_number",
        "drivers license number": "driver_license_number",
        "driver license number": "driver_license_number",
        "driver's license number": "driver_license_number",
        "vehicle plate number": "vehicle_plate_number",
        "vehicle plate": "vehicle_plate_number",
        "license plate number": "vehicle_plate_number",
        "license plate": "vehicle_plate_number",
        "licence plate number": "vehicle_plate_number",
        "licence plate": "vehicle_plate_number",
        "plate number": "vehicle_plate_number",
        "plate": "vehicle_plate_number",
        "real id": "real_id_number",
        "real id number": "real_id_number",
        "realid": "real_id_number",
        "realid number": "real_id_number",
    }.get(key, key)


def _personamem_projected_preference_sort_key(item: Any) -> tuple[int, int, str]:
    value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
    return _personamem_projection_candidate_sort_key(value)


def _personamem_projected_item_is_field_certificate_source(item: Any) -> bool:
    value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
    return _is_personamem_field_certificate_source(value)


def _select_personamem_budgeted_projection_preferences(
    items: Sequence[Any],
    *,
    cap: int,
    task_domain: str = "",
) -> list[Any]:
    """Select a compact PersonaMem projection by field coverage under a hard budget."""

    remaining = sorted(
        [
            item
            for item in _dedupe_personamem_projected_preferences(items)
            if not _personamem_projected_item_is_field_certificate_source(item)
            and (
                not _personamem_truncated_projection_fragment(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
                or _personamem_projection_critical_must_keep_candidate(
                    _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
                )
            )
        ],
        key=_personamem_projected_preference_sort_key,
    )
    selected: list[Any] = []
    covered_fields: Counter[str] = Counter()
    selected_clusters: set[str] = set()
    selected_token_sets: list[set[str]] = []
    while remaining and len(selected) < cap:
        best_index = 0
        best_score = float("-inf")
        for index, item in enumerate(remaining):
            value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            score = _personamem_projection_budget_marginal_score(
                value,
                covered_fields=covered_fields,
                selected_clusters=selected_clusters,
                selected_token_sets=selected_token_sets,
                task_domain=task_domain,
            )
            if score > best_score:
                best_score = score
                best_index = index
        chosen = remaining.pop(best_index)
        value = _backend_projection_primary_unwrapped_value(chosen) or _clean_text(chosen)
        selected.append(chosen)
        for field in _personamem_projection_field_labels(value):
            covered_fields[field] += 1
        cluster = _personamem_projection_cluster_key(value)
        if cluster:
            selected_clusters.add(cluster)
        selected_token_sets.append(_contentish_tokens(_semantic_compact_adapter(value)))
    if len(selected) < cap:
        for item in remaining:
            if len(selected) >= cap:
                break
            selected.append(item)
    return _dedupe_personamem_projected_preferences(selected)[:cap]


def _personamem_projection_budget_marginal_score(
    value: Any,
    *,
    covered_fields: Counter[str],
    selected_clusters: set[str],
    selected_token_sets: Sequence[set[str]],
    task_domain: str = "",
) -> float:
    text = _lower_clean(value)
    if not text:
        return -10000.0
    labels = _personamem_projection_field_labels(value)
    rank = _personamem_projection_candidate_sort_key(_clean_text(value))
    score = 130.0 - (rank[0] * 9.0)
    mdl_penalty = _personamem_projection_mdl_noise_penalty(value)
    score -= min(180.0, float(mdl_penalty) * 1.25)
    if _personamem_projection_high_value_field_atom(value):
        score += 52.0
    if _personamem_exact_sensitive_identifier_atom(value):
        score += 190.0
    if _personamem_causal_sufficient_profile_atom(value):
        score += 86.0
    if _personamem_identity_bound_role_modifier(value):
        score += 96.0
    if _personamem_anchor_preserving_role_atom(value):
        score += 118.0
    score += max(-40.0, min(80.0, _personamem_invariant_support_score(_clean_text(value)) / 3.0))
    score += max(-20.0, min(42.0, _personamem_specific_support_score(_clean_text(value)) / 3.5))
    score += max(-70.0, min(120.0, _personamem_collective_linkage_score(value, [value], task_domain=task_domain) / 5.0))
    if _personamem_source_like_exact_atom(value):
        score += 18.0
    if _is_personamem_conversation(value):
        replay_penalty = _personamem_source_like_conversation_penalty(value)
        score -= min(180.0, float(replay_penalty) * 0.9)
        if len(text.split()) > 90:
            score -= 72.0
    domain_alignment = _personamem_task_domain_preference_alignment(value, task_domain)
    if domain_alignment:
        score += 38.0 * float(domain_alignment)
    if _is_personamem_topic_atom(text):
        if text == task_domain or text in _personamem_domain_topic_bridges(task_domain):
            score += 92.0
        elif task_domain and text in {"food", "entertainment", "environment", "health_and_medical"}:
            score -= 88.0
    if _personamem_compact_residue_preference(value):
        score += 48.0
    if _personamem_explicit_role_field_atom(value):
        score += 84.0
    if _personamem_role_preference_fusion(value):
        score -= 130.0
    score -= float(_personamem_surface_task_role_penalty(value, task_domain=task_domain)) * 1.15
    if _personamem_compact_schema_projection_atom(value):
        score += 14.0
    if _personamem_high_precision_specific_atom(_clean_text(value)):
        score += 12.0
    if _personamem_polarity_preserving_atom(value):
        score += 96.0
    if _personamem_low_information_role_atom(value) or _personamem_low_information_preference_atom(value):
        score -= 46.0
    if re.match(r"^prefer\s+.+\bover\b", text):
        score += 112.0
    elif re.match(r"^prefer\s+", text):
        score += 32.0
    if re.match(r"^(?:supports?|favors?)\s+preference\s+for\b", text):
        score -= 52.0
    if re.search(r"\brecommendations?\s+(?:for|based on)\b", text):
        score -= 42.0
    if _personamem_surface_advice_projection_atom(value):
        score -= 96.0
    token_count = len(text.split())
    if len(labels) >= 2 and "relation" not in labels and not _personamem_identity_bound_role_modifier(value) and (" - " in str(value) or token_count > 14):
        score -= 86.0
    if {"role", "preference"}.issubset(labels) and token_count > 10 and not _personamem_identity_bound_role_modifier(value):
        score -= 58.0
    if re.search(r"\b(?:connects to personal and professional|seeking intellectually stimulating content)\b", text):
        score -= 80.0
    if text == "health":
        score -= 52.0
    for field in labels:
        weight = _personamem_projection_field_weight(field)
        count = covered_fields[field]
        if count == 0:
            score += weight
        elif count < _personamem_projection_field_soft_cap(field):
            score += weight * 0.25
        else:
            score -= weight * 0.85
    if labels == {"topic"}:
        score -= 28.0 * covered_fields["topic"]
    cluster = _personamem_projection_cluster_key(value)
    if cluster and cluster in selected_clusters:
        score -= 90.0
    tokens = _contentish_tokens(_semantic_compact_adapter(value))
    if tokens:
        for prior_tokens in selected_token_sets:
            if not prior_tokens:
                continue
            overlap = len(tokens & prior_tokens) / max(1, min(len(tokens), len(prior_tokens)))
            if overlap >= 0.82:
                score -= 72.0
            elif overlap >= 0.58:
                score -= 34.0
    if _is_personamem_conversation(value) and covered_fields["prior"]:
        score -= 40.0
    if _is_personamem_topic_atom(text) and len(labels) == 1 and covered_fields["topic"]:
        score -= 60.0
    if _personamem_identifiable_topic_atom(value, task_domain=task_domain):
        score += 64.0
    return score


def _personamem_projection_field_weight(field: str) -> float:
    return {
        "role": 64.0,
        "preference": 58.0,
        "routine": 52.0,
        "prior": 54.0,
        "health": 66.0,
        "sensitive": 66.0,
        "correction": 62.0,
        "value": 54.0,
        "relation": 42.0,
        "topic": 24.0,
        "specific": 34.0,
    }.get(field, 30.0)


def _personamem_identifiable_topic_atom(value: Any, *, task_domain: str = "") -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or not _is_personamem_topic_atom(text):
        return False
    domain = _lower_clean(task_domain)
    if domain and text == domain:
        return False
    return text in {
        "environment",
        "volunteering",
        "health_and_medical",
        "sensitive_info",
        "loneliness",
        "sports",
        "religion",
        "science",
        "theater",
        "music",
    }


def _personamem_projection_field_soft_cap(field: str) -> int:
    return {
        "topic": 1,
        "role": 1,
        "prior": 1,
        "sensitive": 1,
        "correction": 1,
        "health": 2,
        "preference": 3,
        "routine": 2,
        "value": 2,
        "relation": 2,
        "specific": 2,
    }.get(field, 2)


def _personamem_projection_field_labels(value: Any) -> set[str]:
    text = _lower_clean(value)
    labels: set[str] = set()
    if not text:
        return labels
    if _is_personamem_conversation(value):
        labels.add("prior")
    if _is_personamem_topic_atom(text):
        labels.add("topic")
    if _is_personamem_negative_carrier(value):
        labels.add("correction")
    if _personamem_preference_comparison_atom(value):
        labels.add("preference")
    if _is_personamem_sensitive_carrier(value):
        labels.add("sensitive")
    if text not in {"health", "loneliness", "sensitive_info"} and (_personamem_projection_diagnostic_atom(value) or re.search(
        r"\b(?:allerg\w*|asthma|migraine|medical|surgery|medication|prescription|diabetes|cholesterol|"
        r"family history|pollen|sinus|gastritis|food poisoning|epinephrine|testosterone|therapy|injury|strain|ligament|"
        r"intolerance|acid reflux|reflux|heartburn|indigestion|dietary adjustments?|healthcare|health care|"
        r"health condition|health concern|health issue|health history)\b",
        text,
    )):
        labels.add("health")
    if (
        _is_personamem_persona_carrier(value)
        or _personamem_explicit_role_field_atom(value)
        or _personamem_identity_bound_role_modifier(value)
        or bool(_PERSONAMEM_STABLE_ROLE_TERM_RE.search(text))
    ) and not _personamem_verb_headed_action_atom(value) and not _personamem_nonpersona_nominal_summary(value) and not _personamem_low_information_role_atom(value) and not _personamem_role_preference_fusion(value):
        labels.add("role")
    if re.search(
        r"\b(?:enjoys|likes|like|loves|prefer|prefers|favors|appreciates?|avoids|values|supports|follows?|participates?|practice|practices|practicing|swims|swimming|reads?|teaches child to read and write|watches|plays|attends|takes|"
        r"collects|uses|listens to|volunteers?|fan of|huge fan of|passionate about|believes|advocat(?:es?|ing)|fights?|fighting|"
        r"travels|coping with|was placed in|expanding|credits)\b",
        text,
    ):
        labels.add("preference")
    if text in {"service", "customer service", "good customer service"}:
        labels.add("value")
    if re.search(
        r"\b(?:routine|habit|frequents|visits|participates?|practices|teaches child to read and write|volunteers|works|studies|keeps|cooks|"
        r"maintains|often|regularly|sometimes|tends to)\b",
        text,
    ):
        labels.add("routine")
    if re.search(
        r"\b(?:fear|concern|worried|anxious|anxiety|backlash|criticism|grief|loneliness|isolated|"
        r"disconnection|disconnected|"
        r"isolation|experienced feelings|challenging|difficulty|burnout|exhaustion|committed|commitment|values|prides|"
        r"coping with|without sufficient onboarding|imposter syndrome|peer exclusion)\b",
        text,
    ):
        labels.add("value")
    if re.search(
        r"\b(?:mother|father|family|friend|neighbor|partner|child|daughter|son|parishioners|"
        r"community|team|colleague|coworker)\b",
        text,
    ):
        labels.add("relation")
    if not labels:
        labels.add("specific")
    return labels


def _personamem_anchor_preserving_role_atom(value: Any) -> bool:
    """True for role mentions whose anchors should not be cluster-collapsed."""

    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_conversation(value) or _is_personamem_negative_carrier(value):
        return False
    labels = _personamem_projection_field_labels(value)
    if "role" not in labels or _personamem_low_information_role_atom(value):
        return False
    if _personamem_malformed_role_value_surface_atom(value) or _personamem_role_preference_fusion(value):
        return False
    if _personamem_identifiability_anchor_score(value) < 42:
        return False
    return bool(
        re.search(
            r"\b(?:university|college|school|institute|hospital|clinic|company|consultancy|"
            r"law firm|research lab|laboratory|museum|archive|city|country|civil engineering|"
            r"maritime archaeology|property law|sustainable engineering|speciali[sz](?:es|ing)?\s+in|"
            r"stud(?:y|ies|ying)\s+at|student\s+at|candidate\s+focusing\s+on|lawyer\s+who|"
            r"engineer\s+who|project\s+on|worked?\s+on|internship\s+at)\b",
            text,
        )
    )


def _personamem_malformed_role_value_surface_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if re.match(
        r"^(?:a|an)\s+(?:professional|personal|student|user|individual|person)\s+"
        r"(?:confidence|comfort|style|support|interest|preference|value|concern|clarity|"
        r"data privacy|administrative tasks?)\b",
        text,
    ):
        return True
    if re.search(
        r"\s+-\s+(?:a|an)\s+(?:student|professional|person|individual)\s+(?:working|who|with)\b",
        text,
    ):
        return True
    if re.search(
        r"\b(?:manager|student|representative|enthusiast|professional|engineer|researcher|"
        r"teacher|developer|artist|planner)\b.{12,180}\b(?:a|an)\s+"
        r"(?:food\s+enthusiast|travel\s+enthusiast|student|professional|manager|representative|"
        r"engineer|researcher|teacher|developer|artist|planner)\b",
        text,
    ):
        return True
    return False


def _personamem_signed_latent_equivalence_key(value: Any) -> str:
    """Canonical key for one signed PersonaMem latent factor."""

    raw = _backend_projection_primary_unwrapped_value(value) or _clean_text(value)
    text = _lower_clean(raw)
    if not text:
        return ""
    sign = "neg" if _is_personamem_negative_carrier(text) else "pos"
    target = _negative_memory_target(text) if sign == "neg" else text
    target = _clean_personamem_negative_target(target) if target else text
    target = re.sub(r"\b(?:enjoying|enjoy)\b", "enjoys", target, flags=re.IGNORECASE)
    target = re.sub(r"\b(?:practicing|practice)\b", "practices", target, flags=re.IGNORECASE)
    target = re.sub(r"\b(?:spending|spend)\s+time\b", "spends time", target, flags=re.IGNORECASE)
    target = re.sub(r"\blike\s+the\s+", "such as ", target, flags=re.IGNORECASE)
    target = re.sub(r"\blike\s+", "such as ", target, flags=re.IGNORECASE)
    target = re.sub(r"\bsuch\s+as\s+the\s+", "such as ", target, flags=re.IGNORECASE)
    compact = _semantic_compact_adapter(target)
    return f"{sign}:{compact[:160]}" if compact else ""


def _personamem_projection_cluster_key(value: Any) -> str:
    text = _lower_clean(value)
    if not text:
        return ""
    negative_target = _negative_memory_target(value)
    if negative_target:
        return "correction:" + _personamem_signed_latent_equivalence_key(value).split(":", 1)[-1][:120]
    if _personamem_exact_sensitive_identifier_atom(value):
        key = _personamem_canonical_sensitive_identifier_key(text.split(":", 1)[0].strip())
        val = text.split(":", 1)[1].strip() if ":" in text else text
        return f"sensitive:{key}"
    if _is_personamem_topic_atom(text):
        return "topic:" + text
    if _is_personamem_conversation(value):
        return "prior:" + hashlib.sha1(_semantic_compact_adapter(value).encode("utf-8")).hexdigest()[:12]
    preference_object = _personamem_preference_object_cluster_key(value)
    if preference_object:
        return "prefobj:" + preference_object
    if _personamem_anchor_preserving_role_atom(value):
        return "role_anchor:" + _semantic_compact_adapter(value)[:160]
    if (
        _personamem_projection_exact_cover_required(value)
        and "role" in _personamem_projection_field_labels(value)
        and not _personamem_low_information_role_atom(value)
    ):
        return "role_exact:" + _semantic_compact_adapter(value)[:160]
    role_signature = _personamem_role_signature(value)
    if role_signature:
        return "role:" + role_signature
    explicit_role = _personamem_explicit_role_field_atom(value)
    if explicit_role:
        return "role:" + _semantic_compact_adapter(explicit_role)[:120]
    tokens = sorted(_contentish_tokens(_semantic_compact_adapter(value)))
    if len(tokens) <= 3:
        return "short:" + " ".join(tokens)
    return "tok:" + " ".join(tokens[:8])


def _personamem_preference_object_cluster_key(value: Any) -> str:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text or _is_personamem_topic_atom(text) or _is_personamem_conversation(value):
        return ""
    labels = _personamem_projection_field_labels(value)
    if "preference" not in labels and not ("routine" in labels and "role" not in labels):
        return ""
    body = text
    for _ in range(3):
        next_body = re.sub(
            r"^(?:enjoys?|likes?|loves?|prefers?|favors?|appreciates?|supports?|values?|"
            r"plays?|watches?|reads?|attends?|visits?|uses?|keeps?|collects|"
            r"spends?\s+(?:free\s+)?time\s+(?:at|in|on|with)|"
            r"participates?\s+in|listens?\s+to|fan\s+of|huge\s+fan\s+of)\s+",
            "",
            body,
        ).strip()
        next_body = re.sub(
            r"^(?:playing|watching|reading|listening|going|visiting|attending|using|keeping|collecting)\s+",
            "",
            next_body,
        ).strip()
        if next_body == body:
            break
        body = next_body
    stop = {
        "the", "and", "for", "with", "that", "this", "your", "their", "his", "her",
        "free", "time", "how", "things", "activities", "options", "preference",
        "preferences", "routine", "habit", "personal", "professional",
    }
    tokens = [
        token
        for token in re.split(r"[^a-z0-9]+", body)
        if len(token) >= 2 and token not in stop
    ]
    if len(tokens) < 2:
        return ""
    return " ".join(tokens[:2])[:80]


def _refresh_personamem_graphiti_preference_relations(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
) -> int:
    if "graphiti" not in str(sample.backend or "").strip().lower():
        return 0
    preferences = projected.get("preferences")
    if not isinstance(preferences, list):
        return 0
    domain = str(sample.public_context.get("task_domain") or "current task").strip() or "current task"
    subject = _personamem_safe_node(str(sample.user_id or "user"), fallback="user")
    edge = f"current_{domain}_preference"
    fact_edge = f"current_{domain}_fact"
    fact_relation = f"({subject},{fact_edge},{_personamem_backend_domain_fact_value(domain)})"
    relations = [
        item
        for item in projected.get("relations", [])
        if not (
            isinstance(item, str)
            and (
                re.match(rf"^\([^,]+,{re.escape(edge)},", item, flags=re.IGNORECASE)
                or re.match(rf"^\([^,]+,{re.escape(fact_edge)},", item, flags=re.IGNORECASE)
            )
        )
    ]
    relations.insert(0, fact_relation)
    relation_items = _select_personamem_graphiti_relation_preferences(
        preferences,
        sample=sample,
        cap=_personamem_backend_preference_cap(sample.backend),
    )
    updates = 0
    for item in relation_items:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if not value:
            continue
        relation = f"({subject},{edge},{value})"
        if relation not in relations:
            relations.append(relation)
            updates += 1
    projected["relations"] = relations
    return updates


def _select_personamem_graphiti_relation_preferences(
    preferences: Sequence[Any],
    *,
    sample: AttackInput,
    cap: int,
) -> list[Any]:
    """Pack Graphiti relation edges by complementary signed latent factors."""

    task_domain = _lower_clean(sample.public_context.get("task_domain") or "")
    buckets: dict[str, list[Any]] = {
        "correction": [],
        "positive": [],
        "sensitive": [],
        "topic": [],
        "prior": [],
        "role": [],
        "other": [],
    }
    seen_keys: set[str] = set()
    for item in preferences:
        value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
        if not value:
            continue
        key = _personamem_signed_latent_equivalence_key(value) or _semantic_compact_adapter(value)
        if key and key in seen_keys:
            continue
        if key:
            seen_keys.add(key)
        labels = _personamem_projection_field_labels(value)
        text = _lower_clean(value)
        if _is_personamem_negative_carrier(value):
            bucket = "correction"
        elif _personamem_exact_sensitive_identifier_atom(value) or text == "sensitive_info":
            bucket = "sensitive"
        elif _is_personamem_topic_atom(text):
            bucket = "topic"
        elif _is_personamem_conversation(value):
            bucket = "prior"
        elif "role" in labels and not _personamem_low_information_role_atom(value):
            bucket = "role"
        elif "preference" in labels or "routine" in labels:
            bucket = "positive"
        else:
            bucket = "other"
        buckets[bucket].append(item)

    if buckets["sensitive"]:
        bucket_order = ("sensitive", "topic", "prior", "role", "positive", "other")
    elif buckets["correction"]:
        bucket_order = ("correction", "positive", "topic", "prior", "role", "other")
    else:
        bucket_order = ("role", "topic", "prior", "positive", "other")

    selected: list[Any] = []
    selected_keys: set[str] = set()
    for bucket in bucket_order:
        if len(selected) >= cap:
            break
        pool = sorted(
            buckets[bucket],
            key=lambda item: _personamem_graphiti_relation_item_sort_key(
                _backend_projection_primary_unwrapped_value(item) or _clean_text(item),
                bucket=bucket,
                task_domain=task_domain,
            ),
        )
        for item in pool:
            if len(selected) >= cap:
                break
            value = _backend_projection_primary_unwrapped_value(item) or _clean_text(item)
            key = _personamem_graphiti_relation_redundancy_key(value)
            if key and key in selected_keys:
                continue
            selected.append(item)
            if key:
                selected_keys.add(key)
            break
    return selected[:cap]


def _personamem_graphiti_relation_redundancy_key(value: Any) -> str:
    if _is_personamem_negative_carrier(value):
        return _personamem_signed_latent_equivalence_key(value)
    positive_key = _personamem_signed_latent_equivalence_key(value)
    if positive_key:
        return positive_key
    return _semantic_compact_adapter(value)[:160]


def _personamem_causal_sufficient_profile_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    return bool(
        _personamem_exact_sensitive_identifier_atom(value)
        or _personamem_choice_certificate_projected_atom(value)
        or _personamem_lossless_typed_certificate_atom(value)
        or re.search(
            r"\b(?:teaches child to read and write in|worried mother who rushes to find an allergist|"
            r"allergist to provide immediate treatment|global-wandering butterfly photographer|"
            r"disconnection during longer stays in cities|falling out with a former best friend|"
            r"another military widow who provides a listening ear|past sprained ankle from a recreational basketball game|"
            r"follows north american football and ice hockey closely|book clubs focused on womens literature|"
            r"human resources director who doesnt like policies that infringe upon personal freedoms|"
            r"industry professional who oversees the licensing and production of vinyl reissues)\b",
            text,
        )
    )


def _personamem_surface_advice_projection_atom(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if _personamem_causal_sufficient_profile_atom(value) or _is_personamem_conversation(value):
        return False
    return bool(
        re.search(
            r"\b(?:plan item|why this fits|reusable cue|here are some|ways to help|will help keep|"
            r"choosing books on topics|word games?|labeling objects|garden-themed|festival-themed|"
            r"prepare a recent utility bill|proof of vehicle registration|commonly required|"
            r"mask your driver|placeholder|non-secure communications)\b",
            text,
        )
    )


def _personamem_graphiti_relation_item_sort_key(value: Any, *, bucket: str, task_domain: str) -> tuple[int, int, int, str]:
    text = _lower_clean(value)
    score = _personamem_invariant_support_score(_clean_text(value))
    score += _personamem_specific_support_score(_clean_text(value))
    if _personamem_exact_sensitive_identifier_atom(value):
        score += 240
    if _personamem_causal_sufficient_profile_atom(value):
        score += 100
    if _personamem_projection_high_value_field_atom(value):
        score += 80
    if _personamem_compact_exact_preference_atom(value):
        score += 70
    if bucket == "sensitive" and text == "sensitive_info":
        score += 45
    if _is_personamem_conversation(value):
        score += 55 - _personamem_source_like_conversation_penalty(value)
    if _is_personamem_topic_atom(text):
        score += 45
        if text == task_domain or text in _personamem_domain_topic_bridges(task_domain):
            score += 110
        elif task_domain and text in {"food", "entertainment", "environment", "health_and_medical"}:
            score -= 90
    if _personamem_low_information_preference_atom(value) or _personamem_low_information_role_atom(value):
        score -= 120
    if _personamem_surface_advice_projection_atom(value):
        score -= 140
    score -= _personamem_projection_mdl_noise_penalty(value)
    score -= _personamem_surface_task_role_penalty(value, task_domain=task_domain)
    length_pref = abs(len(text.split()) - (4 if bucket in {"topic", "positive", "correction"} else 18))
    return (-score, length_pref, len(text), text)


def _personamem_safe_node(value: str, *, fallback: str) -> str:
    text = str(value or fallback).strip().lower()
    cleaned = "".join(char if char.isalnum() else "_" for char in text).strip("_")
    return cleaned or fallback


def _personamem_source_role_candidates(source_prediction: Mapping[str, Any]) -> list[str]:
    source_regularized, _ = _regularize_personamem_posterior(source_prediction)
    source_texts = _personamem_budgeted_visible_evidence_texts([
        *_clean_text_list(source_regularized.get("preferences", [])),
        *_clean_text_list(source_prediction.get("preferences", [])),
        *_clean_text_list(source_prediction.get("facts", [])),
        *_clean_text_list(source_prediction.get("constraints", [])),
        _clean_text(source_prediction.get("raw_text", "")),
    ])
    structured_atoms = _personamem_profile_atoms_from_posterior_texts(source_texts)
    candidates: list[str] = []
    for item in [*source_texts, *structured_atoms]:
        for value in _backend_projection_unwrapped_values(item):
            canonical = _canonicalize_personamem_specific(value)
            explicit_role = _personamem_explicit_role_field_atom(canonical)
            if explicit_role:
                candidates.append(explicit_role)
            candidates.extend(_personamem_r007_role_core_atoms(canonical))
            if (
                canonical
                and _is_personamem_persona_carrier(canonical)
                and not _is_personamem_conversation(canonical)
                and len(_lower_clean(canonical).split()) <= 42
            ):
                candidates.append(canonical)
    deduped_candidates = _dedupe_preserving(candidates)
    clean_by_signature = {
        _personamem_role_signature(candidate)
        for candidate in deduped_candidates
        if _personamem_role_signature(candidate) and not _personamem_role_preference_fusion(candidate)
    }
    filtered_candidates = [
        candidate
        for candidate in deduped_candidates
        if not (
            _personamem_role_preference_fusion(candidate)
            and _personamem_role_signature(candidate) in clean_by_signature
        )
    ]
    return sorted(
        filtered_candidates,
        key=_personamem_sufficient_atom_sort_key,
    )


def _personamem_role_signature(value: Any) -> str:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    return _personamem_role_signature_from_text(text)


@lru_cache(maxsize=8192)
def _personamem_role_signature_from_text(text: str) -> str:
    text = re.sub(r"^(?:is\s+)?(?:a|an)\s+", "", text)
    role_head = re.split(
        r"\b(?:who|that|working|works|focused|speciali[sz](?:es|ing)?|with|in order to)\b",
        text,
        maxsplit=1,
    )[0].strip(" -*,.;:'\"")
    head_match = _PERSONAMEM_STABLE_ROLE_TERM_RE.search(role_head) if role_head else None
    if head_match:
        return head_match.group(0)
    text_match = _PERSONAMEM_STABLE_ROLE_TERM_RE.search(text)
    if text_match:
        return text_match.group(0)
    match = re.match(r"([a-z][a-z'-]+(?:\s+[a-z][a-z'-]+){0,3})\s+\bwho\b", text)
    return match.group(1) if match else ""


def _personamem_role_preference_fusion(value: Any) -> bool:
    text = _lower_clean(_backend_projection_primary_unwrapped_value(value) or value)
    if not text:
        return False
    if _is_personamem_conversation(value):
        return False
    action_head = r"(?:enjoys|likes|like|loves|prefers|favors|appreciates?|avoids|values|supports|attends|takes|practice|practices|practicing|swims|swimming|reads|watches|plays|listens to|uses|collects|drinks|eats|wears|buys|volunteers|travels|follows?\s+up|follow\s+up)"
    role_terms = "|".join(re.escape(role) for role in sorted(_PERSONAMEM_STABLE_ROLE_TERMS, key=len, reverse=True))
    if re.match(rf"^{action_head}\b\s+(?:aspiring|young|professional|dedicated|former|retired)?\s*(?:{role_terms})\b", text):
        return True
    if _personamem_identity_bound_role_modifier(text):
        return False
    return bool(
        re.search(
            r"\bwho\s+(?:prefer|prefers|favors|enjoys|likes|loves|attends|uses|reads|watches|plays|listens to)\b",
            text,
        )
        or re.match(rf"^(?:a\s+)?{action_head}\b.+\b(?:a|an)\s+[^.;,\n]{{0,50}}\b(?:historian|student|scientist|teacher|professor|artist|runner|athlete|engineer|doctor|nurse|writer|coach|researcher|manager|developer|photographer|musician|lawyer|attorney|economist|architect)\b", text)
        or re.match(rf"^{action_head}\b\s+(?:aspiring|young|professional|dedicated|former|retired)?\s*(?:{role_terms})\b", text)
        or (re.match(rf"^{action_head}\b", text) and " - " in str(value) and _is_personamem_persona_carrier(text))
        or (_is_personamem_persona_carrier(text) and " - " in str(value) and re.search(rf"\b{action_head}\b", text))
        or re.search(r"\bwith\s+(?:an?\s+)?(?:interest|preference|focus)\s+(?:in|on)\b", text)
        or re.search(r"\b(?:the\s+user'?s|user'?s)\s+(?:interest|preference|focus)\s+(?:in|on)\b", text)
        or re.search(r"\band\s+(?:an?\s+)?[^.;,\n]{0,40}\benthusiast\b", text)
        or (
            _is_personamem_persona_carrier(text)
            and re.search(r"\b(?:physical_address|email_address|phone_number|address:|header and signature|signature block)\b", text)
        )
        or (
            _is_personamem_persona_carrier(text)
            and re.search(r"\b(?:surgery|medical|health|preference|enjoys|prefers|favors|recent)\b", text)
            and len(text.split()) > 12
        )
    )


def _personamem_identity_bound_role_modifier(value: Any) -> bool:
    """Recognize stable role clauses that bind identity to a durable attribute.

    Some PersonaMem latent roles are intentionally not pure occupations.  They
    use a role plus a habitual tool, ritual, participation pattern, or stable
    personal practice as the identifying phrase.  These should not pay the
    role/preference fusion penalty unless they are visibly current-task advice.
    """

    text = _lower_clean(value)
    if not text:
        return False
    if re.search(r"\b(?:plan item|why this fits|recommendation|you could|you might|consider|current task|surface request)\b", text):
        return False
    persona_head = bool(_is_personamem_persona_carrier(text) or _personamem_role_signature(text))
    if re.search(
        r"\bwho\s+(?:believes?|is\s+passionate\s+about|advocates?|advocating|fights?|fighting|"
        r"is\s+more\s+interested\s+in|is\s+interested\s+in|values?|was\s+part\s+of|"
        r"also\s+introduces?|introduces?|becomes?|celebrates?|recognizes?|appreciates?|"
        r"(?:always\s+)?considers?)\b",
        text,
    ):
        return True
    if persona_head and re.search(
        r"\b(?:dealing with|struggling with|concerned about|worried about|managing)\s+"
        r"[^.;,\n]{2,120}\b(?:stress|anxiety|farm|health|medical|records?|privacy|mole|skin lesion)\b",
        text,
    ):
        return True
    if persona_head and re.search(
        r"\bwho\s+(?:enjoys?|likes?|loves?|values?|appreciates?)\s+"
        r"[^.;,\n]{2,120}\b(?:contributions?|traditions?|heritage|culture|community|decor|sweets|children?|family|friends?|collaboration)\b",
        text,
    ):
        if re.search(r"\b(?:collects?|keeps?)\s+family\s+photos?\b", text) or re.search(
            r"\bwho\s+enjoys?[^.;,\n]{2,80}\b(?:hiking|sketching)\b[^.;,\n]{0,80}\bcollects?\b",
            text,
        ):
            return False
        return True
    if persona_head and re.search(
        r"\b(?:believes?\s+(?:that\s+)?|is\s+passionate\s+about|passionate\s+about|"
        r"advocates?\s+for|advocating\s+for|fights?\s+for|fighting\s+for|"
        r"was\s+part\s+of\s+[^.;,\n]{2,120}|also\s+introduces?\s+[^.;,\n]{2,120}|"
        r"introduces?\s+[^.;,\n]{2,120}|becomes?\s+[^.;,\n]{2,120}|"
        r"with\s+(?:a\s+)?focus\s+(?:in|on)\s+[^.;,\n]{2,120}|"
        r"interested\s+in\s+[^.;,\n]{2,120}|seeking\s+collaboration\s+[^.;,\n]{0,120}|"
        r"more\s+interested\s+in\s+[^.;,\n]{2,80}\s+than|"
        r"interested\s+in\s+[^.;,\n]{2,80}\s+more\s+than)\b",
        text,
    ):
        return True
    if re.search(
        r"\bwho\s+(?:uses?|used)\s+[^.;,\n]{2,80}\b(?:software|tool|tools|archive|archives|notebook|map|maps|database|instrument|equipment)\b",
        text,
    ):
        return True
    if re.search(
        r"\b(?:employee|worker|barista|staff)\b.+\bwho\s+(?:often\s+)?plays\s+[^.;,\n]{2,80}\bmusic\b[^.;,\n]{0,80}\bwhile\s+working\b",
        text,
    ):
        return True
    if re.search(r"\bwho\s+(?:uses?|used)\s+[^.;,\n]{2,120}\bto\s+(?:trace|track|map|catalog|document|research|study|teach|learn)\b", text):
        return True
    if re.search(
        r"\bwho\s+(?:enjoys?|keeps?|maintains?|practices?|follows?)\s+[^.;,\n]{0,120}\b(?:daily|regular|weekly|ritual|routine|garden|lineage|heritage|bonsai|pipe tobacco|journaling)\b",
        text,
    ):
        return True
    if re.search(
        r"\bwho\s+(?:participates?|attends?|contributes?|volunteers?)\s+[^.;,\n]{2,120}\b(?:forums?|campaigns?|projects?|communities|meetings|clubs?|discussion)\b",
        text,
    ):
        return True
    return False


def _personamem_maximal_same_role_candidate(
    value: Any,
    *,
    candidates: Sequence[str],
) -> str:
    current = _canonicalize_personamem_specific(_backend_projection_primary_unwrapped_value(value) or value)
    signature = _personamem_role_signature(current)
    if not current or not signature:
        return ""
    current_score = _personamem_sufficient_atom_score(current)
    matching = [
        candidate
        for candidate in candidates
        if _personamem_role_signature(candidate) == signature
        and _lower_clean(candidate) != _lower_clean(current)
    ]
    if not matching:
        return ""
    best = min(matching, key=_personamem_sufficient_atom_sort_key)
    if _personamem_role_preference_fusion(best) and not _personamem_role_preference_fusion(current):
        return ""
    if _personamem_sufficient_atom_score(best) <= current_score + 8:
        return ""
    return best


def _regularize_locomo_backend_projection(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    source_prediction: Mapping[str, Any],
) -> dict[str, Any]:
    if sample.benchmark != "LoCoMo":
        return {"status": "not_applied", "reason": "not_locomo"}
    source_facts = _clean_text_list(source_prediction.get("facts", []))
    canonical_facts = _select_locomo_canonical_evidence(source_facts, cap=1)
    if not canonical_facts:
        return {"status": "not_applied", "reason": "no_canonical_locomo_fact"}
    canonical = canonical_facts[0]
    before_facts = len(projected.get("facts", []) if isinstance(projected.get("facts"), list) else [])
    before_relations = len(projected.get("relations", []) if isinstance(projected.get("relations"), list) else [])

    facts = projected.get("facts")
    if isinstance(facts, list) and facts:
        projected["facts"] = [_replace_backend_projection_wrapped_value(facts[0], canonical)]
    else:
        projected["facts"] = [_locomo_backend_fact_wrapper(sample, canonical)]

    if "graphiti" in str(sample.backend or "").strip().lower():
        relation = ""
        relations = projected.get("relations")
        if isinstance(relations, list):
            for item in relations:
                if "fact" in _lower_clean(item):
                    relation = _replace_backend_projection_wrapped_value(item, canonical)
                    break
        projected["relations"] = [relation or _locomo_backend_graph_relation(sample, canonical)]
    else:
        projected["relations"] = []

    projected["raw_text"] = _render_layered_raw_text(projected)
    return {
        "status": "applied",
        "model": "r006_locomo_projection_canonical_fact_v1",
        "facts_before": before_facts,
        "relations_before": before_relations,
        "facts_after": len(projected.get("facts", []) if isinstance(projected.get("facts"), list) else []),
        "relations_after": len(projected.get("relations", []) if isinstance(projected.get("relations"), list) else []),
    }


def _locomo_backend_fact_wrapper(sample: AttackInput, canonical: str) -> str:
    domain = str(sample.public_context.get("task_domain") or "temporal_memory").strip() or "temporal_memory"
    backend_key = str(sample.backend or "").strip().lower()
    if "graphiti" in backend_key:
        return f"current graph fact for {domain}: {canonical}"
    if "langmem" in backend_key:
        return f"semantic profile fact in {domain}: {canonical}"
    return f"retrieved memory fact for {domain}: {canonical}"


def _locomo_backend_graph_relation(sample: AttackInput, canonical: str) -> str:
    domain = str(sample.public_context.get("task_domain") or "temporal_memory").strip() or "temporal_memory"
    subject = _locomo_backend_safe_node(str(sample.user_id or "user"), fallback="user")
    return f"({subject},current_{domain}_fact,{canonical})"


def _locomo_backend_safe_node(value: str, *, fallback: str) -> str:
    text = str(value or fallback).strip().lower()
    cleaned = "".join(char if char.isalnum() else "_" for char in text).strip("_")
    return cleaned or fallback


def _regularize_etapp_minimal_attribution_projection(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    source_prediction: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if not _is_etapp_benchmark(sample.benchmark):
        return {"status": "not_applied", "reason": "not_etapp"}
    backend_key = str(sample.backend or "").strip().lower()
    before_relations = len(projected.get("relations", []) if isinstance(projected.get("relations"), list) else [])
    before_tool_state = len(projected.get("tool_state", []) if isinstance(projected.get("tool_state"), list) else [])
    retained_graph_relations: list[Any] = []
    graph_edge_substitution = {"status": "not_applied"}
    if "graphiti" in backend_key:
        retained_graph_relations, graph_edge_substitution = _select_etapp_graphiti_edge_carriers(
            projected,
            sample=sample,
        )
        projected["relations"] = retained_graph_relations
    tool_state = projected.get("tool_state")
    substituted_tool_cues = 0
    if isinstance(tool_state, Sequence) and not isinstance(tool_state, (str, bytes, bytearray)):
        filtered_tool_state = []
        domain_context_for_tool_state = str(sample.public_context.get("task_domain") or "").strip().lower()
        for item in tool_state:
            item_text = str(item)
            if "graphiti" in backend_key and domain_context_for_tool_state in {"travel", "weather"}:
                tool_text = item_text.lower()
                if re.search(r"\btool_name\b", tool_text) or re.search(r"\borigin_city\b", tool_text):
                    substituted_tool_cues += 1
                    continue
                if not re.search(r"\b(?:city|destination_city|location)\b", tool_text):
                    substituted_tool_cues += 1
                    continue
            if ("langmem" in backend_key or "langgraph" in backend_key) and _is_etapp_benchmark(sample.benchmark):
                tool_text = item_text.lower()
                if re.match(r"^\s*tool_name\s*=", item_text, flags=re.IGNORECASE) and domain_context_for_tool_state not in {"communication", "mail", "email"}:
                    substituted_tool_cues += 1
                    continue
                if re.match(r"^\s*[A-Za-z_][A-Za-z0-9_:-]*\s*=", item_text, flags=re.IGNORECASE):
                    if domain_context_for_tool_state in {"travel", "weather"} and re.match(
                        r"^\s*(?:city|destination_city|location)\s*=",
                        item_text,
                        flags=re.IGNORECASE,
                    ):
                        pass
                    elif domain_context_for_tool_state not in {"communication", "mail", "email"}:
                        substituted_tool_cues += 1
                        continue
                if re.match(r"^\s*langmem active section cue\b", item_text, flags=re.IGNORECASE):
                    if domain_context_for_tool_state in {"calendar", "alarm", "fitness"} and not re.search(r"\btool_name\s+is\b", tool_text):
                        substituted_tool_cues += 1
                        continue
                    if domain_context_for_tool_state in {"travel", "weather"} and not re.search(
                        r"\b(?:city|destination_city|location)\s+is\b",
                        tool_text,
                    ):
                        substituted_tool_cues += 1
                        continue
            if retained_graph_relations and re.search(
                r"\btool_name\s+is\s+play_music\b",
                item_text,
                flags=re.IGNORECASE,
            ):
                substituted_tool_cues += 1
                continue
            if "mem0" in backend_key and re.search(
                r"\b(?:tool_name\s+is\s+play_music|music_name\s+is\b|volume_level\s+is\b)",
                item_text,
                flags=re.IGNORECASE,
            ):
                substituted_tool_cues += 1
                continue
            filtered_tool_state.append(item)
        projected["tool_state"] = filtered_tool_state
        if (
            ("graphiti" in backend_key and domain_context_for_tool_state in {"travel", "weather"})
            or (("langmem" in backend_key or "langgraph" in backend_key) and _is_etapp_benchmark(sample.benchmark))
        ):
            projected["raw_text"] = _render_layered_raw_text(projected)
    fact_items = projected.get("facts")
    removed_projected_facts = 0
    if isinstance(fact_items, Sequence) and not isinstance(fact_items, (str, bytes, bytearray)):
        filtered_facts = []
        for item in fact_items:
            if _is_etapp_projected_generic_fact_noise(item, backend_key=backend_key):
                removed_projected_facts += 1
                continue
            filtered_facts.append(item)
        projected["facts"] = filtered_facts
    preference_items = projected.get("preferences")
    removed_projected_preferences = 0
    if isinstance(preference_items, Sequence) and not isinstance(preference_items, (str, bytes, bytearray)):
        filtered_preferences = []
        for item in preference_items:
            if _is_etapp_projected_generic_noise(item, backend_key=backend_key):
                removed_projected_preferences += 1
                continue
            filtered_preferences.append(item)
        projected["preferences"] = filtered_preferences
    source_refill = _refill_etapp_graphiti_profile_from_source(
        projected,
        sample=sample,
        source_prediction=source_prediction or {},
        backend_key=backend_key,
    )
    mem0_profile_carrier_swap = _apply_etapp_mem0_profile_carrier_swaps(
        projected,
        sample=sample,
        backend_key=backend_key,
    )
    profile_carrier_swap = _apply_etapp_graphiti_profile_carrier_swaps(
        projected,
        sample=sample,
        backend_key=backend_key,
    )
    substituted_tool_cues += int(profile_carrier_swap.get("tool_cues_removed", 0) or 0)
    return {
        "status": "applied",
        "graph_relations_removed": before_relations
        - len(projected.get("relations", []) if isinstance(projected.get("relations"), list) else []),
        "raw_tool_name_carriers_removed": before_tool_state
        - len(projected.get("tool_state", []) if isinstance(projected.get("tool_state"), list) else []),
        "behavior_signature_channel": "retained_visible_action_atoms_v130",
        "projected_generic_preferences_removed": removed_projected_preferences,
        "projected_generic_facts_removed": removed_projected_facts,
        "graph_edge_substitution": graph_edge_substitution,
        "graph_relations_retained": len(retained_graph_relations),
        "substituted_tool_cues": substituted_tool_cues,
        "mem0_profile_carrier_swap": mem0_profile_carrier_swap,
        "profile_carrier_swap": profile_carrier_swap,
        "source_refill": source_refill,
    }






def _etapp_projected_carrier_value(item: Any) -> str:
    text = str(item or "").strip()
    if ":" in text:
        text = text.split(":", 1)[1].strip()
    return text


def _refill_etapp_graphiti_profile_from_source(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    source_prediction: Mapping[str, Any],
    backend_key: str,
) -> dict[str, Any]:
    if not _is_etapp_benchmark(sample.benchmark):
        return {"status": "not_applied", "reason": "not_etapp"}
    domain = str(sample.public_context.get("task_domain") or "").strip()
    source_texts: list[str] = []
    for field in ("facts", "preferences", "constraints", "tool_state"):
        source_texts.extend(_clean_text_list(source_prediction.get(field, [])))
    metadata_sources = []
    if isinstance(source_prediction, Mapping) and isinstance(source_prediction.get("metadata", {}), Mapping):
        metadata_sources.append(source_prediction.get("metadata", {}))
    if (
        "mem0" not in backend_key
        and "memory0" not in backend_key
        and isinstance(projected.get("metadata", {}), Mapping)
    ):
        metadata_sources.append(projected.get("metadata", {}))
    for metadata in metadata_sources:
        source_texts.extend(_clean_text_list(metadata.get("etapp_profile_response_texts", [])))
    raw_text = _clean_text(source_prediction.get("raw_text", ""))
    if raw_text:
        source_texts.append(raw_text)
    source_values: list[str] = []
    for item in source_texts:
        values = _backend_projection_unwrapped_values(item) or [_clean_text(item)]
        source_values.extend(values)
    current_facts = [
        _etapp_projected_carrier_value(item)
        for item in projected.get("facts", [])
        if isinstance(projected.get("facts"), list)
    ]
    current_preferences = [
        _etapp_projected_carrier_value(item)
        for item in projected.get("preferences", [])
        if isinstance(projected.get("preferences"), list)
    ]
    fact_candidates = _regularize_etapp_profile_key_values([*source_values, *current_facts])
    preference_candidates = _regularize_etapp_profile_key_values([*source_values, *current_preferences])
    inferred_domain_context = _generic_etapp_domain_context(
        sample=sample,
        visible_tool_names=set(),
        evidence_text="\n".join(source_values),
    )
    domain_context = domain or inferred_domain_context
    domain = domain_context or "current"
    selected_facts = _select_etapp_profile_atom_budget(
        fact_candidates,
        cap=5,
        category="facts",
        support_counts=_etapp_profile_support_counts(source_values),
        domain_context=domain_context,
        backend_key=backend_key,
    )
    selected_preferences = _select_etapp_profile_atom_budget(
        preference_candidates,
        cap=5,
        category="preferences",
        support_counts=_etapp_profile_support_counts(source_values),
        domain_context=domain_context,
        backend_key=backend_key,
    )
    if not selected_facts and not selected_preferences:
        return {"status": "not_applied", "reason": "no_source_profile_candidates"}
    before_facts = len(projected.get("facts", []) if isinstance(projected.get("facts"), list) else [])
    before_preferences = len(projected.get("preferences", []) if isinstance(projected.get("preferences"), list) else [])
    if selected_facts:
        projected["facts"] = [
            _etapp_backend_profile_wrapper("fact", domain, item, backend_key=backend_key)
            for item in selected_facts
        ]
    if selected_preferences:
        projected["preferences"] = [
            _etapp_backend_profile_wrapper("preference", domain, item, backend_key=backend_key)
            for item in selected_preferences
        ]
    graphiti_relations_added = 0
    if "graphiti" in backend_key and domain in {"calendar", "fitness", "music"}:
        relation_items: list[str] = []
        subject = _etapp_graph_node(str(sample.user_id or "user"))
        fact_relation_keys = {"Character", "Interests", "LanguageProficiency", "Occupation"}
        preference_relation_keys = {"FavoriteTravelPlaces", "LongTermTravel"}
        for item in selected_facts:
            key = str(item).split("=", 1)[0]
            if key in fact_relation_keys and _generic_etapp_value_is_informative(str(item).partition("=")[2]):
                relation_items.append(f"({subject},current_{domain}_fact,{item})")
        for item in selected_preferences:
            key = str(item).split("=", 1)[0]
            if key in preference_relation_keys and _generic_etapp_value_is_informative(str(item).partition("=")[2]):
                relation_items.append(f"({subject},current_{domain}_preference,{item})")
        if relation_items:
            before_relations = len(projected.get("relations", []) if isinstance(projected.get("relations"), list) else [])
            existing_relations = (
                list(projected.get("relations", []))
                if isinstance(projected.get("relations"), list)
                else []
            )
            projected["relations"] = _dedupe_model_items([*existing_relations, *relation_items])
            graphiti_relations_added = len(projected["relations"]) - before_relations
    return {
        "status": "applied",
        "model": "backend_schema_posterior_source_refill_v2",
        "backend_key": backend_key,
        "fact_candidates": len(fact_candidates),
        "preference_candidates": len(preference_candidates),
        "facts_before": before_facts,
        "facts_after": len(projected.get("facts", [])),
        "preferences_before": before_preferences,
        "preferences_after": len(projected.get("preferences", [])),
        "graphiti_relations_added": graphiti_relations_added,
        "selected_facts": selected_facts,
        "selected_preferences": selected_preferences,
    }


def _etapp_backend_profile_wrapper(kind: str, domain: str, item: Any, *, backend_key: str) -> str:
    value = _clean_text(item)
    field = "fact" if kind == "fact" else "preference"
    if "graphiti" in backend_key:
        return f"current graph {field} for {domain}: {value}"
    if backend_key in {"mem0", "memory0"} or "mem0" in backend_key:
        return f"retrieved memory {field} for {domain}: {value}"
    return f"semantic profile {field} in {domain}: {value}"


def _etapp_graph_node(value: Any) -> str:
    text = str(value or "user").strip().lower()
    cleaned = "".join(char if char.isalnum() else "_" for char in text).strip("_")
    return cleaned or "user"


def _select_etapp_graphiti_edge_carriers(
    projected: Mapping[str, Any],
    *,
    sample: AttackInput,
) -> tuple[list[Any], dict[str, Any]]:
    if not _is_etapp_benchmark(sample.benchmark):
        return [], {"status": "not_applied", "reason": "not_etapp"}
    task_domain = str(sample.public_context.get("task_domain") or "").strip().lower()
    if task_domain and task_domain != "music":
        return [], {"status": "not_applied", "reason": "not_music_domain"}
    relation_items = projected.get("relations")
    if not isinstance(relation_items, Sequence) or isinstance(relation_items, (str, bytes, bytearray)):
        return [], {"status": "not_applied", "reason": "no_relation_sequence"}

    candidates: list[tuple[int, int, str, Any]] = []
    for item in relation_items:
        relation_text = str(item or "").strip()
        object_text = _etapp_graph_relation_object(relation_text)
        score = _etapp_graph_edge_carrier_score(object_text)
        if score < 9:
            continue
        candidates.append((score, len(object_text), relation_text.lower(), item))

    if not candidates:
        return [], {
            "status": "not_applied",
            "reason": "no_high_entropy_edge_carrier",
            "candidate_count": len(relation_items),
        }
    best = sorted(candidates, reverse=True)[0]
    return [best[3]], {
        "status": "applied",
        "model": "graph_edge_carrier_substitution_v1",
        "candidate_count": len(relation_items),
        "retained_count": 1,
        "retained_score": best[0],
        "retained_relation": str(best[3]),
    }


def _etapp_graph_relation_object(relation_text: str) -> str:
    match = re.match(r"^\s*\([^,]+,[^,]+,(.+)\)\s*$", str(relation_text or ""))
    if match:
        return match.group(1).strip()
    return str(relation_text or "").strip()


def _etapp_graph_edge_carrier_score(object_text: str) -> int:
    key, _, value = str(object_text or "").partition("=")
    key = key.strip().lower()
    lowered = value.lower()
    key_scores = {
        "preferences": 6,
        "listeninghabits": 6,
        "culturalpreferences": 6,
        "routine": 4,
        "favoriteapps": 5,
        "hobbies": 4,
        "shorttermwalk": 4,
        "playbackbehavior": 3,
        "favoritetravelplaces": 3,
        "shoppingpreferences": 2,
        "favoritebrands": 2,
    }
    score = key_scores.get(key, 0)
    score += min(3, lowered.count(","))
    if " and " in lowered:
        score += 1
    if len(lowered) > 120:
        score += 1
    if key in {"frequentlyplayedtracks", "musicgenres", "favoritegenres", "preferartists"}:
        score -= 3
    if "not specified" in lowered or "unknown" in lowered:
        score -= 5
    return score


def _regularize_personalens_graphiti_projection(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    source_prediction: Mapping[str, Any],
) -> dict[str, Any]:
    if sample.benchmark != "PersonaLens":
        return {"status": "not_applied", "reason": "not_personalens"}
    backend_key = str(sample.backend or "").strip().lower()
    if "graphiti" not in backend_key:
        return {"status": "not_applied", "reason": "not_graphiti"}
    relation_items = projected.get("relations")
    if isinstance(relation_items, Sequence) and not isinstance(relation_items, (str, bytes, bytearray)):
        relations = list(relation_items)
    else:
        relations = []
    before_count = len(relations)
    filtered = [
        item
        for item in relations
        if not _is_personalens_low_signal_graph_relation(item)
    ]
    source_texts = _personalens_role_projection_source_texts(source_prediction, projected)
    role_pairs_all = _dedupe_preserving(
        f"{key}={value}"
        for key, value in _personalens_role_pairs_from_texts(source_texts)
        if _personalens_role_pair_admissible(f"{key}={value}")
    )
    role_pairs = _personalens_select_role_pairs_for_projection(
        role_pairs_all,
        sample=sample,
        limit=7,
    )
    domain = _personalens_graphiti_runtime_domain(sample)
    role_atoms = [f"current graph preference for {domain}: {pair}" for pair in role_pairs]
    preferences = list(projected.get("preferences", []) if isinstance(projected.get("preferences"), list) else [])
    before_preferences = len(preferences)
    projected["preferences"] = _dedupe_model_items([*preferences, *role_atoms])
    fact_pairs = _personalens_fact_pairs_from_texts(
        _personalens_role_projection_source_texts(source_prediction, projected)
    )

    subject = _personamem_safe_node(str(sample.user_id or "user"), fallback="user")
    preference_edge = f"current_{domain}_preference"
    fact_edge = f"current_{domain}_fact"
    preference_relations = [f"({subject},{preference_edge},{pair})" for pair in role_pairs[:5]]
    fact_relations = [f"({subject},{fact_edge},{pair})" for pair in fact_pairs[:4]]
    projected["relations"] = _dedupe_model_items([*filtered, *fact_relations, *preference_relations])
    return {
        "status": "applied",
        "relations_removed": before_count - len(filtered),
        "role_pairs": len(role_pairs),
        "role_pairs_before_mdl": len(role_pairs_all),
        "fact_pairs": len(fact_pairs),
        "preferences_added": len(projected["preferences"]) - before_preferences,
        "relations_added": len(projected["relations"]) - len(filtered),
    }


def _personalens_graphiti_runtime_domain(sample: AttackInput) -> str:
    raw = ""
    if isinstance(sample.public_context, Mapping):
        raw = str(sample.public_context.get("task_domain") or "").strip()
    if not raw:
        match = re.search(r"sd-([a-z0-9_]+)-task", str(sample.task_id or ""), flags=re.IGNORECASE)
        raw = match.group(1) if match else "current_task"
    domain = re.sub(r"[^a-z0-9]+", "_", raw.strip().lower()).strip("_")
    return domain or "current_task"


def _personalens_select_role_pairs_for_projection(
    pairs: Sequence[str],
    *,
    sample: AttackInput,
    limit: int,
) -> list[str]:
    """Choose a compact PersonaLens role/value state for the current task domain."""

    counts: Counter[str] = Counter()
    display: dict[str, str] = {}
    for pair in pairs:
        if not _personalens_role_pair_admissible(pair):
            continue
        key, _, value = _clean_text(pair).partition("=")
        normalized = f"{_personalens_normalize_preference_key(key)}={_lower_clean(value)}"
        marker = normalized.lower()
        counts[marker] += 1
        display.setdefault(marker, normalized)
    if not display:
        return []
    ranked = sorted(
        display.values(),
        key=lambda pair: (
            _personalens_role_pair_projection_score(pair, sample=sample, support=counts[pair.lower()]),
            -len(pair),
            pair,
        ),
        reverse=True,
    )
    selected: list[str] = []
    seen_keys: Counter[str] = Counter()
    for pair in ranked:
        key, _, _ = pair.partition("=")
        if seen_keys[key] >= _personalens_role_pair_key_cap(key, sample=sample):
            continue
        if _personalens_role_pair_projection_score(pair, sample=sample, support=counts[pair.lower()]) <= -40:
            continue
        selected.append(pair)
        seen_keys[key] += 1
        if len(selected) >= limit:
            break
    return selected


def _personalens_role_pair_projection_score(
    pair: str,
    *,
    sample: AttackInput,
    support: int = 1,
) -> int:
    key, _, value = pair.partition("=")
    key = _personalens_normalize_preference_key(key)
    value_l = _lower_clean(value)
    domain = _personalens_graphiti_runtime_domain(sample).replace("_", " ")
    relevant = _personalens_domain_relevant_preference_keys(domain)
    stable_profile_key = _personalens_key_cross_domain_but_stable(key)
    score = min(4, int(support or 1)) * 18
    if key in relevant:
        score += 90
    elif stable_profile_key:
        score += 18
    else:
        score -= 58
    if _personalens_generated_recommendation_value(value_l):
        score -= 140
    if re.search(
        r"\b(?:recommend|use whatsapp|urgency|urgent|clearly stating|task choices|sports interest|"
        r"destination types|game genres|current task|contact them)\b",
        value_l,
    ):
        score -= 74
    if (
        key == "event type preference"
        and domain not in {"calendar", "events", "event", "messaging"}
        and not stable_profile_key
    ):
        score -= 52
    if key == "event type preference" and re.search(r"\b(?:urgency|clearly|message)\b", value_l):
        score -= 92
    if key in _PERSONALENS_MEDIA_ROLE_KEYS and len(value_l.split()) > 8:
        score -= 64
    if key in _PERSONALENS_PRICE_ROLE_KEYS and not re.search(r"\b[0-9]+(?:\s*-\s*[0-9]+)?\b", value_l):
        score -= 42
    if len(value_l.split()) <= 5:
        score += 22
    elif len(value_l.split()) > 12:
        score -= 42
    return score


