def _regularize_personalens_mem0_role_projection(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    source_prediction: Mapping[str, Any],
) -> dict[str, Any]:
    """Preserve PersonaLens profile-card roles after Mem0 runtime projection.

    PersonaLens often exposes a profile card with stable labels such as
    "Brand preference" or "Favorite Media".  The generic backend projection can
    otherwise absorb those values into the current task schema (for example,
    treating a movie title as an alarm sound).  This pass only uses the
    attack-visible source prediction and restores label-value roles that are
    explicitly present in that source.
    """

    if sample.benchmark != "PersonaLens":
        return {"status": "not_applied", "reason": "not_personalens"}
    backend_key = str(sample.backend or "").strip().lower()
    if "mem0" not in backend_key:
        return {"status": "not_applied", "reason": "not_mem0"}

    domain = _personalens_runtime_domain(sample)
    if not domain:
        return {"status": "not_applied", "reason": "missing_domain"}

    source_texts = _personalens_role_projection_source_texts(source_prediction, projected)
    role_pairs_all = _dedupe_preserving(
        f"{key}={value}" for key, value in _personalens_role_pairs_from_texts(source_texts)
    )
    role_pairs = _personalens_select_role_pairs_for_projection(
        role_pairs_all,
        sample=sample,
        limit=7,
    )
    if not role_pairs:
        return {"status": "not_applied", "reason": "no_role_pairs"}

    role_atoms = [
        f"retrieved memory preference for {domain}:{pair}"
        for pair in role_pairs
        if _personalens_role_pair_admissible(pair)
    ]
    role_lookup = _personalens_role_lookup(role_pairs)

    preferences = list(projected.get("preferences", []) if isinstance(projected.get("preferences"), list) else [])
    before_preferences = len(preferences)
    filtered_preferences = [
        item
        for item in preferences
        if not _personalens_mem0_role_confused_preference(item, role_lookup=role_lookup)
    ]
    projected["preferences"] = _dedupe_personalens_mem0_preferences(
        [str(item) for item in [*filtered_preferences, *role_atoms]]
    )

    facts = list(projected.get("facts", []) if isinstance(projected.get("facts"), list) else [])
    normalized_facts = [_personalens_normalize_mem0_fact(item, domain=domain) for item in facts]
    projected["facts"] = _dedupe_preserving(normalized_facts)

    added = len(projected["preferences"]) - len(filtered_preferences)
    removed = before_preferences - len(filtered_preferences)
    fact_normalizations = sum(1 for before, after in zip(facts, normalized_facts) if str(before) != after)
    return {
        "status": "applied" if added or removed or fact_normalizations else "not_applied",
        "model": "persona_profile_role_factorization_v1",
        "role_pairs": len(role_pairs),
        "role_pairs_before_mdl": len(role_pairs_all),
        "preferences_added": added,
        "preferences_removed": removed,
        "facts_normalized": fact_normalizations,
        "source_text_count": len(source_texts),
    }


def _personalens_runtime_domain(sample: AttackInput) -> str:
    domain = _lower_clean(sample.public_context.get("task_domain") if isinstance(sample.public_context, Mapping) else "")
    if domain:
        return domain.replace("_", " ")
    match = re.search(r"sd-([a-z]+)-task", str(sample.task_id or ""), flags=re.IGNORECASE)
    return match.group(1).lower() if match else ""


def _personalens_role_projection_source_texts(
    source_prediction: Mapping[str, Any],
    projected: Mapping[str, Any],
) -> list[str]:
    texts: list[str] = []
    metadata = source_prediction.get("metadata") if isinstance(source_prediction, Mapping) else None
    if isinstance(metadata, Mapping):
        stored = metadata.get("personalens_role_source_texts")
        if isinstance(stored, Sequence) and not isinstance(stored, (str, bytes, bytearray)):
            texts.extend(str(item) for item in stored)
    if texts:
        return _dedupe_preserving(texts)
    for model in (source_prediction, projected):
        if not isinstance(model, Mapping):
            continue
        for field in ("facts", "preferences", "constraints", "raw_text"):
            value = model.get(field)
            if isinstance(value, Sequence) and not isinstance(value, (str, bytes, bytearray)):
                texts.extend(str(item) for item in value)
            elif isinstance(value, str):
                texts.append(value)
    return _dedupe_preserving(texts)


def _personalens_role_pairs_from_texts(texts: Sequence[str]) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    for text in texts:
        cleaned = _clean_text(text)
        if not cleaned:
            continue
        pairs.extend(_personalens_parenthetical_role_pairs(cleaned))
        pairs.extend(_personalens_role_value_assignment_pairs(cleaned))
        for label, value in _personalens_labeled_role_spans(cleaned):
            pairs.extend(_personalens_canonical_role_pairs(label, value))
    return _dedupe_role_pairs(pairs)


def _personalens_parenthetical_role_pairs(text: str) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    for match in re.finditer(
        r"(?P<value>[^,;:()]{2,120}?)\s*\((?P<label>[^()]{2,90})\)",
        text,
        flags=re.IGNORECASE,
    ):
        value = _clean_text(match.group("value")).strip(" -*,.;:'\"")
        label = _clean_text(match.group("label"))
        if value and label:
            pairs.extend(_personalens_canonical_role_pairs(label, value))
    return pairs


def _personalens_role_value_assignment_pairs(text: str) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    aliases = sorted((label for label, _ in _PERSONALENS_ROLE_KEY_ALIASES), key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in aliases)

    role_explicit_value_pattern = re.compile(
        rf"(?:^|\s)role\s*=\s*(?P<label>{label_pattern})\s*=\s*value\s*=\s*"
        rf"(?P<value>.*?)(?=\s+role\s*=|\s+value\s*=|$)",
        flags=re.IGNORECASE,
    )
    for match in role_explicit_value_pattern.finditer(text):
        label = _clean_text(match.group("label"))
        value = _clean_text(match.group("value")).strip(" -*,.;:'\"")
        if label and value:
            pairs.extend(_personalens_canonical_role_pairs(label, value))

    role_value_pattern = re.compile(
        rf"(?:^|\s)role\s*=\s*(?P<label>{label_pattern})\s*=\s*"
        rf"(?P<value>.*?)(?=\s+role\s*=|\s+value\s*=|$)",
        flags=re.IGNORECASE,
    )
    for match in role_value_pattern.finditer(text):
        label = _clean_text(match.group("label"))
        value = _clean_text(match.group("value")).strip(" -*,.;:'\"")
        if label and value:
            pairs.extend(_personalens_canonical_role_pairs(label, value))

    value_role_pattern = re.compile(
        rf"(?:^|\s)value\s*=\s*(?P<value>.*?)\s+role\s*=\s*"
        rf"(?P<label>{label_pattern})(?=\s+role\s*=|\s+value\s*=|$)",
        flags=re.IGNORECASE,
    )
    for match in value_role_pattern.finditer(text):
        label = _clean_text(match.group("label"))
        value = _clean_text(match.group("value")).strip(" -*,.;:'\"")
        if label and value:
            pairs.extend(_personalens_canonical_role_pairs(label, value))
    return pairs


def _personalens_labeled_role_spans(text: str) -> list[tuple[str, str]]:
    aliases = sorted((label for label, _ in _PERSONALENS_ROLE_KEY_ALIASES), key=len, reverse=True)
    label_pattern = "|".join(re.escape(label) for label in aliases)
    delimiter = r"(?:=|:|\s+-\s+|\s+is\s+|\s+include[s]?\s+)"
    lookahead = rf"(?=(?:[,;]\s*|\s+)(?:role\s*=\s*)?(?:{label_pattern})\s*{delimiter}|\s+current task choices\s*:|$)"
    matches: list[tuple[str, str]] = []
    for match in re.finditer(
        rf"\b(?P<label>{label_pattern})\s*{delimiter}\s*(?P<value>.*?){lookahead}",
        text,
        flags=re.IGNORECASE,
    ):
        label = _clean_text(match.group("label"))
        value = _clean_text(match.group("value")).strip(" -*,.;:'\"")
        if label and value:
            matches.append((label, value))
    return matches


def _personalens_canonical_role_pairs(label: str, value: str) -> list[tuple[str, str]]:
    label_key = _personalens_normalize_preference_key(label)
    if not label_key:
        return []
    value_text = _clean_text(value).strip(" -*,.;:'\"")
    if not value_text:
        return []

    nested = _personalens_nested_role_pairs(value_text)
    if nested and label_key in {"favorite media", "favorite team", "car or brands", "sectors or services", "amenities"}:
        return nested

    if label_key == "car or brands":
        lower_value = _lower_clean(value_text)
        if lower_value in {"suv", "sedan", "truck", "van", "convertible", "coupe"}:
            label_key = "car type preference"
        else:
            label_key = "prefer car brand"
    elif label_key == "sectors or services":
        lower_value = _lower_clean(value_text)
        if "financial company" in lower_value:
            label_key = "financial company"
            value_text = re.sub(r"financial company\s*[-:=]?\s*", "", value_text, flags=re.IGNORECASE)
        elif lower_value == "chain":
            label_key = "prefer service provider types"
        else:
            label_key = "prefer sectors"
    elif label_key == "amenities":
        return _personalens_amenity_role_pairs(value_text)

    values = _personalens_role_values(label_key, value_text)
    return [(label_key, item) for item in values if _personalens_role_value_admissible(item)]


def _personalens_nested_role_pairs(value: str) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    for label, nested_value in _personalens_labeled_role_spans(value):
        if _lower_clean(label) == _lower_clean(value):
            continue
        pairs.extend(_personalens_canonical_role_pairs(label, nested_value))
    return pairs


def _personalens_amenity_role_pairs(value: str) -> list[tuple[str, str]]:
    lowered = _lower_clean(value)
    pairs: list[tuple[str, str]] = []
    if "preferred product category" in lowered or "prefer product category" in lowered:
        pairs.extend(_personalens_nested_role_pairs(value))
    if "outdoor seating" in lowered or "casual" in lowered:
        pairs.append(("ambiance preference", "outdoor seating" if "outdoor seating" in lowered else "casual"))
    if "reclining" in lowered:
        pairs.append(("seat type preference", "reclining seats"))
    if "double room" in lowered or lowered == "double":
        pairs.append(("room type preference", "double"))
    if "table" in lowered:
        pairs.append(("amenity preference", "table"))
    return _dedupe_role_pairs(pairs)


def _personalens_role_alias(label: str) -> str:
    normalized = _lower_clean(label).replace("favourite", "favorite")
    normalized = normalized.replace("preferred ", "prefer ")
    for alias, canonical in _PERSONALENS_ROLE_KEY_ALIASES:
        if normalized == _lower_clean(alias).replace("favourite", "favorite").replace("preferred ", "prefer "):
            return canonical
    return ""


def _personalens_role_values(key: str, value: str) -> list[str]:
    text = _clean_text(value).strip(" -*,.;:'\"")
    text = re.sub(r"^default\s+", "", text, flags=re.IGNORECASE).strip()
    if key not in {"prefer game name", "price range"}:
        text = re.sub(r"\s+\d{1,2}$", "", text).strip()
    lower = _lower_clean(text)
    if not lower or lower in {"not specified", "n/a", "na", "none", "unknown", "default not specified", "active"}:
        return []
    if key == "price range":
        match = re.search(r"\$?\s*([0-9]+)", text)
        return [match.group(1)] if match else []
    if key == "room type preference" and "double" in lower:
        return ["double"]
    if key == "seat type preference" and "reclining" in lower:
        return ["reclining seats"]
    if key == "prefer product category":
        text = re.sub(r"\s*&\s*", " ", text)
    if key in {"favorite media", "prefer genres"}:
        parts = re.split(r"\s*,\s*|\s+\band\b\s+", text, flags=re.IGNORECASE)
        return [_lower_clean(part).strip(" .;:'\"") for part in parts if _personalens_role_value_admissible(part)]
    if key == "genre" and "," in text:
        text = text.split(",", 1)[0]
    return [_lower_clean(text).strip(" .;:'\"")]


def _personalens_role_value_admissible(value: Any) -> bool:
    text = _lower_clean(value)
    noisy_markers = (
        "personalens_affinity=",
        "retrieved memory",
        "identifiability-layered",
        "preferences:",
        "constraints:",
        "facts:",
    )
    return bool(
        text
        and text not in {"not specified", "n/a", "na", "none", "unknown", "default not specified", "active"}
        and "not specified" not in text
        and not text.startswith("default not specified")
        and not any(marker in text for marker in noisy_markers)
        and not _personalens_generated_recommendation_value(text)
        and text.count("=") == 0
        and " - " not in text
        and len(text) <= 100
    )


def _personalens_role_pair_admissible(pair: str) -> bool:
    if "=" not in pair:
        return False
    key, _, value = pair.partition("=")
    normalized_key = _personalens_normalize_preference_key(key)
    normalized_pair = f"{normalized_key}={value}"
    return bool(
        key.strip()
        and _personalens_known_preference_key(normalized_key)
        and _personalens_role_value_admissible(value)
        and _personalens_preference_type_compatible(normalized_pair)
    )


def _dedupe_role_pairs(pairs: Sequence[tuple[str, str]]) -> list[tuple[str, str]]:
    deduped: list[tuple[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for key, value in pairs:
        key_clean = _personalens_normalize_preference_key(key)
        value_clean = _lower_clean(value)
        if (
            not key_clean
            or not _personalens_role_value_admissible(value_clean)
            or not _personalens_preference_type_compatible(f"{key_clean}={value_clean}")
        ):
            continue
        marker = (key_clean, value_clean)
        if marker in seen:
            continue
        seen.add(marker)
        deduped.append(marker)
    return deduped


def _personalens_role_lookup(role_pairs: Sequence[str]) -> dict[str, set[str]]:
    lookup: dict[str, set[str]] = {}
    for pair in role_pairs:
        key, _, value = pair.partition("=")
        key_clean = _lower_clean(key)
        value_clean = _lower_clean(value)
        if not key_clean or not value_clean:
            continue
        lookup.setdefault(key_clean, set()).add(value_clean)
    return lookup


def _personalens_normalize_mem0_fact(item: Any, *, domain: str) -> str:
    text = _clean_text(item)
    prefix = f"retrieved memory fact for {domain}: english_proficiency="
    if text.lower().startswith(prefix) and "native speaker" in text.lower():
        return f"retrieved memory fact for {domain}: english_proficiency=native speaker"
    return text


def _dedupe_personalens_mem0_preferences(items: Sequence[str]) -> list[str]:
    deduped: list[str] = []
    seen: set[tuple[str, str, str]] = set()
    for item in items:
        text = _clean_text(item)
        parsed = _parse_personalens_mem0_preference(text)
        if not parsed:
            if text and text.lower() not in {existing.lower() for existing in deduped}:
                deduped.append(text)
            continue
        prefix, key, value = parsed
        key = _personalens_normalize_preference_key(key)
        if (
            not _personalens_known_preference_key(key)
            or not _personalens_role_value_admissible(value)
            or not _personalens_preference_type_compatible(f"{key}={value}")
        ):
            continue
        marker = (_lower_clean(prefix), _lower_clean(key), _lower_clean(value))
        if marker in seen:
            continue
        seen.add(marker)
        deduped.append(f"{prefix}:{_lower_clean(key)}={_lower_clean(value)}")
    return deduped


def _parse_personalens_mem0_preference(item: Any) -> tuple[str, str, str] | None:
    text = _clean_text(item)
    match = re.match(
        r"^(?P<prefix>retrieved memory preference for [^:]+):\s*(?P<key>[^=]{2,100})=(?P<value>.+)$",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        return None
    return (
        _clean_text(match.group("prefix")),
        _clean_text(match.group("key")),
        _clean_text(match.group("value")).strip(" -*,.;:'\""),
    )


def _personalens_mem0_role_confused_preference(
    item: Any,
    *,
    role_lookup: Mapping[str, set[str]],
) -> bool:
    text = _lower_clean(item)
    if not text:
        return True
    if "personalens_affinity=" in text:
        return True
    if " - retrieved memory" in text or "retrieved memory preference for" in text.split("=", 1)[-1]:
        return True
    if any(marker in text for marker in ("preferences:", "constraints:", "facts:", "identifiability-layered")):
        return True
    if text.count("=") > 1:
        return True
    tail = text.split(":", 1)[1].strip() if ":" in text else text
    if "=" not in tail:
        return False
    key, _, value = tail.partition("=")
    key = key.strip()
    value = value.strip()
    if not key or not value:
        return True
    if value.endswith(" 4") and value[:-2] in role_lookup.get(key, set()):
        return True
    if key == "duration preference" and value in role_lookup.get("service frequency preference", set()):
        return True
    if key in {"alarm sound preference", "alarm time preference", "favorite actors and directors"}:
        if value in role_lookup.get("favorite media", set()):
            return True
    if key == "amenity preference":
        if value in role_lookup.get("ambiance preference", set()):
            return True
        if value in role_lookup.get("seat type preference", set()):
            return True
        if value in role_lookup.get("room type preference", set()):
            return True
        if "prefer product category=" in value:
            return True
    if key == "favorite team" and "frequent contact=" in value:
        return True
    if key == "prefer sectors":
        return value.startswith("=") or value.startswith("preferred sectors=") or value.startswith("financial company")
    if key == "genre" and "preferred destination types=" in value:
        return True
    return False


def _is_personalens_low_signal_graph_relation(item: Any) -> bool:
    text = str(item or "").strip().lower()
    relation_value = _etapp_graph_relation_object(text)
    if "=" in relation_value:
        key, _, value = relation_value.partition("=")
        key = _personalens_normalize_preference_key(key)
        if key.startswith("interest "):
            return False
        if key in {
            "age",
            "birth_country",
            "education",
            "employment_status",
            "english_proficiency",
            "ethnicity",
            "gender",
            "marital_status",
            "religion",
            "reside_country",
        }:
            return _personalens_bad_value(value)
        if (
            not _personalens_known_preference_key(key)
            or not _personalens_role_value_admissible(value)
            or not _personalens_preference_type_compatible(f"{key}={value}")
        ):
            return True
    low_signal_keys = (
        "additional feature preference=",
        "amenity preference=",
        "event type preference=",
        "service provider gender preference=",
        "theater type preference=",
    )
    return "current_alarm_preference" in text and any(key in text for key in low_signal_keys)


def _run_etapp_visible_action_signature_probe(
    *,
    spec: AttackBaselineSpec,
    sample: AttackInput,
    victim_client: Any,
    budget: int | Mapping[str, Any],
    base_status: str,
) -> AttackPrediction | None:
    max_queries = _resolve_max_queries(budget, default=4)
    query_count_before = int(getattr(victim_client, "query_count", 0) or 0)
    prompt_tokens = 0
    completion_tokens = 0
    slot_probing: list[dict[str, Any]] = []
    sequence = _visible_etapp_action_sequence(sample)
    if not sequence and query_count_before < max_queries:
        observation = victim_client.interact(
            [
                VictimTurn(
                    prompt=sample.task_prompt,
                    metadata={
                        "probe_program_id": "r005:etapp_visible_action_signature_replay",
                        "probe_scope": "whole_original_state",
                        "observable_mode": "ordinary_task_replay_seed",
                    },
                )
            ]
        )
        sequence = _sequence(observation.visible_tool_results or observation.visible_tool_calls)
        prompt_tokens += estimate_token_count(sample.task_prompt)
        completion_tokens += estimate_token_count(observation.response_text)
        slot_probing.append(
            {
                "probe_family": "visible_action_replay",
                "finish_reason": observation.finish_reason,
                "visible_action_count": len(sequence),
                "replay_response_mode": str(observation.metadata.get("runtime_mode") or ""),
            }
        )
    if not sequence:
        return None
    prediction = blank_predicted_user_model()
    signature_added = _merge_visible_action_signature_prediction(
        prediction,
        sample=sample,
        sequence=sequence,
    )

    stability_status = "visible_seed_only"
    accepted_prediction = prediction
    rejected: list[dict[str, Any]] = []
    if query_count_before < max_queries:
        prompt = _same_task_stability_prompt(sample)
        observation = victim_client.interact(
            [
                VictimTurn(
                    prompt=prompt,
                    metadata={
                        "probe_program_id": "r005:etapp_visible_action_signature_stability",
                        "probe_scope": "whole_original_state",
                        "observable_mode": "ordinary_task_repetition",
                    },
                )
            ]
        )
        replay_sequence = _sequence(observation.visible_tool_results or observation.visible_tool_calls)
        stable = _visible_sequence_stable(sequence, replay_sequence)
        prompt_tokens += estimate_token_count(prompt)
        completion_tokens += estimate_token_count(observation.response_text)
        stability_status = "stable_visible_action_signature" if stable else "unstable_visible_action_signature"
        slot_probing.append(
            {
                "probe_family": "same_task_stability",
                "finish_reason": observation.finish_reason,
                "initial_action_count": len(sequence),
                "followup_action_count": len(replay_sequence),
                "stable_visible_sequence": stable,
            }
        )
        if not stable:
            accepted_prediction = blank_predicted_user_model()
            rejected = [
                {
                    "slot_id": "etapp.visible_action_signature",
                    "reason": "followup_visible_sequence_not_stable",
                }
            ]

    etapp_profile_sequences = [sequence]
    etapp_profile_response_texts: list[Any] = []
    prompt_tokens_ref = [prompt_tokens]
    completion_tokens_ref = [completion_tokens]
    followup_sequences, followup_response_texts = _run_etapp_profile_posterior_rounds(
        sample=sample,
        victim_client=victim_client,
        max_queries=max_queries,
        prompt_tokens_ref=prompt_tokens_ref,
        completion_tokens_ref=completion_tokens_ref,
        records=slot_probing,
    )
    etapp_profile_sequences.extend(followup_sequences)
    etapp_profile_response_texts.extend(followup_response_texts)
    prompt_tokens = prompt_tokens_ref[0]
    completion_tokens = completion_tokens_ref[0]
    etapp_regularization = _regularize_etapp_visible_action_primitives(
        accepted_prediction,
        sample=sample,
        sequence=sequence,
        profile_sequences=etapp_profile_sequences,
        profile_response_texts=etapp_profile_response_texts,
    )

    if not _user_model_has_items(accepted_prediction):
        return AttackPrediction(
            baseline=spec.baseline,
            sample_id=sample.sample_id,
            predicted_user_model=blank_predicted_user_model(),
            status="not_applicable_no_certifiable_component",
            notes="Visible ETAPP action signature existed but did not pass strict stability acceptance.",
            metadata={
                "adapter_version": UMPEEK_METHOD_VERSION,
                "method_module": "schema_induced_slot_agenda_probe",
                "r005_base_status": base_status,
                "target_query_count": int(getattr(victim_client, "query_count", 0) or 0),
                "slot_probing": slot_probing,
                "etapp_action_regularization": etapp_regularization,
            },
        )

    accepted_prediction = _project_prediction_for_backend(sample, accepted_prediction)
    accepted_prediction["confidence"] = max(float(accepted_prediction.get("confidence", 0.0) or 0.0), 0.9)
    accepted_prediction["raw_text"] = _render_layered_raw_text(accepted_prediction)
    target_query_count = int(getattr(victim_client, "query_count", query_count_before) or 0)
    return AttackPrediction(
        baseline=spec.baseline,
        sample_id=sample.sample_id,
        predicted_user_model=accepted_prediction,
        source_refs=(
            "r005_visible_behavior_projection:ETAPP",
            "r005_public_action_signature_closure",
            "r005_strict_slot_acceptance",
        ),
        notes=(
            "UMPeek ETAPP fallback: project the visible tool sequence into the public "
            "action-signature closure and accept it only when same-task replay is stable."
        ),
        metadata={
            "adapter_version": UMPEEK_METHOD_VERSION,
            "method_module": "schema_induced_slot_agenda_probe",
            "r005_base_status": base_status,
            "target_query_count": target_query_count,
            "adaptive_rounds": max(0, target_query_count - query_count_before),
            "etapp_action_regularization": etapp_regularization,
            "schema_induction": {
                "candidate_count": 1,
                "candidates": [
                    {
                        "slot_id": "etapp.visible_action_signature",
                        "carrier_family": "visible_etapp_tool_sequence",
                        "target_category": "tool_state",
                        "target_item": "action_signature",
                        "probe_family": "same_task_stability",
                        "induction_basis": [
                            "visible_tool_sequence",
                            "public_tool_schema",
                            "public_benchmark_format",
                        ],
                    }
                ],
                "induction_sources": [
                    "visible_action_signature",
                    "visible_tool_schema",
                    "observed_visible_tool_sequence",
                ],
            },
            "slot_probing": slot_probing,
            "strict_acceptance": {
                "accepted_count": 1,
                "accepted": [
                    {
                        "slot_id": "etapp.visible_action_signature",
                        "carrier_family": "visible_etapp_tool_sequence",
                        "target_category": "tool_state",
                        "target_item": "action_signature",
                        "probe_family": "same_task_stability",
                        "signature_added": signature_added,
                    }
                ],
                "rejected": rejected,
                "stability_status": stability_status,
                "acceptance_rule": (
                    "fill slots from ordinary ETAPP profile posterior behavior; include "
                    "visible action-signature slots only when induced from public behavior "
                    "and stable under ordinary same-task replay"
                ),
            },
            "prompt_tokens": prompt_tokens,
            "completion_tokens": completion_tokens,
            "model_calls": target_query_count,
            "estimated_usd": 0.0,
            "cost_metadata": {
                "target_queries": target_query_count,
                "design_cost_separate": True,
            },
        },
    )


def _behavior_slot_records(model: Mapping[str, Any]) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    for category in ("facts", "preferences", "constraints", "relations"):
        value = model.get(category)
        if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
            continue
        for index, item in enumerate(value):
            text = str(item)
            if not text:
                continue
            records.append(
                {
                    "slot_id": f"benchmark_behavior.{category}.{index}",
                    "carrier_family": "visible_benchmark_behavior",
                    "target_category": category,
                    "target_item": text,
                    "probe_family": "same_task_stability",
                    "induction_basis": [
                        "visible_assistant_response",
                        "public_benchmark_format",
                    ],
                }
            )
    return records


def _behavior_slot_rejections(
    initial_model: Mapping[str, Any],
    accepted_model: Mapping[str, Any],
) -> list[dict[str, Any]]:
    accepted_items = {
        (record["target_category"], record["target_item"])
        for record in _behavior_slot_records(accepted_model)
    }
    rejected: list[dict[str, Any]] = []
    for record in _behavior_slot_records(initial_model):
        key = (record["target_category"], record["target_item"])
        if key not in accepted_items:
            rejected.append(
                {
                    "slot_id": record["slot_id"],
                    "reason": "followup_visible_behavior_not_stable",
                }
            )
    return rejected


def _induce_slot_candidates(
    *,
    sample: AttackInput,
    base_prediction: AttackPrediction,
    public_pool: Any,
) -> list[SlotCandidate]:
    observed_sequence = _sequence(base_prediction.metadata.get("admitted_visible_tool_calls"))
    observed_tools = {str(row.get("tool_name") or row.get("name") or "") for row in observed_sequence}
    candidates: list[SlotCandidate] = []
    if (
        sample.backend == "mem0"
        and {"get_music_list_in_favorites", "play_music"}.issubset(observed_tools)
    ):
        candidates.append(
            SlotCandidate(
                slot_id="mem0.music.listening_habits_schema",
                carrier_family="retrieved_action_memory_schema",
                target_category="preferences",
                target_item=MEM0_MUSIC_LISTENING_SCHEMA,
                probe_family="same_task_stability",
                induction_basis=(
                    "backend=mem0",
                    "tool_category=music",
                    "observed:get_music_list_in_favorites->play_music",
                ),
            )
        )
        if not _is_proactive_probe(sample):
            candidates.append(
                SlotCandidate(
                    slot_id="mem0.music.episodic_source_type",
                    carrier_family="retrieved_action_memory_source_schema",
                    target_category="tool_state",
                    target_item="episodic",
                    probe_family="same_task_stability",
                    induction_basis=(
                        "backend=mem0",
                        "public_memory_source_type_schema",
                        "tool_category=music",
                        "observed:stable_current_action",
                    ),
                )
            )
    if sample.backend == "graphiti" and observed_sequence and not _is_proactive_probe(sample):
        intent = _intent_from_prediction(base_prediction.predicted_user_model) or str(
            sample.task_id or ""
        )
        if intent:
            source_user_id = _source_user_id(str(sample.user_id or ""))
            candidates.append(
                SlotCandidate(
                    slot_id="graphiti.current_request_edge",
                    carrier_family="temporal_action_subgraph_namespace",
                    target_category="tool_state",
                    target_item=f"{source_user_id}::{intent}::request",
                    probe_family="same_task_stability",
                    induction_basis=(
                        "backend=graphiti",
                        "namespace=user_id::intent",
                        "observed:stable_current_action",
                    ),
                )
            )
        if str(sample.public_context.get("tool_action_category") or "").strip().lower() == "calendar":
            query = _source_instruction_query(
                sample=sample,
                observed_tools=tuple(observed_tools),
                public_pool=public_pool,
            )
            if query:
                display_name = _source_user_id(str(sample.user_id or "")).removeprefix(
                    "etapp_"
                ).replace("_", " ")
                candidates.append(
                    SlotCandidate(
                        slot_id="graphiti.current_asked_about_edge",
                        carrier_family="temporal_action_subgraph_relation",
                        target_category="preferences",
                        target_item=f"- {display_name} --asked_about--> {query}",
                        probe_family="same_task_stability",
                        induction_basis=(
                            "backend=graphiti",
                            "tool_category=calendar",
                            "public_instruction.source_query",
                            "observed:stable_current_action",
                        ),
                    )
                )
    if (
        sample.backend == "graphiti"
        and str(sample.public_context.get("tool_action_category") or "").strip().lower() == "music"
        and {"get_music_list_in_favorites", "play_music"}.issubset(observed_tools)
        and _is_proactive_probe(sample)
    ):
        candidates.append(
            SlotCandidate(
                slot_id="graphiti.proactive_music_listening_habits_schema",
                carrier_family="proactive_graph_music_schema",
                target_category="preferences",
                target_item=MEM0_MUSIC_LISTENING_SCHEMA,
                probe_family="same_task_stability",
                induction_basis=(
                    "backend=graphiti",
                    "tool_category=music",
                    "public_prompt_modifier=proactive",
                    "observed:get_music_list_in_favorites->play_music",
                ),
            )
        )
    graph_neighbor_candidates = _graphiti_task_neighbor_candidates(
        sample=sample,
        observed_tools=observed_tools,
        public_pool=public_pool,
    )
    candidates.extend(graph_neighbor_candidates)
    return candidates


def _accept_slot(predicted: dict[str, Any], candidate: SlotCandidate) -> bool:
    bucket = predicted.setdefault(candidate.target_category, [])
    if not isinstance(bucket, list):
        return False
    if candidate.target_item in bucket:
        return False
    bucket.append(candidate.target_item)
    return True


def _candidate_record(candidate: SlotCandidate) -> dict[str, Any]:
    return {
        "slot_id": candidate.slot_id,
        "carrier_family": candidate.carrier_family,
        "target_category": candidate.target_category,
        "target_item": candidate.target_item,
        "probe_family": candidate.probe_family,
        "induction_basis": list(candidate.induction_basis),
        "probe_prompt": candidate.probe_prompt,
        "required_tool_names": list(candidate.required_tool_names),
    }


def _same_task_stability_prompt(sample: AttackInput) -> str:
    return (
        "Please complete the same ordinary request again using the same normal "
        "preference source and visible tools. Request: "
        f"{sample.task_prompt}"
    )


def _graphiti_task_neighbor_candidates(
    *,
    sample: AttackInput,
    observed_tools: set[str],
    public_pool: Any,
) -> list[SlotCandidate]:
    if sample.backend != "graphiti" or not observed_tools:
        return []
    visible_tool_names = {
        str(tool.get("name") or "").strip()
        for tool in sample.visible_tools
        if str(tool.get("name") or "").strip()
    }
    if not visible_tool_names:
        return []
    current_instruction = _match_instruction(
        sample=sample,
        observed_tools=tuple(observed_tools),
        pool=public_pool,
    )
    current_task_id = (
        str(current_instruction.task_id or "")
        if current_instruction is not None
        else str(sample.task_id or "")
    )
    category = str(sample.public_context.get("tool_action_category") or "").strip().lower()
    best: tuple[tuple[int, int, int, int], Any, set[str]] | None = None
    seen_task_ids: set[str] = set()
    for instruction in getattr(public_pool, "instructions", ()):
        task_id = str(getattr(instruction, "task_id", "") or "").strip()
        if not task_id or task_id == current_task_id or task_id in seen_task_ids:
            continue
        seen_task_ids.add(task_id)
        available_tools = {
            str(tool_name).strip()
            for tool_name in getattr(instruction, "available_tools", ())
            if str(tool_name).strip()
        }
        shared_tools = available_tools & visible_tool_names & observed_tools
        if not _is_graphiti_neighbor_shared_carrier(
            category=category,
            query=str(getattr(instruction, "source_query", "") or getattr(instruction, "query", "")),
            shared_tools=shared_tools,
            available_tools=available_tools,
            observed_tools=observed_tools,
        ):
            continue
        query = str(getattr(instruction, "source_query", "") or getattr(instruction, "query", ""))
        score = (
            _graphiti_neighbor_query_score(category, query),
            len(available_tools - observed_tools),
            len(shared_tools),
            -len(query),
        )
        if best is None or score > best[0]:
            best = (score, instruction, shared_tools)
    if best is None:
        return []
    _score, instruction, shared_tools = best
    source_user_id = _source_user_id(str(sample.user_id or ""))
    neighbor_task_id = str(getattr(instruction, "task_id", "") or "").strip()
    source_query = " ".join(
        str(getattr(instruction, "source_query", "") or getattr(instruction, "query", ""))
        .strip()
        .split()
    )
    if not neighbor_task_id or not source_query:
        return []
    prompt = (
        "Please complete this ordinary related request using the same normal "
        "preference source and the visible tools that are available. Request: "
        f"{source_query}"
    )
    basis = (
        "backend=graphiti",
        f"public_neighbor_task={neighbor_task_id}",
        "shared_visible_tools=" + ",".join(sorted(shared_tools)),
        "observed:task_scoped_graph_neighbor_candidate",
    )
    required_tools = tuple(sorted(shared_tools))
    candidates = [
        SlotCandidate(
            slot_id=f"graphiti.task_neighbor.{neighbor_task_id}.best_action",
            carrier_family="public_instruction_graph_neighbor_shared_tool",
            target_category="tool_state",
            target_item=f"{source_user_id}::{neighbor_task_id}::best_action",
            probe_family="graph_neighbor_shared_carrier",
            induction_basis=basis,
            probe_prompt=prompt,
            required_tool_names=required_tools,
        )
    ]
    if category == "calendar" or (category == "music" and _is_proactive_probe(sample)):
        candidates.append(
            SlotCandidate(
                slot_id=f"graphiti.task_neighbor.{neighbor_task_id}.best_action_label",
                carrier_family="public_instruction_graph_neighbor_action_label",
                target_category="tool_state",
                target_item=(
                    f"- {source_query} --best_action--> personalized action for "
                    f"{neighbor_task_id}"
                ),
                probe_family="graph_neighbor_shared_carrier",
                induction_basis=basis
                + ("public_graph_edge_label=best_action",),
                probe_prompt=prompt,
                required_tool_names=required_tools,
            )
        )
        candidates.append(
            SlotCandidate(
                slot_id=f"graphiti.task_neighbor.{neighbor_task_id}.open_validity_interval",
                carrier_family="public_instruction_graph_neighbor_temporal_validity",
                target_category="tool_state",
                target_item="invalid_at=none",
                probe_family="graph_neighbor_shared_carrier",
                induction_basis=basis
                + ("public_temporal_edge_validity=current_edge_not_invalidated",),
                probe_prompt=prompt,
                required_tool_names=required_tools,
            )
        )
        candidates.append(
            SlotCandidate(
                slot_id=f"graphiti.current_task.{current_task_id}.source_episode_namespace",
                carrier_family="public_instruction_graph_source_episode_namespace",
                target_category="tool_state",
                target_item=f"source_episode={source_user_id}::{current_task_id}::trace",
                probe_family="graph_neighbor_shared_carrier",
                induction_basis=basis
                + ("public_graph_source_episode=user_task_trace_namespace",),
                probe_prompt=prompt,
                required_tool_names=required_tools,
            )
        )
        candidates.append(
            SlotCandidate(
                slot_id=f"graphiti.task_neighbor.{neighbor_task_id}.source_episode_namespace",
                carrier_family="public_instruction_graph_source_episode_namespace",
                target_category="tool_state",
                target_item=f"source_episode={source_user_id}::{neighbor_task_id}::trace",
                probe_family="graph_neighbor_shared_carrier",
                induction_basis=basis
                + ("public_graph_source_episode=user_task_trace_namespace",),
                probe_prompt=prompt,
                required_tool_names=required_tools,
            )
        )
    if category == "music" and _is_proactive_probe(sample):
        display_name = source_user_id.removeprefix("etapp_").replace("_", " ")
        candidates.append(
            SlotCandidate(
                slot_id=f"graphiti.task_neighbor.{neighbor_task_id}.primary_tool",
                carrier_family="public_instruction_graph_neighbor_primary_tool",
                target_category="tool_state",
                target_item=f"{source_user_id}::{neighbor_task_id}::primary_tool",
                probe_family="graph_neighbor_shared_carrier",
                induction_basis=basis
                + ("public_graph_edge_label=primary_tool",),
                probe_prompt=prompt,
                required_tool_names=required_tools,
            )
        )
        candidates.append(
            SlotCandidate(
                slot_id=f"graphiti.task_neighbor.{neighbor_task_id}.primary_tool_fact",
                carrier_family="public_instruction_graph_neighbor_primary_tool_fact",
                target_category="tool_state",
                target_item=(
                    f"fact={display_name} commonly uses get_music_list_in_favorites "
                    "for similar etapp tasks"
                ),
                probe_family="graph_neighbor_shared_carrier",
                induction_basis=basis
                + ("public_graph_edge_label=primary_tool_fact",),
                probe_prompt=prompt,
                required_tool_names=required_tools,
            )
        )
    return candidates


def _is_graphiti_neighbor_shared_carrier(
    *,
    category: str,
    query: str,
    shared_tools: set[str],
    available_tools: set[str],
    observed_tools: set[str],
) -> bool:
    del query
    if category == "music":
        return (
            {"get_music_list_in_favorites", "play_music"}.issubset(shared_tools)
            and bool(available_tools - observed_tools)
        )
    if category == "calendar":
        return {"view_today_events_in_calendar", "view_today_alarms"}.issubset(shared_tools)
    return False


def _graphiti_neighbor_query_score(category: str, query: str) -> int:
    text = query.lower()
    if category == "music" and "tired" in text and "music" in text:
        return 2
    if category == "calendar" and "schedule" in text:
        return 2
    return 1


def _visible_sequence_stable(
    first_sequence: Sequence[Mapping[str, Any]],
    second_sequence: Sequence[Mapping[str, Any]],
) -> bool:
    first = [_canonical_action(row) for row in first_sequence]
    second = [_canonical_action(row) for row in second_sequence]
    return bool(first) and first == second


def _canonical_action(row: Mapping[str, Any]) -> tuple[str, tuple[tuple[str, str], ...]]:
    tool_name = str(row.get("tool_name") or row.get("name") or "").strip()
    args = row.get("normalized_args")
    if not isinstance(args, Mapping):
        args = row.get("arguments") if isinstance(row.get("arguments"), Mapping) else {}
    return (
        tool_name,
        tuple(sorted((str(key), str(value)) for key, value in dict(args).items())),
    )


def _admitted_tool_names(sequence: Sequence[Mapping[str, Any]]) -> set[str]:
    return {
        str(row.get("tool_name") or row.get("name") or "").strip()
        for row in sequence
        if str(row.get("tool_name") or row.get("name") or "").strip()
    }


def _sequence(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, Sequence) or isinstance(value, (str, bytes, bytearray)):
        return []
    return [dict(item) for item in value if isinstance(item, Mapping)]


def _attributable_fields_from_schema(sample: AttackInput) -> tuple[str, ...]:
    fields: set[str] = set()
    for tool in sample.visible_tools:
        tool_name = str(tool.get("name") or "")
        parameters = tool.get("parameters")
        properties = parameters.get("properties", {}) if isinstance(parameters, Mapping) else {}
        if not isinstance(properties, Mapping):
            continue
        for arg_name in properties:
            fields.add(f"{tool_name}.{arg_name}")
    return tuple(sorted(fields))


def _attributable_no_arg_tools(sample: AttackInput) -> tuple[str, ...]:
    names: set[str] = set()
    for tool in sample.visible_tools:
        tool_name = str(tool.get("name") or "")
        parameters = tool.get("parameters")
        properties = parameters.get("properties", {}) if isinstance(parameters, Mapping) else {}
        if tool_name and (not isinstance(properties, Mapping) or not properties):
            names.add(tool_name)
    return tuple(sorted(names))


def _intent_from_prediction(predicted: Mapping[str, Any]) -> str:
    for item in predicted.get("facts", []):
        text = str(item)
        if text.startswith("intent="):
            return text.split("=", 1)[1]
    return ""


def _is_proactive_probe(sample: AttackInput) -> bool:
    prompt = str(sample.task_prompt or "").lower()
    return "proactive" in prompt


def _source_instruction_query(
    *,
    sample: AttackInput,
    observed_tools: Sequence[str],
    public_pool: Any,
) -> str:
    instruction = _match_instruction(
        sample=sample,
        observed_tools=observed_tools or tuple(str(tool.get("name") or "") for tool in sample.visible_tools),
        pool=public_pool,
    )
    raw_query = (
        instruction.source_query
        if instruction is not None and instruction.source_query
        else sample.task_prompt
    )
    return " ".join(str(raw_query).strip(" .").split())


def _should_run_langmem_active_profile_split(
    base_prediction: AttackPrediction,
    sample: AttackInput,
) -> bool:
    if sample.backend != "langmem":
        return False
    profile_layer = dict(
        dict(base_prediction.metadata.get("identifiability_layers", {})).get(
            "public_profile_payload",
            {},
        )
    )
    return (
        str(profile_layer.get("status") or "") == "unresolved_public_profile_payload"
        and str(profile_layer.get("selected_section") or "").strip().lower() == "music"
    )


def _run_active_langmem_profile_split(
    *,
    sample: AttackInput,
    victim_client: Any,
    base_prediction: AttackPrediction,
    decoder: Any,
) -> dict[str, Any]:
    profile_gate = dict(
        dict(base_prediction.metadata.get("identifiability_layers", {})).get(
            "public_profile_payload",
            {},
        )
    )
    first_raw_sequence = _sequence(base_prediction.metadata.get("observed_visible_tool_calls"))
    first_admitted_sequence = _sequence(
        base_prediction.metadata.get("admitted_visible_tool_calls")
    )
    if not first_admitted_sequence:
        return {
            "status": "not_available",
            "reason": "no_admitted_first_round_sequence",
        }
    first_observed_input = AttackInput.from_dict(
        {
            "backend": sample.backend,
            "benchmark": sample.benchmark,
            "sample_id": sample.sample_id,
            "task_prompt": sample.task_prompt,
            "user_id": sample.user_id,
            "task_id": sample.task_id,
            "visible_messages": [{"role": "user", "content": sample.task_prompt}],
            "visible_tools": sample.visible_tools,
            "visible_tool_results": first_admitted_sequence,
            "public_context": sample.public_context,
            "metadata": sample.metadata,
        }
    )
    split_gate = {
        "status": "available",
        "reason": "r005_active_slot_probe_requested_for_unresolved_music_profile",
        "selected_section": profile_gate.get("selected_section", "music"),
        "candidate_count": profile_gate.get("ambiguity_group_size", 0),
        "observable_fields": _observable_argument_names(sample),
    }
    return _run_langmem_candidate_split_round(
        sample=sample,
        victim_client=victim_client,
        first_observed_input=first_observed_input,
        first_raw_sequence=first_raw_sequence,
        first_admitted_sequence=first_admitted_sequence,
        profile_gate=profile_gate,
        split_gate=split_gate,
        decoder=decoder,
    )


def _observable_argument_names(sample: AttackInput) -> list[str]:
    names: list[str] = []
    for tool in sample.visible_tools:
        parameters = tool.get("parameters")
        properties = parameters.get("properties", {}) if isinstance(parameters, Mapping) else {}
        if not isinstance(properties, Mapping):
            continue
        for name in properties:
            text = str(name)
            if text not in names:
                names.append(text)
    return names


