for _canonical_key in tuple(_GENERIC_ETAPP_CANONICAL_KEYS.values()):
    _GENERIC_ETAPP_ROLE_ALIASES.setdefault(_canonical_key.lower(), _canonical_key)
    _GENERIC_ETAPP_ROLE_ALIASES.setdefault(
        re.sub(r"(?<!^)(?=[A-Z])", " ", _canonical_key).lower(),
        _canonical_key,
    )
for _alias, _canonical_key in tuple(_GENERIC_ETAPP_ROLE_ALIASES.items()):
    # Public schemas/logs often surface snake_case role names such as
    # favorite_genres or preferred_volume_level.  Treat separator style as a
    # schema-label variant, not as a benchmark-specific concrete value repair.
    if " " in _alias:
        _GENERIC_ETAPP_ROLE_ALIASES.setdefault(_alias.replace(" ", "_"), _canonical_key)
        _GENERIC_ETAPP_ROLE_ALIASES.setdefault(_alias.replace(" ", ""), _canonical_key)

