@lru_cache(maxsize=1)
def _generic_etapp_role_label_pattern() -> str:
    labels = sorted(
        {label for label in _GENERIC_ETAPP_ROLE_ALIASES if label.strip()},
        key=len,
        reverse=True,
    )
    return "|".join(re.escape(label) for label in labels)


def _generic_etapp_alias_key(label: Any) -> str:
    text = str(label or "").strip()
    if ":" in text and re.search(r"\b(?:fact|preference|profile|memory|graph)\b", text, flags=re.IGNORECASE):
        text = text.rsplit(":", 1)[-1]
    text = re.sub(r"[_-]+", " ", text)
    text = re.sub(r"\s*/\s*", "/", text)
    text = re.sub(r"\s+", " ", text)
    return text.strip(" -*,.;:").lower()


def _generic_etapp_canonical_key(label: Any) -> str:
    alias_key = _generic_etapp_alias_key(label)
    if not alias_key:
        return ""
    direct = _GENERIC_ETAPP_ROLE_ALIASES.get(alias_key) or _GENERIC_ETAPP_CANONICAL_KEYS.get(alias_key)
    if direct:
        return direct
    compact = re.sub(r"[\s_/-]+", "", alias_key)
    for alias, canonical_key in _GENERIC_ETAPP_ROLE_ALIASES.items():
        if re.sub(r"[\s_/-]+", "", alias) == compact:
            return canonical_key
    return ""


def _generic_etapp_truncate_cross_field_value(value: Any) -> str:
    text = str(value or "")
    text = re.sub(r"^\s*value\s*=\s*", "", text, flags=re.IGNORECASE)
    role_boundary = re.search(r"\s+(?:role|tool_name|value)\s*=", text, flags=re.IGNORECASE)
    if role_boundary:
        text = text[: role_boundary.start()]
    label_pattern = _generic_etapp_role_label_pattern()
    if label_pattern:
        boundary = re.search(
            rf"(?:[,;|]\s*|\s+)\b(?:{label_pattern})\s*(?:=|:|\bis\b|\bare\b|\binclude(?:s)?\b)",
            text,
            flags=re.IGNORECASE,
        )
        if boundary:
            text = text[: boundary.start()]
    text = re.split(r"\b(?:skip categories|use only concrete|write unknown only)\b", text, maxsplit=1, flags=re.IGNORECASE)[0]
    return text.strip(" -*,.;:")


def _generic_etapp_schema_role_value_pairs(text: Any) -> list[tuple[str, str]]:
    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    role_label = r"(?:Role|Field|Schema|Key|Profile\s+Key|Preference\s+Key)"
    value_label = r"(?:Value|Val|Literal)"
    boundary = rf"(?=(?:[,;|]\s*)?\b{role_label}\s*[:=]|[.;\n]|$)"
    pattern = re.compile(
        rf"\b{role_label}\s*[:=]\s*(?P<label>[^,;|.:\n]{{2,80}}?)\s+"
        rf"{value_label}\s*[:=]\s*(?P<value>.*?){boundary}",
        flags=re.IGNORECASE,
    )
    pairs: list[tuple[str, str]] = []
    for match in pattern.finditer(source):
        canonical_key = _generic_etapp_canonical_key(match.group("label"))
        value = _generic_etapp_truncate_cross_field_value(match.group("value"))
        if canonical_key and _generic_etapp_value_is_informative(value):
            pairs.append((canonical_key, value))
    return pairs


def _generic_etapp_role_value_assignment_pairs(text: Any) -> list[tuple[str, str]]:
    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    label_pattern = _generic_etapp_role_label_pattern()
    if not label_pattern:
        return []
    boundary = rf"(?=\s+(?:role|tool_name|value)\s*=|(?:[,;]\s*)?(?:{label_pattern})\s*=|[.;\n]|$)"
    patterns = (
        re.compile(
            rf"(?:^|\s)(?:role|tool_name)\s*=\s*(?P<label>{label_pattern})\s*=\s*value\s*=\s*"
            rf"(?P<value>.*?){boundary}",
            flags=re.IGNORECASE,
        ),
        re.compile(
            rf"(?:^|\s)(?:role|tool_name)\s*=\s*(?P<label>{label_pattern})\s+value\s*=\s*"
            rf"(?P<value>.*?){boundary}",
            flags=re.IGNORECASE,
        ),
        re.compile(
            rf"(?:^|\s)(?:role|tool_name)\s*=\s*(?P<label>{label_pattern})\s*:\s*"
            rf"(?P<value>.*?){boundary}",
            flags=re.IGNORECASE,
        ),
        re.compile(
            rf"(?:^|\s)value\s*=\s*(?P<label>{label_pattern})\s*=\s*"
            rf"(?P<value>.*?){boundary}",
            flags=re.IGNORECASE,
        ),
    )
    pairs: list[tuple[str, str]] = []
    for pattern in patterns:
        for match in pattern.finditer(source):
            canonical_key = _generic_etapp_canonical_key(match.group("label"))
            value = _generic_etapp_truncate_cross_field_value(match.group("value"))
            if canonical_key and _generic_etapp_value_is_informative(value):
                pairs.append((canonical_key, value))
    return pairs


def _generic_etapp_labeled_role_values(text: Any) -> list[tuple[str, str]]:
    source = " ".join(str(text or "").strip().split())
    if not source:
        return []
    label_pattern = _generic_etapp_role_label_pattern()
    if not label_pattern:
        return []
    separator = r"(?:=|:|\bis\b|\bare\b|\binclude(?:s)?\b|\bsuch as\b|\blike\b)"
    boundary = rf"(?=(?:[,;|]\s*|\s+)\b(?:role\s*=\s*|tool_name\s*=\s*)?(?:{label_pattern})\s*{separator}|[.;\n]|$)"
    pattern = re.compile(
        rf"\b(?P<label>{label_pattern})\s*{separator}\s*(?P<value>.*?){boundary}",
        flags=re.IGNORECASE,
    )
    pairs: list[tuple[str, str]] = [
        *_generic_etapp_schema_role_value_pairs(source),
        *_generic_etapp_role_value_assignment_pairs(source),
    ]
    for match in pattern.finditer(source):
        canonical_key = _generic_etapp_canonical_key(match.group("label"))
        value = _generic_etapp_truncate_cross_field_value(match.group("value"))
        if canonical_key and _generic_etapp_value_is_informative(value):
            pairs.append((canonical_key, value))
    return pairs


def _generic_etapp_sentence_role_values(text: Any) -> list[tuple[str, str]]:
    source = str(text or "")
    pairs: list[tuple[str, str]] = []
    for segment in re.split(r"(?<=[.;!?])\s+|\n+", source):
        sentence = " ".join(segment.strip(" -*").split())
        if not sentence:
            continue
        if "=" in sentence and _generic_etapp_labeled_role_values(sentence):
            continue
        lowered = sentence.lower()
        if re.search(r"\b(?:i am|i'm|user is|profile is)\s+([^.;]+)", sentence, flags=re.IGNORECASE):
            value = re.sub(
                r"^.*?\b(?:i am|i'm|user is|profile is)\s+",
                "",
                sentence,
                count=1,
                flags=re.IGNORECASE,
            )
            value = _generic_etapp_truncate_cross_field_value(value)
            if any(marker in value.lower() for marker in ("friendly", "focused", "organized", "creative", "analytical", "reliable", "optimistic", "introverted", "extroverted", "pragmatic", "empathetic")):
                pairs.append(("Character", value))
        if re.search(r"\b(?:works as|works in|profession is|occupation is)\b", lowered):
            match = re.search(r"\b(?:works as|works in|profession is|occupation is)\s+(?:a|an)?\s*([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                pairs.append(("Occupation", _generic_etapp_truncate_cross_field_value(match.group(1))))
        student_match = re.search(
            r"\b(?P<student>(?:college|university|graduate|undergraduate)\s+student)"
            r"(?:\s*,?\s*(?:major(?:s|ing)? in|stud(?:y|ies|ying))\s+(?P<major>[^.;]+))?",
            sentence,
            flags=re.IGNORECASE,
        )
        if student_match:
            student = _generic_etapp_clean_profile_value(student_match.group("student"))
            major = _generic_etapp_clean_profile_value(student_match.group("major") or "")
            pairs.append(("Occupation", f"{student},majors in {major}" if major else student))
            if major:
                pairs.append(("EducationLevel", major))
        if re.search(r"\b(?:degree|studied|studies|major(?:ed)? in|education)\b", lowered):
            match = re.search(r"\b(?:degree in|studied|studies|major(?:ed)? in|education(?: is|:)?)\s+([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                pairs.append(("EducationLevel", _generic_etapp_truncate_cross_field_value(match.group(1))))
        if re.search(r"\b(?:fluent in|speaks|native speaker of|conversational)\b", lowered):
            match = re.search(r"\b(?:fluent in|speaks|native speaker of|conversational(?: in)?)\s+([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                pairs.append(("LanguageProficiency", _generic_etapp_truncate_cross_field_value(match.group(1))))
        location_match = re.search(
            r"\b(?:you(?:'re| are)|user is|located|based|living)\s+(?:in|near|around)\s+([A-Z][A-Za-z .'-]{2,60}?)(?=\s+\b(?:and|while|with|but|who|that)\b|[.;,]|$)",
            sentence,
        )
        if location_match:
            pairs.append(("Location", _generic_etapp_truncate_cross_field_value(location_match.group(1))))
        if re.search(r"\b(?:fixed income|income|budget)\b", lowered):
            match = re.search(r"\b(?:income|budget(?: context)?|fixed income)\s*(?:is|:|=|from)?\s*([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                pairs.append(("IncomeLevel", _generic_etapp_truncate_cross_field_value(match.group(1))))
        if re.search(r"\b(?:daily|usually|routine|every morning|wind down|water aerobics|walks?)\b", lowered):
            match = re.search(r"\b(?:enjoy(?:s)?|keeping active with|routine(?: includes)?|usually|daily)\s+([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                value = _generic_etapp_routine_clause_value(match.group(1))
                if value:
                    pairs.append(("Routine", value))
        short_walk_match = re.search(
            r"\bprefer(?:s)?\s+short\s+walks?\s+(?:in|through|around|along)\s+([^.;]+)",
            sentence,
            flags=re.IGNORECASE,
        )
        if short_walk_match:
            pairs.append(("ShortTermWalk", f"prefer short walks in {_generic_etapp_truncate_cross_field_value(short_walk_match.group(1))}"))
        if re.search(r"\b(?:hobb(?:y|ies)|enjoy(?:s)?|interested in|love(?:s)?|likes?)\b", lowered):
            match = re.search(r"\b(?:hobb(?:y|ies)(?: include| are)?|enjoy(?:s)?|interested in|love(?:s)?|likes?)\s+([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                value = _generic_etapp_activity_clause_value(match.group(1))
                if value:
                    pairs.append(("Hobbies", value))
        if re.search(r"\b(?:shops?|shopping|stores?|brands?)\b", lowered):
            match = re.search(r"\b(?:shops? at|shopping(?: preferences)?(?: include| are)?|brands?(?: include| are)?|supporting)\s+([^.;]+)", sentence, flags=re.IGNORECASE)
            if match:
                value = _generic_etapp_shopping_clause_value(match.group(1))
                if value:
                    pairs.append(("ShoppingPreferences", value))
        if re.search(r"\b(?:music|artist|song|track|jazz|classical|rock|country|folk|blues)\b", lowered):
            artist_match = re.search(
                r"\b(?:preferred\s+artists?|favorite\s+artists?|artists?|music by|inspired by)\s*(?:include|includes|are|is|:|=)?\s+([^.;]+)",
                sentence,
                flags=re.IGNORECASE,
            )
            if artist_match:
                pairs.append(("PreferArtists", _generic_etapp_truncate_cross_field_value(artist_match.group(1))))
            genre_match = re.search(r"\b(?:genre|genres)\s+(?:include|includes|are|is|like|such as)?\s*([^.;]+)", sentence, flags=re.IGNORECASE)
            if genre_match and any(marker in genre_match.group(1).lower() for marker in ("jazz", "classical", "rock", "country", "folk", "blues", "pop", "electronic")):
                pairs.append(("FavoriteGenres", _generic_etapp_truncate_cross_field_value(genre_match.group(1))))
            enjoyed_music_match = re.search(
                r"\b(?:enjoy|enjoys|like|likes)\s+([^.;]{1,100}?\b(?:music|jazz|classical|rock|country|folk|blues|pop|electronic)\b[^.;]*)",
                sentence,
                flags=re.IGNORECASE,
            )
            if enjoyed_music_match:
                music_value = _generic_etapp_truncate_cross_field_value(enjoyed_music_match.group(1))
                if any(marker in music_value.lower() for marker in ("jazz", "classical", "rock", "country", "folk", "blues", "pop", "electronic")):
                    pairs.append(("FavoriteGenres", music_value))
            track_like_match = re.search(
                r"\btracks?\s+like\s+([^.;]+)",
                sentence,
                flags=re.IGNORECASE,
            )
            if track_like_match:
                pairs.append(("FrequentlyPlayedTracks", _generic_etapp_truncate_cross_field_value(track_like_match.group(1))))
        if re.search(r"\b(?:extended stays?|long stays?)\b", lowered):
            match = re.search(
                r"\b(?:occasionally\s+)?(?:enjoy(?:s)?\s+)?((?:extended|long)\s+stays?[^.;]*)",
                sentence,
                flags=re.IGNORECASE,
            )
            if match:
                pairs.append(("LongTermTravel", _generic_etapp_truncate_cross_field_value(match.group(1))))
        media_match = re.search(
            r"\b(?:enjoy|enjoys|like|likes)\s+([^.;]*\b(?:movies?|dramas?|tv shows?|documentaries|comed(?:y|ies)|thrillers?)\b[^.;]*)",
            sentence,
            flags=re.IGNORECASE,
        )
        if media_match:
            pairs.append(("MoviesAndTVShows", _generic_etapp_truncate_cross_field_value(media_match.group(1))))
    return [
        (key, value)
        for key, value in pairs
        if key and _generic_etapp_value_is_informative(value)
    ]


def _generic_etapp_select_clauses(value: Any, markers: Sequence[str]) -> str:
    text = _generic_etapp_truncate_cross_field_value(value)
    clauses = [
        clause.strip(" -*,.;:")
        for clause in re.split(r",|\bor\b|\band\b", text, flags=re.IGNORECASE)
        if clause.strip(" -*,.;:")
    ]
    selected: list[str] = []
    for clause in clauses:
        lowered = clause.lower()
        if any(marker in lowered for marker in markers):
            selected.append(clause)
        elif selected:
            break
    if not selected:
        return _generic_etapp_clean_profile_value(text)
    return _generic_etapp_clean_profile_value(", ".join(selected))


def _generic_etapp_routine_clause_value(value: Any) -> str:
    return _generic_etapp_select_clauses(
        value,
        (
            "daily",
            "morning",
            "evening",
            "routine",
            "walk",
            "water aerobics",
            "workout",
            "exercise",
            "commute",
            "wind down",
            "meal prep",
        ),
    )


def _generic_etapp_activity_clause_value(value: Any) -> str:
    return _generic_etapp_select_clauses(
        value,
        (
            "walk",
            "aerobics",
            "reading",
            "book",
            "garden",
            "golf",
            "fishing",
            "running",
            "yoga",
            "sports",
            "community",
            "painting",
            "music",
            "travel",
            "fitness",
            "cooking",
            "writing",
        ),
    )


def _generic_etapp_shopping_clause_value(value: Any) -> str:
    return _generic_etapp_select_clauses(
        value,
        ("shop", "store", "brand", "wear", "clothing", "product", "sale", "coupon", "gear", "durable"),
    )


def _regularize_etapp_visible_action_primitives(
    predicted: dict[str, Any],
    *,
    sample: AttackInput,
    sequence: Sequence[Mapping[str, Any]],
    profile_sequences: Sequence[Sequence[Mapping[str, Any]]] = (),
    profile_response_texts: Sequence[Any] = (),
) -> dict[str, Any]:
    evidence_sequences = [
        [dict(item) for item in candidate_sequence if isinstance(item, Mapping)]
        for candidate_sequence in (sequence, *profile_sequences)
        if candidate_sequence
    ]
    signature = _etapp_visible_action_signature(sample=sample, sequence=sequence)
    signature_source = "original_visible_action"
    if signature is None:
        for candidate_sequence in evidence_sequences:
            signature = _etapp_visible_action_signature(sample=sample, sequence=candidate_sequence)
            if signature is not None:
                signature_source = "ordinary_followup_action"
                break
    if signature is None:
        has_profile_text = any(
            _etapp_profile_response_text_and_scope(response_entry)[0].strip()
            for response_entry in profile_response_texts
        )
        if not has_profile_text:
            return {"status": "not_applied", "reason": "no_visible_action_or_profile_evidence"}
        signature_source = "ordinary_followup_profile_text"
        signature = {
            "intent": str(sample.task_id or sample.sample_id or "etapp_task"),
            "key_decision_fields": {},
            "proactive": _is_proactive_probe(sample),
            "tool_sequence": [],
        }

    signature_item = {
        "source_ref": f"visible_etapp_action_signature:{signature_source}",
        "action_signature": json.dumps(signature, ensure_ascii=False, sort_keys=True),
    }
    tool_sequence = signature.get("tool_sequence") if isinstance(signature, Mapping) else None
    if isinstance(tool_sequence, Sequence) and not isinstance(tool_sequence, (str, bytes, bytearray)):
        replay_actions = [copy.deepcopy(item) for item in tool_sequence if isinstance(item, Mapping)]
        if replay_actions:
            predicted["replayed_behavior"] = replay_actions

    primitive_items: list[Any] = []
    public_memory_id = _etapp_public_memory_id(sample)
    if public_memory_id:
        primitive_items.append(public_memory_id)
    primitive_items.append("injection_enabled=true")
    visible_action_keys: set[str] = {"tool_name"}
    for action in signature.get("tool_sequence", []):
        if not isinstance(action, Mapping):
            continue
        tool_name = str(action.get("tool_name") or "").strip()
        if tool_name:
            primitive_items.append(f"tool_name={tool_name}")
        action_args = action.get("normalized_args")
        if not isinstance(action_args, Mapping):
            action_args = action.get("key_decision_fields")
        for key, value in dict(action_args if isinstance(action_args, Mapping) else {}).items():
            if value not in (None, "", [], {}):
                visible_action_keys.add(str(key).strip().lower())
                primitive_items.append(f"{key}={value}")
    for key, value in dict(signature.get("key_decision_fields") or {}).items():
        if value not in (None, "", [], {}):
            visible_action_keys.add(str(key).strip().lower())
            primitive_items.append(f"{key}={value}")
            if str(key).strip().lower() == "city":
                visible_action_keys.add("location")
                primitive_items.append(f"location={value}")
    backend_key_for_signature = str(sample.backend or "").strip().lower()
    if "mem0" in backend_key_for_signature:
        predicted.setdefault("metadata", {})
        if isinstance(predicted["metadata"], dict):
            predicted["metadata"]["etapp_action_signature"] = signature_item
    else:
        primitive_items.append(signature_item)

    profile_facts: list[Any] = []
    profile_preferences: list[Any] = []
    for profile_sequence in evidence_sequences or (sequence,):
        projected = _etapp_profile_atoms_from_visible_sequence(profile_sequence)
        profile_facts.extend(projected["facts"])
        profile_preferences.extend(projected["preferences"])
    raw_profile_response_texts: list[str] = []
    for response_entry in profile_response_texts:
        response_text, evidence_scope = _etapp_profile_response_text_and_scope(response_entry)
        if response_text:
            raw_profile_response_texts.append(response_text)
        projected = _etapp_profile_atoms_from_visible_text(
            response_text,
            evidence_scope=evidence_scope,
        )
        profile_facts.extend(projected["facts"])
        profile_preferences.extend(projected["preferences"])
    if raw_profile_response_texts:
        predicted.setdefault("metadata", {})
        if isinstance(predicted.get("metadata"), dict):
            predicted["metadata"]["etapp_profile_response_texts"] = raw_profile_response_texts[:16]

    visible_tool_names = {
        str(tool.get("name") or "").strip()
        for tool in sample.visible_tools
        if isinstance(tool, Mapping)
    }
    for evidence_sequence in evidence_sequences:
        for action in evidence_sequence:
            if isinstance(action, Mapping):
                tool_name = str(action.get("tool_name") or action.get("name") or "").strip()
                if tool_name:
                    visible_tool_names.add(tool_name)
    profile_signal_source_text = "\n".join(
        str(item)
        for item in [*profile_facts, *profile_preferences, *primitive_items, *raw_profile_response_texts]
        if str(item).strip()
    )
    profile_signal_text = profile_signal_source_text.lower()
    if {"play_music", "get_music_list_in_favorites"} & visible_tool_names and (
        "frequentlyplayedtracks=" in profile_signal_text
        or "preferredvolumelevel=" in profile_signal_text
        or "music_name=" in profile_signal_text
        or "volume_level=" in profile_signal_text
    ):
        primitive_items.append("tool_name=play_music")
    if "get_music_list_in_favorites" in visible_tool_names and (
        "frequentlyplayedtracks=" in profile_signal_text
        or "favoritegenres=" in profile_signal_text
        or "musicgenres=" in profile_signal_text
        or "preferartists=" in profile_signal_text
    ):
        primitive_items.append("tool_name=get_music_list_in_favorites")
    if {
        "boil_water_in_home",
        "control_bathtub_in_home",
        "control_light_in_home",
        "get_home_temperature_and_humidity",
    } & visible_tool_names:
        if re.search(r"\blocation\s*=\s*bedroom\b|\blocation is bedroom\b", profile_signal_text):
            primitive_items.append("location=bedroom")
        if "control_bathtub_in_home" in visible_tool_names and re.search(
            r"\b(?:fill\s*=\s*true|water_level\s*=|bathtub|bath)\b",
            profile_signal_text,
        ):
            primitive_items.append("tool_name=control_bathtub_in_home")
        if "control_light_in_home" in visible_tool_names and re.search(
            r"\b(?:action\s*=\s*on|light(?:s)?\b|turn(?:ing)?\s+on)\b",
            profile_signal_text,
        ):
            primitive_items.append("tool_name=control_light_in_home")
        if "get_home_temperature_and_humidity" in visible_tool_names and re.search(
            r"\b(?:temperature\s*=|humidity|home temperature)\b",
            profile_signal_text,
        ):
            primitive_items.append("tool_name=get_home_temperature_and_humidity")
    if "get_current_health_and_mood_status" in visible_tool_names and (
        re.search(r"\b(?:tired|mood|health|fatigue|energy)\b", _lower_clean(sample.task_prompt))
        or re.search(r"\b(?:mood|health|tired|fatigue|energy)\b", profile_signal_text)
    ):
        primitive_items.append("tool_name=get_current_health_and_mood_status")

    backend_key = str(sample.backend or "").strip().lower()
    music_name = _generic_etapp_music_name_from_atoms(profile_signal_source_text)
    if music_name:
        primitive_items.append(f"music_name={music_name}")
    primitive_items = _compress_etapp_tool_state_items(
        primitive_items,
        sample=sample,
        visible_tool_names=visible_tool_names,
        preserve_keys=visible_action_keys,
    )

    before_counts = {
        "facts": len(predicted.get("facts", []) if isinstance(predicted.get("facts"), list) else []),
        "preferences": len(predicted.get("preferences", []) if isinstance(predicted.get("preferences"), list) else []),
        "constraints": len(predicted.get("constraints", []) if isinstance(predicted.get("constraints"), list) else []),
        "relations": len(predicted.get("relations", []) if isinstance(predicted.get("relations"), list) else []),
        "tool_state": len(predicted.get("tool_state", []) if isinstance(predicted.get("tool_state"), list) else []),
    }
    fact_cap, preference_cap = _etapp_projection_caps(sample.backend)
    regularized_facts = _regularize_etapp_profile_key_values(profile_facts)
    regularized_preferences = _regularize_etapp_profile_key_values(profile_preferences)
    domain_context = _generic_etapp_domain_context(
        sample=sample,
        visible_tool_names=visible_tool_names,
        evidence_text=profile_signal_text,
    )
    fact_selection_cap = max(fact_cap + 3, fact_cap * 2)
    preference_selection_cap = max(preference_cap + 3, preference_cap * 2)
    fact_support = _etapp_profile_support_counts(profile_facts)
    preference_support = _etapp_profile_support_counts(profile_preferences)
    projected_facts = _select_etapp_profile_atom_budget(
        regularized_facts,
        cap=fact_selection_cap,
        category="facts",
        support_counts=fact_support,
        domain_context=domain_context,
        backend_key=backend_key,
    )
    projected_preferences = _select_etapp_profile_atom_budget(
        regularized_preferences,
        cap=preference_selection_cap,
        category="preferences",
        support_counts=preference_support,
        domain_context=domain_context,
        backend_key=backend_key,
    )

    predicted["facts"] = _dedupe_model_items(projected_facts)
    predicted["preferences"] = _dedupe_model_items(projected_preferences)
    predicted["constraints"] = []
    predicted["relations"] = []
    predicted["tool_state"] = _dedupe_model_items(primitive_items)
    return {
        "status": "applied",
        "model": "visibility_ladder_schema_role_value_lattice_v5",
        "visibility_ladder_signature_source": signature_source,
        "before_counts": before_counts,
        "regularized_fact_count": len(regularized_facts),
        "regularized_preference_count": len(regularized_preferences),
        "supported_fact_count": sum(1 for item in regularized_facts if fact_support.get(str(item), 0) > 1),
        "supported_preference_count": sum(
            1 for item in regularized_preferences if preference_support.get(str(item), 0) > 1
        ),
        "after_fact_count": len(predicted["facts"]),
        "after_preference_count": len(predicted["preferences"]),
        "after_tool_state_count": len(predicted["tool_state"]),
        "fact_budget_cap": fact_selection_cap,
        "preference_budget_cap": preference_selection_cap,
        "domain_context": domain_context or "general",
        "projection_selection_mode": "schema_role_value_lattice_budgeted_selection",
        "public_memory_id_present": bool(public_memory_id),
        "concrete_value_repairs_enabled": False,
    }


def _compress_etapp_tool_state_items(
    items: Sequence[Any],
    *,
    sample: AttackInput,
    visible_tool_names: set[str],
    preserve_keys: set[str] | None = None,
) -> list[Any]:
    task_text = _lower_clean(sample.task_prompt)
    music_context = bool({"play_music", "get_music_list_in_favorites"} & visible_tool_names) or any(
        marker in task_text for marker in ("music", "song", "track", "artist", "playlist")
    )
    compressed: list[Any] = []
    noisy_keys = {"category", "content", "title", "reminder", "end_time"}
    preserve_keys = {str(key).strip().lower() for key in (preserve_keys or set()) if str(key).strip()}
    for item in items:
        if isinstance(item, Mapping):
            compressed.append(item)
            continue
        text = str(item or "").strip()
        lowered = text.lower()
        key = lowered.split("=", 1)[0].strip() if "=" in lowered else ""
        if key in noisy_keys and key not in preserve_keys:
            continue
        if any(
            f" {noise_key} is " in lowered
            for noise_key in noisy_keys
            if noise_key not in preserve_keys
        ):
            continue
        if "current_city" in lowered:
            continue
        if (key == "music_name" or " music_name is " in lowered) and not music_context:
            continue
        compressed.append(item)
    return _dedupe_model_items(compressed)


def _regularize_etapp_profile_key_values(items: Sequence[str]) -> list[str]:
    by_key: dict[str, list[str]] = {}
    passthrough: list[str] = []
    for raw_item in items:
        for text in _backend_projection_unwrapped_values(raw_item):
            if not text:
                continue
            for labeled_key, labeled_value in _generic_etapp_labeled_role_values(text):
                for labeled_normalized in _generic_etapp_normalize_key_value_items(labeled_key, labeled_value):
                    if labeled_normalized and _generic_etapp_atom_type_compatible(labeled_normalized):
                        labeled_normalized_key = _generic_etapp_canonical_key(labeled_normalized.split("=", 1)[0])
                        if labeled_normalized_key:
                            by_key.setdefault(labeled_normalized_key, []).append(labeled_normalized)
                            for expanded in _generic_etapp_cross_role_expansions(labeled_normalized):
                                expanded_key = _generic_etapp_canonical_key(expanded.split("=", 1)[0])
                                if expanded_key:
                                    by_key.setdefault(expanded_key, []).append(expanded)
            if "=" not in text:
                if _generic_etapp_value_is_informative(text):
                    passthrough.append(text)
                continue
            key, _, raw_value = text.partition("=")
            canonical_key = _generic_etapp_canonical_key(key)
            if not canonical_key:
                continue
            for nested_key, nested_value in _generic_etapp_labeled_role_values(raw_value):
                for nested_normalized in _generic_etapp_normalize_key_value_items(nested_key, nested_value):
                    if nested_normalized and _generic_etapp_atom_type_compatible(nested_normalized):
                        nested_normalized_key = _generic_etapp_canonical_key(nested_normalized.split("=", 1)[0])
                        if nested_normalized_key:
                            by_key.setdefault(nested_normalized_key, []).append(nested_normalized)
            for normalized in _generic_etapp_normalize_key_value_items(canonical_key, raw_value):
                if normalized and _generic_etapp_atom_type_compatible(normalized):
                    normalized_key = _generic_etapp_canonical_key(normalized.split("=", 1)[0]) or canonical_key
                    by_key.setdefault(normalized_key, []).append(normalized)
                    for expanded in _generic_etapp_cross_role_expansions(normalized):
                        expanded_key = _generic_etapp_canonical_key(expanded.split("=", 1)[0])
                        if expanded_key:
                            by_key.setdefault(expanded_key, []).append(expanded)

    _augment_etapp_cross_role_profile_values(by_key)
    output = list(passthrough)
    for key in sorted(by_key):
        candidates = _dedupe_texts(by_key[key])
        ranked = sorted(candidates, key=_etapp_profile_atom_score, reverse=True)
        if key in _GENERIC_ETAPP_MULTI_VALUE_KEYS:
            output.extend(ranked[:4])
        else:
            output.append(ranked[0])
    return _dedupe_texts(output)


def _partition_regularized_etapp_profile_atoms(
    facts: Sequence[str],
    preferences: Sequence[str],
) -> tuple[list[str], list[str]]:
    regularized = _regularize_etapp_profile_key_values([*facts, *preferences])
    fact_atoms: list[str] = []
    preference_atoms: list[str] = []
    for item in regularized:
        key = str(item).split("=", 1)[0] if "=" in str(item) else str(item)
        canonical_key = _generic_etapp_canonical_key(key)
        if canonical_key in _GENERIC_ETAPP_FACT_KEYS:
            fact_atoms.append(item)
        elif canonical_key:
            preference_atoms.append(item)
    return _dedupe_texts(fact_atoms), _dedupe_texts(preference_atoms)


def _generic_etapp_normalize_key_value_items(key: str, raw_value: Any) -> list[str]:
    value = _generic_etapp_clean_profile_value(_generic_etapp_truncate_cross_field_value(raw_value))
    if not _generic_etapp_value_is_informative(value):
        return []

    if key == "Age":
        match = re.search(r"\b([1-9][0-9]{0,2})\b", value)
        if not match:
            return []
        age = int(match.group(1))
        if age < 5 or age > 110:
            return []
        return [f"Age={age}"]

    if key == "Gender":
        lowered = value.lower()
        if re.search(r"\b(?:nonbinary|non-binary|genderqueer)\b", lowered):
            return ["Gender=non-binary"]
        if re.search(r"\b(?:female|woman)\b", lowered):
            return ["Gender=female"]
        if re.search(r"\b(?:male|man)\b", lowered):
            return ["Gender=male"]
        return []

    if key == "LanguageProficiency":
        language_value = re.split(
            r"\b(?:and\s+)?(?:i\s+)?(?:look\s+forward|looking\s+forward|happy\s+to|nice\s+to)\b",
            value,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0].strip(" ,.;:!")
        language_value = re.sub(r"^(?:both\s+)", "", language_value, flags=re.IGNORECASE).strip(" ,.;:!")
        if not re.search(
            r"\b(?:english|spanish|french|german|italian|mandarin|chinese|japanese|korean|arabic|hindi|portuguese|russian|fluent|native|conversational|basic|intermediate|advanced)\b",
            language_value,
            flags=re.IGNORECASE,
        ):
            return []
        if re.fullmatch(
            r"[A-Za-z]+(?:\s+(?:and|,)\s*[A-Za-z]+)+",
            language_value,
            flags=re.IGNORECASE,
        ):
            language_value = f"fluent in {language_value}"
        return [f"LanguageProficiency={_generic_etapp_normalize_free_text_value(language_value)}"]

    if key == "PreferredVolumeLevel":
        numbers = [
            max(0, min(100, int(item)))
            for item in re.findall(r"\b([0-9]{1,3})\s*%?\b", value)
        ]
        if len(numbers) >= 2:
            return [f"PreferredVolumeLevel=prefer {numbers[0]} {numbers[1]} volume"]
        if numbers:
            return [f"PreferredVolumeLevel=prefer {numbers[0]} volume"]
        return [f"PreferredVolumeLevel={value}"] if _generic_etapp_value_is_informative(value) else []

    if key == "PreferArtists":
        value = re.split(
            r"\b(?:and\s+you\s+enjoy|and\s+enjoy|you\s+enjoy|you\s+like|movies?|tv shows?)\b",
            value,
            maxsplit=1,
            flags=re.IGNORECASE,
        )[0].strip(" ,.;:")
        if re.search(r"\b(?:movies?|tv shows?|dramas?|documentar(?:y|ies)|comed(?:y|ies)|thrillers?|reality)\b", value, flags=re.IGNORECASE):
            return []

    values = (
        _split_etapp_profile_values(
            value,
            preserve_parentheses=key == "FrequentlyPlayedTracks",
        )
        if key in _GENERIC_ETAPP_SPLIT_VALUE_KEYS
        else [value]
    )
    normalized: list[str] = []
    if key in _GENERIC_ETAPP_SPLIT_VALUE_KEYS and key != "FrequentlyPlayedTracks" and len(values) > 1:
        aggregate = _generic_etapp_normalize_free_text_value(value)
        if key in {"FavoriteGenres", "MusicGenres"}:
            aggregate = _generic_etapp_normalize_short_list_value(aggregate).lower()
        elif key in {"PreferArtists"}:
            aggregate = _generic_etapp_normalize_short_list_value(aggregate)
        if _generic_etapp_value_is_informative(aggregate):
            normalized.append(f"{key}={aggregate}")
    for item_value in values:
        cleaned = _generic_etapp_clean_profile_value(item_value)
        if not _generic_etapp_value_is_informative(cleaned):
            continue
        if key == "FrequentlyPlayedTracks":
            cleaned = _generic_etapp_normalize_track_value(cleaned)
            if not cleaned:
                continue
        elif key == "PreferArtists":
            cleaned = _generic_etapp_normalize_short_list_value(cleaned)
        elif key in {"FavoriteGenres", "MusicGenres"}:
            cleaned = _generic_etapp_normalize_short_list_value(cleaned).lower()
        else:
            cleaned = _generic_etapp_normalize_free_text_value(cleaned)
        if _generic_etapp_value_is_informative(cleaned):
            normalized.append(f"{key}={cleaned}")
    return _dedupe_texts(normalized)


def _generic_etapp_cross_role_expansions(normalized_item: str) -> list[str]:
    key, _, raw_value = str(normalized_item or "").partition("=")
    value = _generic_etapp_clean_profile_value(raw_value)
    lowered = value.lower()
    expansions: list[str] = []
    if key in {"CulturalPreferences", "Interests", "InterestActivity", "Hobbies"} and re.search(
        r"\b(?:friendly|community-focused|optimistic|organized|empathetic|detail-oriented|creative|"
        r"introspective|analytical|ambitious|hardworking|pragmatic|sociable|motivated|reliable)\b",
        lowered,
    ):
        expansions.append(f"Character={value}")
    if key == "Routine" and re.search(
        r"\b(?:strength training|cardiovascular|outdoor activities|running|free weight|yoga|tabata|hiking|cycling|golf|sailing|workouts?|fitness)\b",
        lowered,
    ):
        expansions.append(f"Preferences={value}")
    if key == "TravelHabits" and re.search(r"\b(?:long stays?|extended stays?|business events?|relaxation|luxury amenities)\b", lowered):
        expansions.append(f"LongTermTravel={value}")
    if key == "TravelHabits" and re.search(r"\b(?:short walk|walks?|nearby|local outing)\b", lowered):
        expansions.append(f"ShortTermWalk={value}")
    if key == "LanguageProficiency" and re.search(
        r"\b(?:cuisine|cuisines|traditions?|cultural|culture|heritage|mediterranean|asian|hispanic)\b",
        lowered,
    ):
        expansions.append(f"CulturalPreferences={value}")
    if key in {"CulturalPreferences", "Interests", "InterestActivity", "ShoppingPreferences", "Hobbies", "Preferences"}:
        if re.search(r"\b(?:music|album|artist|band|song|track|playlist)\b", lowered):
            for match in re.finditer(r"\bmusic\s*\((?P<genres>[^()]{2,180})\)", value, flags=re.IGNORECASE):
                for normalized in _generic_etapp_normalize_key_value_items("MusicGenres", match.group("genres")):
                    expansions.append(normalized)
            artist_texts: list[str] = []
            for match in re.finditer(r"\b(?:albums?|artists?|bands?)\s*\((?P<artists>[^()]{2,160})\)?", value, flags=re.IGNORECASE):
                artist_texts.append(match.group("artists"))
            for match in re.finditer(
                r"\b(?:artists?|bands?|music by|listens? to)\s*(?:include|includes|are|is|:|=)?\s*(?P<artists>[^.;()]{2,160})",
                value,
                flags=re.IGNORECASE,
            ):
                artist_texts.append(match.group("artists"))
            for artist_text in artist_texts:
                for normalized in _generic_etapp_normalize_key_value_items("PreferArtists", artist_text):
                    expansions.append(normalized)
            genre_hits = [
                genre
                for genre in (
                    "alternative rock",
                    "experimental electronic",
                    "ambient",
                    "rock",
                    "pop",
                    "jazz",
                    "classical",
                    "country",
                    "folk",
                    "blues",
                    "electronic",
                    "hip hop",
                    "indie",
                    "acoustic",
                )
                if re.search(rf"\b{re.escape(genre)}\b", lowered)
            ]
            if genre_hits:
                expansions.append(f"MusicGenres={', '.join(genre_hits)}")
            preferred_artist_match = re.search(
                r"\bprefer(?:s|red)?\s+(?P<artist>[A-Z][A-Za-z0-9 .&'-]{1,80})",
                value,
                flags=re.IGNORECASE,
            )
            if preferred_artist_match:
                for normalized in _generic_etapp_normalize_key_value_items("PreferArtists", preferred_artist_match.group("artist")):
                    expansions.append(normalized)
    if key in {"Interests", "InterestActivity", "Hobbies"} and re.search(
        r"\b(?:rock climbing|weight training|yoga|urban cycling|jogging|running|cycling|fitness|workout|exercise)\b",
        lowered,
    ):
        expansions.append(f"Preferences={value}")
    if key == "Character" and re.search(r"\b(?:routine|daily|walks?|hikes?|weekend)\b", lowered):
        routine_value = _generic_etapp_routine_clause_value(value)
        if routine_value:
            expansions.append(f"Routine={routine_value}")
    return expansions


def _augment_etapp_cross_role_profile_values(by_key: dict[str, list[str]]) -> None:
    travel_values = [
        value
        for item in by_key.get("TravelHabits", [])
        for _, _, value in [str(item).partition("=")]
        if value
    ]
    place_values = [
        value
        for item in by_key.get("FavoriteTravelPlaces", [])
        for _, _, value in [str(item).partition("=")]
        if value
    ]
    if not travel_values:
        return
    for travel_value in travel_values:
        lowered = travel_value.lower()
        if not re.search(r"\b(?:long stays?|extended stays?|business events?|relaxation|luxury)\b", lowered):
            continue
        if place_values:
            for place_value in place_values[:2]:
                by_key.setdefault("LongTermTravel", []).append(
                    f"LongTermTravel={travel_value} in {place_value}"
                )
        else:
            by_key.setdefault("LongTermTravel", []).append(f"LongTermTravel={travel_value}")


_GENERIC_ETAPP_ACTIVITY_ONLY_MARKERS = (
    "aerobics",
    "beach volleyball",
    "fitness",
    "golf",
    "group fitness",
    "hiking",
    "hiit",
    "rollerblading",
    "skiing",
    "sports",
    "walk",
    "workout",
    "yoga",
)

_GENERIC_ETAPP_TRAVEL_PLACE_MARKERS = (
    "beach",
    "city",
    "coastal",
    "destination",
    "festival",
    "landmark",
    "museum",
    "nature retreat",
    "park",
    "town",
    "travel",
)

_GENERIC_ETAPP_RECOMMENDATION_MARKERS = (
    "brief:",
    "candidate choice",
    "chosen choice",
    "i recommend",
    "outing brief",
    "personal cue",
    "recommend a",
    "recommend an",
    "role=value",
    "start your day",
    "tool cue",
)


def _generic_etapp_atom_type_compatible(item: Any) -> bool:
    key, value = _generic_etapp_atom_key_value(item)
    if not key or not _generic_etapp_value_is_informative(value):
        return False
    lowered = value.lower()
    if any(marker in lowered for marker in _GENERIC_ETAPP_RECOMMENDATION_MARKERS):
        return False
    if "preferences=none" in lowered or lowered in {"user_location", "default_location", "current"}:
        return False
    if key == "Location":
        return not lowered.startswith(("user_", "default_", "current"))
    if key == "Age":
        return bool(re.fullmatch(r"[1-9][0-9]{0,2}", value.strip()))
    if key == "Gender":
        return lowered in {"male", "female", "non-binary"}
    if key == "FrequentlyPlayedTracks":
        return not _etapp_bad_track_value(lowered)
    if key == "FavoriteTravelPlaces":
        has_activity = any(marker in lowered for marker in _GENERIC_ETAPP_ACTIVITY_ONLY_MARKERS)
        has_place = any(marker in lowered for marker in _GENERIC_ETAPP_TRAVEL_PLACE_MARKERS)
        return not (has_activity and not has_place)
    if key in {"FavoriteGenres", "MusicGenres", "PreferArtists"}:
        return len(value) <= 160 and not _generic_etapp_value_has_role_boundary(value)
    if key == "Routine":
        return not any(marker in lowered for marker in ("recommend", "brief", "candidate", "chosen"))
    if key == "ShoppingPreferences":
        if lowered in {"preferences", "preference", "preferences none"}:
            return False
        return "preferences=none" not in lowered
    return not _generic_etapp_value_has_role_boundary(value)


def _generic_etapp_clean_profile_value(value: Any) -> str:
    cleaned = _clean_etapp_profile_value(_generic_etapp_truncate_cross_field_value(value))
    cleaned = cleaned.strip(" \"'`[]{}()")
    cleaned = re.sub(r"\s+", " ", cleaned)
    cleaned = re.sub(r"\s+([,.;:])", r"\1", cleaned)
    return cleaned.strip(" -*,.;:")


def _generic_etapp_value_is_informative(value: Any) -> bool:
    text = str(value or "").strip(" -*,.;:").lower()
    if text in _GENERIC_ETAPP_EMPTY_VALUES:
        return False
    if not text or len(text) < 2:
        return False
    if text.startswith(("not specified", "unspecified", "unknown", "no specific")):
        return False
    if text in {"the user", "user", "profile", "preference", "preferences"}:
        return False
    return True


def _generic_etapp_normalize_track_value(value: str) -> str:
    cleaned = _generic_etapp_clean_profile_value(value)
    if not cleaned:
        return ""
    by_match = re.match(
        r"(?P<track>.+?)\s+\bby\b\s+(?P<artist>.+)$",
        cleaned,
        flags=re.IGNORECASE,
    )
    if by_match:
        track = _generic_etapp_clean_profile_value(by_match.group("track"))
        artist = _generic_etapp_clean_profile_value(by_match.group("artist"))
        if track and artist:
            return f"{track} - {artist}"
    paren_match = re.match(r"(?P<track>.+?)\s*\((?P<artist>[^()]{2,120})\)?\s*$", cleaned)
    if paren_match:
        track = _generic_etapp_clean_profile_value(paren_match.group("track"))
        artist = _generic_etapp_clean_profile_value(paren_match.group("artist"))
        if track and artist:
            return f"{track} - {artist}"
    dash_match = re.match(r"(?P<track>.+?)\s*[-–]\s*(?P<artist>.+)$", cleaned)
    if dash_match:
        track = _generic_etapp_clean_profile_value(dash_match.group("track"))
        artist = _generic_etapp_clean_profile_value(dash_match.group("artist"))
        if track and artist:
            return f"{track} - {artist}"
    if _etapp_bad_track_value(cleaned.lower()):
        return ""
    return cleaned


def _generic_etapp_normalize_short_list_value(value: str) -> str:
    cleaned = _generic_etapp_clean_profile_value(value)
    cleaned = re.sub(r"^(?:and|or)\s+", "", cleaned, flags=re.IGNORECASE)
    return cleaned.strip(" -*,.;:")


def _generic_etapp_normalize_free_text_value(value: str) -> str:
    cleaned = _generic_etapp_clean_profile_value(value)
    cleaned = re.sub(r"\b(?:the user's?|user's?)\b", "", cleaned, flags=re.IGNORECASE)
    return re.sub(r"\s+", " ", cleaned).strip(" -*,.;:")


def _generic_etapp_music_name_from_atoms(evidence_text: str) -> str:
    matches = re.findall(
        r"\b(?:FrequentlyPlayedTracks|music_name)\s*=\s*([^;\n|]+)",
        str(evidence_text or ""),
        flags=re.IGNORECASE,
    )
    for match in matches:
        track = _generic_etapp_normalize_track_value(match)
        if not track:
            continue
        if " - " in track:
            track = track.split(" - ", 1)[0]
        return track.lower()
    return ""


def _generic_etapp_domain_context(
    *,
    sample: AttackInput,
    visible_tool_names: set[str],
    evidence_text: str,
) -> str:
    task_domain = str(sample.public_context.get("task_domain") or "").strip().lower()
    if task_domain:
        return task_domain
    text = " ".join(
        [
            str(sample.task_prompt or "").lower(),
            " ".join(sorted(visible_tool_names)).lower(),
            str(evidence_text or "").lower(),
        ]
    )
    domain_markers = (
        ("music", ("music", "song", "track", "artist", "genre", "play_music")),
        ("calendar", ("calendar", "alarm", "event", "schedule")),
        ("weather", ("weather", "forecast", "temperature")),
        ("travel", ("travel", "flight", "hotel", "destination")),
        ("shopping", ("shopping", "brand", "product", "purchase")),
        ("health", ("meal", "diet", "workout", "exercise", "health")),
    )
    for domain, markers in domain_markers:
        if any(marker in text for marker in markers):
            return domain
    return ""


def _etapp_profile_facts_from_real_agent_text(text: str) -> list[str]:
    source = str(text or "")
    facts: list[str] = []
    for key, value in _generic_etapp_labeled_role_values(source):
        if key in _GENERIC_ETAPP_FACT_KEYS:
            facts.append(f"{key}={value}")
    for key, value in _generic_etapp_sentence_role_values(source):
        if key in _GENERIC_ETAPP_FACT_KEYS:
            facts.append(f"{key}={value}")
    for match in re.finditer(r"\b([1-9][0-9]{0,2})\s*[- ]year[- ]old\b", source, flags=re.IGNORECASE):
        facts.append(f"Age={match.group(1)}")
    for match in re.finditer(r"\bage\s*(?:is|:|=)?\s*([1-9][0-9]{0,2})\b", source, flags=re.IGNORECASE):
        facts.append(f"Age={match.group(1)}")
    if re.search(r"\b(?:female user|user is female|woman)\b", source, flags=re.IGNORECASE):
        facts.append("Gender=female")
    elif re.search(r"\b(?:male user|user is male|man)\b", source, flags=re.IGNORECASE):
        facts.append("Gender=male")
    elif re.search(r"\b(?:nonbinary|non-binary|genderqueer)\b", source, flags=re.IGNORECASE):
        facts.append("Gender=non-binary")
    generic_patterns = (
        ("Location", r"\b(?:lives in|based in|located in|city(?: is|:|=))\s+([^.;,\n]+)"),
        ("Occupation", r"\b(?:works as|works in|occupation is|profession is)\s+(?:a|an)?\s*([^.;,\n]+)"),
        ("EducationLevel", r"\beducation level\s*(?:is|:|=)?\s*([^.;\n]+)"),
        ("IncomeLevel", r"\b(?:income|budget)\s*(?:level|context)?\s*(?:is|:|=)?\s*([^.;\n]+)"),
        ("LanguageProficiency", r"\b(?:speaks|fluent in|native speaker of|language(?:s)?(?: are| is|:|=))\s+([^.;\n]+)"),
        ("CulturalPreferences", r"\b(?:cultural preferences?|cultural interests?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("InterestActivity", r"\b(?:interests?|activities)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("Character", r"\b(?:character|personality|communication style)\s*(?:is|:|=)\s*([^.;\n]+)"),
    )
    for key, pattern in generic_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _generic_etapp_clean_profile_value(match.group(1))
            if value:
                facts.append(f"{key}={value}")
    return _regularize_etapp_profile_key_values(facts)


def _etapp_profile_preferences_from_real_agent_text(text: str) -> list[str]:
    source = str(text or "")
    preferences: list[str] = []
    for key, value in _generic_etapp_labeled_role_values(source):
        if key not in _GENERIC_ETAPP_FACT_KEYS:
            preferences.append(f"{key}={value}")
    for key, value in _generic_etapp_sentence_role_values(source):
        if key not in _GENERIC_ETAPP_FACT_KEYS:
            preferences.append(f"{key}={value}")
    track_patterns = (
        r"\b(?:frequently plays|often plays|plays|listens to|favorite tracks? include|preferred tracks? include|tracks? include|songs? include)\s+['\"]?([^'\";]+?)['\"]?\s+\bby\b\s+([^.;\n]+)",
        r"['\"]?([A-Z][A-Za-z0-9 '&]+?)['\"]?\s*[-–]\s*([A-Z][A-Za-z0-9 '&]+)(?=[,.;\n]|$)",
    )
    for pattern in track_patterns:
        for match in re.finditer(pattern, source):
            window = source[max(0, match.start() - 80) : match.end() + 40].lower()
            if pattern.startswith("['") and not any(marker in window for marker in ("music", "track", "song", "play", "listen")):
                continue
            preferences.append(
                f"FrequentlyPlayedTracks={_generic_etapp_clean_profile_value(match.group(1))} - "
                f"{_generic_etapp_clean_profile_value(match.group(2))}"
            )

    labeled_patterns = (
        ("FavoriteGenres", r"\b(?:favorite|preferred|music)\s+genres?\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("PreferArtists", r"\b(?:favorite|preferred)\s+artists?\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("ListeningHabits", r"\blistening habits?\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("PlaybackBehavior", r"\bplayback(?: behavior)?\s*(?:is|:|=)\s*([^.;\n]+)"),
        ("PreferredVolumeLevel", r"\b(?:volume|preferred volume(?: level)?)\s*(?:is|at|around|:|=)?\s*([0-9]{1,3}\s*%?|[^.;\n]+)"),
        ("BooksAndAuthors", r"\b(?:books?|authors?|reading)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("MoviesAndTVShows", r"\b(?:movies?|tv shows?|shows?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("DietaryHabits", r"\b(?:diet|dietary habits?|meal preferences?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("Hobbies", r"\bhobbies\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("DevicePreferences", r"\b(?:devices?|device preferences?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("FavoriteApps", r"\b(?:apps?|favorite apps?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("FavoriteTravelPlaces", r"\b(?:favorite travel places?|travel places?|destinations?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("TravelHabits", r"\btravel(?: habits?| style)?\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("FavoriteBrands", r"\b(?:brands?|favorite brands?)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("ShoppingPreferences", r"\bshopping(?: preferences?)?\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("SmartHomeUsage", r"\b(?:smart home|home style|temperature/comfort)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
        ("Routine", r"\b(?:routine|evening routine)\s*(?:include|includes|are|is|:|=)\s*([^.;\n]+)"),
    )
    for key, pattern in labeled_patterns:
        for match in re.finditer(pattern, source, flags=re.IGNORECASE):
            value = _generic_etapp_clean_profile_value(match.group(1))
            if value:
                preferences.append(f"{key}={value}")
    return _regularize_etapp_profile_key_values(preferences)


def _fuse_etapp_cross_round_profile_evidence(
    *,
    facts: Sequence[str],
    preferences: Sequence[str],
    evidence_text: str,
    backend_key: str,
) -> tuple[list[str], list[str]]:
    del evidence_text, backend_key
    return (
        _regularize_etapp_profile_key_values(facts),
        _regularize_etapp_profile_key_values(preferences),
    )


def _restore_etapp_langmem_music_core_profile_atoms(
    *,
    facts: Sequence[str],
    preferences: Sequence[str],
    fact_candidates: Sequence[str],
    preference_candidates: Sequence[str],
    evidence_text: str,
) -> tuple[list[str], list[str], dict[str, Any]]:
    del fact_candidates, preference_candidates, evidence_text
    return (
        _dedupe_texts([str(item) for item in facts if str(item).strip()]),
        _dedupe_texts([str(item) for item in preferences if str(item).strip()]),
        {
            "status": "not_applied",
            "reason": "generic_schema_role_value_projection_disables_concrete_restore",
        },
    )


def _restore_etapp_graphiti_music_core_profile_atoms(
    *,
    facts: Sequence[str],
    preferences: Sequence[str],
    evidence_text: str,
) -> tuple[list[str], list[str], dict[str, Any]]:
    del evidence_text
    return (
        _dedupe_texts([str(item) for item in facts if str(item).strip()]),
        _dedupe_texts([str(item) for item in preferences if str(item).strip()]),
        {
            "status": "not_applied",
            "reason": "generic_schema_role_value_projection_disables_concrete_restore",
        },
    )


def _regularize_etapp_backend_music_preferences(
    preferences: Sequence[str],
    *,
    backend_key: str,
) -> list[str]:
    del backend_key
    return _regularize_etapp_profile_key_values(preferences)


