def _apply_etapp_graphiti_profile_carrier_swaps(
    projected: dict[str, Any],
    *,
    sample: AttackInput,
    backend_key: str,
) -> dict[str, Any]:
    del projected, sample, backend_key
    return {
        "status": "not_applied",
        "reason": "generic_schema_role_value_projection_disables_concrete_carrier_swap",
        "tool_cues_removed": 0,
    }


def _etapp_budget_atom_score(
    item: str,
    *,
    category: str,
    domain_context: str = "",
    backend_key: str = "",
) -> tuple[int, int, int]:
    del backend_key
    key, _, value = str(item).partition("=")
    fact_priority = {
        "Age": 90,
        "Location": 86,
        "Occupation": 84,
        "EducationLevel": 82,
        "Gender": 80,
        "LanguageProficiency": 78,
        "CulturalPreferences": 76,
        "Interests": 75,
        "InterestActivity": 74,
        "Character": 72,
        "IncomeLevel": 70,
    }
    preference_priority = {
        "FrequentlyPlayedTracks": 92,
        "PreferArtists": 90,
        "FavoriteGenres": 88,
        "MusicGenres": 86,
        "ListeningHabits": 82,
        "PlaybackBehavior": 80,
        "PreferredVolumeLevel": 78,
        "FavoriteApps": 76,
        "DevicePreferences": 74,
        "DietaryHabits": 72,
        "BooksAndAuthors": 70,
        "MoviesAndTVShows": 68,
        "Hobbies": 66,
        "FavoriteTravelPlaces": 64,
        "TravelHabits": 62,
        "FavoriteBrands": 60,
        "ShoppingPreferences": 58,
        "Routine": 56,
        "Preferences": 54,
        "SmartHomeUsage": 52,
        "NewsSources": 50,
    }
    if domain_context == "music" and category == "preferences":
        preference_priority = {
            **preference_priority,
            "FrequentlyPlayedTracks": 110,
            "PreferArtists": 106,
            "FavoriteGenres": 104,
            "MusicGenres": 102,
            "ListeningHabits": 100,
            "PlaybackBehavior": 98,
            "PreferredVolumeLevel": 96,
        }
    base = (fact_priority if category == "facts" else preference_priority).get(key, 10)
    generic_score = _etapp_profile_atom_score(item)[0]
    value_length = min(len(value), 180)
    return (base + generic_score, value_length, -len(str(item)))


def _etapp_profile_atom_score(item: str) -> tuple[int, int, int]:
    key, _, value = str(item).partition("=")
    cleaned = _generic_etapp_clean_profile_value(value)
    lower_value = cleaned.lower()
    score = 0
    if key in _GENERIC_ETAPP_FACT_KEYS:
        score += 12
    if key in _GENERIC_ETAPP_MULTI_VALUE_KEYS:
        score += 10
    if " - " in cleaned and key == "FrequentlyPlayedTracks":
        score += 24
    if re.search(r"\b[0-9]{1,3}\s*%?\b", cleaned) and key in {"Age", "PreferredVolumeLevel"}:
        score += 18
    if "," in cleaned:
        score += min(18, 4 * cleaned.count(","))
    if len(cleaned) >= 12:
        score += 8
    if len(cleaned) >= 40:
        score += 8
    if not _generic_etapp_value_is_informative(cleaned):
        score -= 100
    if key == "FrequentlyPlayedTracks" and _etapp_bad_track_value(lower_value):
        score -= 80
    prefer_long = key in {
        "BooksAndAuthors",
        "CulturalPreferences",
        "DevicePreferences",
        "DietaryHabits",
        "FavoriteApps",
        "FavoriteBrands",
        "FavoriteTravelPlaces",
        "Hobbies",
        "IncomeLevel",
        "Interests",
        "InterestActivity",
        "LanguageProficiency",
        "ListeningHabits",
        "LongTermTravel",
        "MoviesAndTVShows",
        "PlaybackBehavior",
        "Preferences",
        "Routine",
        "ShoppingPreferences",
        "ShortTermWalk",
        "TravelHabits",
    }
    length_score = min(len(cleaned), 180) if prefer_long else -len(cleaned)
    return (score, length_score, -len(str(item)))


# Freeze-candidate ETAPP cleanup: keep this pass schema/role/value based.
#
# Earlier cleanup rules rejected or restored ETAPP atoms with concrete values
# from quick samples. The final active definitions below intentionally replace
# those rules with generic checks over role names, value informativeness, and
# evidence-scaffold contamination only.

_GENERIC_ETAPP_UNCERTAIN_VALUE_MARKERS = (
    "not explicitly",
    "not specified",
    "unspecified",
    "unknown",
    "likely",
    "probably",
    "possibly",
    "could be",
    "might be",
    "would use",
    "would like",
    "if available",
    "available",
    "no specific",
)

_GENERIC_ETAPP_SCAFFOLD_VALUE_MARKERS = (
    "candidate",
    "chosen",
    "decision=",
    "decision:",
    "option a",
    "option b",
    "personal cue",
    "profile context",
    "evidence cue",
    "tool cue",
    "tool=",
    "tool:",
    "role=",
    "role:",
    "value=",
    "value:",
    "please ",
    "write ",
    "include only",
    "use concrete",
)


def _generic_etapp_atom_key_value(item: Any) -> tuple[str, str]:
    key, _, value = str(item or "").partition("=")
    canonical_key = _generic_etapp_canonical_key(key)
    return canonical_key, _generic_etapp_clean_profile_value(value)


def _generic_etapp_value_has_role_boundary(value: Any) -> bool:
    text = str(value or "")
    label_pattern = _generic_etapp_role_label_pattern()
    if not label_pattern:
        return False
    return bool(
        re.search(
            rf"(?:[,;|]\s*|\s+)\b(?:{label_pattern})\s*"
            r"(?:=|:|\bis\b|\bare\b|\binclude(?:s)?\b)",
            text,
            flags=re.IGNORECASE,
        )
    )


def _generic_etapp_projected_value_is_noise(
    item: Any,
    *,
    category: str,
) -> bool:
    del category
    key, value = _generic_etapp_atom_key_value(item)
    lowered = value.lower()
    if not key or not _generic_etapp_value_is_informative(value):
        return True
    if not _generic_etapp_atom_type_compatible(item):
        return True
    if _generic_etapp_value_has_role_boundary(value):
        return True
    if any(marker in lowered for marker in _GENERIC_ETAPP_UNCERTAIN_VALUE_MARKERS):
        return True
    if any(marker in lowered for marker in _GENERIC_ETAPP_SCAFFOLD_VALUE_MARKERS):
        return True
    if key == "Age":
        return not bool(re.fullmatch(r"[1-9][0-9]{0,2}", value.strip()))
    if key == "Gender":
        return value.strip().lower() not in {"male", "female", "non-binary"}
    if key == "PreferredVolumeLevel":
        return not bool(re.search(r"\b[0-9]{1,3}\s*%?\b|\b(?:low|medium|high|quiet|loud)\b", lowered))
    if key == "FrequentlyPlayedTracks":
        return _etapp_bad_track_value(lowered)
    if key in {"FavoriteGenres", "MusicGenres", "PreferArtists"}:
        return len(value) > 160
    if key == "PlaybackBehavior":
        return any(marker in lowered for marker in ("preferred volume", "volume level", "play tracks on demand"))
    return False


def _is_etapp_projected_generic_fact_noise(item: Any, *, backend_key: str) -> bool:
    del backend_key
    return _generic_etapp_projected_value_is_noise(item, category="facts")


def _is_etapp_projected_generic_noise(item: Any, *, backend_key: str) -> bool:
    del backend_key
    return _generic_etapp_projected_value_is_noise(item, category="preferences")
